#include <string.h>

typedef struct {
    int command;
    char address[17];
    unsigned char data[];
} MAC_PDU;

void manageArray(int size) {
    MAC_PDU** pduArray = (MAC_PDU**)malloc(size * sizeof(MAC_PDU*));
    for (int i = 0; i < size; i++) {
        pduArray[i] = (MAC_PDU*)malloc(sizeof(MAC_PDU));
        pduArray[i]->command = rand() % 100;
        sprintf(pduArray[i]->address, "%02x%02x%02x%02x%02x%02x", 
                rand() & 0xFF, rand() & 0xFF, rand() & 0xFF, rand() & 0xFF, 
                rand() & 0xFF, rand() & 0xFF);
        pduArray[i]->data = (unsigned char*)malloc(1024); // assuming max data length
        for (int j = 0; j < 1024; j++) {
            pduArray[i]->data[j] = rand() % 256;
        }
        // calculate and set checksum
    }
}

void validateChecksum(MAC_PDU* pdu) {
    unsigned int sum = 0;
    for (int i = 0; i < sizeof(pdu->data); i++) {
        sum += pdu->data[i];
    }
    if (sum != pdu->command) {
        printf("Invalid checksum\n");
    } else {
        printf("Checksum validated\n");
    }
}

