typedef struct {
    int key;
    long offset;
} record;

record* initArrays(int* keys, long* offsets, int numRecords) {
    // Allocate memory for the 'keys' array.
    int* keysArray = (int*)malloc(numRecords * sizeof(int));
    if (!keysArray) return NULL; // Handle allocation error.

    // Initialize the 'keys' array with random values.
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        keysArray[i] = rand() % 100;
    }

    // Allocate memory for the 'offsets' array.
    long* offsetsArray = (long*)malloc(numRecords * sizeof(long));
    if (!offsetsArray) return NULL; // Handle allocation error.

    // Initialize the 'offsets' array with random values.
    for (int i = 0; i < numRecords; i++) {
        offsetsArray[i] = (rand() % 10000000);
    }

    // Allocate memory for the 'records' array.
    record* recordsArray = (record*)malloc(numRecords * sizeof(record));
    if (!recordsArray) return NULL; // Handle allocation error.

    // Initialize each record's key and offset fields.
    for (int i = 0; i < numRecords; i++) {
        recordsArray[i].key = keysArray[i];
        recordsArray[i].offset = offsetsArray[i];
    }

    // Free the temporary arrays to prevent memory leaks.
    free(keysArray);
    free(offsetsArray);

    return recordsArray;
}

void freeArrays(record* records, int numRecords) {
    // Deallocate the 'records' array.
    free(records);

