#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_LINE_LENGTH 1024
#define OUTPUT_FILE_NAME "output.txt"
#define COMPRESSION_RATIO 0.7

void print_manpage() {
    printf("Usage: program [options] [input_file]\n");
    printf("Options:\n");
    printf("- --manpage\tDisplay detailed help information\n");
    printf("- -cs \tCompress each line of the input file\n");
    printf("- -o output_file\tRedirect the output to a specified file\n");
    printf("- -v \tEnable verbose mode for compression\n");
}

int main(int argc, char* argv[]) {
    int opt_compression = 0;
    int opt_output = 0;
    int opt_verbose = 0;
    FILE* input_file = NULL;
    FILE* output_file = NULL;

    // Parse command line arguments
    while (1) {
        static struct option long_options[] = {
            {"manpage", no_argument, 0, 'h'},
            {"cs", no_argument, 0, 'c'},
            {"o", required_argument, 0, 'o'},
            {"v", no_argument, 0, 'v'},
            {0, 0, 0, 0}
        };

        int option_index = 0;
        int c = getopt_long(argc, argv, "hcv:o:", long_options, &option_index);

        if (c == -1) break;

        switch (c) {
            case 'h':
                print_manpage();
                return 0;
            case 'c':
                opt_compression = 1;
                break;
            case 'o':
                opt_output = 1;
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    perror("Error opening output file");
                    return -1;
                }
                break;
            case 'v':
                opt_verbose = 1;
                break;
        }
    }

    // Check for input file
    if (argc > optind) {
        const char* input_filename = argv[optind];
        input_file = fopen(input_filename, "r");
        if (!input_file) {
            perror("Error opening input file");
            return -1;
        }
    } else {
        printf("No input file provided. Use --manpage for usage information.\n");
        return 0;
    }

    // Read and process the input file
    int line_count = 0;
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, input_file)) {
        line_count++;

        if (opt_compression) {
            // Simple compression algorithm: replace every other character with a dash
            for (int i = 0; i < strlen(buffer); i += 2)
                buffer[i] = '-';
            printf("%s", buffer);
            if (opt_output) {
                fwrite(buffer, sizeof(char), strlen(buffer), output_file);
            }
        } else {
            printf("%s", buffer);
        }

        if (opt_verbose) {
            printf(" (%d)\n", line_count);
        } else {
            printf("\n");
        }
    }

    fclose(input_file);
    if (!opt_output) fclose(stdout);

    return 0;
}
