#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void extract_sections(const char *input_file_name,
                       const char *delimiter_pattern,
                       const char *output_file1_name,
                       const char *output_file2_name) {
    FILE *input_file = fopen(input_file_name, "r");
    if (input_file == NULL) {
        printf("Error opening input file: %s\n", input_file_name);
        return;
    }

    FILE *output_file1 = fopen(output_file1_name, "w");
    FILE *output_file2 = fopen(output_file2_name, "w");

    char buffer[1024];
    char *section_buffer = NULL;
    size_t section_buffer_size = 0;

    int section_counter = 0;
    int current_section_number = 0;

    while (fgets(buffer, sizeof(buffer), input_file) != NULL) {
        if (strchr(buffer, delimiter_pattern[0]) != NULL &&
            strcmp(strtok(buffer, delimiter_pattern), "Section") == 0) {
            // New section found
            current_section_number++;

            if (section_counter > 0) {
                // Write previous section to output file
                fwrite(section_buffer, 1, section_buffer_size, output_files[section_counter - 1]);
                fflush(output_files[section_counter - 1]);

                fclose(output_files[section_counter - 1]);
                free(section_buffer);
            }

            section_counter = current_section_number;
            section_buffer = (char *)malloc(1024);
            section_buffer_size = 0;

            output_files[current_section_number - 1] =
                    current_section_number % 2 ? output_file1 : output_file2;
        } else if (section_counter > 0) {
            // Still in the same section
            size_t new_buffer_size = strlen(buffer) + section_buffer_size + 1;
            char *new_buffer = (char *)realloc(section_buffer, new_buffer_size);
            strcpy(new_buffer + section_buffer_size, buffer);
            section_buffer_size = new_buffer_size;
            section_buffer = new_buffer;
        } else {
            // Not in a section
            size_t new_buffer_size = strlen(buffer) + 1;
            char *new_buffer = (char *)malloc(new_buffer_size);
            strcpy(new_buffer, buffer);
            section_buffer = new_buffer;
            section_buffer_size = new_buffer_size;
        }
    }

    if (section_counter > 0) {
        // Write last section to output file
        fwrite(section_buffer, 1, section_buffer_size, output_files[section_counter - 1]);
        fflush(output_files[section_counter - 1]);

        fclose(output_files[section_counter - 1]);
        free(section_buffer);
    }

    fclose(input_file);
    fclose(output_file1);
    fclose(output_file2);

    return;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        printf("Usage: %s <input_file> <delimiter_pattern> <output_file1> <output_file2>\n", argv[0]);
        return 1;
    }

    extract_sections(argv[1], argv[2], argv[3], argv[4]);

    return 0;
}
