typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    u_char ip_address[MAX_IP_ADDRESS_LENGTH];
} HostIPPair;

u_char* perform_dns_resolution(const char* hostname) {
    // Create a socket for the DNS query
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return NULL;
    }

    // Set up the socket to send and receive data
    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

    // Perform the DNS query asynchronously
    pthread_t thread;
    pthread_create(&thread, NULL, dns_query_thread_handler, (void*)hostname);
    pthread_join(thread, NULL);

    // Close the socket
    close(sockfd);

    return NULL; // IP address not resolved yet
}

void* dns_query_thread_handler(void* arg) {
    const char* hostname = (const char*)arg;
    struct addrinfo hints, *res;

    // Initialize the getaddrinfo function with our query parameters
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for simplicity
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;

    // Perform the DNS query and resolve the IP address
    int ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0) {
        printf("getaddrinfo() failed: %s\n", gai_strerror(ret));
        return NULL;
    }

    // Send the resolved IP address to a specified socket for further processing
    int sockfd = ...; // obtain the socket handle from the existing network stack
    sendto(sockfd, res->ai_addr, res->ai_addrlen, 0, (struct sockaddr*)res->ai_addr, res->ai_addrlen);

    // Free the memory allocated by getaddrinfo
    freeaddrinfo(res);
    return NULL;
}

int main() {
    const char* hostname = "example.com";
    u_char* ip_address = perform_dns_resolution(hostname);
    if (ip_address != NULL) {
        printf("Resolved IP address: %s\n", inet_ntoa(*((struct in_addr*)ip_address)));
    } else {
        printf("Error resolving the IP address\n");
    }

    return 0;
}
