int findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void printArray(int* arr, int size) {
    printf("[");
    for (int i = 0; i < size; i++) {
        printf("%d", arr[i]);
        if (i < size - 1)
            printf(", ");
    }
    printf("]\n");
}

int main() {
    int max_size = 10000;
    int* arr = NULL;
    int size = 0;

    // Read integers from standard input
    while (scanf("%d", &arr[size]) == 1 && size < max_size) {
        size++;
    }

    if (size >= max_size) {
        printf("Error: Input exceeds maximum size of %d elements.\n", max_size);
        return 1;
    }

    // Allocate memory for the array
    arr = (int*) realloc(arr, sizeof(int) * size);

    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return 2;
    }

    // Check if the input array is sorted in ascending order
    int prev = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] <= prev) {
            printf("Error: Input array is not sorted in ascending order.\n");
            return 3;
        }
        prev = arr[i];
    }

    // Find and print the largest integer in the array
    int max = findLargest(arr, size);
    printf("The largest integer is %d.\n", max);

    free(arr);
    return 0;
}
