#define MAX_LOG_MESSAGE 1024

typedef enum {
    ERROR,
} log_level;

void logConditionError(int is_error_occurred, const char *format, ...) {
    if (!is_error_occurred) return;

    static int file_descriptors[2] = {0}; // To manage multiple threads
    FILE *log_file;
    va_list args;

    if (file_descriptors[1]) {
        log_file = fileno(file_descriptors[1]);
    } else {
        log_file = fopen("error.log", "a");
        if (!log_file) return; // Handle error
        file_descriptors[0] = fileno(log_file);
        file_descriptors[1] = log_file;
    }

    va_start(args, format);
    char message[MAX_LOG_MESSAGE];
    vsnprintf(message, MAX_LOG_MESSAGE - 1, "[ERROR][%ld][Thread ID: %lu]%s\n", 
               time(NULL), (long)pthread_self(), format, args);
    message[MAX_LOG_MESSAGE - 1] = '\0';
    fprintf(log_file, "%s", message);

    va_end(args);

    if (file_descriptors[1]) {
        fclose(log_file);
    }
}
