#include <openssl/ssl.h>
#include <openssl/aes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void *encrypt_file(const char *file_path, const char *command_line_option, const char *key_string) {
    // Initialize OpenSSL
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int err;

    // Set up the cipher algorithm based on the command line option
    if (strcmp(command_line_option, "AES-256-CBC") == 0) {
        AES_set_encrypt_key((unsigned char*)key_string, strlen(key_string), &ctx);
    } else {
        // Handle other encryption algorithms here
    }

    FILE *file = fopen(file_path, "rb+");
    if (!file) return NULL;

    fseek(file, 0L, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    char buffer[1024];
    int chunk_size = sizeof(buffer);
    long remaining = file_size;
    long processed = 0;

    // Start the encryption process
    time_t start_time = time(NULL);
    printf("Encryption started at %s.\n", asctime(localtime(&start_time)));

    while (remaining > 0) {
        int bytes_read = fread(buffer, 1, chunk_size, file);

        if (bytes_read < 0) {
            // Handle I/O error
            fclose(file);
            return NULL;
        }

        int bytes_written = AES_cbc_encrypt(buffer, buffer, bytes_read, ctx, key_string);

        if (bytes_written < 0) {
            // Handle encryption error
            fclose(file);
            return NULL;
        }

        printf("\rProcessed %ld of %ld bytes (%.2f%%)...", processed + bytes_read, file_size, ((double)processed / file_size) * 100);
        fflush(stdout);

        remaining -= bytes_read;
        processed += bytes_read;
    }

    // End the encryption process
    time_t end_time = time(NULL);
    printf("Encryption completed at %s.\n", asctime(localtime(&end_time)));

    fclose(file);
    EVP_CIPHER_CTX_free(ctx);

    return ctx;
}
