struct SemaphorePool {
    sem_t **semaphores;
    int size;
};

void semaphore_pool_init(struct SemaphorePool *pool, int initial_value, int num_semaphores) {
    pool->size = num_semaphores;
    pool->semaphores = (sem_t **)malloc(num_semaphores * sizeof(sem_t *));
    for(int i = 0; i < num_semaphores; i++) {
        semaphores[i] = sem_open("my_semaphore", O_CREAT, initial_value);
    }
}

void semaphore_pool_exit(struct SemaphorePool *pool) {
    for(int i = 0; i < pool->size; i++) {
        sem_close(pool->semaphores[i]);
        free(pool->semaphores);
    }
}

int main() {
    struct SemaphorePool my_pool;
    int initial_value = 5, num_semaphores = 10;

    semaphore_pool_init(&my_pool, initial_value, num_semaphores);

    // Use the pool
    for(int i = 0; i < num_semaphores; i++) {
        sem_post(my_pool.semaphores[i]);
    }

    semaphore_pool_exit(&my_pool);
}
