class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& service)
        : io_(service), connection_pool_(new boost::asio::ip::tcp::connect(service)) {}

    void send_requests(const std::vector<Request>& requests) {
        for (const auto& request : requests) {
            if (request.type == RequestType::GET) {
                get_request(request.url, request.params);
            } else {
                // Handle other request types
            }
        }
    }

private:
    void get_request(const std::string& url, const std::vector<std::pair<std::string, std::string>>& params) {
        boost::asio::ip::tcp::socket socket(*connection_pool_);
        boost::asio::connect(socket, boost::asio::ip::tcp::v4(), url);

        boost::asio::write(socket, "GET " + url + " HTTP/1.0\r\n");

        for (const auto& param : params) {
            boost::asio::write(socket, param.first + ": " + param.second + "\r\n");
        }

        boost::asio::write(socket, "\r\n");

        boost::asio::read_until(socket, boost::asio::ip::tcp::v4(), "\r\n\r\n", [this](boost::system::error_code ec) {
            if (!ec) {
                // Validate response format
                // ...
            } else {
                // Handle failed request
            }
        });
    }

    boost::asio::io_service& io_;
    std::unique_ptr<boost::asio::ip::tcp::connect> connection_pool_;
};

