public List<UserProfile> GetPaginatedUserProfiles(List<FilterCriterion> filterCriteria, SqlConnection connection, SqlCommand command)
{
    var userProfileList = new List<UserProfile>();

    // Construct the SQL query with parameterization
    var query = "SELECT * FROM UserProfiles";
    if (filterCriteria.Count > 0)
    {
        query += " WHERE ";
        bool firstFilter = true;
        foreach (var filter in filterCriteria)
        {
            switch (filter.Type)
            {
                case FilterType.Email:
                    query += $"Email LIKE '%{filter.Value}%'";
                    break;
                case FilterType.Name:
                    query += $"Name LIKE '%{filter.Value}%'";
                    break;
                // Add more cases as needed
            }
            if (!firstFilter) query += " AND ";
            firstFilter = false;
        }
    }

    // Handle sorting and pagination
    if (filterCriteria.Any(f => f.Type == FilterType.SortOrder))
    {
        var sortOrderFilter = filterCriteria.First(f => f.Type == FilterType.SortOrder);
        query += $" ORDER BY {sortOrderFilter.Value} {sortOrderFilter.Direction}";
    }
    else
    {
        query += " ORDER BY Email ASC"; // Default sort order if no sorting is specified
    }

    if (filterCriteria.Any(f => f.Type == FilterType.PageSize))
    {
        var pageSizeFilter = filterCriteria.First(f => f.Type == FilterType.PageSize);
        query += $" LIMIT {pageSizeFilter.Value}";
    }
    else
    {
        query += " LIMIT 10"; // Default page size if no pagination is specified
    }

    // Execute the SQL command and populate the result set
    using (var reader = command.ExecuteReader())
    {
        while (reader.Read())
        {
            var userProfile = new UserProfile();
            userProfile.Email = reader["Email"].ToString();
            userProfile.Name = reader["Name"].ToString();
            // Add more property assignments as needed
            userProfileList.Add(userProfile);
        }
    }

    return userProfileList;
}
