using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    private const int MaxBatchSize = 1000; // adjust this value as needed for performance and memory constraints
    private readonly XmlDocument _xmlDoc;
    private readonly XPathDocument _xpathDoc;
    private readonly List<string> _attributeNamespaces = new List<string>();

    public XmlParser(string xmlString)
    {
        _xmlDoc = new XmlDocument();
        _xmlDoc.LoadXml(xmlString);
        _xpathDoc = new XPathDocument(_xmlDoc);
    }

    public List<XmlNode> FindElements(string xpathExpression, string attributeName, string attributeValue)
    {
        try
        {
            XPathExpression expression = _xpathDoc.Compile(xpathExpression);
            if (expression == null)
                throw new Exception($"Invalid XPath expression: {xpathExpression}");

            XPathNodeIterator nodes = _xpathDoc.CreateNavigator().SelectSingleNode(expression.Compile()).Select();
            List<XmlNode> result = new List<XmlNode>();

            foreach (XPathNodeIterator node in GetBatchedNodes(nodes))
            {
                foreach (XmlNode xmlNode in node.Current())
                {
                    if (xmlNode.HasAttributes && !string.IsNullOrEmpty(attributeName) && !string.IsNullOrEmpty(attributeValue))
                    {
                        XmlAttribute attribute = xmlNode.Attributes[attributeName];
                        if (attribute != null && attribute.Value.ToLower().Contains(attributeValue.ToLower()))
                            result.Add(xmlNode);
                    }
                    else
                        result.AddRange(GetMatchingNodes(xmlNode, expression));
                }
            }

            return result;
        }
        catch (Exception ex)
        {
            // log the error and provide a meaningful message if an invalid XPath expression is provided
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return new List<XmlNode>();
        }
    }

    private IEnumerable<XPathNodeIterator> GetBatchedNodes(XPathNodeIterator nodes)
    {
        int batchSize = Math.Min(MaxBatchSize, nodes.Count);
        for (int i = 0; i < nodes.Count; i += batchSize)
        {
            yield return nodes.Skip(i).Take(batchSize);
        }
    }

    private List<XmlNode> GetMatchingNodes(XmlNode parentNode, XPathExpression expression)
    {
        List<XmlNode> result = new List<XmlNode>();
        foreach (XmlNode node in parentNode.SelectNodes(expression))
        {
            if (!node.HasAttributes || !GetNamespace(node) == null)
                continue;

            string nodeName = node.Name;
            foreach (XmlAttribute attribute in node.Attributes)
            {
                _attributeNamespaces.Add(attribute.NamespaceURI);
            }

            result.Add(node);

            foreach (XmlNode childNode in GetMatchingNodes(node, expression))
            {
                result.Add(childNode);
            }
        }

        return result;
    }

    private string GetNamespace(XmlNode node)
    {
        XmlAttribute namespaceAttr = node.Attributes["xmlns"];
        if (namespaceAttr != null)
            return namespaceAttr.Value;
        else
            return null;
    }
}
