import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class MD5Hasher {

    public static String[][] processBatch(String[][] batch) {
        List<String> results = new ArrayList<>();

        for (String[] strings : batch) {
            long startTime = System.currentTimeMillis();

            try {
                for (String s : strings) {
                    if (validateInput(s)) {
                        MessageDigest md = MessageDigest.getInstance("MD5");
                        byte[] bytes = s.getBytes();
                        md.update(bytes);
                        String hash = DatatypeConverter.printHexBinary(md.digest()).toUpperCase();
                        results.add(hash);
                    }
                }

                long endTime = System.currentTimeMillis();
                System.out.println("Batch processed in " + (endTime - startTime) + " ms.");
            } catch (NoSuchAlgorithmException e) {
                System.err.println("Error processing batch: " + e.getMessage());
            }
        }

        return results.toArray(new String[0][]);
    }

    private static boolean validateInput(String s) {
        if (s == null || s.trim().isEmpty()) {
            return false;
        }

        if (s.length() > 1024) {
            return false;
        }

        return true;
    }
}
