public static CacheUpdateResponse UpdateWidgetContent(string widgetId, object newDataPayload, WidgetUpdateFrequency updateFrequency)
{
    Dictionary<string, CacheUpdateResponse> cachedWidgets = _cache.Get("widgets");

    if (cachedWidgets == null)
    {
        cachedWidgets = new Dictionary<string, CacheUpdateResponse>();
        _cache.Set("widgets", cachedWidgets);
    }

    if (!cachedWidgets.ContainsKey(widgetId))
    {
        cachedWidgets.Add(widgetId, new CacheUpdateResponse { NeedsRefresh = true });
    }
    else
    {
        CacheUpdateResponse existingResponse = cachedWidgets[widgetId];

        if (existingResponse.NeedsRefresh && updateFrequency == WidgetUpdateFrequency.Frequent)
        {
            // Update logic here
            newDataPayload = ...; // process data payload

            existingResponse.NeedsRefresh = false;
        }
        else if (!existingResponse.NeedsRefresh && updateFrequency != WidgetUpdateFrequency.Frequent)
        {
            existingResponse.NeedsRefresh = true;
        }
    }

    return cachedWidgets[widgetId];
}

public enum WidgetUpdateFrequency
{
    Frequent,
    Infrequent,
    Rare
}

