import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class StateLoader {

    public static MoSTState loadState(String directory, String filename) {
        File file = new File(directory, filename);
        ObjectInputStream ois = null;
        try {
            FileInputStream fis = new FileInputStream(file);
            ois = new ObjectInputStream(fis);

            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                MoSTState state = (MoSTState) obj;

                // Validate the integrity of the loaded object
                if (!state.isValid()) {
                    System.out.println("Warning: Loaded state is outdated.");
                }

                return state;
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        } finally {
            try {
                if (ois != null) ois.close();
            } catch (IOException e) {
                System.out.println("Error closing ObjectInputStream: " + e.getMessage());
            }
        }

        return null;
    }
}
