const fs = require('fs');
const path = require('path');
const { validate } = require('ajv'); // Assuming ajv for schema validation
const logger = require('./logger'); // External logging service
const cache = {};

function readConfigFile(directory, filename) {
  const fileCacheKey = `${directory}/${filename}`;

  if (cache[fileCacheKey]) {
    return Promise.resolve(cache[fileCacheKey]);
  }

  const start = Date.now();

  return new Promise((resolve, reject) => {
    fs.readFile(path.join(directory, filename), 'utf8', (err, data) => {
      if (err) {
        logger.error(`Error reading file ${fileCacheKey}: ${err.message}`);
        reject(err);
      } else {
        const config = JSON.parse(data);

        // Validate configuration against predefined schema
        const schema = ...; // Define your schema here
        const isValid = validate(schema, config);

        if (!isValid) {
          logger.error(`Invalid configuration: ${JSON.stringify(config)}`);
          reject(new Error('Invalid configuration'));
        } else {
          cache[fileCacheKey] = data;
          const end = Date.now();
          logger.info(`Read file ${fileCacheKey} in ${(end - start) / 1000} seconds`);
          resolve(data);
        }
      }
    });
  }).timeout(5000); // Add timeout to prevent blocking
}
