function runTests(moduleLabel, config, testFunction) {
  try {
    const module = require(moduleLabel);
  } catch (err) {
    console.error(`Failed to load module ${moduleLabel}: ${err}`);
    return;
  }

  if (!config || typeof config !== 'object') {
    config = {};
  }

  let blueslipReset = () => { };
  try {
    const blueslip = require('blueslip');
    blueslipReset = () => blueslip.reset();
  } catch (err) {
    console.warn(`Failed to load Blueslip: ${err}`);
  }

  if (!config.blueslip || config.blueslip !== 'reset') {
    blueslipReset = () => { };
  }

  let testCount = 0;
  const testResults = [];

  async function runTest(testName, testFunction) {
    try {
      await testFunction();
      testResults.push({ name: testName, success: true });
    } catch (err) {
      testResults.push({ name: testName, success: false, error: err });
    }
  }

  for (const testName in module) {
    if (module.hasOwnProperty(testName)) {
      const test = module[testName];
      if (!config.skip && typeof test === 'function') {
        try {
          await runTest(testName, () => test());
        } catch (err) {
          console.error(`Failed to execute test ${testName}: ${err}`);
        }
      }
    }
  }

  const logLevel = config.logLevel || 'info';
  const logger = (message) => {
    if (logLevel === 'debug') {
      console.log(message);
    } else if (logLevel === 'info') {
      console.info(message);
    }
  };

  let totalTime = 0;
  for (const result of testResults) {
    logger(`Test ${result.name} ${result.success ? 'passed' : 'failed'} in ${Date.now() - Date.parse(result.startDate)}ms`);
    if (!result.success) {
      console.error(result.error);
    }
    totalTime += Date.now() - Date.parse(result.startDate);
  }

