function extractBibleBooks(text) {
  const oldTestamentRegex = /\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah| Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/ig;
  const newTestamentRegex = /\b(?:Matthew|Mark|Luke|John|Acts|Romans|1Corinthians|2Corinthians|Galatians|Ephesians|Philippians|Colossians|1Thessalonians|2Thessalonians|1Timothy|2Timothy|Titus|Philemon|Hebrews|James|1Peter|2Peter|1John|2John|3John|Jude|Revelation)\b/ig;
  const bibleBooks = {};

  for (const testamentRegex of [oldTestamentRegex, newTestamentRegex]) {
    Object.keys(bibleBooks).forEach((book) => delete bibleBooks[book]);
    let matches = text.match(RegExp(testamentRegex, 'g'));
    if (!matches) continue;

    for (const match of matches) {
      const lowercaseMatch = match.toLowerCase();
      if (!bibleBooks[lowercaseMatch]) bibleBooks[lowercaseMatch] = 0;
      bibleBooks[lowercaseMatch]++;
    }
  }

  return bibleBooks;
}
