function collectAndGraphData(stream) {
  const data = [];
  let paused = false;
  const mutex = new Mutex();
  const graph = new Graph();

  async function handler(chunk) {
    try {
      if (paused) return;
      await mutex.lock();
      try {
        data.push(...chunk);
        for (const item of chunk) {
          const [vertex, edges] = randomGraphElements();
          graph.addVertex(vertex);
          for (const edge of edges) {
            graph.addEdge(edge[0], edge[1], { randomProperty: Math.random() });
          }
        }
      } finally {
        await mutex.unlock();
      }
    } catch (err) {
      console.error(err);
    }
  }

  stream.on('data', handler);

  function pause() {
    paused = true;
  }

  function resume() {
    paused = false;
  }

  return { pause, resume, data: () => data, graph };
}
