['```
function copyBytes(dataChunks, numBytes) {
  const buffer = Buffer.alloc(0);
  let bytesRead = 0;
  let segments = Math.ceil(numBytes / 1024);

  for (let i = 0; i < segments; i++) {
    const startByte = bytesRead;
    const endByte = Math.min(startByte + 1024, numBytes);
    let bytesCopied = 0;

    do {
      const chunk = dataChunks.shift();
      if (!chunk) return { buffer: null, interrupted: true };

      const bytesAvailable = Math.min(chunk.length - (endByte - startByte), endByte - startByte);
      chunk.copy(buffer, bytesRead, bytesRead + bytesAvailable);
      bytesCopied += bytesAvailable;
    } while (bytesReads < endByte && dataChunks.length > 0);

    if (bytesReads < endByte) return { buffer: null, interrupted: true };

    bytesRead = endByte;
  }

  return { buffer, interrupted: false };
}
