function extractFilteredRows(tableName, filterRules) {
    const table = document.getElementById(tableName);
    const filteredRows = [];

    function traverseTable(tableNode, currentPath = []) {
        Array.from(tableNode.children).forEach((node) => {
            if (node.tagName === 'TR') {
                const rowValues = [];
                node.children.forEach((cell) => {
                    if (cell.tagName === 'TD' || cell.tagName === 'TH') {
                        rowValues.push(cell.textContent);
                    }
                });
                let matchesFilter = true;
                filterRules.forEach((rule) => {
                    const ruleMatches = rule.test(rowValues);
                    if (!ruleMatches) {
                        matchesFilter = false;
                        break;
                    }
                });
                if (matchesFilter) {
                    filteredRows.push({ ...currentPath, values: rowValues });
                }
            } else if (node.tagName === 'TBODY' || node.tagName === 'TFOOT') {
                traverseTable(node, currentPath);
            }
        });
    }

    traverseTable(table);

    return filteredRows;
}
