// file-loader.js

class FileLoader {
  constructor() {
    this.fileList = [];
    this.errorHandler = (error) => console.error('File loading error:', error);
  }

  addFile(file) {
    this.fileList.push(file);
  }

  loadFiles() {
    return Promise.all(
      this.fileList.map((file) => {
        return new Promise((resolve, reject) => {
          // Load file content
          const script = document.createElement('script');
          script.src = file;
          document.head.appendChild(script);

          // Wait for file execution to complete
          setTimeout(() => {
            script.onload = () => resolve();
            script.onerror = (error) => reject(error);
          }, 0);
        });
      })
    ).then((results) => {
      // Check if all files were loaded successfully
      if (!results.some((result) => result instanceof Error)) {
        return this.fileList;
      } else {
        throw new Error('One or more files failed to load');
      }
    }).catch(this.errorHandler);
  }
}

// Example usage:
const fileLoader = new FileLoader();
fileLoader.addFile('script1.js');
fileLoader.addFile('script2.js');
fileLoader.loadFiles().then((files) => console.log('Files loaded:', files)).catch(this.errorHandler);

