import java.io.IOException;
import java.net.URI;
import java.nio.channels.AsynchronousChannelGroup;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;

public class AsynchronousConnectionPool {
    private final AsynchronousChannelGroup group;
    private final List<AsynchronousSocketChannel> channels = new ArrayList<>();

    public AsynchronousConnectionPool(int numChannels) throws IOException, InterruptedException {
        this.group = AsynchronousChannelGroup.withThreadPool(Runtime.getRuntime().availableProcessors());
        for (int i = 0; i < numChannels; i++) {
            AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(this.group);
            channels.add(channel);
        }
    }

    public void connect(URI uri) throws IOException, ExecutionException {
        for (AsynchronousSocketChannel channel : channels) {
            if (!channel.isConnecting() && !channel.isOpen()) {
                channel.connect(new InetSocketAddress(uri.getHost(), 80));
                break;
            } else if (channel.isConnected()) {
                return; // already connected
            }
        }
    }

    public void close() throws IOException, InterruptedException {
        for (AsynchronousSocketChannel channel : channels) {
            channel.close();
        }
    }
}
