use reqwest::blocking::{get,post};
use reqwest::header;
use reqwest::redirect::Policy;
use std::collections::HashMap;

async fn create_http_client(url: &str) -> reqwest::Client {
    let client = reqwest::Client::builder()
        .keep_alive(true)
        .max_connections(1000)
        .timeout(std::time::Duration::from_millis(5000))
        .connect_timeout(std::time::Duration::from_millis(2000))
        .gzip(true)
        .redirect(std::sync::mpsc::channel());
    let client = client
        .danger_accept_invalid_certs(false)
        .ssl_verifystate(false)
        .build();
    client
}

async fn make_request(client: &reqwest::Client, url: &str) -> reqwest::blocking::Response {
    match get(client, url).send().await {
        Ok(response) => response,
        Err(error) => {
            println!("Error sending request: {}", error);
            panic!();
        }
    }
}

async fn post_request(client: &reqwest::Client, url: &str, body: String) -> reqwest::blocking::Response {
    match post(client, url).header(header::CONTENT_TYPE, "application/json").body(&body).send().await {
        Ok(response) => response,
        Err(error) => {
            println!("Error sending request: {}", error);
            panic!();
        }
    }
}

async fn main() {
    let client = create_http_client("https://example.com").await;
    let url = "https://example.com/endpoint";
    let body = "{\"key\": \"value\"}".to_string();

    let response = post_request(&client, url, body).await;

    if response.status().is_success() {
        println!("Request successful!");
    } else {
        println!("Request failed with status code: {}", response.status());
    }
}
