use std::time::{Duration, Instant};
use std::process::Command;
use synclazy::SyncLazy;
use process_control::{Process, ExitCode};
use env_logger::{Logger, LogBuilder};

struct CompileReport {
    compile_time: Duration,
    memory_usage_before: u64,
    memory_usage_after: u64,
    errors: Vec<String>,
}

impl CompileReport {
    fn new() -> Self {
        Self {
            compile_time: Duration::from_millis(0),
            memory_usage_before: 0,
            memory_usage_after: 0,
            errors: vec![]
        }
    }

    fn summarize(&self) -> String {
        format!("Compile Time: {:?}\nMemory Usage Before: {}\nMemory Usage After: {}\nErrors: {:?}", self.compile_time, self.memory_usage_before, self.memory_usage_after, self.errors)
    }
}

fn compile_rust() -> CompileReport {
    let mut log_builder = LogBuilder::new();
    let _logger = Logger::from_logger(log_builder.log_level(std::env!("LOG_LEVEL")));
    env_logger::init();

    let mut report = CompileReport::new();
    let start_time = Instant::now();

    // Measure time taken for the compilation
    report.compile_time = Duration::from_millis(start_time.elapsed().as_millis());

    // Capture resident set size of the process before and after compilation
    let memory_usage_before = get_resident_set_size();
    report.memory_usage_before = memory_usage_before;

    let output = Command::new("rustc")
        .arg("--verbose")
        .output()
        .expect("Failed to execute command");

    if !output.status().is_success() {
        // Catch errors that occur during compilation
        for line in String::from_utf8_lossy(&output.stdout).lines() {
            match rustc_driver::catch_with_exit_code(line) {
                Ok(error) => report.errors.push(format!("Error: {} (line {})"), error.line_number),
                Err(_) => continue,
            }
        }

        let memory_usage_after = get_resident_set_size();
        report.memory_usage_after = memory_usage_after;
    } else {
        // If compilation is successful, capture resident set size only once
        let memory_usage_after = get_resident_set_size();
        report.memory_usage_after = memory_usage_after;
    }

    report
}

fn main() {
    let report = compile_rust();
    println!("{}", report.summarize());
}
