using System;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Linq;

public class EmployeeRepository
{
    private readonly string _connectionString;
    private readonly int _pageSize = 10;

    public EmployeeRepository(string connectionString)
    {
        _connectionString = connectionString;
    }

    public List<Employee> GetEmployees(int supervisorId, string department = null, string jobTitle = null, int page = 1)
    {
        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            connection.Open();

            SqlCommand command = new SqlCommand("GetEmployees", connection);
            command.CommandType = System.Data.CommandType.StoredProcedure;

            command.Parameters.AddWithValue("@supervisorId", supervisorId);

            if (!string.IsNullOrEmpty(department))
            {
                command.Parameters.AddWithValue("@department", department);
            }

            if (!string.IsNullOrEmpty(jobTitle))
            {
                command.Parameters.AddWithValue("@jobTitle", jobTitle);
            }

            SqlDataReader reader = command.ExecuteReader();

            List<Employee> employees = new List<Employee>();

            while (reader.Read())
            {
                Employee employee = new Employee
                {
                    Name = reader["Name"].ToString(),
                    City = reader["City"].ToString(),
                    Address = reader["Address"].ToString()
                };
                employees.Add(employee);
            }

            reader.Close();

            int totalCount = GetTotalCount(connection, supervisorId, department, jobTitle);

            int startIndex = (page - 1) * _pageSize;

            List<Employee> paginatedEmployees = employees.Skip(startIndex).Take(_pageSize).ToList();

            return new PaginatedResult
            {
                Employees = paginatedEmployees,
                TotalCount = totalCount,
                PageSize = _pageSize,
                CurrentPage = page
            };
        }
    }

    private int GetTotalCount(SqlConnection connection, int supervisorId, string department, string jobTitle)
    {
        SqlCommand command = new SqlCommand("GetEmployeeCount", connection);
        command.CommandType = System.Data.CommandType.StoredProcedure;

        command.Parameters.AddWithValue("@supervisorId", supervisorId);

        if (!string.IsNullOrEmpty(department))
        {
            command.Parameters.AddWithValue("@department", department);
        }

        if (!string.IsNullOrEmpty(jobTitle))
        {
            command.Parameters.AddWithValue("@jobTitle", jobTitle);
        }

        int count = Convert.ToInt32(command.ExecuteScalar());
        return count;
    }
}

public class Employee
{
    public string Name { get; set; }
    public string City { get; set; }
    public string Address { get; set; }
}

public class PaginatedResult
{
    public List<Employee> Employees { get; set; }
    public int TotalCount { get; set; }
    public int PageSize { get; set; }
    public int CurrentPage { get; set; }
}
