function generateSecureRandomString($length, $charset, $password = null) {
    if (empty($charset)) {
        throw new InvalidArgumentException('Charset cannot be empty');
    }

    if (!isset($GLOBALS['hash_function'])) {
        $GLOBALS['hash_function'] = 'md5';
    }

    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= substr(str_shuffle($charset), 0, 1);
    }

    if (!empty($password)) {
        $hashedPassword = hash($GLOBALS['hash_function'], $password);
        return array('random_string' => $randomString, 'hashed_password' => $hashedPassword);
    } else {
        return $randomString;
    }
}

