            // Validate new password strength
            if (!isValidPasswordStrength($newPassword)) {
                throw new Exception('New password does not meet strength criteria');
            }

            // Update user's password in database
            $stmt = $this->db->prepare("UPDATE users SET password = :new_password WHERE id = :user_id AND password = :old_password");
            $stmt->bindParam(':user_id', $userId);
            $stmt->bindParam(':old_password', $oldPassword);
            $stmt->bindParam(':new_password', $newPassword);
            $stmt->execute();

            // Handle transient errors with retry logic
