#include <stdlib.h>

struct Node {
    int state;
    struct Node* next;
};

int* constructSubsequence(int* states, int numStates, struct Node* fsa, int start, int end, bool includeStart, int maxLen) {
    if (numStates < 1 || start < 0 || start >= numStates || end < 0 || end >= numStates || !includeStart && start == end) {
        return NULL;
    }

    int* subsequence = malloc((maxLen + 1) * sizeof(int));
    if (!subsequence) {
        return NULL;
    }

    int count = 0;
    struct Node* current = fsa;
    while (current != NULL && count < maxLen) {
        if (includeStart || current->state >= start && current->state <= end) {
            subsequence[count++] = current->state;
            if (count == maxLen) {
                break;
            }
        }
        current = current->next;
    }

    if (count > 0) {
        subsequence[count] = 0;
    } else {
        free(subsequence);
        return NULL;
    }

    int* nextState = malloc((count + 1) * sizeof(int));
    if (!nextState) {
        free(subsequence);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        nextState[i] = subsequence[i];
    }
    nextState[count] = 0;

    // Update the 'next' pointer of the last state in the subsequence
    if (count > 1) {
        int* lastState = &subsequence[count - 2];
        *lastState = count;
    }

    free(subsequence);
    return nextState;
}
