using System;

public class CustomRandomGenerator
{
    private double _min;
    private double _max;
    private int _precision;

    public CustomRandomGenerator(double min, double max, int precision)
    {
        _min = min;
        _max = max;
        _precision = precision;
    }

    public double GenerateFloat()
    {
        Random random = new Random();
        return (double)(random.NextDouble() * (_max - _min) + _min);
    }

    public int GenerateIntExclusive()
    {
        Random random = new Random();
        return random.Next((int)_min, (int)_max);
    }

    public int[] GenerateSequence(int count)
    {
        Random random = new Random();
        int[] sequence = new int[count];
        for (int i = 0; i < count; i++)
        {
            sequence[i] = random.Next((int)_min + 1, (int)_max);
        }
        return sequence;
    }

    public string GenerateStringRepresentation()
    {
        return $"Range: [{_min}, {_max}] Precision: {_precision}";
    }

    public void AdjustRange(double newMin, double newMax)
    {
        _min = newMin;
        _max = newMax;
    }

    public override string ToString()
    {
        return GenerateStringRepresentation();
    }
}
