const fetch = require('node-fetch');
const { PerformanceObserver } = require('perf_hooks');

function aggregateAsync(url, initialValue, callbackFunction, {
  maxRetries = 3,
  retryDelay = 1000,
} = {}) {
  let attempts = 0;
  let result = initialValue;

  const observer = new PerformanceObserver({
    observe: (type, entryList) => {
      if (type === 'promise') {
        entryList.forEach(entry => {
          console.log(`Promise: ${entry.duration}ms`);
        });
      }
    },
  });

  function fetchAndAggregate() {
    return fetch(url)
      .then(response => response.json())
      .then(data => {
        const numbers = data.map(Number);
        let accumulator = initialValue;
        for (let num of numbers) {
          accumulator = callbackFunction(accumulator, num);
        }
        result = accumulator;
      })
      .catch(error => {
        if (error.name === 'TimeoutError' || error.message.includes('Connection timed out')) {
          // Handle connection timeout
          attempts++;
          if (attempts <= maxRetries) {
            setTimeout(() => fetchAndAggregate(), retryDelay);
          } else {
            console.error(`Max retries reached for ${url}`);
          }
        } else if (error.name === 'FetchError') {
          // Handle network-related errors
          console.error(`Network error occurred while fetching ${url}: ${error.message}`);
        } else {
          // Handle data parsing issues
          console.error(`Error occurred while parsing data from ${url}: ${error}`);
        }
      });
  }

  return fetchAndAggregate();
}

const sampleUrl = 'https://example.com/api/data';
const callbackFunction = (acc, curr) => acc + curr;
const initialValue = 0;

aggregateAsync(sampleUrl, initialValue, callbackFunction)
  .then(() => console.log(`Aggregated result: ${result}`))
  .catch(error => console.error('Error:', error));
