char* append_slash(char* str, int size_limit, int strict_size_checking) {
    if (!str || !size_limit)
        return NULL;

    char* result = malloc(size_limit + 2);
    if (!result)
        return NULL;

    int chars_left = size_limit - 1;
    for (char* p = str; *p && --chars_left >= 0; ++p) {
        if (*p > 0x7F || (strict_size_checking && strlen(p) + 1 > size_limit)) {
            free(result);
            return NULL;
        }
        *(result++) = *p;
    }

    *result++ = '/';
    *result = '\0';

    return result;
}
