#include <string.h>
#include <math.h>

#define MAX_LINE_LENGTH 1024
#define MAX_INTEGER_COUNT 1000

typedef struct {
    int* integers;
    int count;
} IntegerArray;

IntegerArray readLine(FILE* file) {
    IntegerArray line;
    char buffer[MAX_LINE_LENGTH];
    fgets(buffer, MAX_LINE_LENGTH, file);
    size_t length = strlen(buffer);

    // Find the last integer in the line
    char* p = buffer + length - 1;
    int i = 0;
    while (i < MAX_INTEGER_COUNT && p > buffer) {
        if (*p == '\n' || *p == ' ') {
            *p = '\0';
            break;
        }
        p--;
        i++;
    }

    line.count = i + 1;

    // Dynamically allocate memory for integers
    line.integers = (int*)malloc((line.count) * sizeof(int));
    sscanf(buffer, "%d", &line.integers[0]);
    for (int j = 1; j < line.count; j++) {
        sscanf(buffer + length - i - 2 - j, "%d", &line.integers[j]);
    }

    return line;
}

void processLine(IntegerArray line) {
    int sum = 0;
    int max = line.integers[0];
    int min = line.integers[0];

    for (int i = 0; i < line.count; i++) {
        sum += line.integers[i];
        if (line.integers[i] > max) {
            max = line.integers[i];
        } else if (line.integers[i] < min) {
            min = line.integers[i];
        }
    }

    printf("%s", line.integers);
    if (line.count >= 3) {
        double average = (line.integers[line.count - 2] + line.integers[line.count - 1]) / 2.0;
        printf(", Sum: %d, Max: %d, Min: %d, Average: %.2f", sum, max, min, average);
    }
    printf("\n");
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (!file) {
        return 1;
    }

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        IntegerArray line = readLine(file);
        processLine(line);

        // Free dynamically allocated memory
        free(line.integers);
    }

    fclose(file);
    return 0;
}
