#include <stdio.h>
#include <string.h>
#include <ctype.h>

void modify_filename(const char *input, char *output) {
    int digit_count = 0;
    const char *p = input;

    // Count the number of digits in the original filename
    while (*p && isdigit(*p)) {
        p++;
        digit_count++;
    }

    // Extract the first letter of the filename
    const char *first_letter = p;
    if (*first_letter == '\0') {
        *output = '1';
        strcat(output, ".txt");
    } else {
        *output = tolower(*first_letter);
        if (isdigit(*p)) {
            sprintf(output + 2, "%d", digit_count);
        }
        switch (*first_letter) {
            case 'a':
                strcat(output, ".txt");
                break;
            case 'b':
                strcat(output, ".docx");
                break;
            default:
                strcat(output, ".txt");
        }
    }

    // Ensure the new filename does not exceed a maximum length of 256 characters
    char temp[257];
    sprintf(temp, "%s", output);
    if (strlen(temp) > 255) {
        for (int i = strlen(temp) - 1; i >= 0 && i < 255; i--) {
            temp[i] = '\0';
        }
        strcat(output, "...");
    }

    strcpy(output, temp);
}
