// Function to derive a secure key and IV from the password
int aes256_cbc_init(const char* password, unsigned char** out_key, unsigned char** out_iv) {
    // Initialize PBKDF2 with SHA-256 for key stretching
    const EVP_PBE_ALG ealgo = EVP_PBE_ALG_SHA256;
    const int itercount = 10000; // Adjust according to your security requirements

    // Derive the 256-bit key using PBKDF2 and SHA-256
    unsigned char* derived_key = NULL;
    if (!PBKDF2(password, strlen(password), NULL, 0, &derived_key, 32, itercount, ealgo)) {
        return -1; // Error in key derivation
    }

    // Derive the IV using PBKDF2 and SHA-256
    unsigned char* derived_iv = NULL;
    if (!PBKDF2(password, strlen(password), NULL, 0, &derived_iv, 16, itercount, ealgo)) {
        OPENSSL_free(derived_key); // Free the key memory
        return -1; // Error in IV derivation
    }

    *out_key = derived_key;
    *out_iv = derived_iv;

    return 1; // Key and IV derivation successful
}

// Cleanup function to disable the cipher context and release resources
void aes256_cbc_free(unsigned char* key, unsigned char* iv) {
    OPENSSL_free(key);
    OPENSSL_free(iv);
}
