int copy_mp3_to_ogg(const char *src_dir, const char *dest_dir) {
    int result = 0;
    DIR *dir = opendir(src_dir);
    if (dir == NULL) return 1;

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
        char src_file[1024], dest_file[1024];
        strcpy(src_file, src_dir);
        strcat(src_file, "/");
        strcat(src_file, ent->d_name);

        strcpy(dest_file, dest_dir);
        strcat(dest_file, "/");

        if (strcmp(ent->d_type, "directory") == 0) {
            mkdir(dest_file + strlen(dest_file), S_IRWXU | S_IRGRP | S_IROTH);
            copy_mp3_to_ogg(strcat(src_file, ent->d_name + 1), dest_file);
        } else if (strcmp strrchr(ent->d_name, '.') == ".mp3") {
            FILE *fp = fopen(src_file, "rb");
            if (fp == NULL) continue;

            char cmd[1024];
            sprintf(cmd, "ffmpeg -i \"%s\" -ar 44.1k -ac 2 -ab 128k \"%s\"", src_file, strcat(dest_file, strrchr(ent->d_name, '.') ? ent->d_name : ent->d_name + 1));
            system(cmd);
        }

        closedir(dir);
    }
    return result;
}
