#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>

#define MAX_BG_PROCESSES 10
#define LOG_FILE_SIZE_LIMIT 1024 * 1024 // 1MB

typedef struct {
    pid_t pid;
    char command[256];
} BackgroundProcess;

void log_to_file(char* message, int* file_size) {
    FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) return;
    fwrite(message, strlen(message), 1, log_file);
    fclose(log_file);
    (*file_size)++;
}

int run_command_in_background(char* command, char** envp, int max_env_vars, const char* var_to_set, const char* var_to_unset, size_t log_limit) {
    int i = 0;
    BackgroundProcess bg_processes[MAX_BG_PROCESSES];
    pid_t current_pid;

    // Check for exceeded maximum number of background processes
    for (i = 0; i < MAX_BG_PROCESSES; i++) {
        if (bg_processes[i].pid == 0) break;
    }

    if (i >= MAX_BG_PROCESSES) return 0; // failed to start new process

    // Set environment variables
    setenv(var_to_set, "new_value", 1);
    unsetenv(var_to_unset);

    current_pid = fork();
    if (current_pid < 0) {
        log_to_file("Forking failed\n", &log_limit);
        return 0;
    }

    if (current_pid > 0) { // parent process
        bg_processes[i].pid = current_pid;
        bg_processes[i].command = command;
        wait(NULL); // release resources for the new child process
        i++;
        return 1; // successfully started a new background process
    } else { // child process
        execve(command, NULL, envp);
        log_to_file("Failed to execute command\n", &log_limit);
        _exit(1);
    }
}
