    {
        var result = new SiteLaunchResult();

        if (!Directory.Exists(directoryPath))
        {
            return new SiteLaunchResult { IsSuccessful = false, ErrorMessage = "Directory not found." };
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return new SiteLaunchResult { IsSuccessful = false, ErrorMessage = "No web.config file found." };
        }

        try
        {
            var processStartInfo = new ProcessStartInfo
            {
                FileName = "your_web_server_executable.exe", // Replace with your actual executable name.
                WorkingDirectory = directoryPath,
                CreateNoWindow = true
            };

            using (var process = Process.Start(processStartInfo))
            {
                process.WaitForExit();

                if (process.ExitCode == 0)
                {
                    result.IsSuccessful = true;
                }
                else
                {
                    result.ErrorMessage = $"Web site launch failed with exit code {process.ExitCode}.";
                }
            }
        }
        catch (Exception ex)
        {
            result.IsSuccessful = false;
            result.ErrorMessage = $"Error launching web site: {ex.Message}";
        }

        return result;
    }
}
