import java.io.*;
import java.util.logging.*;

public class DirectoryManager {
    private final Logger logger = Logger.getLogger(DirectoryManager.class.getName());
    private final int MAX_RETRIES = 3;

    public void manageDirectory(String directoryPath, String[] commands) throws IOException {
        File directory = new File(directoryPath);
        if (!directory.exists()) {
            directory.mkdirs();
        }

        File logFile = new File("log.txt");
        FileOutputStream fileOutputStream = null;
        try (PrintStream printStream = new PrintStream(logFile)) {
            logger.addHandler(new ConsoleHandler(printStream));
            for (String command : commands) {
                deleteFilesInDirectory(directory);
                executeCommand(command, directory);
                verifyChecksum(directory);
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error writing to log file", e);
            throw new IOException("Failed to write to log file");
        } finally {
            if (fileOutputStream != null) {
                try {
                    fileOutputStream.close();
                } catch (IOException ignored) {}
            }
        }
    }

    private void deleteFilesInDirectory(File directory) throws IOException {
        for (File file : directory.listFiles()) {
            if (file.isDirectory()) {
                deleteFilesInDirectory(file);
            } else {
                file.delete();
                logger.log(Level.INFO, "Deleted file: " + file.getAbsolutePath());
            }
        }
    }

    private void executeCommand(String command, File directory) throws IOException {
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            logger.log(Level.INFO, "Command output: " + line);
        }
        int exitStatus = process.waitFor();
        if (exitStatus != 0) {
            for (int retry = 0; retry < MAX_RETRIES; retry++) {
                try {
                    process.destroy();
                    Thread.sleep(1000); // wait before retrying
                    process = Runtime.getRuntime().exec(command);
                    reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    while ((line = reader.readLine()) != null) {
                        logger.log(Level.INFO, "Command output: " + line);
                    }
                    exitStatus = process.waitFor();
                    if (exitStatus == 0) {
                        break;
                    }
                } catch (InterruptedException | IOException e) {
                    logger.log(Level.SEVERE, "Error executing command", e);
                    throw new IOException("Failed to execute command");
                }
            }
        }
    }

    private void verifyChecksum(File directory) throws IOException {
        // implement your checksum verification logic here
    }
}
