#include <json-c/json.h>
#include <string.h>

int is_valid_oauth_token(const char *token_string, int grace_period) {
    json_object *json = json_object_from_json_string(token_string);
    if (json == NULL) {
        return 0; // invalid JSON format
    }

    if (!json_object_object_test(json, "access_token") ||
        !json_object_object_test(json, "expires_in") ||
        !json_object_object_test(json, "token_type")) {
        json_object_put(json);
        return 0; // required fields missing
    }

    char *token_type = json_object_get_string_value(json, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(json);
        return 0; // token type is not 'Bearer'
    }

    int expires_in = json_object_get_int_value(json, "expires_in");
    if (expires_in <= 0 || (json_object_get_int_value(json, "expires_in") + grace_period < 1)) {
        json_object_put(json);
        return 0; // expires_in is not a positive integer
    }

    char *access_token = json_object_get_string_value(json, "access_token");
    if (access_token == NULL || strlen(access_token) <= 0 ||
        json_object_string_test(json, "access_token", '{"\0"}') < 0) {
        json_object_put(json);
        return 0; // access token is empty or contains reserved characters
    }

    json_object_put(json);
    return 1;
}
