    public DataTableReader ProcessCSVFile(string filePath, string connectionString)
    {
        DataTableReader result = null;
        using (SqlConnection conn = new SqlConnection(connectionString))
        {
            conn.Open();
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(conn))
            {
                bulkCopy.DestinationTableName = "dbo.YourTable";
                using (StreamReader reader = File.OpenText(filePath))
                {
                    string[] headers = reader.ReadLine().Split(',');
                    DataTable dt = new DataTable();
                    foreach (string header in headers)
                    {
                        dt.Columns.Add(header);
                    }
                    int i = 0;
                    string line;
                    while ((line = reader.ReadLine()) != null)
                    {
                        DataRow dr = dt.NewRow();
                        foreach (string column in headers)
                        {
                            dr[column] = line.Split(',')[i];
                            i++;
                        }
                        dt.Rows.Add(dr);
                    }
                    bulkCopy.WriteToServer(dt.CreateDataReader());
                }
            }
        }
        return new DataTableReader(dt);
    }
}
