public class CryptographyHelper
{
    public static List<CryptographyOperation> DecryptTripleDES(string base64EncodedMessage, string key, string iv)
    {
        TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider();
        tripleDes.Key = Convert.FromBase64String(key);
        tripleDes.IV = Convert.FromBase64String(iv);

        byte[] bytes = Convert.FromBase64String(base64EncodedMessage);
        using (MemoryStream ms = new MemoryStream(bytes))
        {
            using (CryptoStream cs = new CryptoStream(ms, tripleDes.CreateDecryptor()))
            {
                byte[] decryptedBytes = new byte[bytes.Length];
                cs.Read(decryptedBytes, 0, bytes.Length);

                return DecryptOperations();
            }
        }
    }

    public static List<CryptographyOperation> DecryptOperations()
    {
        List<CryptographyOperation> operations = new List<CryptographyOperation>();

        try
        {
            operations.Add(new CryptographyOperation("SHA256", SHA256.Create()));
            operations.Add(new CryptographyOperation("AES", Aes.Create()));
            operations.Add(new CryptographyOperation("TripleDES", TripleDESCryptoServiceProvider.Create()));
        }
        catch (CryptographicException)
        {
            // Handle unavailable functions
            Console.WriteLine("Error: Some cryptographic operations are not available.");
        }

        return operations;
    }
}

public class CryptographyOperation
{
    public string Name { get; set; }
    public ICryptoTransform CryptoTransform { get; set; }

    public CryptographyOperation(string name, ICryptoTransform cryptoTransform)
    {
        Name = name;
        CryptoTransform = cryptoTransform;
    }
