    public void ProcessLargeDataset(string[] dataset, string outputFilepath)
    {
        using (var md5 = MD5.Create())
        {
            using (var streamWriter = new FileStream(outputFilepath, FileMode.Create))
            {
                foreach (string str in dataset)
                {
                    byte[] hashBytes;
                    using (var streamReader = new MemoryStream())
                    {
                        using (var writer = new StreamWriter(streamReader))
                        {
                            writer.Write(str);
                        }
                        streamReader.Position = 0;
                        using (var md5Stream = md5.ComputeHash(streamReader))
                        {
                            hashBytes = md5Stream.ToArray();
                        }
                    }
                    streamWriter.Write(BitConverter.ToString(hashBytes).Replace("-", "").ToLower());
                }
            }
        }
    }
}
