import axios from 'axios';
import { logger } from './logger';

function uploadFile(url) {
  const startTime = new Date().getTime();
  const fileSizeRegex = /\((\d+)x(\d+)\)/;
  const fileMatch = url.match(fileSizeRegex);
  const fileSize = parseInt(fileMatch[1]) * parseInt(fileMatch[2]);

  if (fileSize > 100000000) {
    throw new Error('File size exceeds 100MB limit');
  }

  return axios.get(url, { responseType: 'arraybuffer' })
    .then(response => {
      const endTime = new Date().getTime();
      logger.info(`Upload start time: ${startTime} | End time: ${endTime}`);
      logger.info(`File size: ${fileSize} bytes`);
      logger.info(`Status code: ${response.status}`);

      return response.data;
    })
    .catch(error => {
      if (axios.isAxiosError(error)) {
        const { status, statusText } = error.response;

        logger.error(`Upload failed with status code ${status}: ${statusCodeMessage(status)}`);
      } else {
        logger.error('Unknown error occurred during upload');
      }

      return Promise.reject(error);
    });
}

function statusCodeMessage(statusCode) {
  switch (statusCode) {
    case 400:
      return 'Bad Request';
    case 401:
      return 'Unauthorized';
    case 403:
      return 'Forbidden';
    case 404:
      return 'Not Found';
    default:
      return 'Unknown Status Code';
  }
}
