function constructSubsequence(states, numStates, fsa, startState, endState, includeStart, maxLen) {
  let subseq = [];
  let stateCount = 0;
  let nextPtr = null;

  for (let i = startState; i <= endState && stateCount < maxLen; i++) {
    if (!fsa[i]) continue;
    let state = { id: i, next: fsa[i].next };
    subseq.push(state);
    stateCount++;
    nextPtr = i;
  }

  if (stateCount === 0) return null;

  for (let i = startState; i <= endState && stateCount < maxLen; i++) {
    if (!fsa[i]) continue;
    let state = { id: i, next: fsa[i].next };
    let found = false;
    for (let j = 0; j < subseq.length; j++) {
      if (subseq[j].id === i) {
        found = true;
        break;
      }
    }
    if (!found && stateCount < maxLen) subseq.push(state);
  }

  return { subseq, stateCount, nextPtr };
}

