  const shellCmd = 'curl https://api.example.com/random-data';
  const shellProcess = spawn(shellCmd, [], {
    detached: false,
    stdio: ['pipe', 'pipe', 'pipe']
  });

  // Pipe data from shell command to browser
  let outputData = '';
  shellProcess.stdout.on('data', (chunk) => {
    outputData += chunk.toString();
