  // Set random properties on vertices and edges using external data
  const jsonData = JSON.parse(outputData);
  for (const edge of edges) {
    const propValue = jsonData[Math.floor(Math.random() * jsonData.length)].value;
    edge.props['randomProperty'] = propValue;
  }
