use std::path::{Path, PathBuf};
use clap::{App, Arg};

struct LogProcessor {
    input_dir: String,
    output_file: String,
}

impl LogProcessor {
    async fn process_log_files(&self) -> Result<(), Box<dyn std::error::Error>> {
        let mut files = fs::read_dir(&Path::new(&self.input_dir))
            .await
            .map_err(|e| e.into())?
            .filter_map(|entry| entry.ok())
            .filter(|entry| entry.as_ref().and_then(|p| p.file_name()).is_some());

        let mut metrics = HashMap::new();

        while let Some(file) = files.next_file().await {
            if let Ok(file) = file {
                let file_path = file.path();
                if file_path.extension() == Some("log".to_string()) {
                    let log_content = fs::read_to_end(&file_path).await?;
                    // Extract specific metrics from the log content
                    let metric = extract_metric(log_content);
                    *metrics.entry(metric.clone()).or_insert(0) += 1;
                }
            } else {
                error!("Error reading file: {}", file.error());
            }
        }

        // Aggregate and write the report to the output file
        fs::write(&Path::new(&self.output_file), format!("{:?}", metrics)).await?;
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let matches = App::new("Log Processor")
        .version("1.0")
        .author("Your Name")
        .about("Process log files and generate a report")
        .arg(Arg::with_name("input_dir")
             .short("i")
             .long("input-directory")
             .takes_value(true)
             .required(true))
        .arg(Arg::with_name("output_file")
             .short("o")
             .long("output-file")
             .takes_value(true)
             .required(true))
        .get_matches();

    let input_dir = matches.value_of("input_dir").unwrap();
    let output_file = matches.value_of("output_file").unwrap();

    let log_processor = LogProcessor {
        input_dir: input_dir.to_string(),
        output_file: output_file.to_string(),
    };

    if let Err(e) = log_processor.process_log_files().await {
        error!("Error processing logs: {}", e);
    }
}
