use std::path::{Path, PathBuf};
use std::process::Command;
use log::{info, error, warn};

const APP_CONFIG_DIR_ENV_VAR: &str = "APP_CONFIG_DIR";
const DEFAULT_APP_CONFIG_DIR: &str = "/config";
const LOG_FILE: &str = "log.txt";

fn init_app_config_dir(dir_path: &Path) -> Result<(), std::io::Error> {
    if !dir_path.exists() {
        info!("Config directory does not exist, creating...");
        let template_path = Path::new("template");
        Command::new("cp")
            .arg("-r")
            .arg(template_path)
            .arg(dir_path)
            .status()
            .expect("Failed to create config directory")
    } else {
        info!("Config directory exists and is up-to-date");
    }
    Ok(())
}

fn set_app_config_dir_env_var(dir_path: &Path) -> Result<(), std::io::Error> {
    let env_var_val = dir_path.to_str().unwrap();
    if let Err(_) = Command::new("export")
        .arg(APP_CONFIG_DIR_ENV_VAR)
        .arg(env_var_val)
        .status() {
        warn!("Failed to set {} environment variable", APP_CONFIG_DIR_ENV_VAR);
    }
    Ok(())
}

fn list_files(dir_path: &Path, filter_ext: Option<&str>) -> Result<Vec<PathBuf>, std::io::Error> {
    let mut files = Vec::new();
    for entry in dir_path.read_dir()? {
        let entry = entry?;
        if let Some(ext) = entry.file_name().and_then(|n| n.to_str().rfind('.')) {
            let file_ext = &entry.file_name()[..ext];
            match filter_ext {
                Some(f) => {
                    if f == file_ext {
                        files.push(entry.path());
                    }
                }
                None => {
                    files.push(entry.path());
                }
            }
        }
    }
    Ok(files)
}

fn configure_app_config_dir(dir_path: &Path, template_path: &Path) -> Result<(), std::io::Error> {
    if let Err(e) = Command::new("mkdir")
        .arg("-p")
        .arg(dir_path)
        .status() {
        error!("Failed to create config directory: {}", e);
    }
    info!("Configuring config directory...");
    Command::new("cp")
        .arg("-r")
        .arg(template_path)
        .arg(dir_path)
        .status()
        .expect("Failed to configure config directory");
    Ok(())
}

fn handle_dir_creation_timeout(dir_path: &Path) -> Result<(), std::io::Error> {
    info!("Config directory creation timed out, falling back...");
    let backup_dir = Path::new("backup");
    Command::new("cp")
        .arg("-r")
        .arg(dir_path)
        .arg(backup_dir)
        .status()
        .expect("Failed to create backup of config directory");
    Ok(())
}

fn main() -> Result<(), std::io::Error> {
    let dir_path = Path::new(DEFAULT_APP_CONFIG_DIR);
    let template_path = Path::new("template");

    match init_app_config_dir(dir_path.clone()) {
        Ok(_) => {}
        Err(e) => error!("Failed to initialize config directory: {}", e),
    }

    if !dir_path.exists() {
        info!("Config directory does not exist, creating...");
        match configure_app_config_dir(dir_path.clone(), template_path) {
            Ok(_) => {
                info!("Config directory created and configured");
            }
            Err(e) => error!("Failed to create/configure config directory: {}", e),
        }
    } else {
        info!("Config directory exists and is up-to-date");
    }

    match set_app_config_dir_env_var(dir_path.clone()) {
        Ok(_) => {}
        Err(e) => warn!("Failed to set {} environment variable", APP_CONFIG_DIR_ENV_VAR),
    }

    let mut files = list_files(dir_path, Some("conf"))?;
    info!("Listing config files: {:?}", files);

    // Implement directory creation timeout and fallback mechanism
    if let Err(e) = Command::new("timeout")
        .arg("-1m") // 1 minute timeout
        .arg("mkdir")
        .arg("-p")
        .arg(dir_path)
        .status() {
        error!("Config directory creation timed out: {}", e);
        handle_dir_creation_timeout(dir_path)?;
    }

    Ok(())
}
