EVP_CIPHER_CTX* validate_oauth_token_and_encrypt(const char* json_string) {
    EVP_CIPHER_CTX* cipher_ctx = NULL;
    int mode = 0;
    const char* token_type = NULL;

    // Parse JSON string
    json_object* json_obj = json_object_from_string(json_string);
    if (!json_obj) return false;

    // Verify required fields
    if (!json_object_object_get_ex(json_obj, "access_token", &json_object)) {
        ERR_error(ERR_INVALID_TOKEN);
        return false;
    }
    if (!json_object_object_get_ex(json_obj, "expires_in", &json_object)) {
        ERR_error(ERR_INVALID_TOKEN);
        return false;
    }
    if (!json_object_object_get_ex(json_obj, "token_type", &json_object)) {
        ERR_error(ERR_INVALID_TOKEN);
        return false;
    }
    token_type = json_object_string_value(json_obj->string);

    // Validate token type
    if (strcmp(token_type, "Bearer") != 0) {
        ERR_error(ERR_INVALID_TOKEN_TYPE);
        return false;
    }

    int expires_in = json_object_get_int(json_obj, "expires_in");
    if (expires_in <= 0) {
        ERR_error(ERR_EXPIRES_IN_INVALID);
        return false;
    }

    // Parse optional fields
    char* refresh_token = json_object_string_value(json_object_object_get(json_obj, "refresh_token"));

    // Handle edge cases
    if (!json_string && !mode) {
        mode = DES_ECB; // Default to ECB mode for null encryption
    } else if (strcmp(token_type, "Bearer") != 0) {
        ERR_error(ERR_INVALID_TOKEN_TYPE);
        return false;
    }

    // Perform cryptographic operations
    cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        ERR_error(ERR_GENERAL_ERROR);
        return NULL;
    }
    switch (mode) {
        case DES_ECB:
            EVP_CipherInit_ex(cipher_ctx, EVP_des_ecb(), NULL, NULL, 0);
            break;
        case DES_EDE:
            EVP_CipherInit_ex(cipher_ctx, EVP_des_ede(), NULL, NULL, 0);
            break;
        case DES_EDE3:
            EVP_CipherInit_ex(cipher_ctx, EVP_des_ede3(), NULL, NULL, 0);
            break;
        case DES_CFB:
            EVP_CipherInit_ex(cipher_ctx, EVP_des_cfb(), NULL, NULL, 0);
            break;
    }

    // Verify cryptographic operations
    if (!EVP_CIPHER_CTX_set_key_length(cipher_ctx, 8)) {
        ERR_error(ERR_GENERAL_ERROR);
        return NULL;
    }
    int ret = EVP_CipherInit_ex(cipher_ctx, NULL, NULL, NULL, 1);
    if (ret <= 0) {
        ERR_error(ERR_GENERAL_ERROR);
        return NULL;
    }

    // Return cryptographic context
    return cipher_ctx;
}
