import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import org.json.*;

public class TokenVerifier {
    private static final String ALGORITHM = "DES";
    private static final String MODES[] = {"ECB", "EDE", "EDE3", "CFB"};
    private static final String HASH_ALGORITHM = "MD5";

    public static String verifyToken(String token) throws Exception {
        if (token == null || !isJson(token)) return false;

        try (BufferedReader reader = new BufferedReader(new StringReader(token))) {
            int lineCount = 0;
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                lineCount++;
                if (!line.trim().isEmpty()) {
                    sb.append(line).append("\n");
                }
            }

            JSONObject obj = new JSONObject(sb.toString());
            String accessToken = obj.getString("access_token");
            long expiresIn = obj.getLong("expires_in");
            String tokenType = obj.getString("token_type");

            if (accessToken == null || expiresIn < 0 || !tokenType.equals("Bearer")) {
                return false;
            }

            boolean isEncrypted = isJsonCompact(token);
            if (isEncrypted) {
                for (String mode : MODES) {
                    try {
                        String encrypted = encrypt(accessToken, mode);
                        if (encrypted != null) {
                            return encrypted;
                        }
                    } catch (Exception e) {
                        // Log error and continue with next mode
                    }
                }
            }

            return hash(accessToken).toString();
        } catch (JSONException | IOException e) {
            return false;
        }
    }

    private static boolean isJson(String str) {
        try {
            new JSONObject(str);
            return true;
        } catch (JSONException e) {
            return false;
        }
    }

    private static boolean isJsonCompact(String str) {
        try {
            StringReader reader = new StringReader(str);
            BufferedReader bufferedReader = new BufferedReader(reader);
            int lineCount = 0;
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = bufferedReader.readLine()) != null) {
                lineCount++;
                if (!line.trim().isEmpty() && !line.startsWith("{")) {
                    return false;
                }
                if (lineCount > 1) {
                    return true;
                }
            }
            return false;
        } catch (IOException e) {
            return false;
        }
    }

    private static String encrypt(String data, String mode) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM + "/" + mode);
        SecretKeySpec keySpec = new SecretKeySpec(new byte[8], ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);

        byte[] encrypted = cipher.doFinal(data.getBytes());
        return Base64.getEncoder().encodeToString(encrypted);
    }

    private static MessageDigest hash(String data) throws NoSuchAlgorithmException {
        return MessageDigest.getInstance(HASH_ALGORITHM);
    }
}
