import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from time import sleep, time
import re
import os
import shutil

def modify_filename(filename):
    num_digits = len(re.findall('\d', filename))
    file_type = '.' + filename.split('.')[-1]

    new_filename = f"{filename[:-len(file_type)-num_digits]}_{num_digits:0{num_digits}}{file_type}"

    return new_filename


class DFSMD5:
    def __init__(self):
        self.hash_state = {}
        self.errored_files = []

    def dfs_md5(self, root_dir):
        with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
            futures = {executor.submit(self.md5_file, file): file for file in os.listdir(root_dir)}

            for future in as_completed(futures):
                file = futures[future]
                try:
                    future.result()
                except Exception as e:
                    self.errored_files.append((file, str(e)))

    def md5_file(self, filename):
        root_dir = 'root_directory'  # replace with your DFS directory
        file_path = os.path.join(root_dir, filename)

        if not os.path.isfile(file_path):
            for dirpath, dirs, files in os.walk(root_dir):
                if filename in files:
                    file_path = os.path.join(dirpath, filename)
                    break
            else:
                return

        try:
            response = requests.get(f"{url}/files/{file_path}", headers={'Authorization': 'Bearer your_api_key'}, stream=True)

            md5_hash = hashlib.md5()
            for chunk in response.iter_content(chunk_size=8192):
                md5_hash.update(chunk)

            self.hash_state[filename] = md5_hash.hexdigest()
        except requests.exceptions.RequestException as e:
            self.errored_files.append((file_path, str(e)))

    def get_md5_hashes(self):
        return list(self.hash_state.items())

    def update_progress(self, current_time, total_time, num_files):
        if not num_files:
            print(f"Hashing complete in {total_time} seconds.")
        else:
            estimated_time = (total_time - (time() - current_time)) / num_files
            print(f"Progress: {(num_files - len(self.hash_state)) / num_files * 100:.2f}% ({estimated_time:.2f}s remaining)")


def main():
    dfs_md5 = DFSMD5()

    start_time = time()
    dfs_md5.dfs_md5('root_directory')

    end_time = time()

    print("Hashing complete in", end_time - start_time, "seconds.")

    for file, error in dfs_md5.errored_files:
        print(f"Error hashing {file}: {error}")


if __name__ == "__main__":
    main()

```

