    Status status;
    char *payload;
} Message;

typedef struct {
    Message *message;
    int priority;
} Notification;

void generateLogEntries(int count, Notification **notifications) {
    for (int i = 0; i < count; i++) {
        Message *message = (Message *)malloc(sizeof(Message));
        message->timestamp = rand() % 100000;
        message->status = (Status)((rand() % 3));
        int payloadSize = rand() % 1024 + 1;
        char *payload = (char *)malloc(payloadSize);
        for (int j = 0; j < payloadSize; j++) {
            payload[j] = 'a' + rand() % 26;
        }
        payload[payloadSize - 1] = '\0';
        message->payload = payload;

        notifications[i] = (Notification *)malloc(sizeof(Notification));
        notifications[i]->message = message;
        notifications[i]->priority = rand() % 100;
    }
}

void freeNotifications(Notification **notifications, int count) {
    for (int i = 0; i < count; i++) {
        if (notifications[i]) {
            Message *message = notifications[i]->message;
            if (message->payload) {
                free(message->payload);
            }
            free(message);
            free(notifications[i]);
        }
    }
}

