typedef struct {
    int transaction_id;
    double value;
} Transaction;

void filter_transactions(Transaction* transactions, size_t num_transactions) {
    // Initialize internal metrics
    size_t total_processed_transactions = 0;
    double average_transaction_value = 0.0;
    double max_weighted_sum_per_second = 0.0;

    // Calculate weighted sum of each transaction using a custom algorithm
    for (size_t i = 0; i < num_transactions; i++) {
        Transaction* transaction = &transactions[i];
        double weight = exp(-i / 300.0); // dynamic weight adjustment based on transaction frequency and time decay
        double weighted_sum = weight * transaction->value;
        average_transaction_value += transaction->value;
        if (weighted_sum > max_weighted_sum_per_second) {
            max_weighted_sum_per_second = weighted_sum;
        }
    }

    // Update internal metrics
    total_processed_transactions = num_transactions;
    average_transaction_value /= num_transactions;

    // Return maximum weighted sum observed within the last second, the corresponding transaction ID, and the total number of valid transactions processed in the last 5 minutes
    return max_weighted_sum_per_second, max_weighted_sum_per_second > 0 ? &transactions[num_transactions - 1] : NULL, total_processed_transactions;
}

int main() {
    // Initialize transaction data structure
    Transaction* transactions = (Transaction*)malloc(10000 * sizeof(Transaction));
    for (size_t i = 0; i < 10000; i++) {
