from concurrent.futures import ThreadPoolExecutor
from threading import Lock

def modify_filename(filename):
    lock = Lock()
    with lock:
        filename, extension = filename.rsplit('.', 1)
        return f"{filename}{str(int(time.time()))[:6]}.{extension}"

def calculate_md5_hash(directory, base_url, username, password, progress_indicator=None):
    md5_hash = hashlib.md5()
    file_list = []

    def fetch_file(file_info):
        try:
            response = requests.get(f"{base_url}/{file_info['path']}", auth=(username, password), stream=True)
            if response.status_code == 200:
                md5_hash.update(response.content)
                file_list.append((file_info['name'], response.status_code))
        except requests.exceptions.RequestException as e:
            print(f"Error fetching file {file_info['name']}: {e}")

    def recursive_traversal(directory):
        with ThreadPoolExecutor() as executor:
            for item in directory:
                if item['type'] == 'directory':
                    executor.submit(recursive_traversal, item['children'])
                elif item['type'] == 'file':
                    executor.submit(fetch_file, item)

    recursive_traversal(directory)

    while True:
        time.sleep(10)
        print(f"Progress: {len(file_list)}/{sum(1 for _ in directory if _.get('type') == 'file')}")
        if progress_indicator and progress_indicator.update(len(file_list)):
            break

    return [(name, md5.hexdigest()) for name, status in file_list]
