                    metadata_dict = {
                        'user_id': int(fields[0]),
                        'timestamp': int(fields[1]),
                        'event_type': fields[2]
                    }
                    if regex_pattern and not re.match(regex_pattern, metadata_dict['event_type']):
                        continue  # skip line if regex pattern doesn't match
                    metadata.append(metadata_dict)
                except ValueError:
