typedef struct iohandle_list {
    IOHANDLER* handler;
    struct iohandle_list* next;
} IOHANDLELIST;

IOHANDLELIST* discover_io_handlers();
void* alloc_handler(struct iohandle_list**, const char*);
void free_handler(IOHANDLELIST**);
void log_operation(const char*, int);

int main() {
    IOHANDLELIST* handlers = discover_io_handlers();
    // Process the list of I/O handlers
    return 0;
}

IOHANDLELIST* discover_io_handlers() {
    IOHANDLELIST* head = NULL;
    IOHANDLELIST* tail = NULL;

    for (int i = 0; i < NUM_HANDLERS; i++) {
        IOHANDLER* handler = alloc_handler(&head, "Handler name");
        if (!handler) {
            log_operation("Error allocating handler", 1);
            continue;
        }
        // Initialize the handler configuration
        handler->config = // Initialize config here
        tail->next = &IOHANDLELIST{ .handler = handler };
        tail = tail->next;
    }

    return head;
}

void* alloc_handler(struct iohandle_list** list, const char* name) {
    IOHANDLER* handler = malloc(sizeof(IOHANDLER));
    if (!handler) {
        log_operation("Error allocating memory", 1);
        return NULL;
    }
    handler->name = strdup(name);
    if (!handler->name) {
        free(handler);
        log_operation("Error allocating name", 1);
        return NULL;
    }
    // Initialize the I/O operation function
    handler->operation = // Initialize operation here

    (*list)->next = &IOHANDLELIST{ .handler = handler };
    (*list) = (*list)->next;
    return handler;
}

void free_handler(IOHANDLELIST** list) {
    IOHANDLELIST* current = *list;
    IOHANDLELIST* next;

    while (current != NULL) {
        IOHANDLER* handler = current->handler;
        // Free the handler configuration
        free(handler->config);
        free(handler->name);
        free(current);
        current = next;
    }
    *list = NULL;
}

void log_operation(const char* message, int level) {
    // Log operation to a file or console here
}
