#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

void process_log_file(char *input_file_path, char *pattern, char *file1, char *file2, char *file3) {
    FILE *log_file = fopen(input_file_path, "r");
    if (!log_file) {
        perror("Error opening input file");
        return;
    }

    // Initialize variables
    int segment_count = 0;
    int bytes_read = 0;

    // Determine the buffer size based on the log file size
    fseek(log_file, 0L, SEEK_END);
    long log_file_size = ftell(log_file);
    rewind(log_file);

    const int BUFFER_SIZE = (log_file_size > 1024 * 1024) ? 1024 * 1024 : (log_file_size > 256 * 1024) ? 256 * 1024 : 64 * 1024;
    char *buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        perror("Error allocating memory");
        fclose(log_file);
        return;
    }

    // Read the log file in chunks and process each segment
    while (1) {
        size_t bytes_to_read = fread(buffer, 1, BUFFER_SIZE, log_file);

        // Process the current segment
        char *segment_start = buffer;
        char *segment_end = buffer + bytes_to_read;

        while (segment_start < segment_end) {
            if (strstr(segment_start, pattern)) {
                // Extract the relevant segment and write it to a file
                size_t segment_len = segment_end - segment_start;
                FILE *file = (segment_count % 3 == 0) ? fopen(file1, "a") : ((segment_count % 3 == 1) ? fopen(file2, "a") : fopen(file3, "a"));
                if (!file) {
                    perror("Error opening output file");
                    fclose(log_file);
                    free(buffer);
                    return;
                }
                fwrite(segment_start, 1, segment_len, file);
                fclose(file);

                // Update statistics
                segment_count++;
                bytes_read += segment_len;
            }

            segment_start = segment_end + 1;
        }
    }

    // Clean up and report the final statistics
    free(buffer);
    fclose(log_file);
    printf("Segments processed: %d\n", segment_count);
    printf("Bytes read: %zu\n", bytes_read);
}
