semaphore_t* create_semaphore_pool(int num_semaphores, int min_value, int max_value) {
    semaphore_t* pool = (semaphore_t*)malloc_unlocked(sizeof(semaphore_t) * num_semaphores);
    for (int i = 0; i < num_semaphores; i++) {
        sem_init(&pool[i].sem, 1, rand() % (max_value - min_value + 1) + min_value);
        pool[i].value = pool[i].sem->val;
    }
    return pool;
}

void delete_semaphore_pool(semaphore_t* pool, int num_semaphores) {
    for (int i = 0; i < num_semaphores; i++) {
