Session* filter_sessions(Session* sessions, int session_count, SMSNode* sms, int target_user_id, time_t start_timestamp, time_t end_timestamp) {
    Session* filtered_sessions = NULL; // Initialize the filtered session list
    int filtered_session_count = 0;     // Count of included sessions in the filtered list

    SMSNode* current_sms_node = sms;      // Initialize the SMS node pointer
    while (current_sms_node != NULL) {   // Iterate over the SMS linked list
        Session* current_session = &sessions[current_sms_node->sid - 1]; // Get the corresponding session from the array
        if (current_session->user_id == target_user_id && current_session->start_time >= start_timestamp && current_session->end_time <= end_timestamp) {
            Session* new_session = (Session*)malloc(sizeof(Session)); // Allocate memory for a new session
            *new_session = *current_session;                           // Copy the session details
            if (filtered_sessions == NULL) {
                filtered_sessions = new_session;
            } else {
                Session* current_filtered_session = filtered_sessions;
                while (current_filtered_session->next != NULL) {
                    current_filtered_session = current_filtered_session->next;
                }
                current_filtered_session->next = new_session; // Add the new session to the end of the list
            }
            filtered_session_count++;
        }
        current_sms_node = current_sms_node->next;       // Move to the next SMS node
    }

    if (filtered_sessions == NULL) {
        free(filtered_sessions);
        return NULL;
    } else {
        Session* current_filtered_session = filtered_sessions;
        while (current_filtered_session != NULL) {   // Update the last modified timestamp for each session in the list
            time_t current_time = time(NULL);         // Get the current time
            current_filtered_session->last_modified = current_time;    // Update the last modified timestamp
            current_filtered_session = current_filtered_session->next;
        }
        return filtered_sessions;
    }
}
