    public static class SemaphorePool {
        private final int initialSemaphoreCount;
        private final AtomicInteger semaphoreCount = new AtomicInteger(0);
        private final Lock lock = new ReentrantLock();

        public SemaphorePool(int initialSemaphoreCount) {
            this.initialSemaphoreCount = initialSemaphoreCount;
        }

        public void allocateSemaphores(int count) throws InterruptedException {
            for (int i = 0; i < count; i++) {
                lock.lock();
                try {
                    if (!allocateOne()) {
                        throw new InterruptedException("Semaphore exhausted");
                    }
                } finally {
                    lock.unlock();
                }
            }
        }

        private boolean allocateOne() {
            return semaphoreCount.incrementAndGet() <= initialSemaphoreCount;
        }

        public void deallocateSemaphores(int count) {
            for (int i = 0; i < count; i++) {
                lock.lock();
                try {
                    if (!deallocateOne()) {
                        throw new RuntimeException("Semaphore exhausted");
                    }
                } finally {
                    lock.unlock();
                }
            }
        }

        private boolean deallocateOne() {
            return semaphoreCount.decrementAndGet() >= 0;
        }
    }

