using namespace std;
using namespace nlohjson;

const int MAX_LOG_LINE = 1024; // Maximum size of a log line

// Event structure to store event information
struct Event {
    string timestamp;
    string userId;
    string eventType;
};

// Function to parse JSON object and extract relevant fields
Event parseJSON(const string& jsonLine) {
    Event event;

    try {
        nlohjson::object obj = nlohjson::parse(jsonLine).get_obj();
        event.timestamp = obj["timestamp"].get_string();
        event.userId = obj["userId"].get_string();
        event.eventType = obj["eventType"].get_string();
    } catch (const runtime_error& e) {
        // Handle JSON parsing errors
        cerr << "Error parsing JSON: " << e.what() << endl;
        return Event(); // Return a default constructed Event object
    }

    return event;
}

// Function to calculate average time between consecutive events for each user
double calculateAverageTime(const map<string, vector<Event>>& userEvents) {
    double totalDuration = 0.0; // Initialize the total duration

    for (const auto& pair : userEvents) {
        const string& userId = pair.first;
        const vector<Event>& events = pair.second;

        if (events.size() < 2) continue; // Skip users with less than two events

        sort(events.begin(), events.end()); // Sort the events by timestamp

        for (size_t i = 1; i < events.size(); ++i) {
            Event currentEvent = events[i];
            Event previousEvent = events[i - 1];

            // Calculate the time difference between consecutive events
            double timeDiff = stod(currentEvent.timestamp) - stod(previousEvent.timestamp);

            totalDuration += timeDiff;
        }
    }

    return totalDuration / (double)userEvents.size();
}

// Function to generate a summary report for each hour, including the total number of events, 
// the most frequent event type, and the average time between events
void generateSummaryReport(const map<string, vector<Event>>& userEvents, const string& hour) {
    double averageTime = calculateAverageTime(userEvents);

    cout << "Hour: " << hour << endl;
    cout << "Total Events: " << userEvents.size() << endl;

    // Find the most frequent event type for each hour
    map<string, int> eventTypeCounts;
    for (const auto& pair : userEvents) {
        const string& userId = pair.first;
        const vector<Event>& events = pair.second;

        for (const Event& event : events) {
            if (eventTypeCounts.find(event.eventType) == eventTypeCounts.end()) {
                eventTypeCounts[eventType] = 1; // Initialize the count
            } else {
                ++eventTypeCounts[eventType];
            }
        }

        // Find the most frequent event type
        string mostFrequentEventType;
        int maxCount = 0;

        for (const auto& pair : eventTypeCounts) {
            if (pair.second > maxCount) {
                mostFrequentEventType = pair.first;
                maxCount = pair.second;
            }
        }

        cout << "Most Frequent Event Type: " << mostFrequentEventType << endl;
        cout << "Average Time Between Events: " << averageTime << endl;
    }
}

int main() {
    ifstream logFile("log.txt"); // Open the log file

    if (!logFile) {
        cerr << "Error opening log file." << endl;
        return 1; // Return an error code
    }

    string line;
    map<string, vector<Event>> userEvents;

    while (getline(logFile, line)) {
        Event event = parseJSON(line);

        if (!event.timestamp.empty()) {
            string hour = event.timestamp.substr(0, 8); // Extract the hour from the timestamp

            // Process events by hour
            if (userEvents.find(hour) == userEvents.end()) {
                userEvents[hour] = vector<Event>(); // Initialize a new map entry for this hour
            }

            userEvents[hour].push_back(event);
        }
    }

    logFile.close(); // Close the log file

    for (const auto& pair : userEvents) {
        generateSummaryReport(pair.second, pair.first); // Generate the summary report
    }

    return 0;
}
