#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

class NetworkDataProcessor {
private:
    std::vector<double> dataset;
    int samplingInterval = 1;
    char aggregationMethod = 'a'; // a: average, s: sum, m: max

public:
    void setDataset(const std::vector<double>& data) { dataset = data; }
    void setSamplingInterval(int interval) { samplingInterval = interval; }
    void setAggregationMethod(char method) {
        if (method == 'a' || method == 's' || method == 'm')
            aggregationMethod = method;
        else
            std::cerr << "Invalid aggregation method. Defaulting to average." << std::endl;
    }

    // 1. Generate a sample of data points from the dataset based on the specified sampling interval.
    std::vector<double> generateSample() {
        std::vector<double> sample;
        for (int i = 0; i < dataset.size(); i += samplingInterval) {
            if (i + samplingInterval > dataset.size())
                break;
            double sum = 0.0;
            int count = 0;
            for (int j = i; j < i + samplingInterval; ++j) {
                sum += dataset[j];
                ++count;
            }
            switch (aggregationMethod) {
            case 'a':
                sample.push_back(sum / count);
                break;
            case 's':
                sample.push_back(sum);
                break;
            case 'm':
                sample.push_back(dataset[i]);
                break;
            default:
                sample.push_back(sum / count); // default to average
            }
        }
        return sample;
    }

    // 2. Aggregate the entire dataset using the selected aggregation method.
    double aggregate() {
        double sum = std::accumulate(dataset.begin(), dataset.end(), 0.0);
        switch (aggregationMethod) {
        case 'a':
            return sum / dataset.size();
        case 's':
            return sum;
        case 'm':
            return *std::max_element(dataset.begin(), dataset.end());
        default:
            return sum / dataset.size(); // default to average
        }
    }

    // 3. Calculate rolling statistics (e.g., moving average) over a specified window size.
    std::vector<double> calculateRollingStatistics(int windowSize) {
        std::vector<double> rollingStats;
        for (int i = 0; i <= dataset.size() - windowSize; ++i) {
            double sum = 0.0;
            for (int j = i; j < i + windowSize; ++j)
                sum += dataset[j];
            switch (aggregationMethod) {
            case 'a':
                rollingStats.push_back(sum / windowSize);
                break;
            case 's':
                rollingStats.push_back(sum);
                break;
            case 'm':
                rollingStats.push_back(dataset[i]);
                break;
            default:
                rollingStats.push_back(sum / windowSize); // default to average
            }
        }
        return rollingStats;
    }

    // 4. Provide a detailed summary of the dataset, including statistical measures like mean, median, and standard deviation.
    void summarizeDataset() {
        double sum = std::accumulate(dataset.begin(), dataset.end(), 0.0);
        double mean = sum / dataset.size();
        double median = *std::median(&dataset[0], &dataset[0] + dataset.size());
        double stdev = std::sqrt(std::inner_product(dataset.begin(), dataset.end(),
                                                     dataset.begin(), 0.0) /
                                 (dataset.size() - 1));
        std::cout << "Dataset Summary:" << std::endl;
        std::cout << "Mean: " << mean << std::endl;
        std::cout << "Median: " << median << std::endl;
        std::cout << "Standard Deviation: " << stdev << std::endl;
    }

    // Override toString method to display the dataset summary and processing parameters.
    std::string toString() {
        return "Dataset Summary:\nMean: " + std::to_string(aggregate()) +
               "\nMedian: " + std::to_string(median(dataset)) +
               "\nStandard Deviation: " + std::to_string(stddev(dataset)) +
               "\nSampling Interval: " + std::to_string(samplingInterval) +
               "\nAggregation Method: " + (aggregationMethod == 'a' ? "Average" :
                                            aggregationMethod == 's' ? "Sum" : "Max");
    }
};
