#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <arpa/inet.h>

#define MAX_SOURCE_DIR_LENGTH 256
#define MAX_DESTINATION_DIR_LENGTH 256
#define MAX_MP3_FILE_NAME_LENGTH 128
#define MAX_OGG_FILE_NAME_LENGTH 128

typedef unsigned char u_char;

int copyAndConvertMP3(char* sourceDir, char* destinationDir) {
    // Initialize return code to 0 (success)
    int ret = 0;

    DIR* dir = opendir(sourceDir);
    if (dir == NULL) {
        // Unable to open directory
        return 1;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char mp3FileName[MAX_MP3_FILE_NAME_LENGTH];
        strcpy(mp3FileName, sourceDir);
        strcat(mp3FileName, "/");
        strcat(mp3FileName, ent->d_name);

        if (ent->d_type == DT_REG) {
            // Check if the file is an MP3
            if (strstr(ent->d_name, ".mp3") != NULL) {
                char oggFileName[MAX_OGG_FILE_NAME_LENGTH];
                strcpy(oggFileName, destinationDir);
                strcat(oggFileName, "/");
                strcat(oggFileName, ent->d_name);
                strcat(oggFileName, ".ogg");

                // Convert MP3 to OGG
                system((sprintf("ffmpeg -i %s -c:a libvorbis -b:a 128k %s", mp3FileName, oggFileName), NULL));
            }
        }
    }

    closedir(dir);

    return ret;
}

int resolveHostname(char* hostname) {
    // Initialize return code to 0 (success)
    int ret = 0;

    struct addrinfo hints, *result;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        // Unable to resolve hostname
        return 1;
    }

    u_char ip[16];
    inet_pton(AF_INET, ((struct sockaddr_in*)result->ai_addr)->sin_addr.s_addr, ip);

    freeaddrinfo(result);

    return ret;
}
