using namespace std;

struct LogEntry {
    time_t timestamp;
    string operation;
    int uniqueStringsProcessed;
    double averageInsertionTime;
};

void insertAfterInForwardList(
        forward_list<string>& list,
        const string& targetString,
        const string& newString) {

    if (targetString.empty() || newString.empty())
        throw runtime_error("Input strings cannot be empty");

    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == targetString) {
            list.insert_after(it, newString);
            return;
        }
    }

    // If not found, append to the end of the list
    list.append(newString);

}

void logProcessingTime(const LogEntry& entry, ofstream& logFile) {
    logFile << entry.timestamp << ","
           << entry.operation << ","
           << entry.uniqueStringsProcessed << ","
           << entry.averageInsertionTime << endl;
}

int main() {
    // Example usage:
    forward_list<string> list = {"apple", "banana", "cherry"};
    string targetString = "banana";
    string newString = "date";

    auto start = chrono::high_resolution_clock::now();
    insertAfterInForwardList(list, targetString, newString);
    auto end = chrono::high_resolution_clock::now();

    LogEntry logEntry;
    logEntry.timestamp = chrono::duration_cast<chrono::seconds>(end - start).count();
    logEntry.operation = "INSERT";
    logEntry.uniqueStringsProcessed = list.size();
    logEntry.averageInsertionTime = 0.5; // Example value

    ofstream logFile("processing_log.csv");
    logProcessingTime(logEntry, logFile);

    return 0;
}
