                        int to = new Random().nextInt(numVertices);
                        session.run("MATCH (a:Person), (b:Person) WHERE ID(a) = $from AND ID(b) = $to CREATE (a)-[:FRIEND]->(b)", mapOf("from", from, "to", to));
                    }
                    // Add a random number of vertices and edges
