public class MetadataLoader
{
    private readonly object _lock = new object();
    private readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>(new ConcurrentBagComparer<string>());
    private readonly ILogger _logger = null;

    public MetadataLoader(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<Metadata> LoadMetadataAsync(string filePath, string schema)
    {
        try
        {
            using (var stream = File.OpenRead(filePath))
            {
                var metadata = new Metadata();
                await DeserializeAsync(stream, metadata);
                if (!ValidateSchema(metadata, schema))
                {
                    throw new Exception($"Invalid metadata schema: {schema}");
                }
                return metadata;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex.Message);
            throw;
