import hashlib
import mmap
import multiprocessing
from typing import Tuple

def octree_data_structure_init(feature_size: int, num_leaf_nodes: int, data_capacity: int, file_path: str, max_memory_usage_threshold: int) -> Tuple[str, int, bool, dict]:
    try:
        with open(file_path, 'r') as f:
            mm = mmap.mmap(f.fileno(), 0)
            md5_hash = hashlib.md5()
            chunk_checksums = {}
            last_sequence_number = None
            integrity_passed = True

            def process_chunk(chunk_start: int, chunk_end: int):
                nonlocal last_sequence_number
                chunk_md5 = hashlib.md5(mm[chunk_start:chunk_end].encode())
                if mm[chunk_start-1:chunk_start].decode() != str(int((mm.tell()/data_capacity) % num_leaf_nodes)+1).zfill(feature_size):
                    raise ValueError("Invalid sequence number")
                last_sequence_number = int((mm.tell()/data_capacity) % num_leaf_nodes)
                chunk_checksums[chunk_start] = hashlib.md5(mm[chunk_start:chunk_end].encode()).hexdigest()
                md5_hash.update(mm[chunk_start:chunk_end].encode())

            def validate_chunk(chunk_start: int):
                nonlocal integrity_passed
                if chunk_checksums.get(chunk_start) != mm[chunk_start-1:chunk_start+1].decode():
                    raise ValueError("Chunk integrity failed")

            processes = []
            for i in range(0, len(mm), max_memory_usage_threshold):
                process_chunk(i, min(len(mm), i+max_memory_usage_threshold))
                if i % (data_capacity) == 0:
                    processes.append(multiprocessing.Process(target=process_chunk, args=(i-data_capacity, i)))
                    processes[-1].start()
            for p in processes:
                p.join()

            validate_chunk(0)
            return md5_hash.hexdigest(), last_sequence_number, integrity_passed, {'memory_usage': mm.size()}

    except FileNotFoundError as e:
        print(f"Error: {e}. File not found.")
    except IOError as e:
        print(f"Error: {e}. Unable to access file.")
    except Exception as e:
        print(f"Error: {e}. Processing terminated.")

