import hashlib
import os
import requests
import time
import random
import threading

def update_progress(total_files, current_file, start_time):
    if current_file > 0:
        elapsed_time = time.time() - start_time
        throughput = current_file / elapsed_time if elapsed_time > 0 else 0
        remaining_time = (total_files - current_file) / throughput if throughput > 0 else float('inf')
        print(f"Processed {current_file}/{total_files} files. Estimated time remaining: {remaining_time:.2f} seconds.")
    if not threading.main_thread().is_alive():
        return

def calculate_sha256(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as file:
        while chunk := file.read(4096):
            sha256.update(chunk)
    return sha256.hexdigest()

def dfs_hash(directory_url, api_key, directory_depth=0):
    total_files = 0
    start_time = time.time()
    current_file = 0

    def fetch_file(file_path):
        nonlocal current_file
        try:
            response = requests.get(file_path, headers={'Authorization': f'Bearer {api_key}'})
            if response.status_code == 200:
                with open(response.json()['filename'], 'wb') as file:
                    file.write(response.content)
                update_progress(total_files, current_file + 1, start_time)
                sha256 = calculate_sha256(file_path)
                yield file_path, sha256
        except requests.exceptions.RequestException as e:
            print(f"Error fetching {file_path}: {e}")
        finally:
            current_file += 1

    for _, files in requests.get(directory_url).json().items():
        for file in files:
            if 'filename' in file and 'size' in file and file['filename'].endswith('/'):
                yield from dfs_hash(file['filename'], api_key, directory_depth + 1)
            else:
                yield from fetch_file(file['filename'])

    return dict(yield from dfs_hash(directory_url, api_key))

def modify_filename(filename):
    timestamp = int(time.time())
    random_string = ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=random.randint(2, 10)))
    new_extension = f"_{timestamp}_{random_string}{os.path.splitext(filename)[1]}"
    return filename.replace(os.path.splitext(filename)[1], new_extension)
