int current_cell_id = -1;
int message_count = 0;

LTE_EUTRA_SIB10_T* add_message(int cell_id, int tdd_ul_dl_config_index, int subframe_offsets[8]) {
    LTE_EUTRA_SIB10_T* new_message;
    pthread_mutex_lock(&mutex);
    if (current_cell_id != cell_id) {
        current_cell_id = cell_id;
        if (dynamic_array == NULL || message_count >= MAX_MESSAGES) {
            dynamic_array = realloc(dynamic_array, (message_count + 1) * sizeof(LTE_EUTRA_SIB10_T));
        }
    }
    new_message = &((LTE_EUTRA_SIB10_T*)dynamic_array)[message_count++];
    new_message->cell_id = cell_id;
    new_message->tdd_ul_dl_config_index = tdd_ul_dl_config_index;
    for (int i = 0; i < 8; i++) {
        new_message->subframe_offsets[i] = subframe_offsets[i];
    }
    pthread_mutex_unlock(&mutex);
    return new_message;
}

void update_message(int cell_id, int index, LTE_EUTRA_SIB10_T* message) {
    pthread_mutex_lock(&mutex);
    if (current_cell_id == cell_id && index < message_count) {
        ((LTE_EUTRA_SIB10_T*)dynamic_array)[index] = *message;
    }
    pthread_mutex_unlock(&mutex);
}

LTE_EUTRA_SIB10_T* get_message(int cell_id, int index) {
    LTE_EUTRA_SIB10_T* result = NULL;
    pthread_mutex_lock(&mutex);
    if (current_cell_id == cell_id && index < message_count) {
        result = &((LTE_EUTRA_SIB10_T*)dynamic_array)[index];
    }
    pthread_mutex_unlock(&mutex);
    return result;
