    try:
        # Initialize octree data structure
        octree = [None] * (1 << 10)  # dynamic memory allocation
        for i in range(len(octree)):
            octree[i] = {'leaf': None, 'data': []}

        # Allocate memory for prefix leafs and data arrays
        prefix_leafs = [[] for _ in range(1 << 20)]
        data_arrays = [[] for _ in range(1 << 15)]

        # Process file in chunks
        chunk_size = 1024 * 10
        file_chunks = [file_path[i:i + chunk_size] for i in range(0, os.path.getsize(file_path), chunk_size)]

        # Asynchronously process each chunk and validate integrity
        import concurrent.futures
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(process_chunk, file_chunks[i], cache_size_limit) for i in range(len(file_chunks))}
            for future in futures.values():
                result = future.result()
                if not result[2]:
                    return (None, None, False)

        # Compute MD5 hash
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in file_chunks:
                md5_hash.update(chunk)
        hexdigest = md5_hash.hexdigest().upper()

        # Extract sequence number from last line
        with open(file_path, 'r') as f:
            lines = [line.strip() for line in f.readlines()]
        sequence_number = int(lines[-1].split(' ')[-1])

        return (hexdigest, sequence_number, True)
    except Exception as e:
        print(f"Error: {str(e)}")
        return (None, None, False)

