import requests
import time
from collections import defaultdict
from logging.handlers import RotatingFileHandler

CHECKSUM_SERVICE_URL = 'https://example.com/checksum'
CPU_THRESHOLD = 0.8
MEMORY_THRESHOLD = 0.7
FILTERED_LOGS = []

def process_and_filter_logs(log_file_path, filtering_keyword, priority_threshold):
    log_file_size = os.path.getsize(log_file_path)

    if log_file_size > 100 * 1024 * 1024:
        with requests.Session() as s:
            checksum_url = f'{CHECKSUM_SERVICE_URL}?path={log_file_path}'
            while True:
                try:
                    response = s.head(checksum_url, timeout=5)
                    if response.status_code == 200:
                        break
                    else:
                        time.sleep(1)
                except requests.exceptions.RequestException as e:
                    print(f'Error checking checksum: {e}')
        if response.status_code != 200:
            return []

    with open(log_file_path, 'rb') as f:
        chunk_size = 1024 * 1024
        chunks = [f.read(chunk_size) for _ in range((log_file_size + chunk_size - 1) // chunk_size)]
        for i, chunk in enumerate(chunks):
            try:
                log_lines = chunk.decode().strip().split('\n')
                for line in log_lines:
                    if filtering_keyword.lower() in line.lower():
                        priority = int(line.split(':')[0].strip())
                        if priority > priority_threshold:
                            FILTERED_LOGS.append(line)
            except Exception as e:
                print(f'Error processing chunk {i}: {e}')

    return FILTERED_LOGS
