    public static MoSTState loadStateFromFile(String filePath) throws Exception {
        try (ObjectInputStream ois = new ObjectInputStream(new CipherInputStream(new FileInputStream(filePath), getCipher()))) {
            return (MoSTState) ois.readObject();
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
            return null;
        }
    }

    private static Cipher getCipher() throws Exception {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        keyStore.load(new FileInputStream("keystore.jks"), "password".toCharArray());

        Key key = keyStore.getKey("mykey", "password".toCharArray());
        return Cipher.getInstance("DES/ECB/PKCS5Padding");
    }

    public static Semaphore getSemaphore(int initialValue) {
        return new Semaphore(initialValue);
    }

    public static boolean validateOAuthTokenResponse(String jsonStr) throws Exception {
        JsonNode json = new JsonNode(jsonStr);
        if (!json.has("access_token") || !json.has("expires_in") || !json.has("token_type")) {
            System.out.println("Invalid OAuth token response: missing required fields");
            return false;
        }
        String accessToken = json.get("access_token").asText();
        int expiresIn = json.get("expires_in").intValue();
        String tokenType = json.get("token_type").asText();

        if (accessToken == null || !tokenType.equals("Bearer") || expiresIn <= 0) {
            System.out.println("Invalid OAuth token response: invalid values");
            return false;
        }
        return true;
    }

    public static void stopService() throws Exception {
        // Send message to messaging system
    }
}
