void populateNfaapiPdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t n) {
    FILE *fp = fopen("/path/to/valid_rntis.txt", "r");
    if (!fp) {
        perror("Error opening RNTI file");
        exit(1);
    }

    char buffer[BUFFER_SIZE];
    int rnti_cache[RNTI_CACHE_SIZE];
    int cache_index = 0;

    while (fgets(buffer, BUFFER_SIZE, fp)) {
        int rnti;
        if (sscanf(buffer, "%d", &rnti) == 1) {
            rnti_cache[cache_index++] = rnti;
            if (cache_index >= RNTI_CACHE_SIZE) {
                cache_index = 0;
            }
        }
    }

    fclose(fp);

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        int rnti_idx = rand() % cache_index;
        pdu.rnti = rnti_cache[rnti_idx];

        // Generate random RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values
        srand(time(NULL));
        pdu.rx_ue_information_tag = (uint32_t)rand();
        for (int j = 0; j < 4; ++j) {
            pdu.crc_indication_rel8_tag[j] = (uint8_t)rand();
        }

        // Set CRCFLAG randomly
        int crcflag;
        srand(time(NULL));
        crcflag = rand() % 2;

        if (crcflag == 0) {
            pdu.crc_indication_rel8_tag[3] &= ~(1 << 7);
        } else {
            pdu.crc_indication_rel8_tag[3] |= (1 << 7);
        }

        // Compute MD5 hash for RNTI
        unsigned char md5_hash[16];
        char rnti_str[6];
        itoa(pdu.rnti, rnti_str, 10);

        FILE *fp_md5 = fopen("/usr/bin/md5sum", "r");
        if (!fp_md5) {
            perror("Error opening MD5 file");
            exit(1);
        }

        char buffer_md5[BUFFER_SIZE];
        int64_t bytes_read;
        while ((bytes_read = fread(buffer_md5, 1, BUFFER_SIZE, fp_md5)) > 0) {
            // Compute MD5 hash for RNTI
            unsigned char md5_hash[16];
            uint8_t* p = (uint8_t*)rnti_str;
            for (int j = 0; j < 6; ++j) {
                md5_hash[j] = p[j];
            }
            // Add more code to compute MD5 hash
        }

        fclose(fp_md5);

        (*pdus)[i] = pdu;

        free(pdu.crc_indication_rel8_tag);
    }
}
