#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

int* readInput(int* size) {
    int* array = (int*)malloc(MAX_SIZE * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    *size = 0;
    while (*size < MAX_SIZE && scanf("%d", &array[*size]) == 1) {
        (*size)++;
    }
    if (*size >= MAX_SIZE) {
        printf("Error: Input exceeded maximum size of %d elements.\n", MAX_SIZE);
        exit(1);
    }
    return array;
}

void validateArray(int* array, int size) {
    for (int i = 0; i < size - 1; i++) {
        if (array[i] >= array[i + 1]) {
            printf("Error: Input array is not sorted in ascending order.\n");
            exit(1);
        }
    }
}

int findLargest(int* array, int size) {
    return *std::max_element(array, array + size);
}

void printLargest(int* array, int size) {
    if (size == 0) {
        printf("Error: Input array is empty.\n");
        return;
    }
    int largest = findLargest(array, size);
    if (largest < 0) {
        printf("The largest integer in the array is %d\n", -largest);
    } else {
        printf("The largest integer in the array is %d\n", largest);
    }
}

int main() {
    int size;
    int* array = readInput(&size);
    validateArray(array, size);
    printLargest(array, size);
    free(array);
    return 0;
}
