#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 50000

int findLargest(int* arr, int n) {
    if (n == 0) return -1; // edge case: empty array
    int largest = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > largest) largest = arr[i];
    }
    return largest;
}

void printLargest(int* arr, int n) {
    if (n == 0 || n == 1) {
        printf("Error: Array is empty or contains only one element.\n");
        return;
    }
    int largest = findLargest(arr, n);
    if (largest < 0) {
        printf("The largest integer in the array is %d.\n", largest);
    } else {
        printf("The largest integer in the array is %d.\n", largest);
    }
}

int parseInput(char* str, int* arr, int* n) {
    char* token = strtok(str, " ");
    while (token != NULL && *n < MAX_SIZE) {
        if (sscanf(token, "%d", &arr[*n]) == 1) {
            (*n)++;
        }
        token = strtok(NULL, " ");
    }
    return *n;
}

void processDataset(int* arr, int n) {
    if (!is_sorted(arr, n)) {
        printf("Error: Input array is not sorted in ascending order.\n");
        return;
    }
    printLargest(arr, n);
}

int main() {
    int i = 0, count = 0;
    char str[256];
    while (fgets(str, sizeof(str), stdin) != NULL) {
        int* arr = (int*)malloc(MAX_SIZE * sizeof(int));
        int n = parseInput(str, arr, &i);
        processDataset(arr, n);
        free(arr);
    }
    return 0;
}

// helper function to check if the array is sorted
int is_sorted(int* arr, int n) {
    for (int i = 1; i < n; i++) {
        if (arr[i - 1] > arr[i]) return 0;
    }
    return 1;
}
