// Define the message structure
typedef struct {
    int timestamp;
    enum { SUCCESS, FAILURE } status;
    char* payload;
} Message;

// Define the notification structure
typedef struct {
    Message* message;
    int priority;
} Notification;

// Function to dynamically allocate memory for and initialize an array of custom 'message' structures
Message** allocateMessages(int numMessages) {
    Message** messages = (Message**)malloc(numMessages * sizeof(Message*));
    for (int i = 0; i < numMessages; i++) {
        messages[i] = (Message*)malloc(sizeof(Message));
        messages[i]->timestamp = i;
        messages[i]->status = (i % 2 == 0) ? SUCCESS : FAILURE;
    }
    return messages;
}

// Function to dynamically allocate memory for and initialize an array of 'notification' objects
Notification** allocateNotifications(int numNotifications, Message** messages) {
    Notification** notifications = (Notification**)malloc(numNotifications * sizeof(Notification*));
    for (int i = 0; i < numNotifications; i++) {
        notifications[i] = (Notification*)malloc(sizeof(Notification));
        notifications[i]->message = messages[i % numMessages];
        notifications[i]->priority = (i % 2 == 0) ? 1 : 2;
    }
    return notifications;
}

// Function to dynamically allocate memory for and initialize an array of 'message' structures with payloads
Message** allocateMessagesWithPayloads(int numMessages, char* logEntries[]) {
    Message** messages = (Message**)malloc(numMessages * sizeof(Message*));
    for (int i = 0; i < numMessages; i++) {
        messages[i] = (Message*)malloc(sizeof(Message));
        messages[i]->timestamp = i;
        messages[i]->status = (i % 2 == 0) ? SUCCESS : FAILURE;
        messages[i]->payload = logEntries[i];
    }
    return messages;
}

int main() {
    int numMessages = 10;
    Message** messages = allocateMessages(numMessages);

    for (int i = 0; i < numMessages; i++) {
        char* logEntry = (char*)malloc(strlen("Event ") + strlen(" occurred at ") + 5);
        sprintf(logEntry, "Event %d occurred at %d", i, messages[i]->timestamp);
        messages[i]->payload = logEntry;
    }

    int numNotifications = 10;
    Notification** notifications = allocateNotifications(numNotifications, messages);

    for (int i = 0; i < numNotifications; i++) {
        printf("Notification priority %d with message '%s'\n", notifications[i]->priority, notifications[i]->message->payload);

        // Free allocated memory
        free(notifications[i]->message->payload);
        free(notifications[i]->message);
        free(notifications[i]);
    }

    for (int i = 0; i < numMessages; i++) {
        free(messages[i]->payload);
        free(messages[i]);
    }

    // Free allocated memory
    free(messages);
    free(notifications);

    return 0;
}
