import json
import os
import logging
from functools import lru_cache
from concurrent.futures import ThreadPoolExecutor

def process_jsonl_file(file_path):
    logger = logging.getLogger('jsonl_processor')
    logger.setLevel(logging.INFO)

    def process_chunk(chunk, pool):
        latency_stats = {}
        error_rates = {}

        for log_entry in chunk:
            endpoint = log_entry['endpoint']

            if 'latency' in log_entry and 'error' not in log_entry:
                latency = float(log_entry['latency'])
                if endpoint not in latency_stats:
                    latency_stats[endpoint] = [latency]
                else:
                    latency_stats[endpoint].append(latency)
            elif 'error' in log_entry and 'latency' not in log_entry:
                error_rates[endpoint] = error_rates.get(endpoint, 0) + (1 if log_entry['error'] else 0)

        for endpoint, latencies in latency_stats.items():
            avg_latency = round(sum(latencies) / len(latencies), 2)
            yield {'endpoint': endpoint, 'avg_latency': avg_latency}
        for endpoint, error_count in error_rates.items():
            error_rate = (error_count / (len(chunk) if chunk else 1)) * 100
            yield {'endpoint': endpoint, 'error_rate': error_rate}

    @lru_cache(maxsize=None)
    def get_chunk(file_path, start):
        with open(file_path, 'r') as f:
            return [json.loads(line) for line in f.readlines() if line.strip()]

    @lru_cache(maxsize=None)
    def available_memory():
        try:
            mem_info = os.popen('free -m').read().strip()
            total_memory = int(re.search(r'Total:\s+(\d+)', mem_info).group(1))
            return total_memory
        except Exception as e:
            logger.error(f'Error determining memory availability: {e}')
            return 0

    @lru_cache(maxsize=None)
    def available_cpu():
        try:
            cpu_info = os.popen('mpstat -a').read().strip()
            available_cpus = re.search(r'avail.+\d+', cpu_info).group(0).split()[2]
            return float(available_cpus.replace(',', '.'))
        except Exception as e:
            logger.error(f'Error determining CPU availability: {e}')
            return 0

    chunk_size = 10000
    start_time = time.time()

    pool = ThreadPoolExecutor()

    for i in range(0, len(get_chunk(file_path, 0)), chunk_size):
        chunk = get_chunk(file_path, i)

        if not chunk:
            break

        with pool.submit(process_chunk) as future:
            stats_report = future.result()

            memory_usage = available_memory() / 1024
            elapsed_time = time.time() - start_time

            yield {'stats': stats_report, 'memory_usage': memory_usage, 'elapsed_time': elapsed_time}

    pool.shutdown()
