    public static class SemaphorePool {
        private final Map<Integer, Semaphore> pool;
        private final int minValue;
        private final int maxValue;

        public SemaphorePool(int minValue, int maxValue) {
            this.minValue = minValue;
            this.maxValue = maxValue;
            this.pool = new HashMap<>();
        }

        public void addSemaphore(int value) throws InterruptedException {
            if (!pool.containsKey(value)) {
                pool.put(value, new Semaphore(0));
            }
        }

        public boolean tryAcquire(int value) throws InterruptedException {
            return pool.getOrDefault(value, null).tryAcquire();
        }

        public void release(int value) {
            pool.getOrDefault(value, null).release();
        }
    }

