        printf("Memory allocation failed.\n");
        return NULL;
    }

    int i = 0;
    while (i < MAX_SIZE && !feof(stdin)) {
        if (fscanf(stdin, "%d", &arr[i]) != 1) {
            // Handle invalid input
            printf("Invalid input. Exiting.\n");
            free(arr);
            return NULL;
        }
        if (i > 0 && arr[i - 1] > arr[i]) {
            // Detect and log unusual delay in data arrival
            printf("Unusual delay detected at index %d.\n", i);
        }
        i++;
    }

    *size = i;
    return arr;
}

void validate_array(int* arr, int size) {
    for (int i = 1; i < size; i++) {
        if (arr[i - 1] > arr[i]) {
            printf("Array is not sorted in ascending order.\n");
            exit(1);
        }
    }
}

int find_largest(int* arr, int size) {
    return *max_element(arr, arr + size);
}

void print_largest(int* arr, int size) {
    if (size == 0) {
        printf("No elements in the array.\n");
    } else {
        printf("Largest integer: %d\n", find_largest(arr, size));
    }
}

int main() {
    int size = 0;
    int* arr = read_input(&size);
    if (!arr) {
        return 1;
    }

    validate_array(arr, size);

    print_largest(arr, size);

    free(arr);
    return 0;
}
