import javax.crypto.spec.IvParameterSpec;

public class CryptoHelper {

    private static final String TRIPLE_DES_ALGORITHM = "DESede";
    private static final String AES_ALGORITHM = "AES";

    private Map<String, Cipher> ciphers;
    private Map<String, SecretKey> keys;
    private Map<String, IvParameterSpec> ivs;

    public CryptoHelper() {
        this.ciphers = new ConcurrentHashMap<>();
        this.keys = new ConcurrentHashMap<>();
        this.ivs = new ConcurrentHashMap<>();

        // Initialize cryptographic operations
        for (String cipherName : getCipherNames()) {
            try {
                SecretKey key = generateKey(cipherName);
                IvParameterSpec iv = generateIv(cipherName);

                Cipher cipher = Cipher.getInstance(TRIPLE_DES_ALGORITHM);
                cipher.init(Cipher.DECRYPT_MODE, key, iv);
                ciphers.put(cipherName, cipher);

                keys.put(cipherName, key);
                ivs.put(cipherName, iv);
            } catch (NoSuchAlgorithmException | InvalidKeyException e) {
                // Handle unavailable cryptographic operations
                System.err.println("Error initializing " + cipherName + ": " + e.getMessage());
            }
        }
    }

    public Object deserialize(byte[] serializedData, byte[] encryptedMessage, String cipherName)
            throws RuntimeException {

        try (ByteArrayInputStream bais = new ByteArrayInputStream(encryptedMessage);
             Cipher cipher = ciphers.get(cipherName)) {
            // Decrypt the message using Triple DES
            byte[] decryptedBytes = decrypt(bais, cipher);

            try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                 ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decryptedBytes))) {
                // Deserialize the object
                return ois.readObject();
            } catch (ClassNotFoundException e) {
                throw new RuntimeException("Error deserializing object: " + e.getMessage());
            }
        } catch (IllegalBlockSizeException | BadPaddingException e) {
            throw new RuntimeException("Error decrypting message: " + e.getMessage());
        }
    }

    private byte[] decrypt(ByteArrayInputStream bais, Cipher cipher)
            throws IllegalBlockSizeException, BadPaddingException {

        // Decrypt the message using Triple DES
        CipherInputStream cis = new CipherInputStream(bais, cipher);
        return StreamUtils.readFully(new DigestInputStream(cis));
    }

    public Map<String, CryptoOperation> getAvailableOperations() {
        return new ConcurrentHashMap<>();
    }
}
