        rewind(file);

        // Compute the MD5 hash of the chunk
        MD5_Init(&ctx);
        unsigned char* buffer = malloc(1024);
        size_t bytes_read;
        while ((bytes_read = fread(buffer, 1, 1024, file)) > 0) {
            MD5_Update(&ctx, buffer, bytes_read);
        }
        free(buffer);

        // Compute the final hash
        MD5_Final(md, &ctx);

        // Checksum validation mechanism
        if (!validate_checksum(file_size, md)) {
            result.valid_checksum = false;
            printf("Checksum validation failed.\n");
            break;
        }

        // Extract sequence number from the last line
