        char* line = malloc(1024);
        size_t bytes_read = fread(line, 1, 1024, file);
        int sequence = extract_sequence_number(line);
        free(line);

        result.sequence = sequence;
        result.hexdigest = md_to_hex_string(md);
    }

    fclose(file);
    free(prefix_leaves);
    free(data_array);

    return result;
