void process_log_file(char *input_path, char *pattern, int num_segments, char **output_paths) {
    // Open input log file
    int input_fd = open(input_path, O_RDONLY);
    if (input_fd == -1) {
        perror("Error opening input log file");
        exit(EXIT_FAILURE);
    }

    // Initialize segment buffers and output files
    size_t buffer_size = 1024 * 1024; // 1MB buffer
    char *buffer = malloc(buffer_size);
    FILE **output_files = malloc(num_segments * sizeof(FILE *));
    for (int i = 0; i < num_segments; i++) {
        output_files[i] = fopen(output_paths[i], "w");
        if (!output_files[i]) {
            perror("Error opening output file");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize parsing and segment counters
    char *log_data;
    size_t log_size = lseek(input_fd, 0, SEEK_END) + 1; // Add 1 for null termination
    log_data = malloc(log_size);
    read(input_fd, log_data, log_size - 1); // Read log data into buffer
    log_data[log_size - 1] = '\0'; // Null terminate

    size_t segment_count = 0;
    char *segment_start;
    while ((segment_start = strstr(log_data, pattern)) != NULL) {
        size_t segment_len = strlen(segment_start);
        write(output_files[segment_count % num_segments], log_data, segment_start - log_data); // Write segment to output file
        write(output_files[segment_count % num_segments], segment_start, segment_len); // Write segment content to output file
        fputc('\n', output_files[segment_count % num_segments]); // Append newline character
        segment_count++;
    }

    fclose(input_fd);
    for (int i = 0; i < num_segments; i++) {
        fclose(output_files[i]);
    }
    free(buffer);
    free(log_data);
    free(output_files);
}
