void process_log_file(const char* input_path, const char* boundary_pattern, const char* output1, const char* output2, const char* output3) {
    // Initialize variables
    FILE *input = fopen(input_path, "r");
    FILE *output1_file = fopen(output1, "w");
    FILE *output2_file = fopen(output2, "w");
    FILE *output3_file = fopen(output3, "w");
    char buffer[1024];
    int segment_count = 0;

    if (input == NULL || output1_file == NULL || output2_file == NULL || output3_file == NULL) {
        // Handle errors
        printf("Error opening file\n");
        return;
    }

    // Process the log file
    while (fgets(buffer, sizeof(buffer), input)) {
        // Identify segment boundaries based on the pattern
        if (strstr(buffer, boundary_pattern) != NULL) {
            // Extract relevant segments and write them to output files
            fwrite(buffer, 1, strlen(buffer), output1_file);
            fwrite(buffer, 1, strlen(buffer), output2_file);
            fwrite(buffer, 1, strlen(buffer), output3_file);

            // Increment segment count
            segment_count++;
        }
    }

    // Close files and handle any errors
    fclose(input);
    fclose(output1_file);
    fclose(output2_file);
    fclose(output3_file);

    if (ferror(input) || ferror(output1_file) || ferror(output2_file) || ferror(output3_file)) {
        printf("Error processing log file\n");
    }

    // Print status and progress
    printf("Segments processed: %d\n", segment_count);
}
