NFAPI_CRC_INDICATION_PDU_T* generate_array(int n, FILE* config_file) {
    srand(time(NULL)); // seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    FILE* fp = fopen(config_file, "r");
    if (!fp) {
        printf("Error opening configuration file!\n");
        free(array);
        return NULL;
    }

    int rnti_range = 0; // read RNTI range from config file
    fread(&rnti_range, sizeof(int), 1, fp);

    for (int i = 0; i < n; i++) {
        array[i].rx_ue_info.rssi = rand() % 256;
        array[i].rx_ue_info.tag[0] = 'T'; // initialize tag with a fixed value
        array[i].rnti = rand() % rnti_range + 1;
        array[i].crc_indication_rel8_tag = (rand() % 2) ? CRCFLAG_ON : CRCFLAG_OFF;
    }

    fclose(fp);
    return array;
}

int validate_array(NFAPI_CRC_INDICATION_PDU_T* array, int n) {
    for (int i = 0; i < n; i++) {
