// Define structure for MAC transaction record
typedef struct {
    TX_MESSAGE tx_message;
    unsigned int sequence_number;
    time_t transaction_timestamp;
} MAC_TRANSACTION_RECORD;

// Function to initialize and populate array of MAC_TRANSACTION_RECORD structures
MAC_TRANSACTION_RECORD* generate_MAC_transaction_records(const char* json_file) {
    // Initialize variables
    int M = 0; // Number of elements in the array
    unsigned int min_sequence_number = 0;
    unsigned int max_sequence_number = 0;

    // Parse JSON configuration to determine number of elements and range of valid sequence numbers
    FILE* file = fopen(json_file, "r");
    if (file == NULL) {
        printf("Error: Unable to open the JSON file.\n");
        return NULL;
    }

    // Read configuration settings from JSON file
    json_t* root = json_load_file(file, 0);
    if (root == NULL || !json_is_object(root)) {
        printf("Error: Invalid or missing JSON configuration.\n");
        fclose(file);
        return NULL;
    }
    M = json_integer_value(json_object_get(root, "M"));
    min_sequence_number = json_integer_value(json_object_get(root, "min_sequence_number"));
    max_sequence_number = json_integer_value(json_object_get(root, "max_sequence_number"));

    // Initialize array of MAC_TRANSACTION_RECORD structures
    MAC_TRANSACTION_RECORD* mac_transaction_records = NULL;
    if (M > 0) {
        mac_transaction_records = (MAC_TRANSACTION_RECORD*)malloc(sizeof(MAC_TRANSACTION_RECORD) * M);
        for (int i = 0; i < M; i++) {
            // Initialize TX_MESSAGE structure
            // ...

            // Set sequence number and timestamp
            mac_transaction_records[i].sequence_number = rand() % (max_sequence_number - min_sequence_number + 1) + min_sequence_number;
            mac_transaction_records[i].transaction_timestamp = time(NULL);

            // Validate integrity of generated data before returning
            for (int j = 0; j < M; j++) {
                if (mac_transaction_records[j].sequence_number > max_sequence_number || mac_transaction_records[j].sequence_number < min_sequence_number) {
                    printf("Error: Sequence number out of bounds.\n");
                    free(mac_transaction_records);
                    return NULL;
                }
            }
        }
    }

    fclose(file);
    json_decref(root);

    // Return initialized and populated array
    return mac_transaction_records;
}
