typedef struct {
    int tx_message;
    int sequence_number;
    time_t transaction_timestamp;
} MAC_TRANSACTION_RECORD;

void init_and_populate_array(int *M, json_object *config) {
    // Read configuration settings from the JSON file
    int M_val = json_object_get_int(config, "array_size");
    int seq_min = json_object_get_int(config, "sequence_number_min");
    int seq_max = json_object_get_int(config, "sequence_number_max");

    MAC_TRANSACTION_RECORD *records;
    if (*M == 0) {
        // Dynamically allocate memory for the array
        records = (MAC_TRANSACTION_RECORD *)malloc(*M * sizeof(MAC_TRANSACTION_RECORD));
        if (!records) {
            printf("Error allocating memory for the array.\n");
            return;
        }
    } else {
        // Use the pre-allocated memory
        records = (MAC_TRANSACTION_RECORD *)malloc(*M * sizeof(MAC_TRANSACTION_RECORD));
    }

    // Populate the array with valid transaction records
    int i;
    for (i = 0; i < *M; i++) {
        records[i].tx_message = rand() % 100 + 1;
        records[i].sequence_number = rand() % (seq_max - seq_min) + seq_min;
        records[i].transaction_timestamp = time(NULL);
    }

    // Validate the integrity of the generated data
    for (i = 0; i < *M; i++) {
        if (records[i].sequence_number < seq_min || records[i].sequence_number > seq_max) {
            printf("Error: sequence number out of bounds.\n");
            return;
        }
    }

    // Implement caching mechanism to minimize JSON file reads
    json_object *cache = json_object_new_object();
    for (i = 0; i < *M; i++) {
        char *key = malloc(strlen("seq_") + strlen(&records[i].sequence_number));
        sprintf(key, "seq_%d", records[i].sequence_number);
        json_object_object_add(cache, key, json_object_new_int(records[i].tx_message));
    }

    // Integrate the function with an external logging service
    FILE *log_file = fopen("logs.log", "a");
    if (!log_file) {
        printf("Error opening log file.\n");
        return;
    }
    fprintf(log_file, "Transaction records initialized and populated.\n");

    fclose(log_file);
}

int main() {
    // Initialize the JSON configuration
    json_object *config = json_object_from_file("config.json");
    if (!config) {
        printf("Error reading configuration file.\n");
        return 1;
    }

    int M = 10; // Set the initial array size

    init_and_populate_array(&M, config);

    // Periodic updates to the configuration settings through a notification system
    json_object *new_config = json_object_from_file("new_config.json");
    if (new_config) {
        M = json_object_get_int(new_config, "array_size");
        json_object_free(config);
        config = new_config;
    }

    return 0;
}
