typedef struct {
    int id;
    char name[64];
    struct {
        char type[32];
        char version[16];
        void* parameters;
    } services[10];
} NetworkSliceInstance;

typedef struct _Node {
    int id;
    NetworkSliceInstance* instance;
    struct _Edge** edges;
    int numEdges;
    struct _Node* parent;
    struct _Node* child[8];
} Node;

typedef struct _Edge {
    int from, to;
    float bandwidth, latency, reliability;
} Edge;

void freeNode(Node* node) {
    if (node->instance)
        free(node->instance);
    for (int i = 0; i < node->numEdges; i++)
        free(node->edges[i]);
}

Node* createNode(int id, Node* parent) {
    Node* node = malloc(sizeof(Node));
    node->id = id;
    node->parent = parent;
    return node;
}

void insertEdge(Node* node, int from, int to, float bandwidth, float latency, float reliability) {
    Edge* edge = malloc(sizeof(Edge));
    edge->from = from;
    edge->to = to;
    edge->bandwidth = bandwidth;
    edge->latency = latency;
    edge->reliability = reliability;
    node->edges = realloc(node->edges, (node->numEdges + 1) * sizeof(Edge*));
    node->edges[node->numEdges] = edge;
    node->numEdges++;
}

void updateNode(Node* node, int id, float bandwidth, float latency, float reliability) {
    for (int i = 0; i < node->numEdges; i++) {
        Edge* edge = node->edges[i];
        if (edge->from == id || edge->to == id) {
            edge->bandwidth = bandwidth;
            edge->latency = latency;
            edge->reliability = reliability;
            return;
        }
    }
}

void deleteEdge(Node* node, int from, int to) {
    for (int i = 0; i < node->numEdges; i++) {
        Edge* edge = node->edges[i];
        if (edge->from == from && edge->to == to) {
            free(edge);
            memmove(&node->edges[i], &node->edges[i + 1], (node->numEdges - i - 1) * sizeof(Edge*));
            node->numEdges--;
            return;
        }
    }
}

void freeGraph(Node* root) {
    if (!root)
        return;
    for (int i = 0; i < 8; i++) {
        Node* child = root->child[i];
        if (child)
            freeGraph(child);
    }
    freeNode(root);
}

void computeMD5(char* buffer, int len) {
    unsigned char md[MD5_DIGEST_LENGTH];
    MD5(buffer, len, md);
    // Add logging and error handling
}

int main() {
    Node* root = createNode(0, NULL);
    // ... Create instances and edges ...
    freeGraph(root);
    return 0;
}
