#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 10000
#define MAX_PRIORITY_LEVELS 5

typedef enum {
    LOW,
    MEDIUM,
    HIGH,
    CRITICAL
} priority_level_t;

typedef struct TASK_REQUEST_T {
    int task_id;
    priority_level_t priority_level;
    void* payload;
} task_request_t;

typedef struct {
    task_request_t requests[MAX_TASKS];
    size_t head, tail;
    pthread_mutex_t lock;
} task_queue_t;

void* alloc_task_queue(size_t capacity) {
    return calloc(1, sizeof(task_queue_t));
}

int enqueue_task(task_queue_t* queue, task_request_t request) {
    pthread_mutex_lock(&queue->lock);
    if (queue->tail >= MAX_TASKS) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    queue->requests[queue->tail] = request;
    queue->tail++;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

task_request_t* dequeue_task(task_queue_t* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->head == queue->tail) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }
    task_request_t* request = &queue->requests[queue->head];
    queue->head++;
    pthread_mutex_unlock(&queue->lock);
    return request;
}

void free_task_queue(void* queue_ptr) {
    task_queue_t* queue = (task_queue_t*)queue_ptr;
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
