void processAndIndexWebContent(const char* url, int num_pages) {
    CURL *curl;
    CURLcode res;
    FILE *fp;
    long http_code;
    struct curl_slist *curl_list = NULL;

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
