            exit(1);
        }

        // Process the downloaded data
        processPageData(data);
    }

    // Clean up curl
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}

void write_memory(void *ptr, size_t size, size_t nmemb, void *data) {
    char *buffer = (char *)data;
    memcpy(buffer, ptr, size * nmemb);
}

