typedef struct {
    int id;
    long timestamp;
    float amount;
    char status[9]; // 8 chars for "success" and null-terminator
} Transaction;

typedef struct Node {
    Transaction transaction;
    int id;
    struct Node* next;
} Node;

typedef struct Edge {
    int source;
    int destination;
    struct Edge* next;
} Edge;

void addNode(Node** head, Transaction transaction) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->transaction = transaction;
    newNode->next = *head;
    *head = newNode;
}

void updateNodeStatus(Node** head, int id, char status[]) {
    Node* current = *head;
    while (current != NULL) {
        if (current->transaction.id == id) {
            strcpy(current->transaction.status, status);
            return;
        }
        current = current->next;
    }
}

void addEdge(Edge** head, int source, int destination) {
    Edge* newEdge = (Edge*)malloc(sizeof(Edge));
    newEdge->source = source;
    newEdge->destination = destination;
    newEdge->next = *head;
    *head = newEdge;
}

Transaction* getTransactions(Node* head) {
    Node* current = head;
    Transaction* transactions = NULL;
    while (current != NULL) {
        transactions = (Transaction*)realloc(transactions, sizeof(Transaction) * (transactions ? transactions[0].id + 1 : 1));
        transactions[transactions->id++] = current->transaction;
        current = current->next;
    }
    return transactions;
}

void printTransactions(Node* head) {
    Transaction* transactions = getTransactions(head);
    for (int i = 0; i < transactions->id; i++) {
        printf("Transaction %d: timestamp = %ld, amount = %.2f, status = %s\n", 
              transactions[i].id, transactions[i].timestamp, transactions[i].amount, transactions[i].status);
    }
    free(transactions);
}

int main() {
    Node* head = NULL;
    Transaction transaction1 = {1, 1643723400, 100.00f, "success"};
    addNode(&head, transaction1);

    Edge* edgeHead = NULL;
    addEdge(&edgeHead, 1, 2);

    printTransactions(head);

    return 0;
}
