typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct linked_list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct linked_list_node* next;
} linked_list_node;

typedef struct linked_list {
    linked_list_node* head;
    pthread_mutex_t lock;
    int count;
} linked_list;

linked_list* create_linked_list() {
    linked_list* list = (linked_list*)malloc(sizeof(linked_list));
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
    return list;
}

void insert_node(linked_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    linked_list_node* new_node = (linked_list_node*)malloc(sizeof(linked_list_node));
    new_node->data = data;
    new_node->next = list->head;
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        linked_list_node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void serialize_linked_list(linked_list* list, FILE* file) {
    linked_list_node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_linked_list(linked_list* list, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    linked_list_node* current = list->head;
    int i = 0;
    while (current != NULL) {
        fread(&data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        i++;
        current = current->next;
    }
    return data;
}

NFAPI_CRC_INDICATION_PDU_T* filter_linked_list(linked_list* list) {
    NFAPI_CRC_INDICATION_PDU_T* filtered_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int i = 0;
    linked_list_node* current = list->head;
    while (current != NULL) {
        if (current->data.CRCFLAG) {
            filtered_data[i] = current->data;
            i++;
        }
        current = current->next;
    }
    return filtered_data;
}

void export_to_csv(NFAPI_CRC_INDICATION_PDU_T* data, int count, FILE* file) {
    for (int i = 0; i < count; i++) {
        if (data[i].RNTI != -1) { // handle invalid RNTI values
            fprintf(file, "%s,%d,%s,", data[i].RX_UE_INFORMATION_TAG, data[i].RNTI, data[i].CRC_INDICATION_REL8_TAG);
            if (data[i].CRCFLAG)
                fprintf(file, "true\n");
            else
                fprintf(file, "false\n");
        } else { // handle empty lists
            fprintf(file, "\n");
        }
    }
}

void free_linked_list(linked_list* list) {
    linked_list_node* current = list->head;
    while (current != NULL) {
        linked_list_node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}
