}

int add_request(char* method, char* url, int headers, char* body) {
    HttpRequest* new_request = NULL;
    pthread_mutex_lock(&lock);
    if (request_count < MAX_REQUESTS) {
        new_request = &requests[request_count];
        strcpy(new_request->method, method);
        strcpy(new_request->url, url);
        new_request->headers = headers;
        new_request->body = body;
        request_count++;
    }
    pthread_mutex_unlock(&lock);
    return request_count;
}

