#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    sem_t sem;
    int value;
} semaphore_t;

void* semaphore_init(int value) {
    semaphore_t* sem = (semaphore_t*)malloc(sizeof(semaphore_t));
    sem->value = value;
    if(semop(sem->sem, O_CREAT, 1) == -1) {
        free(sem);
        return NULL;
    }
    return sem;
}

int semaphore_acquire(semaphore_t* sem, int timeout) {
    struct timespec ts = {0, (timeout * 1000000)};
    pthread_mutex_lock(&sem->sem);
    if(timeout > 0) {
        while (sem_getvalue(sem->sem, &ts) == -1 && pthread_timespec_to_ms(&ts, &ms)) {
            if(ms <= 0) return -1;
            pthread_cond_timedwait(&sem->cond, &sem->mutex, &ts);
        }
    } else {
        while (sem_getvalue(sem->sem, &ts) == -1 && pthread_timespec_to_ms(&ts, &ms)) {
            if(ms <= 0) return -1;
            pthread_cond_wait(&sem->cond, &sem->mutex);
        }
    }
    sem_post(sem->sem);
    pthread_mutex_unlock(&sem->sem);
    return 0;
}

int semaphore_release(semaphore_t* sem) {
    return semop(sem->sem, O_RELEASE, 1);
}

void semaphore_report(semaphore_t* sem) {
    printf("Semaphore value: %d\n", sem->value);
}

void semaphore_free(void* sem) {
    if (sem != NULL) {
        free((semaphore_t*)sem);
    }
}
