// Define a custom doubly linked list structure for dynamic memory management
typedef struct Node {
    LTE_PDU* pdu;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the LTE PDU structure, containing a PDCP PDU, SPS configuration, and UE context identifier
typedef struct LTE_PDU {
    PDCP_PDU pdcp_pdu;
    SPS_CONFIG sps_config;
    uint32_t ue_context_id;
} LTE_PDU;

// Function to create a new node with the given pdu
Node* create_node(LTE_PDU* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->pdu = pdu;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to initialize the doubly linked list with M elements
void init_list(int M) {
    // Allocate memory for the first node and its contents
    Node* head = (Node*)malloc(sizeof(Node));
    head->pdu = malloc(sizeof(LTE_PDU)); // dynamically allocate LTE_PDU structure
    ... // initialize PDCP PDU, SPS configuration, and UE context identifier

    // Initialize the doubly linked list with M elements
    for (int i = 0; i < M; i++) {
        Node* new_node = create_node(pdu);
        if (i == 0) {
            head->prev = NULL;
            head->next = new_node;
        } else {
            new_node->prev = head;
            head->next = new_node;
        }
    }

    // Initialize the tail pointer
    head->next->next = NULL;
}

// Function to add a new node with pdu at the end of the list
void add_node(LTE_PDU* pdu) {
    Node* new_node = create_node(pdu);
    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        new_node->prev = tail;
        tail = new_node;
    }
}

// Function to remove the node at the given index
void remove_node(int index) {
    if (index < 0 || index >= size) {
        printf("Invalid index\n");
        return;
    }

    // Find the node at the given index
    Node* current = head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Remove the node from the list
    if (current == head) {
        head = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current == tail) {
        tail = current->prev;
    } else {
        current->next->prev = current->prev;
    }

    // Free the node's memory
    free(current->pdu);
    free(current);
}

// Function to serialize the list to a binary file
void serialize_list(FILE* output_file) {
    // Write the size of the list as an integer
    fwrite(&size, sizeof(int), 1, output_file);

    // Write each node's contents and pointers
    Node* current = head;
    while (current != NULL) {
        LTE_PDU* pdu = current->pdu;
        fwrite(&pdu->pdcp_pdu, sizeof(PDCP_PDU), 1, output_file);
        fwrite(&pdu->sps_config, sizeof(SPS_CONFIG), 1, output_file);
        fwrite(&pdu->ue_context_id, sizeof(uint32_t), 1, output_file);

        // Write the pointers
        fwrite(&current->prev, sizeof(Node*), 1, output_file);
        fwrite(&current->next, sizeof(Node*), 1, output_file);

        current = current->next;
    }
}

// Function to deserialize the list from a binary file
void deserialize_list(FILE* input_file) {
    // Read the size of the list as an integer
    int size;
    fread(&size, sizeof(int), 1, input_file);

    // Initialize the head and tail pointers
    head = NULL;
    tail = NULL;

    // Read each node's contents and pointers
    for (int i = 0; i < size; i++) {
        LTE_PDU* pdu = malloc(sizeof(LTE_PDU));

        // Read the PDCP PDU, SPS configuration, and UE context identifier
        fread(&pdu->pdcp_pdu, sizeof(PDCP_PDU), 1, input_file);
        fread(&pdu->sps_config, sizeof(SPS_CONFIG), 1, input_file);
        fread(&pdu->ue_context_id, sizeof(uint32_t), 1, input_file);

        // Read the pointers
        Node* prev = malloc(sizeof(Node));
        fread(&prev, sizeof(Node*), 1, input_file);
        Node* next = malloc(sizeof(Node));
        fread(&next, sizeof(Node*), 1, input_file);

        if (i == 0) {
            head = create_node(pdu);
            tail = head;
        } else {
            prev->next = create_node(pdu);
            prev->next->prev = prev;
            tail = prev->next;
        }
    }
}

// Function to filter the list and return only those PDUs with active SPS configurations
void filter_list() {
    // Initialize an empty list for filtered results
    Node* filtered_head = NULL;
    Node* filtered_tail = NULL;

    // Iterate through the original list and filter out inactive SPS configurations
    Node* current = head;
    while (current != NULL) {
        LTE_PDU* pdu = current->pdu;
        if (pdu->sps_config.active == true) {
            // Add the filtered PDU to the new list
            if (filtered_head == NULL) {
                filtered_head = create_node(pdu);
                filtered_tail = filtered_head;
            } else {
                filtered_tail->next = create_node(pdu);
                filtered_tail->next->prev = filtered_tail;
                filtered_tail = filtered_tail->next;
            }
        }
        current = current->next;
    }

    // Update the head and tail pointers for the original list
    head = NULL;
    tail = NULL;
}

// Function to export the filtered results to a JSON file
void export_json(Node* head) {
    // Open the output file in write mode
    FILE* json_file = fopen("output.json", "w");

    // Write the JSON data
    if (head == NULL) {
        fprintf(json_file, "{}");
    } else {
        Node* current = head;
        while (current != NULL) {
            LTE_PDU* pdu = current->pdu;
            fprintf(json_file, "{\"PDCP PDU\": %u, \"SPS Configuration\": {%u}, \"UE Context Identifier\": %u}", 
                    pdu->pdcp_pdu, pdu->sps_config, pdu->ue_context_id);

            // Add a comma separator for each node except the last one
            if (current != tail) {
                fprintf(json_file, ",");
            }
            current = current->next;
        }
    }

    // Close the output file
    fclose(json_file);
}

int main() {
    int M = 10; // Initialize with M elements

    init_list(M);

    // Add nodes to the list dynamically
    add_node(pdu1);
    add_node(pdu2);
    ...

    // Filter the list and export the results to a JSON file
    filter_list();
    export_json(head);

    return 0;
}
