#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of requests (M)
#define MAX_REQUESTS 1000

typedef struct {
    char method[4];
    char url[256];
    int64_t body_len;
    void* body;
} request_t;

typedef struct {
    pthread_mutex_t lock;
    request_t** requests;
    int count;
    int capacity;
} requests_manager_t;

requests_manager_t* requests_manager_init(int M) {
    requests_manager_t* manager = malloc(sizeof(requests_manager_t));
    manager->requests = (request_t**)calloc(M, sizeof(request_t*));
    manager->count = 0;
    manager->capacity = M;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void requests_manager_destroy(requests_manager_t* manager) {
    for (int i = 0; i < manager->capacity; i++) {
        if (manager->requests[i]) {
            free(manager->requests[i]->body);
            free(manager->requests[i]);
        }
    }
    free(manager->requests);
    pthread_mutex_destroy(&manager->lock);
    free(manager->requests_manager);
}

int requests_manager_add_request(requests_manager_t* manager, request_t* request) {
    if (manager->count >= manager->capacity) {
        // Resize the array when it's full
        int new_capacity = manager->capacity * 2;
        request_t** new_requests = (request_t**)realloc(manager->requests, new_capacity * sizeof(request_t*));
        manager->requests = new_requests;
        manager->capacity = new_capacity;
    }
    pthread_mutex_lock(&manager->lock);
    if (manager->count < manager->capacity) {
        // Add the request to the array
        manager->requests[manager->count++] = request;
    } else {
        printf("Error: Request queue is full\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

request_t* requests_manager_get_request(requests_manager_t* manager, int index) {
    if (index >= 0 && index < manager->count) {
        return manager->requests[index];
    } else {
        printf("Error: Request not found\n");
        return NULL;
    }
}
