// Define the maximum size of the array
const MAX_ARRAY_SIZE = 10000;

class DataCollector {
  constructor() {
    this.dataArray = [];
    this.paused = false;
    this.stream = null;
  }

  startStream(stream) {
    this.stream = stream;
    this.paused = false;
    this.dataArray = [];
  }

  pause() {
    this.paused = true;
  }

  resume() {
    if (this.paused) {
      this.paused = false;
    }
  }

  getStatus() {
    return this.paused ? "paused" : "resumed";
  }

  clearData() {
    this.dataArray = [];
  }

  collectData() {
    while (!this.paused && this.stream) {
      const data = this.stream.read();
      if (data) {
        this.dataArray.push(data);
      }
    }
  }
