Node* list = NULL;
int list_size = 0;
int serialized_count = 0;

// Serialize the linked list to a binary file
void serialize_list(const char* filename) {
    FILE* f = fopen(filename, "wb");
    if (!f) return;

    // Write the serialized count
    fwrite(&serialized_count, sizeof(int), 1, f);

    Node* current = list;
    while (current) {
        // Write each node's data
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
        current = current->next;
    }

    fclose(f);
}

// Deserialize the linked list from a binary file
void deserialize_list(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) return;

    // Read the serialized count
    fread(&serialized_count, sizeof(int), 1, f);

    for (int i = 0; i < serialized_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
        Node* new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = list;
        list = new_node;
    }

    fclose(f);
}

// Create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void create_list(int M) {
    if (list_size >= MAX_LIST_SIZE || M < 0)
        return;

    for (int i = 0; i < M; i++) {
        Node* new_node = malloc(sizeof(Node));
        new_node->data.RX_UE_INFORMATION_TAG[0] = 'R';
        new_node->data.RNTI = rand();
        strcpy(new_node->data.CRC_INDICATION_REL8_TAG, "CRCFlag");
        new_node->data.CRCFLAG = (unsigned char)rand() % 256;
        new_node->next = list;
        list = new_node;
        list_size++;
    }
}

// Get the current size of the linked list
int get_list_size() {
    return list_size;
}
