#include <time.h>

typedef struct {
    int log_id;
    int user_id;
    char* message;
    time_t timestamp;
    struct Node* prev;
    struct Node* next;
} LogEntry;

typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

Node* construct_paginated_log_list(LogEntry** logs, int total_logs, void* ls, int user_id, time_t start_timestamp, time_t end_timestamp, int max_length) {
    // Initialize variables
    int num_included = 0;
    Node* head = NULL;
    Node* tail = NULL;

    // Iterate over log entries to filter and construct paginated list
    for (int i = 0; i < total_logs; i++) {
        LogEntry* entry = &logs[i]->entry;
        if (entry->user_id == user_id && entry->timestamp >= start_timestamp && entry->timestamp <= end_timestamp) {
            Node* new_node = malloc(sizeof(Node));
            new_node->entry = entry;
            new_node->prev = NULL;
            new_node->next = NULL;

            // Update last_accessed timestamp and message (if necessary)
            time_t current_time = time(NULL);
            entry->timestamp = current_time;  // update last_accessed
            if (strlen(entry->message) + 20 > max_length) {
                int msg_len = strlen(entry->message);
                char* new_msg = malloc((msg_len / 2) * sizeof(char));
                strncpy(new_msg, entry->message, msg_len / 2);
                free(entry->message);
                entry->message = new_msg;
            }

            // Add node to list and update head/tail pointers
            if (head == NULL) {
                head = tail = new_node;
            } else {
                tail->next = new_node;
                new_node->prev = tail;
                tail = new_node;
            }
            num_included++;
        }
    }

    // Update count of included logs and return list pointer
    Node* paginated_list = (num_included > 0) ? head : NULL;
    if (paginated_list) {
        paginated_list->prev = NULL;  // reset prev pointer for new paginated list
    }
    return paginated_list;
}

