struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[CRC_INDICATION_REL8_TAG_SIZE];
};

void initAndPopulateNFAPCrcIndications(uint16_t numUes, struct NFAPI_CRC_INDICATION_PDU_T *ueStructures) {
    // Initialize pseudo-random number generator
    srand(time(NULL) + (uint32_t)numUes);

    // Initialize MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    for (int i = 0; i < numUes; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *ueStructure = &ueStructures[i];

        // Compute CRC flag using pseudo-random number generator
        uint8_t crcFlag = rand() % 2;

        // Initialize UE structure
        ueStructure->RX_UE_INFORMATION_TAG = i;
        ueStructure->RNTI = (uint32_t)i << 16;
        MD5_Update(&ctx, &ueStructure->RNTI, sizeof(ueStructure->RNTI));
        MD5_Update(&ctx, &crcFlag, sizeof(crcFlag));

        // Compute and store CRC indication
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5_Final(md5, &ctx);
        memcpy(ueStructure->CRC_INDICATION_REL8_TAG, md5, MD5_DIGEST_LENGTH);

        // Handle potential errors during initialization
        if (i == 0 && MD5_Error() != 0) {
            printf("Error initializing MD5 context: %s\n", MD5_ErrorString());
            return;
        }
    }

    MD5_Final(NULL, &ctx);
}

