void processText(const char *text) {
    // Compile regular expressions for Old Testament books
    regcomp(&bookRegex, OLD_TESTAMENT_BOOKS, REG_EXTENDED);

    // Find all matches of Old Testament books in the text
    const char *p = text;
    while (*p != '\0') {
        if (regexec(&bookRegex, p, MAX_UES, matches, 0) == 0) {
            for (int i = 0; i < MAX_UES; i++) {
                if (matches[i] && strlen(matches[i]) > 0) {
                    // Ignore punctuation and special characters
                    int j = 0;
                    while (j < strlen(matches[i])) {
                        if (!strchr("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", matches[i][j])) {
                            break;
                        }
                        j++;
                    }
                    if (j == strlen(matches[i])) {
                        printf("%s: %d\n", matches[i], j);
                    }
                }
            }
        }
        p = strstr(p, " ");
    }

    // Free regular expression memory
    regfree(&bookRegex);

    // Return object with book names and their frequencies
    return;
}

