typedef struct {
    uint64_t session_id;
    char client_ip[16];
    int connection_state;
} connection_context;

typedef struct {
    pthread_mutex_t lock;
    connection_context *table[HASH_TABLE_SIZE];
    int connections_init;
    uint64_t initialization_time;
    double lookup_time_avg;
    size_t memory_usage_max;
} connection_pool;

connection_pool *init_connection_pool() {
    connection_pool *pool = (connection_pool *)malloc(sizeof(connection_pool));
    pool->connections_init = 0;
    pool->initialization_time = 0;
    pool->lookup_time_avg = 0.0;
    pool->memory_usage_max = 0;
    pthread_mutex_init(&pool->lock, NULL);
    for(int i = 0; i < HASH_TABLE_SIZE; i++) {
        pool->table[i] = NULL;
    }
    return pool;
}

void *connection_pool_thread(void *arg) {
    connection_pool *pool = (connection_pool *)arg;
    // thread logic goes here
    pthread_exit(NULL);
}

int connect_and_setup(connection_pool *pool, uint64_t session_id, char *client_ip) {
    int hash_value = session_id % HASH_TABLE_SIZE;
    if(pool->table[hash_value] == NULL) {
        pool->connections_init++;
    }
    connection_context *connection = (connection_context *)malloc(sizeof(connection_context));
    strcpy(connection->client_ip, client_ip);
    connection->session_id = session_id;
    connection->connection_state = 1; // active
    pool->table[hash_value] = connection;
    return 0;
}

int disconnect_and_release(connection_pool *pool, uint64_t session_id) {
    int hash_value = session_id % HASH_TABLE_SIZE;
    if(pool->table[hash_value] != NULL && pool->table[hash_value]->session_id == session_id) {
        free(pool->table[hash_value]);
        pool->connections_init--;
        return 0;
    }
    return -1;
}

