use tokio::prelude::*;
use rand::{Rng, thread_rng};
use std::env;
use std::sync::atomic::{AtomicUsize, Ordering};
use chrono::prelude::*;

const MAX_CONCURRENT_TASKS: usize = 10;

#[derive(Debug)]
struct NFAPICRCINDICATIONPDU {
    rx_ue_info_tag: u16,
    rnti: u32,
    crc_ind_rel8_tag: u16,
    crcflag: bool,
}

async fn generate_crc_indications(n_tasks: usize) -> Result<(), Box<dyn std::error::Error>> {
    let max_concurrent = env::var("MAX_CONCURRENT_TASKS")
        .unwrap_or(MAX_CONCURRENT_TASKS.to_string())
        .parse::<usize>()
        .unwrap_or(MAX_CONCURRENT_TASKS);
    let n_per_task = env::var("N_PER_TASK")
        .unwrap_or("100".to_string())
        .parse::<usize>()
        .unwrap_or(100);

    if max_concurrent > MAX_CONCURRENT_TASKS {
        log::warn!("Maximum concurrent tasks set too high, limiting to {}", MAX_CONCURRENT_TASKS);
    }

    let (tx, mut rx) = tokio::sync::mpsc::channel(max_concurrent);

    for _ in 0..n_tasks {
        tokio::spawn(async move {
            let mut rng = rand::thread_rng();
            let nfa_pis: Vec<NFAPICRCINDICATIONPDU> = (0..n_per_task).map(|_| {
                NFAPICRCINDICATIONPDU {
                    rx_ue_info_tag: thread_rng().gen(),
                    rnti: thread_rng().gen::<u32>(),
                    crc_ind_rel8_tag: thread_rng().gen(),
                    crcflag: rng.gen(),
                }
            })
            .collect();

            info!("Task started at {}", Utc::now());
            tx.send(nfa_pis).await?;
            info!("Task completed at {}", Utc::now());

            Ok(())
        });
    }

    while let Some(res) = rx.recv().await {
        res?;
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();
    if let Err(e) = generate_crc_indications(10).await {
        error!("Error occurred: {}", e);
    }
}
