NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_crc_indication_pdu(int n, int* crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i;
        pdus[i].RNTI = i + 1;

        if (*crc_flag & (1 << i)) {
            pdus[i].CRC_INDICATION_REL8_TAG.crcFlag = 1;
        } else {
            pdus[i].CRC_INDICATION_REL8_TAG.crcFlag = 0;
        }
    }

    return pdus;
}

void free_nfa_pi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus, int n) {
    if (pdus != NULL) {
        free(pdus);
    }
