} ConnectionContext;

// Hash table structure with lock-free updates
typedef struct {
    pthread_mutex_t* mutex;
    size_t capacity;
    size_t size;
    ConnectionContext** contexts;
} HashTable;

// Function to initialize and populate the hash table
HashTable* init_hash_table(size_t capacity) {
    // Allocate memory for the hash table structure
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));

    // Initialize lock-free mutex
    table->mutex = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(table->mutex, NULL);

    // Initialize hash table parameters
    table->capacity = capacity;
    table->size = 0;
    table->contexts = (ConnectionContext**)malloc(capacity * sizeof(ConnectionContext*));

    return table;
}

// Function to update connection state with lock-free algorithm
void update_connection_state(HashTable* table, int session_id, int new_state) {
    // Calculate the hash value for the given session ID
    size_t index = session_id % table->capacity;

    // Lock-free update of connection state
    if (table->contexts[index] != NULL && table->contexts[index]->connection_state == 1) {
        table->contexts[index]->connection_state = new_state;
    }
}

// Function to log initialization parameters and errors
void log_init_params(HashTable* table, int init_time, size_t memory_usage) {
    printf("Initialization complete in %d ms with %zu bytes of memory used.\n", init_time, memory_usage);
}

