import socket
from threading import Thread

class NetworkPacketCollector:
    def __init__(self, packet_count):
        self.packet_count = packet_count
        self.packets = []
        self.paused = False

    def start_collection(self):
        self.collect_thread = Thread(target=self._collect_packets)
        self.collect_thread.start()

    def stop_collection(self):
        if self.collect_thread:
            self.collect_thread.join()
            self.collect_thread = None

    def pause_collection(self):
        self.paused = True

    def resume_collection(self):
        if self.paused:
            self.paused = False
        else:
            print("Collection is not paused.")

    def get_packets(self):
        return self.packets

    def clear_packets(self):
        self.packets = []

    def check_collection_status(self):
        if not self.collect_thread or self.paused:
            print("Collection is paused.")
        else:
            print("Collection is active.")

# Example usage
collector = NetworkPacketCollector(100)
collector.start_collection()
time.sleep(5)  # Collect packets for 5 seconds
collector.pause_collection()
collector.check_collection_status()  # Output: Collection is paused.
collector.resume_collection()
collector.stop_collection()
