sem_t *sem_create(const char *name, int value);
int sem_open_acquire(sem_t *sem, int timeout);
void sem_report_value(sem_t *sem);

// Configuration file defaults
#define SEM_DEFAULT_VALUE 1
#define SEM_DEFAULT_TIMEOUT 5000

sem_t *sem_create(const char *name, int value) {
    sem_t *sem = sem_open(name, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, value);
    if (sem == SEM_FAILED) {
        printf("Semaphore creation failed.\n");
        return NULL;
    }
    return sem;
}

int sem_open_acquire(sem_t *sem, int timeout) {
    int status = sem_wait_timeout(sem, timeout);
    if (status < 0) {
        printf("Semaphore acquisition timed out.\n");
    } else if (status == 0) {
        printf("Semaphore acquired successfully.\n");
    }
    return status;
}

void sem_report_value(sem_t *sem) {
    int value = sem_get_value(sem);
    printf("Semaphore value: %d\n", value);
}

int main() {
    // Initialize semaphore with default value and timeout
    sem_t *sem = sem_create("my_semaphore", SEM_DEFAULT_VALUE);

    if (sem == NULL) {
        return -1;
    }

    try {
        // Perform operations on the semaphore, reporting its state
        int status = sem_open_acquire(sem, SEM_DEFAULT_TIMEOUT);
        sem_report_value(sem);

        // Release the semaphore with an optional increment/decrement value
        int val = 2;
        sem_post(sem, val);

        // Report final semaphore value
        sem_report_value(sem);
    } catch (int e) {
        printf("Error: %d\n", e);
    }

    // Clean up the semaphore
    sem_close(sem);
    return 0;
}
