void processAudioFiles(const char* sourceDir, const char* destDir, NFAPI_CRC_INDICATION_PDU_T** crcList, size_t* crcCount) {
    DIR* dir = opendir(sourceDir);
    if (dir == NULL) {
        // Handle error
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_type, "MP3") != 0) continue;

        char sourceFilePath[1024];
        sprintf(sourceFilePath, "%s/%s", sourceDir, ent->d_name);

        char destFilePath[1024];
        sprintf(destFilePath, "%s/%s.ogx", destDir, ent->d_name);

        int fileExist = access(destFilePath, F_OK);
        if (fileExist == 0) {
            // Handle duplicate filename
            continue;
        }

        // Convert MP3 to OGG
        system("mp3toogg -i sourceFilePath -o destFilePath");

        NFAPI_CRC_INDICATION_PDU_T* crcItem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crcItem->RX_UE_INFORMATION_TAG = rand();
        crcItem->RNTI = rand();
        strcpy(crcItem->CRCFLAG, "Randomly Set CRC Flag");

        *crcList = realloc(*crcList, (*crcCount + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        *crcList[*crcCount] = crcItem;
        (*crcCount)++;

        closedir(dir);
        dir = opendir(sourceDir);

        if (dir == NULL || !ent) {
            // Handle error
            return;
        }

        char hostname[1024];
        sprintf(hostname, "yourhostname.com");

        struct hostent* host = gethostbyname(hostname);
        if (!host) {
            // Handle DNS resolution error
            return;
        }

        char ipStr[16];
        inet_ntop(AF_INET, host->h_addr, ipStr, sizeof(ipStr));

        u_char ipAddr[sizeof(struct in_addr)];
        memcpy(ipAddr, host->h_addr, sizeof(struct in_addr));

        free(crcItem);

        if (access(destDir, W_OK) == -1) {
            // Handle permission error
            return;
        }

        // Process audio files
        for (size_t i = 0; i < *crcCount; i++) {
            NFAPI_CRC_INDICATION_PDU_T* crcItem = (*crcList)[i];
            // Perform necessary operations on crcItem
        }
    }

    if (dir) closedir(dir);

    return 0;
}
