int parse_xml(const char* xml_file, const char* xpath_expr, const char* target_name) {
    xmlDoc* doc = NULL;
    xmlNode* root = NULL;
    xmlAttr* attr = NULL;
    UEInformation* ue_info = NULL;
    int rnti_sequence[50000][2];
    int num_ue = 0;

    // Initialize the XML parser
    if ((doc = xmlReadFile(xml_file, NULL, 0)) == NULL) {
        return -1; // Error reading file
    }

    // Find the root element of the XML document
    root = xmlDocGetRootElement(doc);
    if (root == NULL || !xmlStrEqual(root->name, (const xmlChar*)xpath_expr)) {
        return -2; // No matching XPath expression found
    }

    // Initialize a hash table to store UE information
    for (int i = 0; i < 50000; i++) {
        rnti_sequence[i][0] = -1;
        rnti_sequence[i][1] = -1;
    }

    // Parse the XML document and store UE information in the hash table
    xmlNode* node = root->children;
    while (node != NULL) {
        if (!xmlStrEqual(node->name, (const xmlChar*)target_name)) {
            node = node->next;
            continue;
        }
        attr = node->properties;
        while (attr != NULL) {
            if (!xmlStrEqual(attr->name, (const xmlChar*)"RX_UE_INFORMATION_TAG")) {
                attr = attr->next;
                continue;
            }
            ue_info = malloc(sizeof(UEInformation));
            ue_info->RX_UE_INFORMATION_TAG = xmlNodeGetContent((xmlNode*)attr);
            ue_info->RNTI = atoi(xmlNodeGetContent((xmlNode*)node->children));
            ue_info->CRC_INDICATION_REL8_TAG = xmlNodeGetContent((xmlNode*)node->next->children);
            ue_info->CRCFLAG = rand() % 2; // Set a random CRC flag

            // Check for duplicate RNTI sequence
            int exists = 0;
            for (int i = 0; i < num_ue; i++) {
                if ((ue_info->RNTI == rnti_sequence[i][0] && ue_info->RX_UE_INFORMATION_TAG == rnti_sequence[i][1])) {
                    exists = 1;
                    break;
                }
            }
            if (exists) {
                // Log error message and halt further processing
                log_error("Duplicate RNTI sequence found");
                free(ue_info);
                return -3; // Error: duplicate RNTI sequence detected
            }

            // Add UE information to the hash table
            rnti_sequence[num_ue][0] = ue_info->RNTI;
            rnti_sequence[num_ue][1] = ue_info->RX_UE_INFORMATION_TAG;
            num_ue++;

            free(ue_info);
            attr = attr->next;
        }
        node = node->next;
    }

    // Release memory and close the XML document
    for (int i = 0; i < num_ue; i++) {
        free(rnti_sequence[i][1]);
    }
    free(rnti_sequence);

    xmlFreeDoc(doc);
    return 0;
}
