#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <xml2.h>
#include <hashlib.h>

typedef struct {
    int RNTI;
    int sequenceNumber;
} FileStructure;

// Function to process and hash file stream with XML parsing
tuple(process_and_hash_file_stream(char* filePath, char* xmlNodeName, int maxThreadCount)) {
    // Initialize variables for file processing
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        return ("Error opening file", -1);
    }

    // Initialize variables for XML parsing
    xmlDocPtr doc = xmlReadFile(filePath, NULL, 0);
    if (!doc) {
        fclose(file);
        return ("Error parsing XML", -1);
    }

    // Initialize variables for MD5 hashing
    uint8_t* hashBuffer = (uint8_t*)malloc(16 * sizeof(uint8_t));
    MD5_CTX md5Context;
    int bytesRead, totalBytesRead = 0;

    // Process file in chunks and calculate MD5 hash
    while ((bytesRead = fread(hashBuffer, 1, 4096, file)) > 0) {
        MD5Update(&md5Context, hashBuffer, bytesRead);
    }

    // Calculate the final MD5 hash value
    uint8_t* hashValue = (uint8_t*)malloc(16 * sizeof(uint8_t));
    MD5Final(&md5Context, hashValue);

    char* hexDigest = (char*)malloc((2 * 16) + 1);
    for (int i = 0; i < 16; ++i) {
        sprintf(hexDigest + (i * 2), "%02x", *(hashValue + i));
    }
    hexDigest[32] = '\0';

    // Parse XML document using XPath
    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (!root) {
        fclose(file);
        free(hashBuffer);
        free(hashValue);
        free(hexDigest);
        return ("Error parsing XML", -1);
    }

    int fileStructuresCount = 0;
    FileStructure* fileStructures = (FileStructure*)malloc(50000 * sizeof(FileStructure));

    xmlNodePtr node = root->children;
    while (node) {
        if (strcmp(node->name, xmlNodeName) == 0) {
            if (fileStructuresCount >= 50000) {
                fclose(file);
                free(hashBuffer);
                free(hashValue);
                free(hexDigest);
                return ("Error: Reached maximum file structures limit", -1);
            }
            fileStructures[fileStructuresCount].RNTI = atoi(node->getChildren()->item->nodeValue);
            fileStructures[fileStructuresCount++].sequenceNumber = atoi(node->getChildren()->item->nextSibling->nodeValue);
        }
        node = node->next;
    }

    // Check for duplicate RNTI and sequence number
    for (int i = 0; i < fileStructuresCount; ++i) {
        for (int j = i + 1; j < fileStructuresCount; ++j) {
            if (fileStructures[i].RNTI == fileStructures[j].RNTI && fileStructures[i].sequenceNumber == fileStructures[j].sequenceNumber) {
                fclose(file);
                free(hashBuffer);
                free(hashValue);
                free(hexDigest);
                return ("Error: Duplicate RNTI and sequence number found", -1);
            }
        }
    }

    // Sort lines of the file
    qsort((void*)fileStructures, fileStructuresCount * sizeof(FileStructure), compare);

    // Extract sequence number from last line
    int sequenceNumber = fileStructures[fileStructuresCount - 1].sequenceNumber;

    fclose(file);
    free(hashBuffer);
    free(hashValue);
    free(hexDigest);

    return (hexDigest, sequenceNumber);
}

// Comparison function for sorting file structures by sequence number
int compare(const void* a, const void* b) {
    FileStructure* fa = (FileStructure*)a;
    FileStructure* fb = (FileStructure*)b;

    if (fa->sequenceNumber < fb->sequenceNumber)
        return -1;
    else if (fa->sequenceNumber > fb->sequenceNumber)
        return 1;
    else
        return 0;
}
