#define MAX_POOL_SIZE 50000
#define LOG_ERROR(fmt, ...) fprintf(stderr, fmt "\n")
#define LOG_INFO(fmt, ...) printf(fmt "\n")

typedef struct {
    int event_timestamp;
    int ue_id;
    int cell_id;
    float signal_strength;
    float packet_loss_rate;
} PHY_STATS_PDU_T;

void init_phy_stats_pool(PHY_STATS_PDU_T **pool);
void free_phy_stats_pool(PHY_STATS_PDU_T *pool);
int get_unique_ue_id(PHY_STATS_PDU_T *pool, int ue_id);
void clear_old_stats(PHY_STATS_PDU_T *pool);

PHY_STATS_PDU_T *phy_stats_pool = NULL;
size_t pool_size = 0;

void init_phy_stats_pool(PHY_STATS_PDU_T **pool) {
    phy_stats_pool = (PHY_STATS_PDU_T *)malloc(MAX_POOL_SIZE * sizeof(PHY_STATS_PDU_T));
    if (!phy_stats_pool) LOG_ERROR("Memory allocation failed");
    else {
        pool_size = MAX_POOL_SIZE;
        memset(phy_stats_pool, 0, MAX_POOL_SIZE * sizeof(PHY_STATS_PDU_T));
    }
}

void free_phy_stats_pool(PHY_STATS_PDU_T *pool) {
    if (pool) {
        free(pool);
        pool = NULL;
    }
}

int get_unique_ue_id(PHY_STATS_PDU_T *pool, int ue_id) {
    for (size_t i = 0; i < pool_size; i++) {
        if (phy_stats_pool[i].ue_id == ue_id) return -1; // duplicate UE ID found
    }
    return 0; // unique UE ID
}

void clear_old_stats(PHY_STATS_PDU_T *pool) {
    size_t threshold = pool_size / 2;
    for (size_t i = 0; i < pool_size; i++) {
        if (i > threshold) break; // only consider recent statistics
        phy_stats_pool[i].event_timestamp = 0; // reset timestamps and other fields
        phy_stats_pool[i].ue_id = 0;
        phy_stats_pool[i].cell_id = 0;
        phy_stats_pool[i].signal_strength = 0.0f;
        phy_stats_pool[i].packet_loss_rate = 0.0f;
    }
}

