            printf("Error allocating memory.\n");
            free(*events);
            *events = NULL;
            return;
        }
    }

    // Validate events
    for (int i = 0; i <= M; i++) {
        if ((*events)[i]->log_level < LOG_LEVEL_INFO || (*events)[i]->log_level > LOG_LEVEL_ERROR) {
            printf("Invalid log level.\n");
            free_events(*events, M);
            *events = NULL;
            return;
        }
    }

    // Process events
    for (int i = 0; i <= M; i++) {
        printf("Processing event %d\n", i);
    }

    free_events(*events, M);

    return;
}

void free_events(NFIX_LOGGING_EVENTS** events, int M) {
    for (int i = 0; i <= M; i++) {
        free((*events)[i]);
    }
    free(*events);
