// Function to generate a unique sequence number for each RNTI
int get_sequence_number(int rnti) {
    return (rnti * 31 + time(NULL)) % MAX_ENTRIES;
}

void initialize_crc_generator() {
    // Initialize pseudo-random number generator with current time, UE ID, and global network ID
    srand((time(NULL) ^ rand()) * (getpid() + getuid()));
}

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate unique RX_UE_INFORMATION_TAG and sequence number
    nfapi_crc->RX_UE_INFORMATION_TAG = (rnti * 31 + time(NULL)) % CRC_TABLE_SIZE;
    int sequence_number = get_sequence_number(rnti);
    nfapi_crc->sequence_number = sequence_number;

    return nfapi_crc;
}

void add_ue(NFAPI_CRC_INDICATION_PDU_T* ue, int rnti) {
    // Reinitialize pseudo-random number generator for the added UE
    initialize_crc_generator();

    // Validate CRC value and log error if invalid
    int crc_value = (ue->RX_UE_INFORMATION_TAG * 31 + time(NULL)) % CRC_TABLE_SIZE;
    if (crc_table[crc_value] == -1) {
        printf("Invalid CRC value for RNTI %d, sequence number %d.\n", rnti, ue->sequence_number);
    }

    // Add UE to the list
    // Implement synchronization mechanism here to handle concurrent access safely

    // Update maximum entries count and limit if exceeded
    static int max_entries = 0;
    if (max_entries >= MAX_ENTRIES) {
        printf("Maximum number of entries reached. Cannot add more UEs.\n");
        return;
    }

    max_entries++;
}

void remove_ue(NFAPI_CRC_INDICATION_PDU_T* ue, int rnti) {
    // Reinitialize pseudo-random number generator for the removed UE
    initialize_crc_generator();

    // Update maximum entries count and limit if exceeded
    static int max_entries = 0;
    if (max_entries > 0) {
        max_entries--;
    }
}

void destroy_ue(NFAPI_CRC_INDICATION_PDU_T* ue) {
    free(ue);
}
