#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 1000
#define CHECKSUM_THRESHOLD 1000

typedef struct {
    int PACKET_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PROTOCOL_TYPE;
    int SEQUENCE_NUMBER;
} MAC_PACKET;

// Function to generate a unique sequence number for each source IP
int generate_sequence_number(char* source_ip) {
    // Use the CRC32 algorithm for generating the sequence number
    unsigned long crc = 0xffffffff;
    int i = 0;
    while (*source_ip != '\0') {
        crc = (crc >> 8) ^ ((unsigned char *)source_ip)[i];
        i++;
    }
    return (int)crc;
}

// Function to manage the list of MAC_PACKET structures
void packet_list_manager(int num_packets, MAC_PACKET* packets[]) {
    // Initialize the list and checksum algorithm
    int packet_id = 0;
    for (int i = 0; i < num_packets; i++) {
        if (packet_id >= MAX_PACKETS) {
            printf("Error: Maximum number of packets exceeded.\n");
            return;
        }
        packets[i]->PACKET_ID = packet_id++;
        // Generate a unique sequence number for each source IP
        packets[i]->SEQUENCE_NUMBER = generate_sequence_number(packets[i]->SOURCE_IP);
    }

    // Validate the integrity of each packet by checksumming the payload
    int checksum = 0;
    for (int i = 0; i < num_packets; i++) {
        unsigned char* payload = (unsigned char*)packets[i]->PAYLOAD;
        int payload_len = strlen((char*)payload);
        for (int j = 0; j < payload_len; j++) {
            checksum += payload[j];
        }
        if (checksum != packets[i]->CHECKSUM) {
            printf("Error: Packet integrity failed.\n");
        }
    }

    // Monitor and log the frequency of each unique sequence generated
    int sequence_frequency[MAX_PACKETS];
    for (int i = 0; i < num_packets; i++) {
        sequence_frequency[packets[i]->SEQUENCE_NUMBER]++;
    }
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (sequence_frequency[i] > CHECKSUM_THRESHOLD) {
            printf("Warning: Potential bias or inefficiency detected.\n");
        }
    }

    // Support dynamic packet addition and removal
    int added_packets = 0;
    for (int i = num_packets - 1; i >= 0; i--) {
        if (packets[i]->PACKET_ID == packets[i-1]->PACKET_ID) {
            // Reinitialize the checksum algorithm for all affected packets
            int packet_id = packets[i]->PACKET_ID;
            for (int j = i; j < num_packets; j++) {
                if (packets[j]->PACKET_ID == packet_id) {
                    packets[j]->CHECKSUM = generate_checksum(packets[j]->PAYLOAD, strlen((char*)packets[j]->PAYLOAD));
                }
            }
        } else {
            added_packets++;
        }
    }

    // Log the frequency of each unique sequence generated
    for (int i = 0; i < num_packets; i++) {
        printf("Sequence %d: Frequency %d\n", packets[i]->SEQUENCE_NUMBER, sequence_frequency[packets[i]->SEQUENCE_NUMBER]);
    }
}

// Function to generate a checksum for the payload of a packet
int generate_checksum(unsigned char* payload, int length) {
    // Use the Adler-32 algorithm for generating the checksum
    unsigned long sum = 0;
    while (length--) {
        sum += *payload++;
        if ((sum & 0xff00) != 0) {
            sum >>= 8;
            sum += 0x10000;
        }
    }
    return (int)sum;
}
