int octree_data_structure_init(size_t feature_size, size_t num_leaf_nodes, size_t data_capacity, const char* file_path, int target_performance_metric, const uint8_t** external_data_sources) {
    FILE* file = fopen(file_path, "rb");
    if (!file) return -1; // handle error

    ue_info* ue_info_array = malloc(sizeof(ue_info) * num_leaf_nodes);
    if (!ue_info_array) return -2; // handle error

    chunk_data* chunks = malloc(sizeof(chunk_data) * data_capacity);
    if (!chunks) return -3; // handle error

    int i, j;
    for (i = 0; i < data_capacity; i++) {
        chunks[i].prefix_leaf = malloc(feature_size);
        chunks[i].data_array = malloc(data_capacity);

        // read file in chunks
        fseek(file, i * feature_size + sizeof(ue_info), SEEK_SET);
        fread(chunks[i].prefix_leaf, 1, feature_size, file);

        // process chunk asynchronously
        pthread_t thread;
        pthread_create(&thread, NULL, (void*)process_chunk, &chunks[i]);
    }

    // validate integrity of each chunk
