    for (i = 0; i < data_capacity; i++) {
        fread(file_contents + i * feature_size, 1, feature_size, file);
    }

    uint8_t* sorted_file_contents = malloc(feature_size * data_capacity);
    if (!sorted_file_contents) return -6; // handle error

    quicksort(sorted_file_contents, 0, data_capacity * feature_size - 1);

    // extract sequence number from last line
    size_t extracted_sequence_number;
    fread(&extracted_sequence_number, sizeof(size_t), 1, file);

    // integrate external data sources
