#include <iostream>
#include <fstream>
#include <sstream>
#include <json/json.h>
#include <map>
#include <vector>

using namespace std;
using namespace json;

// Function to parse JSON object from a line
void parseJSON(const string& line, map<string, string>& obj) {
    istringstream iss(line);
    Json::Value root;
    Json::Reader reader;
    if (reader.parse(iss, root)) {
        for (auto& pair : root["data"].getMemberNames()) {
            obj[pair] = root["data"][pair].asString();
        }
    }
}

// Function to calculate frequency of events per hour
void frequencyEventsPerHour(map<string, string>& obj) {
    // Extract timestamp field and extract hour from it
    string timestamp = obj["timestamp"];
    int hour = stoi(timestamp.substr(11, 2));

    // Map for storing events by user ID and geographic location
    map<string, pair<int, map<string, int>>> frequency;

    // Aggregate events by user ID and geographic location
    if (frequency.find(obj["user_id"]) == frequency.end()) {
        frequency[obj["user_id"]].second.clear();
    }
    frequency[obj["user_id"]].first++;
    frequency[obj["user_id"]].second[obj["geographic_location"]]++;

    // Update frequency map with new event
    frequency[obj["user_id"]].second[obj["geographic_location"]] = max(frequency[obj["user_id"]].second[obj["geographic_location"]], 1);
}

// Function to aggregate event types by user ID
void aggregateEventTypes(map<string, string>& obj) {
    // Map for storing events by user ID and event type
    map<string, map<string, int>> event_types;

    // Aggregate events by user ID and event type
    if (event_types.find(obj["user_id"]) == event_types.end()) {
        event_types[obj["user_id"]].clear();
    }
    event_types[obj["user_id"]][obj["event_type"]]++;

    // Update event types map with new event
    event_types[obj["user_id"]][obj["event_type"]] = max(event_types[obj["user_id"]][obj["event_type"]], 1);
}

// Function to calculate average duration between consecutive events
void calculateAverageDuration(map<string, string>& obj) {
    // Map for storing event intervals by user ID
    map<string, vector<int>> event_intervals;

    // Calculate event interval and update map with new event
    if (event_intervals.find(obj["user_id"]) == event_intervals.end()) {
        event_intervals[obj["user_id"]].clear();
    }
    event_intervals[obj["user_id"]].push_back(stoi(obj["timestamp"].substr(11, 2)) - stoi(obj["previous_timestamp"].substr(11, 2)));
}

// Function to generate summary report
void generateSummaryReport(map<string, map<pair<int, string>, int>>& frequency) {
    // Print total number of events and most frequent event type per user
    for (auto& pair : frequency) {
        cout << "Total events: " << pair.second.size() << endl;
        auto most_frequent_event = *max_element(pair.second.begin(), pair.second.end(),
            [](const pair<string, int>& a, const pair<string, int>& b) { return a.second < b.second; });
        cout << "Most frequent event type: " << most_frequent_event.first << endl;
    }
}

// Function to identify and flag anomalies in the event pattern
void identifyAnomalies(map<string, map<pair<int, string>, int>>& frequency) {
    // Flag events that are more than 2 standard deviations away from the mean duration
    for (auto& pair : frequency) {
        vector<int> durations;
        for (auto& inner_pair : pair.second) {
            durations.push_back(inner_pair.second);
        }
        double mean = mean(durations);
        double std_deviation = stdev(durations, mean);

        // Flag events with duration more than 2 standard deviations away from the mean
        for (auto& inner_pair : pair.second) {
            if (abs(inner_pair.second - mean) > 2 * std_deviation) {
                cout << "Anomaly detected: User ID " << pair.first << ", Event Type " << inner_pair.first << endl;
            }
        }
    }
}

int main() {
    ifstream file("log_file.json");
    string line;

    // Map for storing events by user ID and geographic location
    map<string, map<pair<int, string>, int>> frequency;

    // Map for storing event intervals by user ID
    map<string, vector<int>> event_intervals;

    while (getline(file, line)) {
        map<string, string> obj;
        parseJSON(line, obj);
        frequencyEventsPerHour(obj);
        aggregateEventTypes(obj);

        // Calculate average duration between consecutive events
        if (event_intervals.find(obj["user_id"]) != event_intervals.end()) {
            for (int i = 0; i < event_intervals[obj["user_id"]].size() - 1; i++) {
                calculateAverageDuration(obj);
            }
        }

        // Update previous timestamp and calculate average duration
        obj["previous_timestamp"] = obj["timestamp"];
    }

    // Generate summary report
    generateSummaryReport(frequency);

    // Identify and flag anomalies in the event pattern
    identifyAnomalies(frequency);

    return 0;
}

// Function to calculate mean of a vector
double mean(const vector<int>& numbers) {
    int sum = 0;
    for (int number : numbers) {
        sum += number;
    }
    return static_cast<double>(sum) / numbers.size();
}

// Function to calculate standard deviation of a vector
double stdev(const vector<int>& numbers, double mean) {
    double sum = 0.0;
    for (int num : numbers) {
        sum += pow(num - mean, 2);
    }
    return sqrt(sum / static_cast<double>(numbers.size()));
}
