#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <algorithm>

class NetworkDataProcessor {
private:
    std::vector<double> dataset;
    int samplingInterval;
    std::string aggregationMethod;

public:
    void setDataset(const std::vector<double>& data) {
        dataset = data;
    }

    void setSamplingInterval(int interval) {
        samplingInterval = interval;
    }

    void setAggregationMethod(std::string method) {
        aggregationMethod = method;
    }

    // Method 1: Generate sample of data points
    std::vector<double> generateSample() {
        std::vector<double> sample;
        for (int i = 0; i < dataset.size(); i += samplingInterval) {
            double sum = 0.0;
            int count = 0;
            for (int j = i; j < (i + samplingInterval) && j < dataset.size(); j++) {
                if (!std::isnan(dataset[j])) {
                    sum += dataset[j];
                    count++;
                }
            }
            if (aggregationMethod == "sum") {
                sample.push_back(sum);
            } else if (aggregationMethod == "avg") {
                sample.push_back(sum / count);
            } else if (aggregationMethod == "max") {
                sample.push_back(std::max_element(dataset.begin() + i, dataset.begin() + (i + samplingInterval)) - dataset.begin());
            }
        }
        return sample;
    }

    // Method 2: Aggregate the entire dataset
    double aggregateDataset() {
        double sum = 0.0;
        int count = 0;
        for (const auto& value : dataset) {
            if (!std::isnan(value)) {
                sum += value;
                count++;
            }
        }
        if (aggregationMethod == "sum") {
            return sum;
        } else if (aggregationMethod == "avg") {
            return sum / count;
        } else if (aggregationMethod == "max") {
            return *std::max_element(dataset.begin(), dataset.end());
        }
        return 0.0; // default value
    }

    // Method 3: Calculate rolling statistics
    std::vector<double> calculateRollingStatistics(int windowSize) {
        std::vector<double> rollingStats;
        double sum = 0.0;
        int count = 0;
        for (int i = 0; i < dataset.size(); i++) {
            if (!std::isnan(dataset[i])) {
                sum += dataset[i];
                count++;
            }
            if ((i + 1) % windowSize == 0 && i > 0) {
                rollingStats.push_back(sum / count);
                sum -= dataset[i - windowSize + 1];
                count--;
            }
        }
        return rollingStats;
    }

    // Method 4: Provide a detailed summary of the dataset
    std::string summarizeDataset() {
        std::string summary = "Dataset Summary:\n";
        double mean = aggregateDataset();
        double median = 0.0;
        if (!dataset.empty()) {
            std::nth_element(dataset.begin(), dataset.begin() + (dataset.size() / 2), dataset.end());
            median = *std::max_element(dataset.begin(), dataset.begin() + (dataset.size() / 2));
        }
        double stdev = 0.0;
        if (!dataset.empty()) {
            for (const auto& value : dataset) {
                stdev += std::pow(value - mean, 2);
            }
            stdev = std::sqrt(stdev / dataset.size());
        }
        summary += "Mean: " + std::to_string(mean) + "\n";
        summary += "Median: " + std::to_string(median) + "\n";
        summary += "Standard Deviation: " + std::to_string(stdev) + "\n";
        return summary;
    }

    // Method 5: Dynamically update the dataset and sampling parameters
    void updateDataset(const std::vector<double>& newDataset, int newSamplingInterval, const std::string& newAggregationMethod) {
        setDataset(newDataset);
        setSamplingInterval(newSamplingInterval);
        setAggregationMethod(newAggregationMethod);
    }

    // Export processed data to CSV format
    void exportData(std::ofstream& file) {
        file << "Timestamp," << aggregationMethod << "_Value\n";
        for (int i = 0; i < dataset.size(); i++) {
            if (!std::isnan(dataset[i])) {
                file << i << "," << dataset[i] << "\n";
            }
        }
    }

    // Override toString method
    std::string toString() {
        std::stringstream ss;
        ss << "Dataset: [" << std::accumulate(dataset.begin(), dataset.end(), 0.0, [this](double sum, double value) { return sum + (value != std::nan(")) << "],\n";
        ss << "Sampling Interval: " << samplingInterval << "\n";
        ss << "Aggregation Method: " << aggregationMethod << "\n";
        ss << summarizeDataset();
        return ss.str();
    }
};
