void populate_NFAPI_CRC_INDICATION_PDU_T_array(NFAPI_CRC_INDICATION_PDU_T** pNFAPI_CRC_INDICATION_PDU_T_array, size_t num_users) {
    if (pNFAPI_CRC_INDICATION_PDU_T_array == NULL || num_users <= 0) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    int* rnti_whitelist = get_rnti_whitelist();
    for (size_t i = 0; i < num_users; i++) {
        array[i].RX_UE_INFORMATION_TAG = malloc(100);
        array[i].RNTI = rand() % 100 + 1;
        while (array[i].RNTI > 50) { // Check RNTI value against whitelist
            if (!is_rnti_in_whitelist(array[i].RNTI, rnti_whitelist)) {
                printf("Invalid RNTI: %d\n", array[i].RNTI);
                return;
            }
        }
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    free(rnti_whitelist);
    *pNFAPI_CRC_INDICATION_PDU_T_array = array;
}

int is_rnti_in_whitelist(int rnti, int* whitelist) {
    for (size_t i = 0; i < sizeof(whitelist) / sizeof(whitelist[0]); i++) {
        if (rnti == whitelist[i]) {
            return 1; // Found in whitelist
        }
    }
    return 0; // Not found in whitelist
}

int get_rnti_whitelist() {
    FILE* file = fopen("rnti_whitelist.txt", "r");
    int rnti;
    int count = 0;
    while (fscanf(file, "%d\n", &rnti) == 1) {
        count++;
    }
    rewind(file);
    int* whitelist = malloc(count * sizeof(int));
    for (size_t i = 0; i < count; i++) {
        fscanf(file, "%d\n", &whitelist[i]);
    }
    fclose(file);
    return whitelist;
}
