        md5_update(md5_ctx, &data_chunk[i], 1);
    }
    char hash[16];
    md5_finalize(md5_ctx, hash);

    // Periodically check network connection status
    int retry_count = 0;
    while (retry_count < 10) {
        if (!network_connection_status()) {
            // Network connection lost, enter low-power mode
            low_power_mode();
            break;
        }
        retry_count++;
    }

    if (retry_count >= 10) {
        // Connection remains lost, resume normal operation and clear previous data
        device_context.ue.RX_UE_INFORMATION_TAG = rand() % 256;
