            retryInterval *= 2; // Double the retry interval
        } else {
            printf("Network connection established\n");
            failedAttempts = 0;
            retryInterval = 100; // Reset the retry interval
            break;
        }
    }

    // Return the device identifier map with error codes
    return (void*)deviceIdMapSize;
}

