typedef struct {
    int packet_id;
    // Add other relevant data members as needed
} MAC_TRANSACTION_PDU;

// Dynamic queue structure
typedef struct {
    MAC_TRANSACTION_PDU* packets;
    size_t capacity, used;
    pthread_mutex_t mutex;
    sem_t empty_sem, full_sem;
} Queue;

Queue* queue_init(size_t initial_capacity) {
    Queue* q = malloc(sizeof(Queue));
    q->capacity = initial_capacity;
    q->used = 0;
    q->packets = malloc(initial_capacity * sizeof(MAC_TRANSACTION_PDU));
    pthread_mutex_init(&q->mutex, NULL);
    sem_init(&q->empty_sem, 0, q->capacity);
    sem_init(&q->full_sem, 0, 0);
    return q;
}

void queue_free(Queue* q) {
    free(q->packets);
    pthread_mutex_destroy(&q->mutex);
    sem_destroy(&q->empty_sem);
    sem_destroy(&q->full_sem);
    free(q);
}

int enqueue(Queue* q, MAC_TRANSACTION_PDU packet) {
    pthread_mutex_lock(&q->mutex);
    if (sem_wait(&q->empty_sem) == -1) return -1; // Queue is full
    q->packets[q->used++] = packet;
    sem_post(&q->full_sem);
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int dequeue(Queue* q, MAC_TRANSACTION_PDU* packet) {
    pthread_mutex_lock(&q->mutex);
    if (sem_wait(&q->full_sem) == -1) return -1; // Queue is empty
    *packet = q->packets[--q->used];
    sem_post(&q->empty_sem);
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int resize_queue(Queue* q, size_t new_capacity) {
