#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <hash.h>

#define MAX_QUEUE_SIZE 1000

typedef struct {
    int packet_id;
    char data[1024];
} MAC_TRANSACTION_PDU;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
int queue_size = 0;
MAC_TRANSACTION_PDU *queue[MAX_QUEUE_SIZE];

void process_and_hash_file(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, enqueue_thread_func, NULL);

    while (1) {
        // Read file in chunks
        char buffer[1024];
        int bytes_read = read(fd, buffer, 1024);
        if (bytes_read < 0) {
            perror("Error reading file");
            break;
        }

        pthread_mutex_lock(&queue_lock);
        for (int i = 0; i < bytes_read / sizeof(MAC_TRANSACTION_PDU); i++) {
            MAC_TRANSACTION_PDU* packet = (MAC_TRANSACTION_PDU*)buffer + i * sizeof(MAC_TRANSACTION_PDU);
            // Calculate MD5 hash of the packet
            unsigned char md5_hash[16];
            int result = hash_md5(packet->data, strlen(packet->data), md5_hash);
            if (result < 0) {
                perror("Error calculating MD5 hash");
                break;
            }

            // Enqueue the packet
            if (queue_size == MAX_QUEUE_SIZE) {
                pthread_cond_signal(&queue_cond);
                pthread_mutex_unlock(&queue_lock);
                usleep(10000); // Yield to other threads
                pthread_mutex_lock(&queue_lock);
            }
            queue[queue_size++] = packet;
        }
        pthread_mutex_unlock(&queue_lock);

        if (bytes_read < 1024) {
            break; // End of file reached
        }
    }

    close(fd);
}

void* enqueue_thread_func(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        while (queue_size == MAX_QUEUE_SIZE) {
            pthread_cond_wait(&queue_cond, &queue_lock);
        }
        for (int i = 0; i < queue_size; i++) {
            MAC_TRANSACTION_PDU* packet = queue[i];
            // Process and log the packet
            printf("Packet ID: %d, Hash: ", packet->packet_id);
            for (int j = 0; j < 16; j++) {
                printf("%02x", md5_hash[j]);
            }
            printf("\n");
        }
        queue_size = 0;
        pthread_mutex_unlock(&queue_lock);
    }
}

int main() {
    process_and_hash_file("example.txt");
    return 0;
}
