    }

def replace_placeholders(config_file, placeholders, values):
    for key, value in placeholders.items():
        command = f"sed -i 's/{key}/ {value}/g' {config_file}"
        try:
            subprocess.run(command.split(" "), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"sed command failed: {e}")

def add_crc_indication_pdu_t(config_file, nfapi_crc_indication_pdu_ts):
    for pdu in nfapi_crc_indication_pdu_ts:
        command = f"sed -i '1a\\{pdu}" at the end of file {config_file}'"
        try:
            subprocess.run(command.split(" "), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"sed command failed: {e}")

def main():
    placeholders = {"placeholder1": "value1", "placeholder2": "value2"}
    values = {"value1": "actual_value1", "value2": "actual_value2"}
    nfapi_crc_indication_pdu_ts = [create_nfapi_crc_indication_pdu_t(i) for i in range(10)]

    replace_placeholders("config.txt", placeholders, values)
    add_crc_indication_pdu_t("config.txt", nfapi_crc_indication_pdu_ts)

if __name__ == "__main__":
