        template = config_file.read()

    placeholders = re.findall(r"{{(.*)}}", template)

    if not placeholders:
        raise ValueError("No placeholders found in the configuration file")

    for placeholder in placeholders:
        value = user_values.get(placeholder)
        if value is None:
            raise KeyError(f"No value provided for placeholder '{placeholder}'")
        template = re.sub(rf"{{({placeholder})}}", str(value), template)

