typedef struct {
    int sequence_number;
    time_t start_time;
} PacketContext;

void process_network_packets(int M) {
    // Initialize packet processing queue
    pthread_mutex_init(&queue_lock, NULL);
    packet_queue = (PacketContext**)malloc(M * sizeof(PacketContext*));

    for (int i = 0; i < M; i++) {
        packet_queue[i] = (PacketContext*)malloc(sizeof(PacketContext));
        packet_queue[i]->sequence_number = i;
        packet_queue[i]->start_time = time(NULL);
    }

    // Define a packet processing function
    void* process_packet(void* context) {
        PacketContext* packet = (PacketContext*)context;
        // Validate and process the packet here...
        return NULL;
    }

    // Start M concurrent packet processing tasks
    pthread_t threads[M];
    for (int i = 0; i < M; i++) {
        pthread_create(&threads[i], NULL, process_packet, packet_queue[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < M; i++) {
        pthread_join(threads[i], NULL);
    }

    // Release allocated memory
    for (int i = 0; i < M; i++) {
        free(packet_queue[i]);
    }
    free(packet_queue);

    pthread_mutex_destroy(&queue_lock);
}
