        // log initialization attempt
        printf("Initialization successful. Attempted %d times.\n", attempts);

        // update CRC_PDUs based on performance metrics
        if (check_latency() > 100) {
            for (i = 0; i < N; i++) {
                crc_pdus[i].CRCFLAG = 1;
            }
        } else {
            for (i = 0; i < N; i++) {
                crc_pdus[i].CRCFLAG = 0;
            }
