    "[^a-zA-Z]?(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua| Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther)\\b"
};

// Helper function to process text and extract Bible book names
struct book_names {
    char* name;
    int count;
};
struct book_names extract_book_names(const char* text, unsigned int size) {
    // Initialize result struct
    struct book_names result = {NULL, 0};

    // Loop through regular expressions for Old Testament book names
    for (int i = 0; i < sizeof(old_testament_re) / sizeof(*old_testament_re); i++) {
        // Compile the pattern for this iteration
        regex_t re;
        regcomp(&re, old_testament_re[i], REG_EXTENDED | REG_NEWLINE);

        // Search for matches in the text
        regex_match_t match;
        regmatch_t matched;
        int match_count = 0;
        for (int j = 0; j < size; j++) {
            if (regexec(&re, &text[j], strlen(text) - j, &matched, 0) == 0) {
                // Ignore punctuation and special characters
                if (j + matched.re_nomatch > j && !isalpha(text[j + matched.re_nomatch])) {
                    continue;
                }

                // Update result struct
                char* book_name = malloc((matched.re_namelen + 1) * sizeof(char));
                strcpy(book_name, &text[matched.re_start]);
                if (result.name == NULL || strcmp(result.name, book_name) != 0) {
                    free(result.name);
                    result.name = book_name;
                    result.count++;
                } else {
                    free(book_name);
                }
            }
        }

        // Clean up
        regfree(&re);
    }

    return result;
}

