int validate_oauth_token(char* json_string, size_t N) {
    // Parse JSON string
    json_object* jobj = json_object_from_string(json_string);

    if (json_object_get_type(jobj, "access_token") == json_type_null || 
        json_object_get_type(jobj, "expires_in") != json_type_int || 
        json_object_get_string(jobj, "token_type") != "Bearer") {
        return 0;
    }

    int expires_in = json_object_get_int(jobj, "expires_in");
    if (expires_in <= 0) {
        return 0;
    }

    // Handle null encryption for testing
    des_key_schedule_key(des_key_generate(), NULL);

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Set RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        strcpy(pdu_array[i].RNTI, "000001");
        pdu_array[i].CRC_INDICATION_REL8_TAG = (int)rand() % 256;

        // Set timestamp and sequence number in CRC_INDICATION_REL8_TAG
        pdu_array[i].CRC_INDICATION_REL8_TAG |= ((int)time(NULL)) << 16;
        pdu_array[i].CRC_INDICATION_REL8_TAG += rand() % 256;
    }

    return pdu_array;
}

