} NFAPI_CRC_INDICATION_MEM_POOL;

void* nfapi_crc_indication_populate(int num_users, void* password_info, void* connection_info, void (*callback)(void*)) {
    if (!password_info || !connection_info || !callback) {
        return NULL;
    }

    // Initialize memory pool
    NFAPI_CRC_INDICATION_MEM_POOL* mem_pool = (NFAPI_CRC_INDICATION_MEM_POOL*)malloc(sizeof(NFAPI_CRC_INDICATION_MEM_POOL));
    mem_pool->pool_size = 1024;
    mem_pool->pdus = malloc(mem_pool->pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Validate RNTI values
    int* rnti_whitelist = (int*)malloc(256 * sizeof(int)); // assume max 256 entries in whitelist
    int whitelist_size = read_rnti_whitelist(rnti_whitelist);
    mem_pool->rnti_whitelist = rnti_whitelist;
    mem_pool->whitelist_size = whitelist_size;

    for (int i = 0; i < num_users; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &mem_pool->pdus[i];
        // Populate PDU structure
        pdu->RX_UE_INFORMATION_TAG = valid_rx_ue_info_tag;
        pdu->RNTI = get_valid_rnti(i);
        pdu->CRC_INDICATION_REL8_TAG = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        pdu->CRC_INDICATION_REL8_TAG->CRCFLAG = rand() % 2; // randomly set CRCFLAG

        // Validate RNTI value
        for (int j = 0; j < whitelist_size; j++) {
            if (pdu->RNTI == mem_pool->rnti_whitelist[j]) {
                break;
            }
        }

        if (j >= whitelist_size) {
            free(pdu->CRC_INDICATION_REL8_TAG);
            return NULL;
        }
    }

    // Reclaim unused memory periodically
    reclaim_unused_memory(mem_pool);

    // Log successful population of PDU structures
    log_population_info(num_users, mem_pool);

    return mem_pool;
}

void nfapi_crc_indication_free(NFAPI_CRC_INDICATION_MEM_POOL* mem_pool) {
    if (!mem_pool) {
        return;
    }

    free(mem_pool->pdus);
    free(mem_pool->rnti_whitelist);
    free(mem_pool);
}
