char* generateCertificate(struct OAuthRequest* request) {
    // Fetch private key and certificate from location specified in request
    FILE* privateKeyFile = fopen(request->privateKeyLocation, "rb");
    FILE* certificateFile = fopen(request->certificateLocation, "rb");

    if (!privateKeyFile || !certificateFile) {
        return NULL;
    }

    fseek(privateKeyFile, 0L, SEEK_END);
    long privateKeySize = ftell(privateKeyFile);
    fseek(privateKeyFile, 0L, SEEK_SET);

    fseek(certificateFile, 0L, SEEK_END);
    long certificateSize = ftell(certificateFile);
    fseek(certificateFile, 0L, SEEK_SET);

    char* privateKeyData = (char*)malloc(privateKeySize + 1);
    char* certificateData = (char*)malloc(certificateSize + 1);

    fread(privateKeyData, 1, privateKeySize, privateKeyFile);
    privateKeyData[privateKeySize] = '\0';
    fclose(privateKeyFile);

    fread(certificateData, 1, certificateSize, certificateFile);
    certificateData[certificateSize] = '\0';
    fclose(certificateFile);

    char* pemData = (char*)malloc(privateKeySize + certificateSize + 2);
    sprintf(pemData, "%s\n%s", privateKeyData, certificateData);
    free(privateKeyData);
    free(certificateData);

    return pemData;
}

struct NFAPI_CRC_INDICATION_PDU_T* generateNFAPIList(int listSize) {
    struct NFAPI_CRC_INDICATION_PDU_T* list = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(listSize * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

