        list[i].RNTI = rand();
        sprintf(list[i].CRC_INDICATION_REL8_TAG, "FLAG_%d", rand());
    }

    return list;
}

void freeNFAPIList(struct NFAPI_CRC_INDICATION_PDU_T* list) {
    free(list);
