NFAPI_CRC_INDICATION_PDU_T* generate_nfapi_crc_indication_pdu(int n, FILE** log_file) {
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);

    // Initialize error handling
    if (!ssl) {
        *log_file << "Error initializing SSL" << endl;
        return NULL;
    }

    // Perform authentication and authorization with the remote service
    int auth_status = perform_oauth_auth(ssl, log_file);
    if (auth_status != 0) {
        *log_file << "Authentication failed" << endl;
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Retrieve certificate and private key from the remote service
    X509* cert = get_certificate_from_service(ssl, log_file);
    if (!cert) {
        *log_file << "Error retrieving certificate" << endl;
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Concatenate the certificate and private key into a single PEM file
    BIO* bio = BIO_new(BIO_s_mem());
    PEM_write_bio_X509(bio, cert);

    // Generate the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        // Generate a random RNTI and CRCFLAG
        int rnti = rand() % 100;
        int crcflag = rand() % 2;

        // Set the RX_UE_INFORMATION_TAG to a valid value
        char tag[64];
        for (int j = 0; j < 63; j++) {
            tag[j] = 'a' + (rand() % 26);
        }
        tag[63] = '\0';

        pdu_list[i].RX_UE_INFORMATION_TAG = tag;
        pdu_list[i].RNTI = rnti;

        // Set the CRC_INDICATION_REL8_TAG to a valid value
        char* crc_tag = (char*)malloc(64);
        for (int j = 0; j < 63; j++) {
            crc_tag[j] = 'a' + (rand() % 26);
        }
        crc_tag[63] = '\0';
        pdu_list[i].CRC_INDICATION_REL8_TAG = crc_tag;

        // Set the CRCFLAG to a valid value
        pdu_list[i].CRCFLAG = crcflag;
    }

    SSL_free(ssl);
    SSL_CTX_free(ctx);

    return pdu_list;
}
