// Custom linked list node structure for MAC_FRAME_T and NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    void* data;
    struct {
        struct {
            uint8_t* mac_header;
            size_t header_len;
        } mac_frame;
        struct {
            uint8_t* mac_payload;
            size_t payload_len;
            uint64_t random_mac_addr;
        } mac_payload_info;
    } node;
} custom_list_node;

// Custom linked list structure for MAC_FRAME_T and NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    custom_list_node* head;
    custom_list_node* tail;
    size_t count;
    pthread_mutex_t lock;
} custom_linked_list;

// Initialize the custom linked list with a given initial capacity
custom_linked_list* create_custom_linked_list(size_t initial_capacity) {
    custom_linked_list* new_list = (custom_linked_list*)malloc(sizeof(custom_linked_list));
    new_list->head = NULL;
    new_list->tail = NULL;
    new_list->count = 0;
    pthread_mutex_init(&new_list->lock, NULL);
    return new_list;
}

// Function to generate the list of MAC_FRAME_T structures
void generate_mac_frame_list(size_t M, custom_linked_list** mac_frame_list) {
    *mac_frame_list = create_custom_linked_list(M);

    for (size_t i = 0; i < M; i++) {
        uint8_t* mac_header = (uint8_t*)malloc(6); // assuming 6 bytes for MAC header
        size_t header_len = 6;

        uint8_t* mac_payload = (uint8_t*)malloc(rand() % 100 + 1); // assuming random payload length between 1 and 100 bytes
        size_t payload_len = rand() % 100 + 1;

        uint64_t random_mac_addr = rand();

        custom_linked_list* list = *mac_frame_list;
        pthread_mutex_lock(&list->lock);
        custom_list_node* new_node = (custom_list_node*)malloc(sizeof(custom_list_node));
        new_node->node.mac_frame.mac_header = mac_header;
        new_node->node.mac_frame.header_len = header_len;
        new_node->node.mac_payload_info.mac_payload = mac_payload;
        new_node->node.mac_payload_info.payload_len = payload_len;
        new_node->node.mac_payload_info.random_mac_addr = random_mac_addr;

        if (list->count == 0) {
            list->head = &new_node->node;
            list->tail = &new_node->node;
        } else {
            custom_list_node* prev_tail = &list->tail->node;
            prev_tail->next = &new_node->node;
            list->tail = &new_node->node;
        }

        list->count++;
        pthread_mutex_unlock(&list->lock);
    }
}

// Function to generate the list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_nfa_pi_crc_indication_pdu_list(size_t M, custom_linked_list** nfa_pi_crc_indication_pdu_list) {
    *nfa_pi_crc_indication_pdu_list = create_custom_linked_list(M);

    for (size_t i = 0; i < M; i++) {
        uint8_t* rx_ue_info_tag = (uint8_t*)malloc(16); // assuming 16 bytes for RX UE INFORMATION TAG
        size_t tag_len = 16;

        int rnti = rand(); // assuming random RNTI value

        bool crcflag = rand() % 2; // assuming random CRCFLAG value

        custom_linked_list* list = *nfa_pi_crc_indication_pdu_list;
        pthread_mutex_lock(&list->lock);
        custom_list_node* new_node = (custom_list_node*)malloc(sizeof(custom_list_node));
        new_node->node.rx_ue_info_tag = rx_ue_info_tag;
        new_node->node.tag_len = tag_len;
        new_node->node.rnti = rnti;
        new_node->node.crcflag = crcflag;

        if (list->count == 0) {
            list->head = &new_node->node;
            list->tail = &new_node->node;
        } else {
            custom_list_node* prev_tail = &list->tail->node;
            prev_tail->next = &new_node->node;
            list->tail = &new_node->node;
        }

        list->count++;
        pthread_mutex_unlock(&list->lock);
    }
}

// Function to integrate with the remote analytics service via its REST API
void integrate_with_analytics_service(custom_linked_list* mac_frame_list, custom_linked_list* nfa_pi_crc_indication_pdu_list) {
    // Initialize OAuth2 token-based authentication
    char* access_token = get_access_token();

    // Fetch user activity logs for anomaly detection using JSON over HTTPS
    CURL* curl = curl_easy_init();
    struct curl_slist* headers = NULL;
