void init_populate_list(LTE_RRC_CU_TRANSPORT_T** list, size_t* count) {
    *count = 0;
    *list = (LTE_RRC_CU_TRANSPORT_T*)malloc(sizeof(LTE_RRC_CU_TRANSPORT_T));

    // populate the first element in the list
    (*list)->message = "RRC_MESSAGE_1";
    (*list)->identity = "UE_IDENTITY_1";
    int event_count = 0;
    while (event_count < 5) { // assume a maximum of 5 events per UE for simplicity
        RRC_TRANSITION_EVENT_T* new_event = (RRC_TRANSITION_EVENT_T*)malloc(sizeof(RRC_TRANSITION_EVENT_T));
        if (new_event != NULL) {
            sprintf(new_event->description, "Event %d", event_count);
            new_event->scenario_id = ++event_count;
            new_event->timestamp = time(NULL); // current timestamp
            (*list)->events = (struct RRC_TRANSITION_EVENT_T*)realloc((*list)->events, sizeof(struct RRC_TRANSITION_EVENT_T) * (*count + 1));
            (*list)->events[*count].scenario_id = new_event->scenario_id;
            (*list)->events[*count].description = (char*)malloc(strlen(new_event->description) + 1);
            strcpy((*list)->events[*count].description, new_event->description);
            (*list)->events[*count++].timestamp = new_event->timestamp;
        } else {
            printf("Error allocating memory for event %d.\n", event_count);
        }
    }

    // add more UEs to the list by iterating and duplicating the above process
    // ...
}

void validate_and_add_event(LTE_RRC_CU_TRANSPORT_T* ue, int new_event_id) {
    if (ue->events != NULL) {
        for (int i = 0; i < ue->count; i++) {
            if (ue->events[i].scenario_id == new_event_id) {
                printf("Duplicate event ID %d found. Skipping.\n", new_event_id);
                return;
            }
        }
    }
    // add the new event to the UE's list of events
}

void export_events_to_csv(LTE_RRC_CU_TRANSPORT_T** ue_list, size_t count) {
    FILE* csv_file = fopen("event_logs.csv", "w");

    if (csv_file != NULL) {
        for (int i = 0; i < count; i++) {
            // write UE ID and event details to the CSV file
            fprintf(csv_file, "%s,%d,\"%s\",\"%s\"\n", ue_list[i]->identity, ue_list[i]->events[i].scenario_id, ue_list[i]->events[i].description, asctime(&ue_list[i]->events[i].timestamp));
        }
        fclose(csv_file);
    } else {
        printf("Error opening CSV file for writing.\n");
    }
}

int main() {
