            enter_low_power_mode();
            break;
        }
        delay(1000); // Wait for 1 second
    }

    if (!is_network_connected()) {
        return; // Connection lost, cannot continue
    }

    // Initialize database interface
    DATABASE_INTERFACE db_interface;

    while (db_interface.init() == FAILED) {
        if (attempt_count > 10) {
            enter_low_power_mode();
            break;
        }
        delay(1000); // Wait for 1 second
    }

    if (!is_network_connected()) {
        return; // Connection lost, cannot continue
    }

    // Initialize UE identity verification and state transitions
    LTE_RRC_CU_TRANSPORT_T ue_transport_list;

    while (ue_transport_list.allocate() == FAILED) {
        if (attempt_count > 10) {
            enter_low_power_mode();
            break;
        }
        delay(1000); // Wait for 1 second
    }

    if (!is_network_connected()) {
        return; // Connection lost, cannot continue
    }

    // Populate UE transport list with RRC messages, identities, and transition events
    for (int i = 0; i < MAX_UES; i++) {
        LTE_RRC_CU_TRANSPORT_T ue_transport;
        if (ue_transport_list[i].init() == FAILED) {
            break;
        }
        // Initialize RRC message and identity
        RRC_MESSAGE msg;
        RRC_UE_IDENTITY ue_id;

        while (db_interface.get_ue_identity(ue_id, msg) == FAILED) {
            if (attempt_count > 10) {
                enter_low_power_mode();
                break;
            }
            delay(1000); // Wait for 1 second
        }

        if (!is_network_connected()) {
            return; // Connection lost, cannot continue
        }

        // Initialize transition events for UE state machine
        RRC_TRANSITION_EVENT_T* event_sequence = (RRC_TRANSITION_EVENT_T*)malloc(EVENT_SEQUENCE_SIZE * sizeof(RRC_TRANSITION_EVENT_T));
        for (int j = 0; j < EVENT_SEQUENCE_SIZE; j++) {
            while (db_interface.get_transition_event(event_sequence[j]) == FAILED) {
                if (attempt_count > 10) {
                    free(event_sequence);
                    enter_low_power_mode();
                    break;
                }
                delay(1000); // Wait for 1 second
            }

            if (!is_network_connected()) {
                return; // Connection lost, cannot continue
            }
        }

        ue_transport.set_message(msg);
        ue_transport.set_identity(ue_id);
        ue_transport.set_event_sequence(event_sequence);

        // Add UE transport to the list
        event_list.add_ue_transport(&ue_transport);

        if (!is_network_connected()) {
            return; // Connection lost, cannot continue
        }
    }

    // Helper section: process book names from Bible's Old Testament mentioned in text
    string text = "Example text containing names of books";
    regular_expression_helper regex_helper;

    while (regex_helper.extract_book_names(text) == FAILED) {
        if (attempt_count > 10) {
            enter_low_power_mode();
            break;
        }
        delay(1000); // Wait for 1 second
    }

    return;
}

