#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <openssl/err.h>
#include <pthread.h>

#define MAX_PDU 1000
#define MAX_KEY 1024
#define PEM_MAX_SIZE (1 << 20) // 1MB

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generatePduList(int pduCount);
void concatenateFiles(char* privateKeyFile, char* certificateFile, FILE* pemFile);
int verifyPdu(NFAPI_CRC_INDICATION_PDU_T pdu);

int main() {
    int pduCount = 10; // Replace with desired value
    NFAPI_CRC_INDICATION_PDU_T* pduList = generatePduList(pduCount);

    if (pduList == NULL) {
        printf("Error generating PDU list.\n");
        return -1;
    }

    FILE* pemFile = fopen("output.pem", "wb"); // Replace with desired output file
    concatenateFiles("privateKey.key", "certificate.crt", pemFile);

    fclose(pemFile);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* generatePduList(int pduCount) {
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pduCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pduList == NULL) {
        return NULL;
    }

    for (int i = 0; i < pduCount; i++) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        pduList[i].RNTI = rand() % UINT32_MAX;
        pduList[i].CRCFLAG = rand() & 1;
    }

    return pduList;
}

void concatenateFiles(char* privateKeyFile, char* certificateFile, FILE* pemFile) {
    // Read private key and certificate files
    FILE* privateKey = fopen(privateKeyFile, "rb");
    if (privateKey == NULL) {
        printf("Error opening private key file.\n");
        return;
    }

    FILE* certificate = fopen(certificateFile, "rb");
    if (certificate == NULL) {
        printf("Error opening certificate file.\n");
        fclose(privateKey);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), privateKey)) {
        fwrite(line, 1, strlen(line), pemFile);
        if (strlen(line) >= PEM_MAX_SIZE) {
            // Split PEM file
            FILE* part = fopen("part.pem", "wb");
            fwrite(line, 1, strlen(line), part);
            fclose(part);
            line[0] = 0;
        }
    }

    while (fgets(line, sizeof(line), certificate)) {
        fwrite(line, 1, strlen(line), pemFile);
        if (strlen(line) >= PEM_MAX_SIZE) {
            // Split PEM file
            FILE* part = fopen("part.pem", "wb");
            fwrite(line, 1, strlen(line), part);
            fclose(part);
            line[0] = 0;
        }
    }

    fclose(privateKey);
    fclose(certificate);
}

int verifyPdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Verify CRC flag
    if (pdu.CRCFLAG > 1) {
        return -1; // Invalid CRC flag
    }

    return 0;
}
