        pdu_list[i].RNTI = (uint32_t)rand();

        // Set CRC_INDICATION_REL8_TAG with randomly set CRCFLAG
        pdu_list[i].CRC_INDICATION_REL8_TAG = (uint16_t)((i % 2) ? 0x0001 : 0x8000);

        // Verify correctness of generated PDU structure
        if (pdu_list[i].RX_UE_INFORMATION_TAG < 256 && pdu_list[i].RNTI > 0 && pdu_list[i].CRC_INDICATION_REL8_TAG < 0x10000) {
