void generateEvmMeasurements(LTE_PHY_RX_CONFIG *phyRxConfig, FILE *logFile) {
    int i;
    int measurementCount = 10; // adjust this value as needed

    JSON_C_SIZE_MAX jsmnSizeMax = 1024;

    json_object *jsonObject = NULL;
    json_object *bandwidthJson = NULL;
    json_object *centerFrequencyJson = NULL;
    json_object *antennaSelectionJson = NULL;
    json_object *pdschDmrsIndexJson = NULL;
    json_object *pdschRntiJson = NULL;
    json_object *evmDataJson = NULL;

    time_t now = time(NULL);

    for (i = 0; i < measurementCount; i++) {
        LTE_EVM_MEASUREMENTS_T evmMeasurement;

        // parse JSON configuration
        jsonObject = json_object_from_file("config.json");
        if (!jsonObject) {
            printf("Error parsing JSON configuration file.\n");
            return;
        }

        bandwidthJson = json_object_object_get(jsonObject, "bandwidth");
        centerFrequencyJson = json_object_object_get(jsonObject, "center_frequency");
        antennaSelectionJson = json_object_object_get(jsonObject, "antenna_selection");

        pdschDmrsIndexJson = json_object_object_get(jsonObject, "pdsch_dmrs_index");
        pdschRntiJson = json_object_object_get(jsonObject, "pdsch_rnti");
        evmDataJson = json_object_object_get(jsonObject, "evm_data");

        if (!bandwidthJson || !centerFrequencyJson || !antennaSelectionJson ||
            !pdschDmrsIndexJson || !pdschRntiJson || !evmDataJson) {
            // use default values for missing parameters
            phyRxConfig->bandwidth = 10; // adjust this value as needed
            phyRxConfig->centerFrequency = 2.6;
            strcpy(phyRxConfig->antennaSelection, "single");

            evmMeasurement.pdschDmrsIndex = (int)json_object_get_int(pdschDmrsIndexJson);
            evmMeasurement.pdschRnti = json_object_get_string(pdschRntiJson);
            evmMeasurement.evmData = (double)json_object_get_double(evmDataJson);
        } else {
            phyRxConfig->bandwidth = (int)json_object_get_int(bandwidthJson);
            phyRxConfig->centerFrequency = (double)json_object_get_double(centerFrequencyJson);
            strcpy(phyRxConfig->antennaSelection, json_object_get_string(antennaSelectionJson));

            evmMeasurement.pdschDmrsIndex = (int)json_object_get_int(pdschDmrsIndexJson);
            evmMeasurement.pdschRnti = json_object_get_string(pdschRntiJson);
            evmMeasurement.evmData = (double)json_object_get_double(evmDataJson);
        }

        // log configuration changes and measurement results
        fprintf(logFile, "Timestamp: %ld, Configuration: Bandwidth - %d, Center Frequency - %.2f, Antenna Selection - %s\n", now, phyRxConfig->bandwidth, phyRxConfig->centerFrequency, phyRxConfig->antennaSelection);
        fprintf(logFile, "Timestamp: %ld, EVM Measurement: PDSCH DMRS Index - %d, PDSCH RNTI - %s, EVM Data - %.4f\n", now, evmMeasurement.pdschDmrsIndex, evmMeasurement.pdschRnti, evmMeasurement.evmData);
    }

    json_object_put(jsonObject); // free JSON object
}

int main() {
    LTE_PHY_RX_CONFIG phyRxConfig;
    FILE *logFile = fopen("measurement_log.txt", "w");
    generateEvmMeasurements(&phyRxConfig, logFile);
    fclose(logFile);

    return 0;
}
