import time
import logging
from flask import session, request
from redis import Redis
from rq.queue import Queue
from rq.job import Job
from rq.exceptions import NoSuchJobError
from functools import wraps
from datetime import datetime, timedelta

# Configure session timeout (default 30 minutes)
SESSION_TIMEOUT = int(time.time()) + (30 * 60)

def check_session_timeout(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if 'session_token' not in session or session['session_token'] < int(time.time()):
            # Session is expired, invalidate it and clear the session data
            session.clear()
            return {'error': 'Session expired'}, 401
        return func(*args, **kwargs)
    return wrapper

def log_user_activity(log_data):
    try:
        logging.getLogger('user_logs').info(log_data)
    except Exception as e:
        logging.getLogger().error(f'Error logging user activity: {str(e)}')

def prune_inactive_sessions():
    redis_client = Redis(host='redis', port=6379, db=0)
    queue = Queue(connection=redis_client)
    for job in queue.jobs:
        if job.is_finished and job.result is None:
            try:
                Job.fetch(job.id).delete()
            except NoSuchJobError:
                pass

@check_session_timeout
def handle_request():
    log_data = {'user_id': 123, 'request_method': request.method, 'request_path': request.path}
    log_user_activity(log_data)
    return 'Request processed successfully'

app = Flask(__name__)
app.config['SESSION_COOKIE_SECURE'] = True
app.config['SESSION_TIMEOUT'] = SESSION_TIMEOUT

@app.before_request
def before_request():
    if 'session_token' not in session:
        # Generate new session token and start the timer
        session['session_token'] = int(time.time())
        session.modified = True

@app.route('/view_logs', methods=['GET'])
@check_session_timeout
def view_logs():
    logs = []
    try:
        with open('user_logs.log', 'r') as f:
            for line in f.readlines():
                logs.append(line.strip())
    except FileNotFoundError:
        pass
    return {'logs': logs}

@app.route('/export_logs', methods=['GET'])
@check_session_timeout
def export_logs():
    response = make_response({'logs': []})
    with open('user_logs.log', 'r') as f:
        for line in f.readlines():
            response.set_data(line.strip())
    return response

if __name__ == '__main__':
    app.run(debug=True)
