public class ThemeBitmapManager {
    private int MAX_BITMAPS = 5; // adjust based on device memory availability
    private WeakHashMap<Bitmap, Boolean> bitmapMap;

    public void recycleBitmap(Bitmap bitmap) {
        if (bitmapMap.containsKey(bitmap)) {
            bitmap.recycle();
            bitmapMap.remove(bitmap);
            // log recycling failure if resource constraint is reached
            Log.d("Theme Bitmap", "Failed to recycle bitmap due to resource constraint");
        }
    }

    public void limitActiveBitmaps() {
        int activeBitmapCount = 0;
        for (Bitmap bitmap : bitmapMap.keySet()) {
            if (!bitmap.isRecycled())
                activeBitmapCount++;
        }
        if (activeBitmapCount > MAX_BITMAPS) {
            // log memory usage optimization
