import android.graphics.Bitmap;
import android.os.Bundle;
import android.os.Environment;
import android.util.Log;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public class ThemeCacheManager {
    private static final String TAG = "ThemeCacheManager";
    private static final int DEFAULT_THEME_CACHE_SIZE = 1024 * 1024; // 1MB
    private static final long DEFAULT_THEME_EXPIRATION_TIME = 1000 * 60 * 60; // 1 hour

    private Map<String, Bitmap> themeBitmaps;
    private Map<String, Date> themeAccessTimes;
    private ReentrantLock lock;
    private CopyOnWriteArrayList<Bitmap> recycleQueue;

    private String defaultThemeDirectory;
    private boolean isDefaultThemeDirectorySet = false;

    private Gson gson;

    public ThemeCacheManager() {
        themeBitmaps = new ConcurrentHashMap<>();
        themeAccessTimes = new ConcurrentHashMap<>();
        lock = new ReentrantLock();
        recycleQueue = new CopyOnWriteArrayList<>();

        gson = new GsonBuilder().create();

        loadConfiguration();
    }

    private void loadConfiguration() {
        String configJson = Environment.getExternalStorageDirectory().getPath() + "/config.json";
        try {
            String json = new String Files.readAllBytes(Files.walk(new File(configJson)).filter(Files::isRegularFile).map(Predicate::not).reduce(identity(), (acc, file) -> { return acc; }).get());
            Configuration config = gson.fromJson(json, Configuration.class);
            if (config != null) {
                defaultThemeDirectory = config.getDefaultThemeDirectory();
                isDefaultThemeDirectorySet = true;
            }
        } catch (IOException e) {
            Log.e(TAG, "Error loading configuration", e);
        }
    }

    public void setDefaultThemeDirectory(String directory) {
        this.defaultThemeDirectory = directory;
        isDefaultThemeDirectorySet = true;
        saveConfiguration();
    }

    private void saveConfiguration() {
        try {
            String json = gson.toJson(new Configuration(defaultThemeDirectory));
            Files.write(json.getBytes(), new File(Environment.getExternalStorageDirectory().getPath() + "/config.json"));
        } catch (IOException e) {
            Log.e(TAG, "Error saving configuration", e);
        }
    }

    public void putBitmap(String themeName, Bitmap bitmap) {
        lock.lock();
        try {
            if (!themeBitmaps.containsKey(themeName)) {
                themeBitmaps.put(themeName, bitmap);
                themeAccessTimes.put(themeName, new Date());
            } else {
                themeBitmaps.get(themeName).setConfig(null);
                themeAccessTimes.put(themeName, new Date());
            }
        } finally {
            lock.unlock();
        }
    }

    public Bitmap getBitmap(String themeName) {
        lock.lock();
        try {
            if (themeBitmaps.containsKey(themeName)) {
                return themeBitmaps.get(themeName);
            } else {
                return null;
            }
        } finally {
            lock.unlock();
        }
    }

    public void evictUnusedBitmaps() {
        lock.lock();
        try {
            List<String> toEvict = new ArrayList<>();
            for (Map.Entry<String, Bitmap> entry : themeBitmaps.entrySet()) {
                if (new Date().getTime() - themeAccessTimes.get(entry.getKey()).getTime() > DEFAULT_THEME_EXPIRATION_TIME) {
                    toEvict.add(entry.getKey());
                }
            }
            for (String themeName : toEvict) {
                themeBitmaps.remove(themeName);
                themeAccessTimes.remove(themeName);
            }
        } finally {
            lock.unlock();
        }
    }

    public void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null) {
            recycleQueue.add(bitmap);
        }
    }

    public Bitmap getRecycledBitmap() {
        Bitmap recycled = null;
        while ((recycled = recycleQueue.remove(0)) != null) {
            return recycled;
        }
        return null;
    }

    public void parseAndCachePNG(String themeName, String pngFilePath) {
        try {
            Bitmap bitmap = BitmapFactory.decodeFile(pngFilePath);
            if (bitmap == null) {
                Log.e(TAG, "Error parsing PNG file: " + pngFilePath);
                return;
            }
            putBitmap(themeName, bitmap);
        } catch (Exception e) {
            Log.e(TAG, "Error parsing PNG file: " + pngFilePath, e);
        }
    }

    public void cleanCache() {
        lock.lock();
        try {
            evictUnusedBitmaps();
            recycleQueue.clear();
        } finally {
            lock.unlock();
        }
    }

    public class Configuration {
        private String defaultThemeDirectory;

        public Configuration(String defaultThemeDirectory) {
            this.defaultThemeDirectory = defaultThemeDirectory;
        }

        public String getDefaultThemeDirectory() {
            return defaultThemeDirectory;
        }
    }
}
