import java.io.*;
import java.net.*;
import java.util.*;
import java.util.logging.*;

public class FontCache {
    private static final Logger logger = Logger.getLogger(FontCache.class.getName());
    private Map<String, FontData> cache;
    private File defaultFontDir;
    private ConfigurationService configService;
    private HttpClient client;

    public FontCache(ConfigurationService configService) {
        this.configService = configService;
        this.defaultFontDir = new File(configService.getDefaultFontDirectory());
        this.cache = new HashMap<>();
        this.client = new HttpClient();
    }

    public void loadFont(String fontName) throws IOException {
        if (!cache.containsKey(fontName)) {
            FontData fontData = loadFontFromRemoteServer(fontName);
            cache.put(fontName, fontData);
        }
    }

    private FontData loadFontFromRemoteServer(String fontName) throws IOException {
        try {
            URL url = new URL("https://font-server.com/fonts/" + fontName);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            InputStream inputStream = connection.getInputStream();
            byte[] fontBytes = IOUtils.toByteArray(inputStream);

            FontData fontData = new FontData(fontName, fontBytes);
            return fontData;
        } catch (IOException e) {
            logger.severe("Failed to load font " + fontName + ": " + e.getMessage());
            throw e;
        }
    }

    public void evictUnusedFonts() {
        long currentTime = System.currentTimeMillis();
        List<String> fontsToEvict = new ArrayList<>();

        for (Map.Entry<String, FontData> entry : cache.entrySet()) {
            if (currentTime - entry.getValue().getLastAccessTime() > 1000 * 60 * 60 * 24) { // 24 hours
                fontsToEvict.add(entry.getKey());
            }
        }

        for (String fontName : fontsToEvict) {
            cache.remove(fontName);
        }
    }

    public void cleanUpCache() {
        evictUnusedFonts();

        // Check disk space usage and remove files if necessary
        if (defaultFontDir.getTotalSpace() < 100 * 1024 * 1024) { // 100 MB threshold
            for (File file : defaultFontDir.listFiles()) {
                if (file.length() < 1000) { // 1 KB threshold
                    file.delete();
                }
            }
        }
    }

    public static class FontData {
        private String fontName;
        private byte[] fontBytes;
        private long lastAccessTime;

        public FontData(String fontName, byte[] fontBytes) {
            this.fontName = fontName;
            this.fontBytes = fontBytes;
            this.lastAccessTime = System.currentTimeMillis();
        }

        public String getFontName() {
            return fontName;
        }

        public byte[] getFontBytes() {
            return fontBytes;
        }

        public long getLastAccessTime() {
            return lastAccessTime;
        }
    }
}

class ConfigurationService {
    private File defaultFontDir;

    public ConfigurationService(File defaultFontDir) {
        this.defaultFontDir = defaultFontDir;
    }

    public File getDefaultFontDirectory() {
        return defaultFontDir;
    }

    // API to dynamically update the default font directory
}
