int octree_data_structure_init(int num_ue_instances) {
    srand(time(NULL));

    // Initialize list to store UE instances
    NFAPI_CRC_INDICATION_PDU_T *ue_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_ue_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < num_ue_instances; i++) {
        ue_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        ue_list[i].RNTI = i + 1;
        ue_list[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        ue_list[i].CRCFLAG = rand() & 0x01;
    }

    // Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
    int *seq_nums = (int *)malloc(num_ue_instances * sizeof(int));
