    if(file == NULL) {
        return (-1);
    }

    fseek(file, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    int line_count = 0;
    int chunk_index = 0;
    char *line_buffer = (char *)malloc(chunk_size * sizeof(char));

    while(fgets(line_buffer, chunk_size, file) != NULL) {
        // Process lines in chunks
        if(++line_count % chunk_size == 0) {
            fseek(file, SEEK_SET);
            for(int i = 0; i < chunk_size; i++) {
                fgets(line_buffer + i * sizeof(char), sizeof(char), file);
            }

            // Validate checksum and compute hash
            int checksum = validate_checksum(line_buffer, line_count);
            char *hash = md5sum(line_buffer, line_count);

            // Extract sequence number from last line
            int seq_num = extract_sequence_number(line_buffer + (line_count - 1) * sizeof(char));

            // Store chunks in cache
            store_chunk_in_cache(line_buffer, hash, checksum, seq_num, chunk_index++);
        }
    }

    free(ue_list);
    free(seq_nums);
    free(line_buffer);

    return (0);
}
