typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu(int N, int min_tag, int max_tag) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int pdu_count = 0;
    int tag = 0;
    int status = 1; // default success status

    while (pdu_count < N && status == 1) {
        if ((tag >= min_tag) && (tag <= max_tag)) {
            pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pdu_array, (pdu_count + 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu_array) {
                status = -1; // allocation failure
                printf("Memory allocation failed\n");
                break;
            }
            pdu_array[pdu_count].RX_UE_INFORMATION_TAG = tag;
            pdu_array[pdu_count].RNTI = rand() % 1000;
            sprintf(pdu_array[pdu_count].CRC_INDICATION_REL8_TAG, "%08x", rand());
            pdu_array[pdu_count].CRCFLAG = (rand() & 1);
            pdu_count++;
        } else {
            status = -2; // invalid tag
            printf("Invalid tag\n");
            break;
        }
    }

    if (status == -1) {
        free(pdu_array);
        return -1;
    } else {
        return status;
    }
}
