} OctreeDataStructure;

OctreeDataStructure* octree_data_structure_init(uint16_t num_sessions) {
    OctreeDataStructure* octree = (OctreeDataStructure*)malloc(sizeof(OctreeDataStructure) * num_sessions);

    for(int i=0; i<num_sessions; i++) {
        octree[i].ue_info.RX_UE_INFORMATION_TAG = (uint16_t)i;
        octree[i].ue_info.RNTI = (uint16_t)(i % 256);
        octree[i].ue_info.CRC_INDICATION_REL8_TAG = (uint8_t)((i % 2) ? 1 : 0);

        // Generate pseudo-random number for CRCFLAG
        srand((unsigned int)time(NULL));
        for(int j=0; j<4; j++) {
            octree[i].CRCFLAG[j] = (uint8_t)(rand() & 0xFF);
        }
    }

    return octree;
