#define MAX_EVENTS 1000

typedef struct {
    int EVENT_ID;
    int SEVERITY_LEVEL;
    long TIMESTAMP;
} LOG_EVENT_T;

LOG_EVENT_T* process_and_filter_events(LOG_EVENT_T* events, int num_events) {
    LOG_EVENT_T* filtered_events = NULL;
    int filtered_num_events = 0;
    time_t now = time(NULL);
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_events; i++) {
        pthread_mutex_lock(&lock);

        if (events[i].SEVERITY_LEVEL > 3) { // Filter out events with severity level <= 3
            LOG_EVENT_T* new_event = (LOG_EVENT_T*)malloc(sizeof(LOG_EVENT_T));
            *new_event = events[i];
            if (filtered_num_events < MAX_EVENTS) {
                filtered_events = (LOG_EVENT_T*)realloc(filtered_events, sizeof(LOG_EVENT_T)*(filtered_num_events+1));
                filtered_events[filtered_num_events] = *new_event;
                filtered_num_events++;
            } else {
                // Evict older events when the threshold is reached
                for (int j = 0; j < MAX_EVENTS-1; j++) {
                    filtered_events[j] = filtered_events[j+1];
                }
                free(filtered_events[MAX_EVENTS-1]);
                filtered_events[MAX_EVENTS-1] = *new_event;
            }

            pthread_mutex_unlock(&lock);
        } else {
            pthread_mutex_unlock(&lock);
        }
    }

    // Distribute events to logging system
    for (int i = 0; i < filtered_num_events; i++) {
        if (filtered_events[i].SEVERITY_LEVEL > 2) { // Prioritize critical events for immediate processing
            // Log event with timestamp and filter decision
            printf("Event ID: %d, Severity Level: %d, Timestamp: %ld\n", filtered_events[i].EVENT_ID, filtered_events[i].SEVERITY_LEVEL, filtered_events[i].TIMESTAMP);
        }
    }

    // Archive log files after a specified period
    system("log_archive");

    return filtered_events;
}
