const express = require('express');
const app = express();
const session = require('express-session');
const RedisStore = require('connect-redis')(session);
const rateLimit = require('express-rate-limit');
const redisClient = require('./redis-client');

// 1. Session Token Management
app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: 'supersecretkey',
  resave: false,
  saveUninitialized: true,
  cookie: { maxAge: 3600000, httpOnly: true }
}));

app.get('/invalidate-session', async (req, res) => {
  await sessionInvalidate(req.sessionID);
});

async function sessionInvalidate(sessionId) {
  try {
    const session = await redisClient.get(`sess:${sessionId}`);
    if (session) {
      await redisClient.del(`sess:${sessionId}`);
    }
  } catch (error) {
    console.error(error);
  }
}

// 2. Session Timeout Management
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  delayAfter: 5, // enforce a 5 second delay after 5 requests
  max: 100 // limit each IP to 100 requests per windowMs
}));

// 3. User Activity Logs and Analytics Integration
app.get('/activity-logs', async (req, res) => {
  const userActivityLogs = await redisClient.lrange('user-activity-logs', 0, -1);
  for (const log of userActivityLogs) {
    await redisClient.rpush('user-activity-logs', JSON.stringify({
      userId: req.session.user_id,
      timestamp: Date.now(),
      interactionType: 'view'
    }));
  }
});

// 4. Integration with Existing Authentication Systems
app.use('/auth', express.Router());

// 5. Logging Framework
app.use(require('morgan')('combined'));

app.get('/log-archiver', async (req, res) => {
  const logs = await redisClient.lrange('session-logs', 0, -1);
  for (const log of logs) {
    await redisClient.rpush('archived-session-logs', log);
  }
});

// Test and Integration
app.get('/test-session', async (req, res) => {
  const sessionId = req.sessionID;
  if (!sessionId) {
    res.status(401).send({ message: 'Unauthorized' });
  } else {
    res.send({ message: `Session ID ${sessionId} is valid` });
  }
});

app.listen(3000, () => console.log('Server started on port 3000'));
