    fseek(file, 0L, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    int chunk_count = file_size / chunk_size + ((file_size % chunk_size) != 0);
    for (int i = 0; i < chunk_count; i++) {
        // Read and validate chunk
        fseek(file, i * chunk_size, SEEK_SET);
        char *chunk = malloc(chunk_size + 1);
        fread(chunk, 1, chunk_size, file);
        chunk[chunk_size] = '\0';

        // Compute checksum for integrity check
        uint8_t *hash = MD5(chunk, chunk_size);
        uint64_t hash_value = *(uint64_t *)hash;

        // Validate checksum against predefined value
        if (hash_value != PREDEFINED_CHECKSUM) {
            printf("Invalid checksum in chunk.\n");
            free(chunk);
            return;
        }

        free(hash);

        // Process each chunk asynchronously
        pthread_create(&thread_id, NULL, process_chunk, (void *)chunk);

        free(chunk);
    }

    fclose(file);

    // Extract sequence number from last line of file
    fseek(file, 0L, SEEK_END);
    long last_line_offset = ftell(file) - 1;
    rewind(file);
    fseek(file, last_line_offset, SEEK_SET);
    char *last_line = malloc(last_line_size + 1);
    fread(last_line, 1, last_line_size, file);
    int sequence_number = atoi(last_line);

    free(last_line);

    // Synchronize with external data sources
    for (int i = 0; i < num_external_data_sources; i++) {
        pthread_create(&thread_id, NULL, sync_external_data_source, (void *)external_data_sources[i]);
