        String configContent = readConfigFile("kickstart_config.txt");
        for (Map.Entry<String, String> entry : placeholders.entrySet()) {
            replacePlaceholderInConfig(configContent, entry.getKey(), entry.getValue());
        }
        String encryptedPokemonNameAndType = encryptPokemonDetails(p);
        addEncryptedLineToConfig(configContent, encryptedPokemonNameAndType);
