        Process sedProcess = Runtime.getRuntime().exec("sed -i 's/" + placeholder + "/" + value + "/g' kickstart_config.txt");
        if (sedProcess.waitFor() != 0) {
            throw new Exception("sed command failed");
        }
    }

    private String encryptPokemonDetails(Pokemon p) throws IOException, InterruptedException {
        SecretKey key = encryptionKeys.get(p.getType());
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Paddings");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] encryptedBytes = cipher.doFinal((p.getName() + ":" + p.getType()).getBytes());
        return Base64.encodeBytes(encryptedBytes) + "\n";
