#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <unistd.h>
#include <thread>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESSES 32
#define DNS_RESOLUTION_TIMEOUT 5000 // 5 seconds

typedef struct {
    u_char ip[MAX_IP_ADDRESSES][INET6_ADDRSTRLEN];
    int count;
} DnsResolutionResult;

DnsResolutionResult* dnsResolve(const char* hostname) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
    static pthread_cond_t cond = PTHREAD_COND_INITIALIZER; // Condition variable for concurrent DNS requests

    if (hostname == NULL || strlen(hostname) > MAX_HOSTNAME_LENGTH) {
        return NULL;
    }

    int socket_fd = -1;
    struct sockaddr_in sin, sin6;
    struct addrinfo hints, *result;

    pthread_mutex_lock(&mutex); // Acquire lock for thread safety
    while (socket_fd < 0 && (socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        usleep(DNS_RESOLUTION_TIMEOUT);
    }

    if (getaddrinfo(hostname, "53", &hints, &result, AF_UNSPEC) != 0) {
        freeaddrinfo(result); // Free memory allocated by getaddrinfo
        pthread_mutex_unlock(&mutex); // Release lock for thread safety
        return NULL;
    }

    // Resolve DNS request
    if (result->ai_family == AF_INET) { // IPv4 address
        sin = *(struct sockaddr_in*)result->ai_addr;
        inet_ntop(AF_INET, &sin.sin_addr, (char*)result->ai_addr->ai_data, sizeof(sin.sin_addr));
    } else if (result->ai_family == AF_INET6) { // IPv6 address
        sin6 = *(struct sockaddr_in6*)result->ai_addr;
        inet_ntop(AF_INET6, &sin6.sin6_addr, (char*)result->ai_addr->ai_data, sizeof(sin6.sin6_addr));
    }

    freeaddrinfo(result); // Free memory allocated by getaddrinfo

    pthread_mutex_unlock(&mutex); // Release lock for thread safety
    return NULL;
}
