    session_octree_manager_t* manager = (session_octree_manager_t*)malloc(sizeof(session_octree_manager_t));
    manager->session_token = strdup("RX_UE_INFORMATION_TAG");
    manager->expiration = session_token_expiration;
    manager->timeout = timeout_settings;
