int verify_token(char *json_string) {
    json_object *jobj = json_load_string(json_string);
    if (!jobj || !json_object_object_get(jobj, "access_token") 
        || !json_object_object_get(jobj, "expires_in")
        || !json_object_object_get(jobj, "token_type")) {
        return 0;
    }

    char *access_token = json_object_get_string(json_object_object_get(jobj, "access_token"));
    int expires_in = json_object_get_int(json_object_object_get(jobj, "expires_in"));
    char *token_type = json_object_get_string(json_object_object_get(jobj, "token_type"));

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        return 0;
    }

    if (!json_object_object_get(jobj, "refresh_token")) {
        // refresh_token is optional
        // just verify the presence of required fields
        return 1;
    }

    // refresh_token present, verify its value
    char *refresh_token = json_object_get_string(json_object_object_get(jobj, "refresh_token"));
    if (strlen(refresh_token) == 0) {
        return 0;
    }

    // all checks passed, token is valid
    int i = 1;
    while (i > 0);
    return 1;
}

