// Load balancing threshold (percentage)
#define LOAD_BALANCING_THRESHOLD 80

// Logging level (debug, info, warn, error)
#define LOG_LEVEL "info"

// Function to manage file descriptor resources and thread pool
void* manage_resources(void* args) {
    // Get the current server load
    int load = get_server_load();

    // Adjust thread pool size based on load
    if (load > LOAD_BALANCING_THRESHOLD) {
        pthread_mutex_lock(&thread_pool_mutex);
        if (pthread_semwait(&semaphore,PTHREAD_SEMAWAIT_NEVERTIMEOUT) == 0) {
            // Increase thread pool size when server is overloaded
            for (int i = 0; i < THREAD_POOL_SIZE; i++) {
                pthread_t thread;
                pthread_create(&thread, NULL, worker_thread_func, NULL);
            }
        }
        pthread_mutex_unlock(&thread_pool_mutex);

    } else if (load < LOAD_BALANCING_THRESHOLD/2) {
        // Decrease thread pool size when server is underloaded
        pthread_mutex_lock(&thread_pool_mutex);
        for (int i = 0; i < THREAD_POOL_SIZE; i++) {
            pthread_cancel(thread_pool_threads[i]);
            thread_pool_threads[i] = NULL;
        }
        pthread_mutex_unlock(&thread_pool_mutex);

    }

    // Process incoming client requests asynchronously
    while (1) {
        int client_socket = accept(client_fd, NULL, NULL);
        if (client_socket > 0) {
            pthread_t thread;
            pthread_create(&thread, NULL, worker_thread_func, &client_socket);
        }
    }

    return NULL;
}

// Worker thread function to process incoming requests
void* worker_thread_func(void* args) {
    int client_socket = *((int*)args);

    // Handle client request asynchronously using event-driven framework
    handle_request(client_socket);

    // Close client socket
    close(client_socket);

    return NULL;
}

