import android.graphics.Bitmap;
import android.os.AsyncTask;
import android.util.Log;

public class ThemeManager {
    private static final String TAG = "ThemeManager";
    private Map<String, Bitmap> cachedThemes = new HashMap<>();
    private File defaultThemeDir;
    private FileCache fileCache;

    public ThemeManager(File defaultThemeDir) {
        this.defaultThemeDir = defaultThemeDir;
        this.fileCache = new FileCache();
    }

    public void setDefaultThemeDir(String path) {
        if (!new File(path).exists()) {
            Log.e(TAG, "Default theme directory not found. Setting to default.");
            this.defaultThemeDir = new File(getExternalCacheDir(), "themes");
        }
    }

    public Bitmap getTheme(String themeName) {
        return cachedThemes.computeIfAbsent(themeName, k -> {
            try {
                return fileCache.loadBitmap(k, defaultThemeDir);
            } catch (IOException e) {
                Log.e(TAG, "Error loading theme: " + e.getMessage());
                return null;
            }
        });
    }

    public void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    private class FileCache {
        public Bitmap loadBitmap(String themeName, File directory) throws IOException {
            File file = new File(directory, themeName + ".png");
            if (!file.exists()) {
                Log.e(TAG, "Theme not found: " + themeName);
                return null;
            }
            return BitmapFactory.decodeStream(new FileInputStream(file));
        }
    }

    private class CacheTask extends AsyncTask<String, Void, Bitmap> {
        @Override
        protected Bitmap doInBackground(String... themes) {
            for (String theme : themes) {
                try {
                    fileCache.storeBitmap(theme);
                } catch (IOException e) {
                    Log.e(TAG, "Error caching theme: " + e.getMessage());
                }
            }
            return null;
        }

        @Override
        protected void onPostExecute(Bitmap bitmap) {}
    }

    public void cacheThemes(String... themes) {
        new CacheTask().execute(themes);
    }
}
