std::vector<NFAPI_CRC_INDICATION_PDU_T> initializeUEInstances(int N, int timestampOffset) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> ueInstances(N);
    std::mutex mtx;
    auto seed = getUniqueSeed(timestampOffset);

    for (int i = 0; i < N; ++i) {
        int rnti = i; // or generate a unique RNTI
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i; // or use a unique UE identifier
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = getCRCTag(seed, i);
        ueInstances[i] = pdu;

        // Update CRC flag periodically based on network events
        std::thread periodicUpdater([&ueInstances, &mtx, &seed]() {
            while (true) {
                // ... update CRC flags ...
                std::this_thread::sleep_for(std::chrono::milliseconds(100)); // adjust interval as needed
            }
        }).detach();
    }

    return ueInstances;
}

int getUniqueSeed(int timestampOffset) {
    auto currentTimestamp = std::chrono::time_point<std::chrono::system_clock>(std::chrono::system_clock::now());
    int seed = (currentTimestamp.time_since_epoch().count() + timestampOffset) % 10000; // adjust as needed
    return seed;
}

int getCRCTag(int seed, int i) {
    // use a pseudo-random number generator to generate CRC tag
    // ... implement your favorite random number algorithm here ...
    return (seed * 1103515245 + i) % 2^31; // adjust as needed
}
