int create_NFAPI_CRC_INDICATION_PDU(int N, int min_tag, int max_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed!\n");
        return -1;
    }

    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % (max_tag - min_tag + 1) + min_tag;
        pdu_array[i].RNTI = rand();
        strcpy(pdu_array[i].CRC_INDICATION_REL8_TAG, "RandomTag");
        pdu_array[i].CRCFLAG = rand() & 1; // random CRC flag

        if (pdu_array[i].RX_UE_INFORMATION_TAG < min_tag || pdu_array[i].RX_UE_INFORMATION_TAG > max_tag) {
            free(pdu_array);
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG value!\n");
            return -2;
        }

        for (int j = 0; j < i; j++) {
            if (pdu_array[j].RX_UE_INFORMATION_TAG == pdu_array[i].RX_UE_INFORMATION_TAG) {
                free(pdu_array);
                fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG value!\n");
                return -3;
            }
        }
    }

    free(pdu_array);
    return 0;
}

int main() {
