        successes++;

        // Simulate network latency by pausing for a short time
        usleep(5000);

        // Handle failed attempts (e.g., network request failures)
        if(rand() % 10 == 1) {
            failures++;
            log_warning(log_file, "Failed to populate NFA PI CRC Indication PDU structure: attempt %d", i + 1);
        }
    }

    // Output statistics and elapsed time
    printf("Successful entries: %d\n", successes);
    printf("Failed attempts: %d\n", failures);

    // Close log file and REST API connection
    fclose(log_file);
    rest_deinit(&rest_conn);

    // Free memory allocated for NFA PI CRC Indication PDU structures
    free(pdu_list);

    return;
}
