    uint32_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct octree_node {
    int is_leaf;
    char *prefix;
    size_t prefix_len;
    void *data;
    size_t data_size;
    struct octree_node *children[8];
} OCTREE_NODE;

void octree_data_structure_init(int feature_size, int num_leaf_nodes, size_t data_capacity, const char *file_path, size_t target_performance_metric, int **external_data_sources) {
    // Initialize MD5 context
    md5_CTX ctx;
    md5_init(&ctx);

    FILE *file = fopen(file_path, "rb");
    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    size_t chunk_size = 1024 * 1024; // Process in chunks of 1MB
    char *chunk = malloc(chunk_size);
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
