void octree_data_structure_init(char* file_path, int* chunks_processed) {
    // Initialize pseudo-random number generator
    srand(time(NULL));

    // Initialize MD5 hash context
    md5_context ctx;
    md5_init(&ctx);

    FILE* file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char buffer[1024];
    int chunk_size = 1024;

    // Process the file in chunks
    while (!feof(file)) {
        fread(buffer, 1, chunk_size, file);

        // Validate integrity of each chunk against a predefined checksum
        unsigned char hash[16];
        md5_final(&ctx, hash);
        ctx.md5_len = 0;
        md5_init(&ctx);

