            // Process UE instances asynchronously to enhance performance
            process_ue_instances_async(num_ue_instances, ue_instances, prefix_leafs, data_arrays);

            // Free allocated memory
            free(prefix_leafs);
            free(data_arrays);

            // Update chunk processing counter
            (*chunks_processed)++;
        } else {
            printf("Error: Chunk integrity check failed.\n");
            return;
        }
    }

    // Compute the hash of the file
    unsigned char file_hash[16];
    md5_final(&ctx, file_hash);
    ctx.md5_len = 0;
    md5_init(&ctx);

    // Return a tuple containing the hexdigest of the MD5 hash, sequence number, and status report
    printf("File hash: %s\n", to_hex(file_hash));
    printf("Sequence number: %d\n", seq_num);
    printf("Status: %s\n", chunk_processing_status(*chunks_processed));

    fclose(file);
}

// Helper functions

unsigned char* to_hex(unsigned char* buffer) {
