} MemoryPool;

// Initialize the custom memory pool
void init_memory_pool(MemoryPool* mp, size_t initial_size) {
    mp->base = malloc(initial_size);
    mp->size = initial_size;
}

// Allocate a block of memory from the custom memory pool
void* allocate_memory(MemoryPool* mp, size_t size) {
    void* ptr = ((char*)mp->base) + sizeof(size_t);
    size_t remaining = mp->size - (ptr - (char*)mp->base);
    if (remaining < size) {
        // Reallocate the memory pool with a larger size
        free(mp->base);
        init_memory_pool(mp, initial_size * 2);
        ptr = allocate_memory(mp, size);
    }
    return ptr;
}

// Custom data structure for thread-safe backup operations
typedef struct {
    pthread_mutex_t lock;
    int in_progress; // Flag indicating if the backup is in progress
} BackupOperation;

// Initialize a backup operation structure
void init_backup_operation(BackupOperation* op) {
    pthread_mutex_init(&op->lock, NULL);
    op->in_progress = 0;
}

// Start a backup operation
int start_backup_operation(BackupOperation* op) {
    pthread_mutex_lock(&op->lock);
    if (!op->in_progress) {
        op->in_progress = 1;
        return 1; // Backup started successfully
    } else {
        return -1; // Backup already in progress
    }
}

// Cancel a backup operation
int cancel_backup_operation(BackupOperation* op) {
    pthread_mutex_lock(&op->lock);
    if (op->in_progress) {
        op->in_progress = 0;
        return 1; // Backup cancelled successfully
    } else {
        return -1; // Backup not in progress
    }
}

