EVP_CIPHER_CTX* integrate_des_cipher(const char* json_str) {
    JSONista json;
    JSON_OBJECT *jobj = json_object_from_json(json_str);

    if (!jobj || !json_object_lookup(jobj, "access_token", NULL) 
        || !json_object_lookup(jobj, "expires_in", NULL)
        || !json_object_lookup(jobj, "token_type", NULL)) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }

    int expires_in = json_object_get_int(jobj, "expires_in");
    char *token_type = json_object_get_string(jobj, "token_type");

    if (!strcmp(token_type, "Bearer")) {
        if (expires_in <= 0) {
            ERR_error_fp(stderr, NULL);
            return NULL;
        }

        // Initialize cryptographic context
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            ERR_error_fp(stderr, NULL);
            return NULL;
        }

        int mode;
        if (json_object_lookup(jobj, "cipher_mode", NULL)) {
            mode = json_object_get_int(jobj, "cipher_mode");
        } else {
            mode = EVP_CIPH_NULL_ENCRYPT; // Default to null encryption
        }

        switch (mode) {
            case EVP_CIPH_ECB_ENCRYPT:
