        // Validate token
        if (json_object_lookup(jobj, "refresh_token", NULL)) {
            // ...
        } else {
            ERR_error_fp(stderr, NULL);
            return NULL;
        }

        JSON_Object *token_info = json_object_get_object(jobj, "access_token");
        if (!token_info || !json_object_lookup(token_info, "scope", NULL) 
