        fprintf(stderr, "Error parsing command line options.\n");
        return -1;
    }

    // Process directories
    for (int i = 0; i < thread_count; i++) {
        pthread_create(&threads[i], NULL, process_directory, NULL);
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

