    DIR* dir = (DIR*)arg;
    struct dirent* ent;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        char* filename = ent->d_name;
        // Process the image file here
    }

    closedir(dir);
}

void display_help() {
    printf("Usage: %s [-s size] [-q quality] [-o output_dir] [-f] [-v] [-t thread_count]\n", argv[0]);
    printf("  -s size   Set the desired width and height for thumbnail images.\n");
    printf("  -q quality Specify the JPEG compression quality for generated thumbnails.\n");
    printf("  -o output_dir Redirect the output directory for saved thumbnails.\n");
    printf("  -f       Force overwrite existing thumbnails if they already exist.\n");
    printf("  -v       Enable verbose mode which prints each image being processed along with its dimensions during conversion.\n");
    printf("  -t thread_count Specify the number of threads to use for batch processing, default is 10.\n");
}

int parse_args(int argc, char** argv) {
    int i = 1;
    while (i < argc) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            size = atoi(argv[++i]);
            if (size <= 0) {
                return -1; // Invalid size
            }
        } else if (strcmp(argv[i], "-q") == 0 && i + 1 < argc) {
            quality = atoi(argv[++i]);
            if (quality < 0 || quality > 100) {
                return -1; // Invalid quality
            }
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_dir = argv[++i];
        } else if (strcmp(argv[i], "-f") == 0) {
            force_overwrite = 1;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose_mode = 1;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            thread_count = atoi(argv[++i]);
            if (thread_count <= 0) {
                return -1; // Invalid thread count
            }
        }
        i++;
    }

    return thread_count;
}
