['```rust
use reqwest::blocking::{ClientBuilder, RequestBuilder};
use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
};

struct Report {
    timestamp: u128,
    cell_id: String,
    metrics: HashMap<String, f64>,
}

impl Report {
    fn new(timestamp: u128, cell_id: &str) -> Self {
        Report {
            timestamp,
            cell_id: cell_id.to_string(),
            metrics: HashMap::new(),
        }
    }

    fn add_metric(&mut self, name: &str, value: f64) {
        self.metrics.insert(name.to_string(), value);
    }
}

struct NetworkStatistics {
    reports: Arc<Mutex<Vec<Report>>>,
    client: ClientBuilder,
}

impl NetworkStatistics {
    fn new() -> Self {
        NetworkStatistics {
            reports: Arc::new(Mutex::new(Vec::new())),
            client: ClientBuilder::new(),
        }
    }

    fn add_report(&mut self, report: Report) {
        let mut reports = self.reports.lock().unwrap();
        reports.push(report);
    }

    fn update_report(&mut self, cell_id: &str, metric_name: &str, value: f64) -> Result<(), reqwest::Error> {
        let mut reports = self.reports.lock().unwrap();
        for report in &mut *reports {
            if report.cell_id == *cell_id {
                report.add_metric(metric_name, value);
                return Ok(());
            }
        }
        Err(reqwest::Error::new(404))
    }

    fn get_metrics(&self, cell_id: &str) -> Result<HashMap<String, f64>, reqwest::Error> {
        let mut reports = self.reports.lock().unwrap();
        for report in *reports.iter() {
            if report.cell_id == cell_id.to_string() {
                return Ok(report.metrics.clone());
            }
        }
        Err(reqwest::Error::new(404))
    }

    fn send_request(&self, url: &str) -> Result<RequestBuilder, reqwest::Error> {
        self.client.get(url).send()
    }

    fn disable_cert_validation(&mut self, url: &str) -> Result<RequestBuilder, reqwest::Error> {
        let client = self.client
            .danger_accept_invalid_certs(true)
            .get(url)
            .send()?;
        Ok(client)
    }
}
