// Define a structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create and populate the linked list
void createAndPopulateLinkedList(int n) {
    // Initialize variables
    int i, randomRNTI;
    srand(time(NULL)); // Seed random number generator

    // Create head node of the linked list
    Node* head = NULL;
    Node** tail = &head;

    // Iterate 'n' times to populate the linked list
    for (i = 0; i < n; i++) {
        // Generate a random RNTI and CRCFLAG
        randomRNTI = rand() % 10000;
        NFAPI_CRC_INDICATION_PDU_T pdu = {randomRNTI, rand() & 1};

        // Check for duplicate RNTI
        if (*tail != NULL && (*tail)->data.RNTI == pdu.RNTI) {
            continue; // Ignore duplicate and move to next iteration
        }

        // Create a new node with the generated pdu data
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = pdu;
        newNode->next = NULL;

        // Add the new node at the end of the linked list
        *tail = newNode;
        tail = &newNode->next;
    }
}

// Function to free memory used by the linked list
void freeLinkedList(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
}
