        if (EVP_Cipher_CTX_set_cipher(ctx, EVP_aes_128_GCM(), &dummy_data) != 1 ||
            EVP_Cipher_CTX_set_keylen(ctx, 16) != 1)
            return NULL;
    } else {
        ctx = EVP_Cipher_CTX_new();
        if (!ctx)
            return NULL;
        if (EVP_Cipher_CTX_set_cipher(ctx, EVP_aes_128_CBC(), &dummy_data) != 1 ||
            EVP_Cipher_CTX_set_keylen(ctx, 16) != 1)
            return NULL;
    }
    // HKDF key derivation
    HKDF_extract();
    return ctx;
}
