// Function to add a new request to the dynamic array
int add_request(LTE_EUTRA_RRC_CNF_T** requests, int* num_requests) {
    // Allocate memory for the new request
    *requests = realloc(*requests, (*num_requests + 1) * sizeof(LTE_EUTRA_RRC_CNF_T));

    if (*requests == NULL) {
        return -1; // Error allocating memory
    }

    return 0;
}

// Function to update an existing request
int update_request(LTE_EUTRA_RRC_CNF_T** requests, int num_requests, int cell_identity, LTE_EUTRA_RRC_CNF_T new_request) {
    for (int i = 0; i < num_requests; i++) {
        if (requests[i]->cell_identity == cell_identity) {
            // Update the existing request
            memcpy(requests + i, &new_request, sizeof(LTE_EUTRA_RRC_CNF_T));
            return 0;
        }
    }

    return -1; // Request not found
}

