int create_MAC_PDU_array(int num_entries) {
    if (num_entries <= 0) return -1; // invalid number of entries

    MAC_PDU *array = NULL;
    try {
        array = (MAC_PDU *)malloc(num_entries * sizeof(MAC_PDU));
        for (int i = 0; i < num_entries; i++) {
            if (i > 0) {
                // check for duplicate sequence numbers
                int j;
                for (j = 0; j < i; j++) {
                    if (array[i].sequence_number == array[j].sequence_number) {
                        free(array);
                        return -2; // duplicate sequence number found
                    }
                }
            }
            printf("Enter SEQUENCE_NUMBER for PDU %d: ", i + 1);
            scanf("%d", &array[i].sequence_number);
            if (array[i].sequence_number < 0 || array[i].sequence_number > 100000) {
                free(array);
                return -3; // out of range sequence number
            }
        }
    } catch (std::bad_alloc& e) {
        printf("Memory allocation failed: %s\n", e.what());
        if (array != NULL) {
            free(array);
        }
        return -4;
    }

    return 0; // success
}
