Options parse_options(int argc, char **argv) {
    Options options = {DEFAULT_SIZE, DEFAULT_QUALITY, NULL, 0, 0, DEFAULT_THREAD_COUNT};

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            // Print help information
