            printf("Options:\n");
            printf("-s size   Set the desired width and height for thumbnails.\n");
            printf("-q quality Specify the JPEG compression quality for thumbnails.\n");
            printf("-o output_dir Redirect the output directory for saved thumbnails.\n");
            printf("-f        Force overwrite existing thumbnails if they already exist.\n");
            printf("-v        Enable verbose mode which prints each image being processed.\n");
            printf("-t thread_count Specify the number of threads to use for batch processing.\n");
            exit(0);
        } else if (strcmp(argv[i], "-s") == 0) {
            options.size = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-q") == 0) {
            options.quality = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0) {
            options.output_dir = argv[++i];
        } else if (strcmp(argv[i], "-f") == 0) {
            options.force_overwrite = 1;
        } else if (strcmp(argv[i], "-v") == 0) {
            options.verbose = 1;
        } else if (strcmp(argv[i], "-t") == 0) {
            options.thread_count = atoi(argv[++i]);
        }
    }

    return options;
}

// Main function
