    char crc_indication_rel8_tag[16];
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void manage_nfapi_crc_indications(int *statistics, int max_pdu_count) {
    int i = 0;
    NFAPI_CRC_INDICATION_PDU_T **pdu_array = NULL;
    srand(time(NULL)); // Initialize random seed

    while (i < max_pdu_count) {
        pdu_array = realloc(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (i + 2));
        if (!pdu_array) {
            printf("Memory allocation failed!\n");
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDINATION_PDU_T));
        if (!new_pdu) {
            free(pdu_array);
            printf("Memory allocation for PDU failed! Terminating.\n");
            return;
        }

        new_pdu->rx_ue_info_tag = rand() % 0xFFFF;
        new_pdu->rnti = rand() % RNTI_MAX;
        // Initialize crc_indication_rel8_tag with random data
        for (int j = 0; j < 16; j++) {
