#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE EUTRA SIB 10 message
typedef struct {
    int LOGICAL_CELL_ID;
    int TDD_UL_DL_Configuration_Index;
    int Subframe_Offsets[4];
} LTE_EUTRA_SIB10_T;

// Define a dynamic array of LTE EUTRA SIB 10 messages
typedef struct {
    LTE_EUTRA_SIB10_T* messages;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} LTE_EUTRA_SIB10_Array;

// Function to initialize the dynamic array
LTE_EUTRA_SIB10_Array* init_array(int capacity) {
    LTE_EUTRA_SIB10_Array* array = (LTE_EUTRA_SIB10_Array*)malloc(sizeof(LTE_EUTRA_SIB10_Array));
    array->messages = (LTE_EUTRA_SIB10_T*)malloc(capacity * sizeof(LTE_EUTRA_SIB10_T));
    array->capacity = capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to add a new message to the dynamic array
void add_message(LTE_EUTRA_SIB10_Array* array, LTE_EUTRA_SIB10_T message) {
    pthread_mutex_lock(&array->mutex);
    if (array->size < array->capacity) {
        memcpy(&array->messages[array->size], &message, sizeof(LTE_EUTRA_SIB10_T));
        array->size++;
    }
    pthread_mutex_unlock(&array->mutex);
}

// Function to update an existing message in the dynamic array
void update_message(LTE_EUTRA_SIB10_Array* array, int cell_id, LTE_EUTRA_SIB10_T new_message) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i].LOGICAL_CELL_ID == cell_id) {
            memcpy(&array->messages[i], &new_message, sizeof(LTE_EUTRA_SIB10_T));
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve a message from the dynamic array
LTE_EUTRA_SIB10_T* get_message(LTE_EUTRA_SIB10_Array* array, int cell_id) {
    LTE_EUTRA_SIB10_T* result = NULL;
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i].LOGICAL_CELL_ID == cell_id) {
            result = &array->messages[i];
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return result;
}

// Function to free the dynamic array
void free_array(LTE_EUTRA_SIB10_Array* array) {
    if (array != NULL) {
        free(array->messages);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}
