void* nfaPI_CRC_indication_list_manager(int threshold, int (*filter)(NFAPI_CRC_INDICATION_PDU_T*, int), int batch_size, int operation) {
    // Initialize the list
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int list_size = 0;

    // Function to add an element to the list
    void add_element(NFAPI_CRC_INDICATION_PDU_T new_element) {
