        list_size++;
    }

    // Function to remove an element from the list based on filter function
    void remove_elements(int threshold, int (*filter)(NFAPI_CRC_INDICATION_PDU_T*, int)) {
        for (int i = 0; i < list_size; i++) {
            if (filter(&list[i], threshold) == 1) {
                // Shift elements down to fill the gap
                for (int j = i; j < list_size - 1; j++) {
                    list[j] = list[j + 1];
                }
                list_size--;
                i--;  // Decrement i because we shifted an element
            }
        }
    }

    // Function to iterate over the list and print all elements
    void print_list() {
        for (int i = 0; i < list_size; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRCFLAG);
        }
