        for (int i = 0; i < batch_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T new_element;
            new_element.RX_UE_INFORMATION_TAG = rand();
            new_element.RNTI = rand();
            new_element.CRCFLAG = rand() % 2;

            add_element(new_element);
        }
    } else if (operation == REMOVE_ELEMENT) {
        remove_elements(threshold, filter);
    }

    // Compact the list to minimize memory usage
    if (list_size < MAX_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, list_size * sizeof(NFAPI_CRC_INDATION_PDU_T));
        if (new_list == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }
        list = new_list;
    }

    // Print the list
    print_list();

    // Free the memory allocated for the list
    free(list);
}
