        segment_configs[i].filename = argv[argc-3+i];
        strncpy(segment_configs[i].pattern, argv[2], sizeof(segment_configs[i].pattern));
    }
    int num_segment_configs = 3;

    // Process log file
    int result = parse_log_file(argv[1], segment_configs, num_segment_configs);

    // Free memory
    free(segment_configs);

    return result;
}

int parse_log_file(char* input_filename, segment_config* segment_configs, int num_segment_configs) {
    FILE* input_file = fopen(input_filename, "r");
    if (!input_file) {
        printf("Error opening input file: %s\n", input_filename);
        return -1;
    }

    char buffer[MAX_INPUT_FILE_SIZE];
    int current_position = 0;

    while (fgets(buffer, MAX_INPUT_FILE_SIZE, input_file)) {
        // Process segment
        process_segment(buffer, strlen(buffer), &segment_configs[0], num_segment_configs);

        current_position += strlen(buffer);
    }

    fclose(input_file);

    return 0;
}

void process_segment(char* segment, int segment_length, FILE** output_files, int num_output_files) {
    // Write segment to each output file
    for (int i = 0; i < num_output_files; i++) {
        fwrite(segment, 1, segment_length, output_files[i]);
    }
}

