            resolution_height = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "-q") == 0) {
            i++;
            quality = atoi(argv[i]);
        } else if (strcmp(argv[i], "-o") == 0) {
            i++;
            output_dir = argv[i];
        } else if (strcmp(argv[i], "-f") == 0) {
            force_overwrite = 1;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose_mode = 1;
        } else if (strcmp(argv[i], "-t") == 0) {
            i++;
            thread_count = atoi(argv[i]);
        }
    }

    // Process directories
    for (int i = 1; i < argc; i++) {
        char *dir = argv[i];

        // Check if directory exists
        struct stat sb;
        if (stat(dir, &sb) != 0) {
            printf("Error: Directory '%s' not found.\n", dir);
            continue;
        }

        // Process videos in the directory
        DIR *d;
        struct dirent *ent;
        d = opendir(dir);
        if (d == NULL) {
            printf("Error: Cannot open directory '%s'.\n", dir);
            continue;
        }
        while ((ent = readdir(d)) != NULL) {
            char *file_name = ent->d_name;
            if (strcmp(file_name, ".") == 0 || strcmp(file_name, "..") == 0) {
                continue;
            }

            // Check if file is a video
            if (!is_video_file(dir, file_name)) {
                continue;
            }

            // Generate preview and metadata summary
            generate_preview_and_metadata(dir, file_name, resolution_width, resolution_height, quality, force_overwrite, verbose_mode);

            // Save preview to output directory
            char *preview_file = malloc(strlen(output_dir) + strlen(file_name) + 5);
            strcpy(preview_file, output_dir);
            strcat(preview_file, "/");
            strcat(preview_file, file_name);
            strcat(preview_file, "_preview.mp4");
            save_preview(dir, file_name, preview_file);

            free(preview_file);
        }
        closedir(d);
    }

    return 0;
}
