['```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <string.h>
#include <pthread.h>

#define MAX_THREADS 4

typedef struct {
    char* path;
    int count_only;
    char* output_file;
} Args;

void* process_file(void* arg) {
    Args* args = (Args*)arg;
    FILE* file = fopen(args->path, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    int lines = 0;
    size_t chars = 0;

    char buffer[1024];
    while (fread(buffer, 1, 1023, file)) {
        lines++;
        chars += fread(buffer, 1, 1023, file);
    }
    fclose(file);

    if (!args->count_only) {
        printf("%s: %d lines, %zu characters\n", args->path, lines, chars);
    }

    return NULL;
}

int main(int argc, char** argv) {
    Args args = {0};
    int thread_count = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // Print man page
            printf("Manual page not implemented yet.\n");
            return 1;
        } else if (strcmp(argv[i], "-cs") == 0) {
            args.count_only = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            args.output_file = argv[++i];
        } else if (strstarts(argv[i], "--")) {
            // Unknown option
            printf("Unknown option: %s\n", argv[i]);
            return 1;
        } else {
            // File/directory path
            char* path = argv[i];
            if (access(path, F_OK) != -1 && !strcmp(argv[i], "-")) {
                // Standard input
                args.path = "";
            } else if (stat(path, &args.stat) == 0) {
                // Directory
                DIR* dir = opendir(path);
                if (!dir) {
                    perror("Error opening directory");
                    return 1;
                }
                while (1) {
                    struct dirent* ent = readdir(dir);
                    if (!ent)
                        break;
                    if (strcmp(ent->d_name, ".") && strcmp(ent->d_name, "..")) {
                        char* new_path = malloc(strlen(path) + strlen(ent->d_name) + 2);
                        strcpy(new_path, path);
                        strcat(new_path, "/");
                        strcat(new_path, ent->d_name);
                        args.path = new_path;
                        pthread_t thread;
                        if (pthread_create(&thread, NULL, process_file, &args) != 0) {
                            perror("Error creating thread");
                            free(new_path);
                            return 1;
                        }
                        if (++thread_count >= MAX_THREADS) {
                            while (thread_count > 0) {
                                pthread_join(thread, NULL);
                                thread_count--;
                            }
                            break;
                        }
                    }
                }
                closedir(dir);
            } else {
                // File
                args.path = path;
                pthread_t thread;
                if (pthread_create(&thread, NULL, process_file, &args) != 0) {
                    perror("Error creating thread");
                    return 1;
                }
                thread_count++;
            }
        }
    }

    while (thread_count > 0) {
        pthread_join(thread, NULL);
        thread_count--;
    }

    if (!args.output_file)
        printf("Total lines: %d, total characters: %zu\n", args.lines, args.chars);
    else {
        FILE* file = fopen(args.output_file, "w");
        if (file) {
            fprintf(file, "Total lines: %d, total characters: %zu\n", args.lines, args.chars);
            fclose(file);
        } else
            perror("Error opening output file");

    }

    return 0;
}
