#define THRESHOLD 0.7 // adjust this value based on available system resources

int main(int argc, char **argv) {
    // Initialize variables and parse command-line arguments
    int thread_count = 4;
    pthread_t *threads = NULL;
    int num_threads_allocated = 0;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [options]\n", argv[0]);
            exit(0);
        } else if (strncmp(argv[i], "-s", 2) == 0) {
            // Set thumbnail size
            int size = atoi(argv[i] + 2);
            // ...
        } else if (strncmp(argv[i], "-q", 2) == 0) {
            // Set quality
            int quality = atoi(argv[i] + 2);
            // ...
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            // Set output directory
            char *output_dir = argv[i] + 2;
            // ...
        } else if (strncmp(argv[i], "-f", 2) == 0) {
            // Set flag for concurrent access to output directory
            int concurrent_access = 1;
            // ...
        } else if (strncmp(argv[i], "-v", 2) == 0) {
            // Set verbosity level
            int verbosity = atoi(argv[i] + 2);
            // ...
        } else if (strncmp(argv[i], "-t", 2) == 0) {
            thread_count = atoi(argv[i] + 2);
        }
    }

    // Allocate threads based on available system resources
    num_threads_allocated = (int)((thread_count * THRESHOLD) + 0.5);

    if (num_threads_allocated > 0) {
        threads = (pthread_t *)malloc(num_threads_allocated * sizeof(pthread_t));
    } else {
        thread_count = 1; // fall back to single-threaded mode
    }

    // Process directories concurrently
    pthread_create(&threads[0], NULL, process_directory, NULL);
    for (int i = 1; i < num_threads_allocated; i++) {
        pthread_create(&threads[i], NULL, process_directory, NULL);
    }
    pthread_join(threads[0], NULL);

    // Clean up threads
    for (int i = 0; i < num_threads_allocated; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
}
