typedef struct LTE_EUTRA_SIB10_T {
    int tdd_ul_dl_config_idx;
    int subframe_offsets[8];
    long long cell_specific_ref_timestamp;
} LTE_EUTRA_SIB10_T;

typedef struct DynamicArray {
    LTE_EUTRA_SIB10_T* messages;
    size_t size, capacity;
} DynamicArray;

void dynamic_array_init(DynamicArray* array) {
    array->size = 0;
    array->capacity = 16;
    array->messages = (LTE_EUTRA_SIB10_T*)malloc(array->capacity * sizeof(LTE_EUTRA_SIB10_T));
}

int dynamic_array_add_message(DynamicArray* array, LTE_EUTRA_SIB10_T message) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->messages = (LTE_EUTRA_SIB10_T*)realloc(array->messages, array->capacity * sizeof(LTE_EUTRA_SIB10_T));
    }
    array->messages[array->size] = message;
    array->size++;
    return array->size - 1; // Return the index of the newly added message
}

int dynamic_array_update_message(DynamicArray* array, int idx, LTE_EUTRA_SIB10_T message) {
    if (idx >= array->size || idx < 0) {
        printf("Index out of bounds\n");
        return -1;
    }
    array->messages[idx] = message;
    return 0; // Success
}

int dynamic_array_get_message(DynamicArray* array, int cell_id, long long start_timestamp, long long end_timestamp, LTE_EUTRA_SIB10_T* messages, size_t* count) {
    *count = 0;
    for (int i = 0; i < array->size; i++) {
        if ((array->messages[i].cell_specific_ref_timestamp >= start_timestamp && array->messages[i].cell_specific_ref_timestamp <= end_timestamp) &&
            array->messages[i].cell_id == cell_id) {
            messages[(*count)++] = array->messages[i];
        }
    }
    return *count; // Return the count of retrieved messages
}

int dynamic_array_purge_outdated(DynamicArray* array, int age_threshold) {
    size_t i;
    for (i = 0; i < array->size; i++) {
        if (array->messages[i].cell_specific_ref_timestamp + age_threshold <= time(NULL)) {
            // Purge outdated messages
            memmove(&array->messages[i], &array->messages[i + 1], sizeof(LTE_EUTRA_SIB10_T) * (array->size - i));
            array->size--;
        }
    }
}

void dynamic_array_serialize(DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    fwrite(&array->size, sizeof(size_t), 1, file);
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->messages[i], sizeof(LTE_EUTRA_SIB10_T), 1, file);
    }
    fclose(file);
}

DynamicArray* dynamic_array_deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file\n");
        return NULL;
    }
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    fread(&array->size, sizeof(size_t), 1, file);
    array->messages = (LTE_EUTRA_SIB10_T*)malloc(array->size * sizeof(LTE_EUTRA_SIB10_T));
    for (int i = 0; i < array->size; i++) {
        fread(&array->messages[i], sizeof(LTE_EUTRA_SIB10_T), 1, file);
    }
    fclose(file);
    return array;
}
