#include <zlib.h>

typedef struct {
    int line_count;
    FILE* input_file;
    FILE* output_file;
    int compress;
    int verbose;
} Args;

Args parse_args(int argc, char** argv) {
    Args args = {0};
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-c] [-o output_file] [-v] [input_file]\n", argv[0]);
            exit(0);
        } else if (strcmp(argv[i], "-c") == 0) {
            args.compress = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            char* output_path = strtok(argv[i], "=");
            if (output_path != NULL) {
                args.output_file = fopen(output_path, "w");
                if (args.output_file == NULL) {
                    perror("Error opening output file");
                    exit(1);
                }
            } else {
                args.output_file = stdout;
            }
        } else if (strcmp(argv[i], "-v") == 0) {
            args.verbose = 1;
        } else if (i < argc && strlen(argv[i]) > 0) {
            args.input_file = fopen(argv[i], "r");
            if (args.input_file == NULL) {
                perror("Error opening input file");
                exit(1);
            }
            args.line_count = 0;
        }
    }
    return args;
}

void process_file(Args* args) {
    z_stream strm = {0};
    deflateInit2(&strm, Z_DEFAULT_COMPRESSION, Z_DEFAULT_CHARTYPE, Z_DEFAULT_WORKSPACE, 8, Z_DEFAULT_STRATEGY);
    unsigned char buffer[1024];
    int bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), args->input_file)) > 0) {
        strm.avail = sizeof(buffer);
        strm.next_in = buffer;
        do {
            strm.avail -= deflate(&strm, Z_DEFAULT_COMPRESSION, buffer);
        } while (strm.avail == 0 && !ferror(args->input_file));
        fwrite(buffer, 1, strm.total_out, args->output_file);
    }
    fclose(args->input_file);
    fclose(args->output_file);
}

int main(int argc, char** argv) {
    Args args = parse_args(argc, argv);
    if (args.input_file == NULL) {
        printf("Error: No input file specified. Use --help for usage information.\n");
        exit(1);
    }
    process_file(&args);
    return 0;
}
