struct {
    LTE_EUTRA_SIB10_T* messages[MAX_MESSAGES];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t num_messages;
    int msg_retrieval_freq[256];
    double msg_retrieval_latency[256];
} sib10_manager;

void init_sib10_manager() {
    for (int i = 0; i < MAX_MESSAGES; i++) {
        sib10_manager.messages[i] = NULL;
    }
    pthread_mutex_init(&sib10_manager.mutex, NULL);
    pthread_cond_init(&sib10_manager.cond, NULL);
    sib10_manager.num_messages = 0;
}

void add_sib10_message(int cell_id, int tdd_ul_dl_config_index, int subframe_offsets[8]) {
    size_t idx = sib10_manager.num_messages++;
    LTE_EUTRA_SIB10_T* msg = (LTE_EUTRA_SIB10_T*)malloc(sizeof(LTE_EUTRA_SIB10_T));
    if (!msg) return;

    msg->cell_id = cell_id;
    msg->tdd_ul_dl_config_index = tdd_ul_dl_config_index;
    memcpy(msg->subframe_offsets, subframe_offsets, sizeof(int) * 8);
