}

void update_sib10_message(int cell_id, int idx, LTE_EUTRA_SIB10_T* new_msg) {
    if (idx >= sib10_manager.num_messages) return;

    free(sib10_manager.messages[idx]);
    sib10_manager.messages[idx] = new_msg;
}

LTE_EUTRA_SIB10_T* get_sib10_message(int cell_id, int idx) {
    pthread_mutex_lock(&sib10_manager.mutex);
    if (idx >= sib10_manager.num_messages) {
        pthread_mutex_unlock(&sib10_manager.mutex);
        return NULL;
    }

    LTE_EUTRA_SIB10_T* msg = sib10_manager.messages[idx];
    pthread_cond_signal(&sib10_manager.cond);

    pthread_mutex_unlock(&sib10_manager.mutex);
    return msg;
}

void log_message_retrieval(int cell_id, double latency) {
    int idx = cell_id % 256;
    if (idx >= sizeof(sib10_manager.msg_retrieval_freq) / sizeof(int)) return;

    sib10_manager.msg_retrieval_freq[idx]++;
    sib10_manager.msg_retrieval_latency[idx] += latency;
}

