#include <string.h>

#define MAX_SIZE 1000000
#define FLOAT_FORMAT "%f"

int process_documents(const char* file_name) {
    FILE* file = fopen(file_name, "r");
    if (!file) return -1; // Error handling for file open failure

    float* numbers = NULL;
    int total_elements = 0;

    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break; // End of file reached

        char* token = strtok(line, FLOAT_FORMAT);
        if (!token) continue; // Invalid line format

        float num;
        if (sscanf(token, FLOAT_FORMAT, &num) != 1) {
            printf("Error: Invalid floating-point number format in document.\n");
            continue;
        }

        numbers = realloc(numbers, (total_elements + 1) * sizeof(float));
        if (!numbers) return -2; // Error handling for memory allocation failure

        numbers[total_elements++] = num;

        if (total_elements >= MAX_SIZE) {
            printf("Error: Document exceeds maximum allowed size of %d elements.\n", MAX_SIZE);
            free(numbers);
            numbers = NULL;
            total_elements = 0;
        }
    }

    fclose(file);

    if (!numbers || total_elements == 0) return -3; // Error handling for empty array

    qsort(numbers, total_elements, sizeof(float), float_compare);

    float average = 0.0f;
    for (int i = 0; i < total_elements; i++) {
        average += numbers[i];
    }
    average /= total_elements;

    printf("Average: %.2f\n", average);

    free(numbers);
    return 0;
}

int float_compare(const void* a, const void* b) {
    float fa = *(const float*)a;
    float fb = *(const float*)b;

    if (fa > fb) return -1;
    else if (fa < fb) return 1;
    else return 0;
}
