// Define the LTE_ENB_MESSAGE structure
typedef struct {
    char IMSI[13];
    int timestamp;
    void* NAS_Message; // payload pointer
} LTE_ENB_MESSAGE;

// Function to manage dynamic list of LTE_ENB_MESSAGE structures
void* manage_messages(int N, LTE_ENB_MESSAGE*** messages, int** total_messages, double** process_time) {
    *total_messages = 0;
    *process_time = 0.0;

    // Initialize the message structure array with default capacity
    int capacity = 10; 
    *messages = (LTE_ENB_MESSAGE**)malloc(capacity * sizeof(LTE_ENB_MESSAGE*));

    // Reuse existing structures if possible
    for (int i = 0; i < capacity - 1; i++) {
        if (!(*messages)[i]) {
            (*messages)[i] = malloc(sizeof(LTE_ENB_MESSAGE));
            break;
        }
    }

    // Handle memory allocation failures gracefully
    while (N > capacity) {
        capacity *= 2;
        *messages = realloc(*messages, capacity * sizeof(LTE_ENB_MESSAGE*));
    }

    // Process each message and allocate new memory if necessary
    for (int i = 0; i < N; i++) {
        LTE_ENB_MESSAGE* current_message = (*messages)[i % capacity];
        if (!current_message) {
            current_message = malloc(sizeof(LTE_ENB_MESSAGE));
            memcpy(current_message->IMSI, "123456789012", 13);
            current_message->timestamp = 0;
            current_message->NAS_Message = NULL;
        }

        // Validate IMSI and handle potential integer overflow
        if (atoi(current_message->IMSI) < 0 || atoi(current_message->IMSI) > 9999999999) {
            printf("Invalid IMSI: %s\n", current_message->IMSI);
        }
    }

    // Log memory leaks during testing
    #ifdef DEBUG_MODE
    for (int i = 0; i < capacity - 1; i++) {
        if (!(*messages)[i]) {
            free((*messages)[i]);
        }
    }
    free(*messages);
    #endif

    return current_message;
}

// Function to filter and retrieve messages based on specific IMSI values
LTE_ENB_MESSAGE* find_messages(LTE_ENB_MESSAGE** messages, int N, const char* target_IMSI) {
    LTE_ENB_MESSAGE* result = NULL;

    for (int i = 0; i < N; i++) {
        if (strcmp(messages[i]->IMSI, target_IMSI) == 0) {
            if (!result) {
                result = messages[i];
            }
        }
    }

    return result;
}
