    // function to add a new SIB10 message
    void add_message(int cell_id, int sib10_index, int tdd_ul_dl_config_index, int subframe_offsets[2]) {
        pthread_mutex_lock(&mutex);

        // allocate memory for the new message
        LTE_EUTRA_SIB10_T* new_message = (LTE_EUTRA_SIB10_T*)malloc(sizeof(LTE_EUTRA_SIB10_T));

        if (!new_message) {
            perror("Failed to allocate memory for SIB10 message");
            pthread_mutex_unlock(&mutex);
            return;
        }

        // copy the passed parameters to the new message
        new_message->cell_id = cell_id;
        new_message->sib10_index = sib10_index;
        new_message->tdd_ul_dl_config_index = tdd_ul_dl_config_index;
        memcpy(new_message->subframe_offsets, subframe_offsets, sizeof(int) * 2);

        // append the new message to the dynamic array
        for (int i = 0; i < MAX_MESSAGES; i++) {
            if (!sib10_messages[i]) {
                sib10_messages[i] = new_message;
                break;
            }
        }

        pthread_mutex_unlock(&mutex);

