        pthread_mutex_lock(&mutex);

        for (int i = 0; i < MAX_MESSAGES; i++) {
            if (sib10_messages[i] && sib10_messages[i]->cell_id == cell_id && sib10_messages[i]->sib10_index == sib10_index) {
                // update the existing message
                sib10_messages[i]->tdd_ul_dl_config_index = tdd_ul_dl_config_index;
                memcpy(sib10_messages[i]->subframe_offsets, subframe_offsets, sizeof(int) * 2);

                pthread_mutex_unlock(&mutex);

                // log the operation
                fprintf(log_file, "%ld: Updated SIB10 message with cell ID %d and index %d\n", time(NULL), cell_id, sib10_index);
                return;
            }
