        pthread_mutex_unlock(&mutex);

        // log the operation (no matching message found)
        fprintf(log_file, "%ld: No matching SIB10 message found for cell ID %d and index %d\n", time(NULL), cell_id, sib10_index);
    }

    // function to retrieve a SIB10 message based on its cell ID
    LTE_EUTRA_SIB10_T* get_message(int cell_id) {
        pthread_mutex_lock(&mutex);

        for (int i = 0; i < MAX_MESSAGES; i++) {
            if (sib10_messages[i] && sib10_messages[i]->cell_id == cell_id) {
