    int cs = 0;
    FILE *input_file = NULL;
    FILE *output_file = NULL;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--manpage")) {
            // Display detailed usage instructions
            printf("Usage: %s [options] input_file\n", argv[0]);
            printf("Options:\n");
            printf("- --manpage\tDisplay this help message.\n");
            printf("- -cs\tEnable case-sensitive word counting.\n");
            printf("- -o output_file\tSpecify the output file path for the summary report.\n");
            exit(0);
        } else if (!strcmp(argv[i], "-cs")) {
            cs = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (output_file == NULL) {
                perror("Error opening output file");
                exit(1);
            }
        } else {
            // Check if the remaining argument is an input file
            if (input_file == NULL && !strcmp(argv[i], "-")) {
                input_file = stdin;
            } else if (access(argv[i], F_OK) != -1) {
                input_file = fopen(argv[i], "r");
                if (input_file == NULL) {
                    perror("Error opening input file");
                    exit(1);
                }
            }
        }
    }

    // Check if an input file was provided
    if (input_file == NULL) {
        printf("Usage: %s [options] input_file\n", argv[0]);
        exit(1);
    }

    // Initialize a hash table to store unique words and their frequencies
    int *word_freq = calloc(256, sizeof(int));
    char line[1024];

    if (output_file == NULL) {
        output_file = stdout;
    }

    while (fgets(line, sizeof(line), input_file)) {
        int len = strlen(line);
        for (int i = 0; i < len; i++) {
            char c = tolower((char)line[i]);
            if (!cs && isalpha(c))
                c = toupper(c);
            line[i] = c;
        }

        // Tokenize the line and update the word frequency
        char *word = strtok(line, " ");
        while (word != NULL) {
            int index = (int)*word - 'a';
            if (!cs && isupper((char)*word))
                index += 26;

            if (word_freq[index] == 0)
                word_freq[index]++;
            word = strtok(NULL, " ");
        }
    }

    // Print the summary report
    printf("Summary Report:\n");
    for (int i = 0; i < 256; i++) {
        if (word_freq[i] > 0) {
            fprintf(output_file, "%c: %d\n", 'a' + i, word_freq[i]);
        }
    }

    fclose(input_file);
    fclose(output_file);

    free(word_freq);

    return 0;
}
