#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_METADATA_ENTRIES 1000000
#define MAX_LINE_LENGTH 1024

typedef struct {
    char field1[64];
    int field2;
    float field3;
} MetadataEntry;

MetadataEntry* metadataEntries = NULL;
int numEntries = 0;

void processImage(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file %s\n", filename);
        return;
    }

    MetadataEntry* currentEntry = NULL;
    int currentNumEntries = 0;

    while (1) {
        char line[MAX_LINE_LENGTH];
        if (!fgets(line, sizeof(line), file)) break;

        if (strlen(line) > 1 && line[0] == '#') continue; // Ignore comments

        MetadataEntry* newEntry = (MetadataEntry*)malloc(sizeof(MetadataEntry));
        if (!newEntry) {
            printf("Memory allocation failure\n");
            fclose(file);
            return;
        }

        if (sscanf(line, "#%63s %d %.2f", newEntry->field1, &newEntry->field2, &newEntry->field3) != 3) {
            free(newEntry);
            continue; // Ignore invalid lines
        }

        currentNumEntries++;
        if (currentNumEntries >= MAX_METADATA_ENTRIES) {
            printf("Image %s exceeds maximum allowed size\n", filename);
            fclose(file);
            return;
        }

        if (!metadataEntries) {
            metadataEntries = newEntry;
        } else {
            MetadataEntry* prevEntry = metadataEntries;
            while (prevEntry->field2 >= newEntry->field2) {
                prevEntry = prevEntry->next;
            }
            newEntry->next = prevEntry->next;
            prevEntry->next = newEntry;
        }

        currentEntry = newEntry;
    }

    fclose(file);
}

void calculateAverage() {
    if (!metadataEntries) return;

    MetadataEntry* entry = metadataEntries;
    int sumField2 = 0, countField2 = 0;
    float sumField3 = 0.0f, countField3 = 0.0f;

    while (entry) {
        sumField2 += entry->field2;
        countField2++;
        sumField3 += entry->field3;
        countField3++;

        entry = entry->next;
    }

    printf("Average field2: %.2f\n", (float)sumField2 / countField2);
    printf("Average field3: %.4f\n", sumField3 / countField3);
}

int main() {
    FILE* file = fopen("metadata.txt", "r");
    if (!file) {
        printf("Error opening file\n");
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        int i = 0;
        while (line[i]) {
            // Process each image separately
            processImage(file ? "image.txt" : "");
            if (metadataEntries) break;

            i++;
        }
    }

    calculateAverage();

    return 0;
}
