#include <string.h>

int findLargest(int* arr, int n) {
    int low = 0;
    int high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if ((mid == 0 || arr[mid] >= arr[mid - 1]) && (mid == n - 1 || arr[mid] >= arr[mid + 1]))
            return mid;
        else if (arr[high] > arr[mid])
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1; // Return -1 for invalid input
}

int main() {
    int maxSize = 10000;
    int* arr = NULL;

    printf("Enter a list of integers (max size: %d).\n", maxSize);
    FILE* file = stdin;

    if ((arr = (int*)malloc(maxSize * sizeof(int))) == NULL) {
        fprintf(stderr, "Error allocating memory.\n");
        return 1; // Exit with error
    }

    int count = 0;
    while (count < maxSize && (fscanf(file, "%d", &arr[count]) == 1)) {
        if (feof(file))
            break;
        else if (ferror(file) || (int)arr[count] != arr[count]) {
            fprintf(stderr, "Error reading input.\n");
            free(arr);
            return 1; // Exit with error
        }
        count++;
    }

    if (count >= maxSize) {
        printf("Input exceeds maximum size.\n");
        free(arr);
        return 1; // Exit with error
    }

    for (int i = 0; i < count; i++) {
        for (int j = i + 1; j <= count - 1 && j < maxSize; j++) {
            if (arr[i] > arr[j]) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }

    int maxPos = findLargest(arr, count);

    if (maxPos != -1) {
        printf("The largest integer in the array is %d at position %d.\n", arr[maxPos], maxPos);
    } else {
        printf("Invalid input. No valid integers found.\n");
    }

    free(arr);

    return 0;
}
