}

vector<string> split(const string& s, char c) {
    vector<string> result;
    size_t pos = 0;
    while ((pos = s.find(c)) != string::npos) {
        result.push_back(s.substr(0, pos));
        s.erase(0, pos + 1);
    }
    result.push_back(s);
    return result;
