#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_EVENTS 10000000 // Maximum allowed size for event storage
#define INSTANCES 10 // Number of instances to handle simultaneously
#define BUFFER_SIZE 1024 // Buffer size for file reading

// Event record structure
typedef struct {
    int INSTANCE_ID;
    char EVENT_TYPE[20];
    long TIMESTAMP;
} EventRecord_t;

// Function prototypes
EventRecord_t* initializeInstances(int);
void processLogFiles(char**, int, int*, double*);
void calculateAverageDuration(EventRecord_t**, int);
int validateEventRecord(EventRecord_t*);

int main() {
    // Initialize instances
    EventRecord_t* instances = initializeInstances(INSTANCES);

    // Process log files
    char** logFiles = {"file1.log", "file2.log", "file3.log"};
    int numLogFiles = sizeof(logFiles) / sizeof(logFiles[0]);
    int totalEventsProcessed = 0;
    double averageDuration = 0.0;

    processLogFiles(logFiles, numLogFiles, &totalEventsProcessed, &averageDuration);

    // Print results
    printf("Total events processed: %d\n", totalEventsProcessed);
    printf("Average duration: %.2f seconds\n", averageDuration);

    return 0;
}

EventRecord_t* initializeInstances(int numInstances) {
    EventRecord_t* instances = (EventRecord_t*)malloc(numInstances * sizeof(EventRecord_t));
    for (int i = 0; i < numInstances; i++) {
        instances[i].INSTANCE_ID = i + 1;
        strcpy(instances[i].EVENT_TYPE, "unknown");
        instances[i].TIMESTAMP = 0;
    }
    return instances;
}

void processLogFiles(char** logFiles, int numLogFiles, int* totalEventsProcessed, double* averageDuration) {
    FILE* file;
    char buffer[BUFFER_SIZE];
    EventRecord_t* events = (EventRecord_t*)malloc(MAX_EVENTS * sizeof(EventRecord_t));
    int eventCount = 0;

    for (int i = 0; i < numLogFiles; i++) {
        file = fopen(logFiles[i], "r");
        if (!file) {
            printf("Error opening file %s.\n", logFiles[i]);
            continue;
        }

        while (fgets(buffer, BUFFER_SIZE, file)) {
            EventRecord_t event;

            // Validate and process event record
            int bytesRead = sscanf(buffer, "%d %19s %ld", &event.INSTANCE_ID, event.EVENT_TYPE, &event.TIMESTAMP);
            if (bytesRead != 3) {
                printf("Invalid event record in file %s.\n", logFiles[i]);
                continue;
            }

            // Accumulate valid records
            events[eventCount++] = event;

            // Check for maximum allowed size
            if (eventCount >= MAX_EVENTS) {
                printf("File %s exceeds the maximum allowed size.\n", logFiles[i]);
                break;
            }
        }

        fclose(file);
    }

    *totalEventsProcessed = eventCount;
    calculateAverageDuration(&events, eventCount);
}

void calculateAverageDuration(EventRecord_t** events, int eventCount) {
    // Sort events by timestamp in descending order
    qsort(events[0], eventCount, sizeof(EventRecord_t), (int (*)(const void*, const void*))compareEventRecords);

    // Calculate average duration
    double sum = 0.0;
    for (int i = 0; i < eventCount; i++) {
        sum += events[0][i].TIMESTAMP;
    }
    *averageDuration = sum / eventCount;
}

int compareEventRecords(const void* a, const void* b) {
    EventRecord_t* eventA = *(EventRecord_t**)a;
    EventRecord_t* eventB = *(EventRecord_t**)b;

    return (eventB->TIMESTAMP - eventA->TIMESTAMP);
}
