#include <math.h>

#define MAX_SIZE 50000
#define INVALID_INPUT -1

int find_largest(int* arr, int n) {
    if (n == 0)
        return INVALID_INPUT;
    else if (n == 1)
        return arr[0];

    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void print_summary(int* counts, int total_count) {
    printf("Summary:\n");
    printf("Number of datasets processed: %d\n", total_count / MAX_SIZE);
    printf("Total count of integers processed: %d\n", total_count);
    for (int i = 0; i <= total_count; i++) {
        if (counts[i] > 0) {
            printf("Frequency of integer value %d: %d\n", i, counts[i]);
        }
    }
}

void process_dataset(int** datasets, int* n_datasets, int* total_count, int* counts) {
    for (int i = 0; i < *n_datasets; i++) {
        double max_val = -1;
        int dataset_size = 0;

        // Read and validate the current dataset
        while ((dataset_size < MAX_SIZE) && scanf("%lf", &max_val)) {
            if (ferror(stdin) || feof(stdin))
                break;

            // Round floating-point numbers to nearest integer
            int val = (int)round(max_val);

            // Validate against the maximum size and store in array
            if (dataset_size < MAX_SIZE && (val >= -1)) {
                datasets[i][dataset_size++] = val;
            } else {
                printf("Error: Dataset exceeded maximum size.\n");
                exit(EXIT_FAILURE);
            }
        }

        // Check for invalid input
        if (ferror(stdin) || feof(stdin))
            printf("Error: Invalid input detected.\n");

        // Print the largest integer in the current dataset
        int max = find_largest(datasets[i], dataset_size);
        printf("Largest integer in dataset %d: %d\n", i + 1, max);

        // Update summary statistics
        *total_count += dataset_size;
        for (int j = 0; j < dataset_size; j++) {
            int val = datasets[i][j];
            counts[val]++;
        }
    }

    print_summary(counts, *total_count);
}

int main() {
    int n_datasets = 0;
    scanf("%d", &n_datasets);

    int** datasets = (int**)malloc(n_datasets * sizeof(int*));
    for (int i = 0; i < n_datasets; i++) {
        datasets[i] = (int*)malloc(MAX_SIZE * sizeof(int));
    }

    int total_count = 0;
    int* counts = (int*)calloc(MAX_SIZE + 1, sizeof(int));

    process_dataset(datasets, &n_datasets, &total_count, counts);

    for (int i = 0; i < n_datasets; i++) {
