#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int IMSI;
    ENB_UPLINK_NAS_TRANSPORT nas_transport;
    char NAS_Message[];
} LTE_ENB_MESSAGE;

int manageLTEENBMessages(int N) {
    // Initialize variables to track total messages, processing time, and memory allocation failures
    int total_messages = 0;
    double total_processing_time = 0.0;
    int allocation_failures = 0;

    // Define the size of each LTE_ENB_MESSAGE structure
    size_t message_size = sizeof(LTE_ENB_MESSAGE) + strlen("Initial NAS Message");

    // Create a dynamic list to store LTE_ENB_MESSAGE structures
    LTE_ENB_MESSAGE** message_list = (LTE_ENB_MESSAGE**)malloc(N * sizeof(LTE_ENB_MESSAGE*));

    if (!message_list) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize the message list with null pointers
    for (int i = 0; i < N; i++) {
        message_list[i] = NULL;
    }

    // Initialize a flag to track if we're reusing existing structures or allocating new ones
    int reuse_message = 0;

    // Process each LTE_ENB_MESSAGE structure
    for (int i = 0; i < N; i++) {
        // Allocate memory for the current LTE_ENB_MESSAGE structure, considering potential integer overflow
        LTE_ENB_MESSAGE* message = (LTE_ENB_MESSAGE*)malloc(message_size);

        if (!message) {
            allocation_failures++;
            continue;
        }

        // Initialize the message with a valid IMSI and timestamp
        message->IMSI = rand() % 9999999999 + 1;
        time_t current_timestamp = time(NULL);
        strcpy((char*)message->nas_transport, "Initial NAS Message");
        message->timestamp = current_timestamp;

        // If we're not reusing existing structures, mark the first available slot as occupied
        if (!reuse_message) {
            for (int j = 0; j < N; j++) {
                if (!message_list[j]) {
                    message_list[j] = message;
                    break;
                }
            }

            // Update the reuse flag and total messages processed
            reuse_message = 1;
            total_messages++;
        } else {
            // If we're reusing existing structures, simply mark the current slot as occupied
            message_list[i] = message;
            total_messages++;
        }

        // Calculate processing time for each message
        double processing_time = difftime(time(NULL), current_timestamp);
        total_processing_time += processing_time;

        printf("Processed message %d with IMSI %d and timestamp %.2f.\n", i + 1, message->IMSI, processing_time);

        free(message);
    }

    // Print statistics
    printf("Total messages processed: %d\n", total_messages);
    printf("Average processing time per message: %.2f seconds\n", total_processing_time / total_messages);
    if (allocation_failures > 0) {
        printf("Memory allocation failed %d times.\n", allocation_failures);
    }

    // Free the message list
    for (int i = 0; i < N; i++) {
        free(message_list[i]);
    }
    free(message_list);

    return 0;
}

int main() {
    int N = 10; // Set the desired size of the dynamic list

    manageLTEENBMessages(N);

    return 0;
}
