void read_integers_from_network(int sockfd, int max_size, int** array_ptr) {
    *array_ptr = (int*) malloc(max_size * sizeof(int));
    if (*array_ptr == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }
    int i = 0;
    while (i < max_size && read(sockfd, &((*array_ptr)[i]), sizeof(int)) > 0) {
        i++;
    }
    (*array_ptr) += i;
}

int find_largest_integer(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void print_largest_integer(int sockfd, int max_size, int* array_ptr) {
    int largest = find_largest_integer(array_ptr, max_size);
    printf("Largest integer: %d\n", largest);
    free(array_ptr);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(1);
    }
    struct sockaddr_in servaddr;
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);
    connect(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr));

    int max_size = 10000;
    int* array_ptr = NULL;
    read_integers_from_network(sockfd, max_size, &array_ptr);

    // Validate the array
    for (int i = 1; i < max_size; i++) {
        if (array_ptr[i - 1] > array_ptr[i]) {
            printf("Array is not sorted in ascending order.\n");
            exit(1);
        }
    }

    print_largest_integer(sockfd, max_size, array_ptr);

    close(sockfd);
    return 0;
}
