NFAPI_CRC_INDICATION_PDU_T* init_crc_indication(int n, int (*callback)(int), void (*logger)(const char*)) {
    NFAPI_CRC_INDICATION_PDU_T* pds = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pds) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int i;
    srand(time(NULL)); // Seed random number generator
    for (i = 0; i < n; i++) {
        pds[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pds[i].RNTI = rand() % 200;
        pds[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        if (callback) callback(i);
    }

    for (i = 0; i < n; i++) {
        int crcflag = rand() % 2;
        if (crcflag == 1) {
            pds[i].CRC_INDICATION_REL8_TAG |= (1 << 15); // Set CRCFLAG
        }
    }

    for (i = 0; i < n; i++) {
        if (!pds[i].RX_UE_INFORMATION_TAG || !pds[i].RNTI) {
            printf("Default values used: RX_UE_INFORMATION_TAG=%d, RNTI=%d.\n", pds[i].RX_UE_INFORMATION_TAG, pds[i].RNTI);
            if (logger) logger("Default values used for UE tag and RNTI.");
        }
    }

    // Validate CRC indication data
    for (i = 0; i < n; i++) {
        if (pds[i].CRC_INDICATION_REL8_TAG & (1 << 15)) {
            printf("CRCFLAG set for structure %d.\n", i);
        } else {
            printf("No CRCFLAG set for structure %d.\n", i);
        }
    }

    return pds;
}

void free_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pd, int n) {
    free(pd);
}
