LTE_ENB_MESSAGE** lte_enb_message_list(LTE_ENB_MESSAGE*** current_messages, int* N) {
    // Single-message mode or batch-processing mode?
    if (*N == 1) {
        // Single-message mode: attempt to reuse previously allocated structure
        for (int i = 0; i < *N; i++) {
            LTE_ENB_MESSAGE** message = current_messages;
            // Validate IMSI and handle memory allocation failures gracefully
            if (!(*message)->IMSI || (*message)->IMSI > 999999999) {
                return NULL; // Invalid IMSI or memory allocation failure
            }
        }
    } else {
        // Batch-processing mode: process each batch independently but share common metadata
        for (int i = 0; i < *N; i++) {
            LTE_ENB_MESSAGE** message = current_messages;
            // Validate IMSI and handle memory allocation failures gracefully
            if (!(*message)->IMSI || (*message)->IMSI > 999999999) {
                return NULL; // Invalid IMSI or memory allocation failure
            }
        }
    }

    // Dynamically resize the message list when the current capacity is exceeded
    int new_capacity = *N * 2;
    LTE_ENB_MESSAGE** new_messages = realloc(*current_messages, sizeof(LTE_ENB_MESSAGE*) * new_capacity);
    if (new_messages == NULL) {
