// Define structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to process datasets and generate array of NFAPI_CRC_INDICATION_PDU_T structures
void processDatasets(int numDatasets, int maxElementsPerDataset) {
    // Initialize variables
    int totalProcessed = 0;
    int uniqueIntegers[10000] = {0}; // Assuming maximum frequency is 10,000
    int largestIntegerInEachDataset[numDatasets];
    NFAPI_CRC_INDICATION_PDU_T *pduArray = NULL;

    // Process datasets in parallel using multi-threading
    #pragma omp parallel num_threads(4) // Adjust the number of threads based on your system's capabilities
    {
        int myID = omp_get_thread_num();
        int start, end;

        #pragma omp for schedule(dynamic)
        for (int i = 0; i < numDatasets; i++) {
            int *dataset = (int *)malloc(maxElementsPerDataset * sizeof(int));
            if (!dataset) {
                // Handle memory allocation failure
                fprintf(stderr, "Memory allocation failed for dataset %d.\n", i);
                continue;
            }

            // Initialize retry logic with exponential backoff for critical allocations
            int maxAttempts = 3;
            int delay = 1; // Initial delay in milliseconds

            while (delay <= maxAttempts) {
                if (!dataset) break;

                // Validate dataset to check if it is sorted in ascending order
                int prevElement = INT_MIN;
                for (int j = 0; j < maxElementsPerDataset; j++) {
                    if (dataset[j] < prevElement) {
                        free(dataset);
                        fprintf(stderr, "Dataset %d is not sorted.\n", i);
                        return;
                    }
                    prevElement = dataset[j];
                }

                // Find and print the largest integer in each dataset
                int largestInteger = INT_MIN;
                for (int j = 0; j < maxElementsPerDataset; j++) {
                    if (dataset[j] > largestInteger) largestInteger = dataset[j];
                }
                printf("Largest integer in dataset %d: %d\n", i, largestInteger);

                // Update unique integers and total processed count
                for (int j = 0; j < maxElementsPerDataset; j++) {
                    if (!uniqueIntegers[dataset[j]]) uniqueIntegers[dataset[j]]++;
                    totalProcessed++;
                }

                break;
            }

            free(dataset);
        }
    }

    // Print summary of datasets processed, total count of integers processed, and frequency of each unique integer value
    printf("Total datasets processed: %d\n", numDatasets);
    printf("Total count of integers processed: %d\n", totalProcessed);
    for (int i = 0; i < 10000; i++) {
        if (uniqueIntegers[i]) printf("Frequency of integer %d: %d\n", i, uniqueIntegers[i]);
    }

    // Generate and populate array of NFAPI_CRC_INDICATION_PDU_T structures
    pduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numDatasets * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T structures.\n");
        return;
    }

    for (int i = 0; i < numDatasets; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand();
        pduArray[i].RNTI = rand();
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : -1;
    }

    // Print NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < numDatasets; i++) {
        printf("NFAPI_CRC_INDICATION_PDU_T structure %d: RX_UE_INFORMATION_TAG = %d, RNTI = %d, CRC_INDICATION_REL8_TAG = %s\n",
               i, pduArray[i].RX_UE_INFORMATION_TAG, pduArray[i].RNTI,
               pduArray[i].CRC_INDICATION_REL8_TAG > 0 ? "valid" : "invalid");
    }

    free(pduArray);
}
