        srb->type = (rand() % SRB_TYPE_MAX);
        srb->priority = rand() % 16;
        srb->dataSize = rand() % 1000; // adjust the max size based on your needs
        srb->data = malloc(srb->dataSize);
        for(int j=0;j< srb->dataSize;j++)
            srb->data[j] = (unsigned char)rand();

        time(&srb->timestamp);
        srb->seqNum = i;

        srbs[i] = srb;
    }

    return srbs;
}

void lte_uplink_srbs_deinit(void* pool, int N) {
    LTE_UPLINK_SRB_T** srbs = (LTE_UPLINK_SRB_T**)pool;
    for(int i=0; i < N; i++) {
        free(srbs[i]->data);
        free(srbs[i]);
    }

    free(pool);
}

