void process_datasets(int numDatasets, int datasetSize, int **datasets) {
    // Initialize counters and arrays for processing results
    int totalCount = 0;
    int *uniqueCounts = (int *)malloc((datasetSize + 1) * sizeof(int));
    for (int i = 0; i <= datasetSize; i++) {
        uniqueCounts[i] = 0;
    }

    // Create a thread pool to process datasets in parallel
    pthread_t *threads = (pthread_t *)malloc(numDatasets * sizeof(pthread_t));
    for (int i = 0; i < numDatasets; i++) {
        pthread_create(&threads[i], NULL, process_dataset, (void *)datasets[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < numDatasets; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print processing results
    printf("Processed %d datasets.\n", numDatasets);
    printf("Total count: %d\n", totalCount);

    // Free memory allocated for unique counts
    free(uniqueCounts);
}

void *process_dataset(void *dataset) {
    int datasetSize = *((int *)dataset);
    int *data = (int *)malloc(datasetSize * sizeof(int));
    for (int i = 0; i < datasetSize; i++) {
        data[i] = rand() % 100; // Replace with actual dataset values
    }

    // Validate and sort the dataset in ascending order
    qsort(data, datasetSize, sizeof(int), compare_ints);

    int largestInt = -1;
    for (int i = 0; i < datasetSize; i++) {
        if (data[i] > largestInt) {
            largestInt = data[i];
        }
    }

    printf("Largest integer in dataset: %d\n", largestInt);

    // Free memory allocated for the dataset
    free(data);
}

int compare_ints(const void *a, const void *b) {
    int val1 = *(const int *)a;
    int val2 = *(const int *)b;

    if (val1 < val2) return -1;
    if (val1 > val2) return 1;
    return 0;
}
