// Define a structure to represent network slice instances
typedef struct {
    int id;
    char name[20];
    int servicesCount;
} NetworkSliceInstance;

// Define a structure to represent services within an instance
typedef struct {
    char type[10];
    char version[10];
    int parametersCount;
} Service;

// Function to read input, store data, validate arrays, and determine the maximum value
void manageGraph(int maxElements) {
    // Declare variables to store the graph database
    NetworkSliceInstance* instances = NULL;
    int instancesCount = 0;
    int servicesTotalCount = 0;

    // Read input from standard input
    while (scanf("%d", &maxElements) && maxElements <= 10000) {
        // Allocate memory for new instance and service structures
        if (instancesCount >= sizeof(instances) / sizeof(instances[0])) {
            instances = realloc(instances, (instancesCount + 1) * sizeof(NetworkSliceInstance));
        }
        if (servicesTotalCount >= sizeof(*instances) / sizeof((*instances).servicesCount)) {
            (*instances).servicesCount = realloc((*instances).servicesCount, (servicesTotalCount + 1) * sizeof(Service));
        }

        // Handle potential memory allocation failures gracefully
        if (!instances || !(*instances).servicesCount) {
            printf("Memory allocation failed. Exiting.\n");
            exit(1);
        }
    }

    // Check if input exceeded the maximum size, print an error message and exit
    if (maxElements > 10000) {
        printf("Input exceeds maximum size of 10,000 elements. Exiting.\n");
        exit(1);
    }

    // Find and print the largest integer in the array, considering negative numbers
    int maxVal = 0;
    for (int i = 0; i < instancesCount; i++) {
        if (*instances[i].id > maxVal) {
            maxVal = *instances[i].id;
        }
    }

    // Validate if the input array is sorted in ascending order
    bool isSorted = true;
    for (int i = 1; i < instancesCount; i++) {
        if (*instances[i-1].id >= *instances[i].id) {
            isSorted = false;
            break;
        }
    }

    // Check if all integers are negative, handle robust error handling
    bool allNegative = true;
    for (int i = 0; i < instancesCount; i++) {
        if (*instances[i].id > 0) {
            allNegative = false;
            break;
        }
    }

    printf("Largest integer: %d\n", maxVal);
    if (!isSorted) {
        printf("Input array is not sorted.\n");
    } else if (allNegative) {
        printf("All integers are negative.\n");
    }
}

int main() {
    int maxElements;
    scanf("%d", &maxElements);
    manageGraph(maxElements);
    return 0;
}
