// Structure to hold the largest and average integer values
typedef struct {
    int max;
    double avg;
} result_t;

result_t find_largest(int* arr, int size) {
    result_t res = {INT_MIN, 0.0};

    for (int i = 0; i < size; i++) {
        if (arr[i] > res.max) {
            res.max = arr[i];
        }

        res.avg += arr[i];
    }

    res.avg /= size;

    return res;
}

int main() {
    int max_size = 10000;
    char* filename = NULL;
    FILE* file = stdin;

    // Check if the input stream is a file
    if (stdin != fileno) {
        filename = getenv("FILENAME");
        file = fopen(filename, "r");
        if (!file) {
            printf("Error opening file: %s\n", strerror(errno));
            return 1;
        }
    }

    int* arr = NULL;
    int size = 0;

    // Read the input integers from the file/stream
    while ((size < max_size || fgetc(file) == '\n') && (ferror(file) == 0)) {
        if (!arr) {
            arr = malloc(sizeof(int));
        } else {
            arr = realloc(arr, sizeof(int) * ++size);
        }

        fscanf(file, "%d", &arr[size - 1]);
    }

    // Close the file
    fclose(file);

    // Check for overflow
    if (size > max_size) {
        printf("Error: Input exceeds maximum size of %d elements.\n", max_size);
        free(arr);
        return 1;
    }

    // Validate the input array is sorted in ascending order
    for (int i = 0; i < size - 1; i++) {
        if (arr[i] >= arr[i + 1]) {
            printf("Error: Input array is not sorted.\n");
            free(arr);
            return 1;
        }
    }

    result_t res = find_largest(arr, size);

    // Print the results
    printf("Largest integer: %d\n", res.max);
    if (size > 0) {
        printf("Average integer: %.2f\n", res.avg);
    } else {
        printf("No integers found.\n");
    }

    free(arr);

    return 0;
}

