    char *file_format;
};

int main(int argc, char *argv[]) {
    if (argc == 1) {
        print_usage();
        return 0;
    }

    struct options opt = {0};
    opt.parallel = parse_options(argc, argv);

    // Parse configuration file
    FILE *config_file = fopen("config.txt", "r");
    if (!config_file) {
        err(1, "Failed to open config file");
    }
    struct config cfg;
    fscanf(config_file, "%s\n", &cfg.file_format);
    fclose(config_file);

    process_files(opt.parallel);

    free_memory();

    return 0;
}

void print_usage() {
    printf("Usage: program [options] [input files]\n");
    printf("-cs, --sort-csv : Sort CSV file by the last field\n");
    printf("-o output_file, --output-file=OUTPUT_FILE : Specify the output file name\n");
    printf("--manpage : Display manual page for this program\n");
    printf("--parallel, -p : Process files in parallel\n");
}

int parse_options(int argc, char *argv[]) {
    int opt = 0;
    int parallel = 0;

    while ((opt = getopt(argc, argv, "cs:o:pm")) != -1) {
        switch (opt) {
            case 'c':
                break;
            case 's':
                break;
            case 'o':
                // Store the output file name
                break;
            case 'p':
                parallel = 1;
                break;
            case 'm':
                break;
            default:
                print_usage();
                return -1;
        }
    }

    if (optind > argc) {
        print_usage();
        return -1;
    }

    return parallel;
}

void process_files(int num_files) {
    // Read and process files in parallel
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, (void *) &i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
}

void free_memory() {
    // Free memory allocated for each line
}
