// Function to find the largest integer in an array
int max_integer(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

// Function to calculate the average of integers in an array
double avg_integer(int* arr, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    return sum / n;
}

void read_and_analyze(int** p_arr, int* p_n) {
    *p_arr = malloc(10000 * sizeof(int));
    *p_n = 0;

    int num;
    while (scanf("%d", &num) == 1 && (*p_n < 10000)) {
        (*p_arr)[*p_n] = num;
        (*p_n)++;
    }

    if (*p_n > 0) {
        printf("Largest integer: %d\n", max_integer(*p_arr, *p_n));
        printf("Average integer: %.2f\n", avg_integer(*p_arr, *p_n));

        free(*p_arr);
    }
}

