void* process_dataset(void* arg) {
    int* dataset = (int*)arg;
    int max_val = INT_MIN;
    for(int i = 0; i < MAX_SIZE; i++) {
        if(dataset[i] > max_val)
            max_val = dataset[i];
    }
    printf("Largest integer in the dataset: %d\n", max_val);
}

void* validate_dataset(void* arg) {
    int* dataset = (int*)arg;
    for(int i = 0; i < MAX_SIZE - 1; i++) {
        if(dataset[i] >= dataset[i+1]) {
            printf("Dataset not sorted in ascending order.\n");
            exit(1);
        }
    }
}

void process_datasets(int** datasets, int num_datasets) {
    pthread_t threads[THREADS];
    for(int i = 0; i < num_datasets; i++) {
        pthread_create(&threads[i], NULL, validate_dataset, (void*)datasets[i]);
        pthread_join(threads[i], NULL);
    }
}

