        arr[i].RNTI = rand() % 50;
        strcpy(arr[i].CRC_INDICATION_REL8_TAG, "Random CRC Flag");
    }
}

void print_frequency(int* dataset, int num_elements) {
    int freq[100];
    for(int i = 0; i < 100; i++) {
        freq[i] = 0;
    }
    for(int i = 0; i < num_elements; i++) {
        if(dataset[i] >= 0)
            freq[dataset[i]]++;
    }
    for(int i = 0; i < 100; i++) {
        printf("Frequency of %d: %d\n", i, freq[i]);
    }
}

int main() {
    int num_datasets = 5;
    int** datasets = (int**)malloc(num_datasets * sizeof(int*));
    for(int i = 0; i < num_datasets; i++) {
        datasets[i] = (int*)malloc(MAX_SIZE * sizeof(int));
        if(datasets[i] == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
    }

    for(int i = 0; i < num_datasets; i++) {
        for(int j = 0; j < MAX_SIZE; j++) {
            datasets[i][j] = rand() % 100;
        }
    }

