    populate_array(array, N);

    pthread_t thread[THREADS];
    for(int i = 0; i < num_datasets; i++) {
        pthread_create(&thread[i], NULL, process_dataset, (void*)datasets[i]);
        pthread_join(thread[i], NULL);
