        if (!pduArray) return NULL; // Handle memory allocation failure

        NFAPI_CRC_INDICATION_PDU_T* pdu = &pduArray[i];
        pdu->RX_UE_INFORMATION_TAG = (uint8_t)i;
        pdu->RNTI = rand() % 65535; // Validate RNTI within valid range
        if (pdu->RNTI > 65534) {
            printf("Error: RNTI out of range!\n");
            return NULL;
        }

        time_t timestamp = time(NULL);
        if (timestamp > (time_t)-1) { // Check for potential integer overflow
            printf("Error: Timestamp exceeds maximum representable value!\n");
            return NULL;
        }
        pdu->CRC_INDICATION_REL8_TAG.timestamp = timestamp;

        srand(time(NULL)); // Randomize CRCFLAG and UID
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        pdu->CRC_INDICATION_REL8_TAG.sequenceNumber = (uint16_t)i;
        pdu->CRC_INDICATION_REL8_TAG.UID = rand() % ((1 << 31) - 1); // Handle edge case for extremely large N
    }

