#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int* elements;
    size_t size;
} DynamicList;

DynamicList* process_input(size_t max_size) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    list->size = 0;
    list->elements = NULL;

    size_t total_size = 0;
    while (total_size < max_size && scanf("%d", &list->elements[total_size]) == 1) {
        if (list->size >= total_size) {
            list->elements = realloc(list->elements, sizeof(int) * (total_size + 10));
            if (!list->elements) {
                printf("Memory reallocation failed.\n");
                free(list);
                return NULL;
            }
        }
        total_size++;
    }

    if (scanf("%*c") != EOF) {
        printf("Invalid input format. Expecting integers only.\n");
        free(list);
        return NULL;
    }

    list->size = total_size;

    if (!list->elements) {
        free(list);
        return NULL;
    }

    int max_positive = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i] > 0 && list->elements[i] > max_positive) {
            max_positive = list->elements[i];
        }
    }

    int* sorted_elements = NULL;
    size_t sorted_size = 0;
    int stable_sort = 1; // default to stable sort
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i] >= 0) {
            sorted_elements = realloc(sorted_elements, sizeof(int) * (sorted_size + 10));
            if (!sorted_elements) {
                printf("Memory reallocation failed.\n");
                free(list);
                free(sorted_elements);
                return NULL;
            }
            sorted_elements[sorted_size++] = list->elements[i];
        }
    }

    qsort(sorted_elements, sorted_size, sizeof(int), (int(*)(const void*, const void*))stable_sort ? qsort_stable : qsort_non_stable);

    int distinct_count = 0;
    for (size_t i = 0; i < sorted_size; ++i) {
        if (!binary_search(sorted_elements, sorted_size, sorted_elements[i])) {
            distinct_count++;
        }
    }

    printf("Largest positive integer: %d\n", max_positive);
    printf("Sorted elements: ");
    for (size_t i = 0; i < sorted_size; ++i) {
        printf("%d ", sorted_elements[i]);
    }
    puts("");
    printf("Distinct count: %zu\n", distinct_count);

    if (sorted_size > 1 && !stable_sort) {
        qsort(sorted_elements, sorted_size - 1, sizeof(int), qsort_non_stable);
        for (size_t i = 0; i < sorted_size; ++i) {
            printf("%d ", sorted_elements[i]);
        }
    } else if (sorted_size > 1 && stable_sort) {
        qsort(sorted_elements, sorted_size - 1, sizeof(int), qsort_stable);
        for (size_t i = 0; i < sorted_size; ++i) {
            printf("%d ", sorted_elements[i]);
        }
    } else if (sorted_size > 0 && stable_sort) {
        qsort(sorted_elements, sorted_size - 1, sizeof(int), qsort_stable);
        for (size_t i = 0; i < sorted_size; ++i) {
            printf("%d ", sorted_elements[i]);
        }
    } else if (sorted_size > 0 && !stable_sort) {
        qsort(sorted_elements, sorted_size - 1, sizeof(int), qsort_non_stable);
        for (size_t i = 0; i < sorted_size; ++i) {
            printf("%d ", sorted_elements[i]);
        }
    } else {
        printf("No elements to sort.\n");
    }

    free(sorted_elements);
    free(list->elements);
    free(list);

    return NULL;
}

int binary_search(int* array, size_t size, int target) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == target) {
            return 1;
        }
    }
    return 0;
}

int qsort_stable(int const *v1, int const *v2) {
    int a = *(int*)v1 - *(int*)v2;
    return a < 0 ? -1 : (a > 0) ? 1 : 0;
}

int qsort_non_stable(int const *v1, int const *v2) {
    return *(int*)v1 - *(int*)v2;
}
