typedef struct {
    // ... (NFAPI_CRC_INDICATION_PDU_T structure definition)
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to hold memory statistics
typedef struct {
    uint64_t peak_memory_usage;
    uint64_t total_allocations;
    int least_recently_used_index;
} MemoryStats;

MemoryStats memory_stats = {0};

NFAPI_CRC_INDICATION_PDU_T* allocate_array(int N) {
    if (N <= 0) return NULL; // edge case: N should be positive

    // Calculate peak memory usage
    uint64_t peak_memory_usage = 0;
    for (int i = 0; i < N; i++) {
        size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        void* ptr = malloc(struct_size);
        if (!ptr) return NULL;

        // Initialize CRCFLAG and timestamp
        ((NFAPI_CRC_INDICATION_PDU_T*)ptr)->CRCFLAG = rand() % 2;
        ((NFAPI_CRC_INDICATION_PDU_T*)ptr)->timestamp = time(NULL);

        // Set RNTI within valid range
        int rnti = (rand() % 1000) + 1; // adjust the range as needed

        if (rnti < 0 || rnti > 65535) {
            free(ptr);
            return NULL;
        }

        ((NFAPI_CRC_INDICATION_PDU_T*)ptr)->RNTI = rnti;

        // Update peak memory usage
        peak_memory_usage = MAX(peak_memory_usage, (uint64_t)i * struct_size);

        if (i > 0) {
            // Reuse older structures for LRU-based reclamation
            int lru_index = i % N;
            free(((NFAPI_CRC_INDICATION_PDU_T*)mallocs[lru_index])->ptr);
            mallocs[lru_index]->ptr = ptr;
            memory_stats.least_recently_used_index = lru_index;
        } else {
            // Initialize LRU strategy
            memory_stats.least_recently_used_index = i;
        }

        // Update total allocations and peak memory usage statistics
        memory_stats.total_allocations++;
        if (peak_memory_usage > memory_stats.peak_memory_usage)
            memory_stats.peak_memory_usage = peak_memory_usage;

        mallocs[i].ptr = ptr;
    }

    return mallocs;
}
