#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    int* data;
    size_t size;
} Dataset;

Dataset read_dataset() {
    Dataset dataset = {NULL, 0};

    double num;
    while (scanf("%lf", &num) == 1 && dataset.size < 50000) {
        if (num >= -1) {
            dataset.data = realloc(dataset.data, (dataset.size + 1) * sizeof(int));
            dataset.data[dataset.size++] = (int) round(num);
        } else {
            printf("Error: Invalid input. Maximum size exceeded.\n");
            exit(EXIT_FAILURE);
        }
    }

    return dataset;
}

void print_largest_int(Dataset dataset) {
    if (dataset.size > 0) {
        int largest = dataset.data[0];

        for (size_t i = 1; i < dataset.size; i++) {
            if (dataset.data[i] > largest) {
                largest = dataset.data[i];
            }
        }

        printf("Largest integer: %d\n", largest);

        int sorted = 1;
        for (size_t i = 1; i < dataset.size; i++) {
            if (dataset.data[i - 1] > dataset.data[i]) {
                sorted = 0;
                break;
            }
        }

        printf("Sorting status: %s\n", sorted ? "Ascending" : "Descending");
    } else {
        printf("Error: No data in the dataset.\n");
    }
}

void process_datasets() {
    Dataset datasets[100]; // assume maximum number of datasets
    size_t num_datasets = 0;

    while (scanf("%lf", &num) == 1) {
        if (num >= -1) {
            Dataset dataset = read_dataset();

            if (dataset.size > 0) {
                print_largest_int(dataset);
                free(dataset.data);
                num_datasets++;
            }
        } else {
            printf("Error: Invalid input. Maximum size exceeded.\n");
            exit(EXIT_FAILURE);
        }
    }

    printf("Summary:\n");
    printf("Number of datasets processed: %zu\n", num_datasets);

    int total = 0;
    for (size_t i = 0; i < num_datasets; i++) {
        for (size_t j = 0; j < datasets[i].size; j++) {
            total++;
        }
    }

    printf("Total count of integers processed: %d\n", total);

    int* counts[100]; // assume maximum number of unique integer values
    size_t num_counts = 0;
    for (size_t i = 0; i < num_datasets; i++) {
        for (size_t j = 0; j < datasets[i].size; j++) {
            int val = datasets[i].data[j];

            if (val >= -1) {
                size_t idx = val % 100;

                if (counts[idx] == NULL) {
                    counts[idx] = malloc(sizeof(int));
                    *counts[idx] = 1;
                    num_counts++;
                } else {
                    (*counts[idx])++;
                }
            }
        }
    }

    double avg, med;
    size_t std_dev = 0;

    for (size_t i = 0; i < num_counts; i++) {
        size_t val = *counts[i];

        total += val;

        if (i == 0) {
            avg = (double) total / (num_datasets + 1);
            med = val;
        } else {
            avg = (avg * num_counts + (double) total / (num_datasets + i + 1)) / (num_counts + 1);
            med = ((double) (med * (i - 1) + val) / (i + 1));
        }

        if (i > 0) {
            for (size_t j = i; j >= 1; j--) {
                std_dev += abs(val - *counts[j - 1]);
            }
        }
    }

    printf("Average: %.2f\n", avg);
    printf("Median: %d\n", med);
    printf("Standard deviation: %zu\n", std_dev);
}

int main() {
    process_datasets();
    return 0;
}
