#include <fcntl.h>
#include <sys/mman.h>
#include <openssl/md5.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications_and_process_file(int N, char* file_path) {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *indication_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        indication_array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        indication_array[i].RNTI = rand() % 200;
        indication_array[i].CRCFLAG = rand() % 2;
    }

    int file_descriptor = open(file_path, O_RDONLY);
    if (file_descriptor == -1) {
        printf("Error opening file: %s\n", file_path);
        return NULL;
    }

    struct stat sb;
    fstat(file_descriptor, &sb);

    char* buffer = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, file_descriptor, 0);

    if (buffer == MAP_FAILED) {
        printf("Error mapping file: %s\n", file_path);
        close(file_descriptor);
        return NULL;
    }

    close(file_descriptor);

    unsigned char* md5_buffer = malloc(16);
    MD5_CTX ctx;
    MD5_Init(&ctx);

    int chunk_size = 1024;
    for (int i = 0; i < sb.st_size; i += chunk_size) {
        int read_size = min(chunk_size, sb.st_size - i);

        if (read(read_buffer, buffer + i, read_size) != read_size) {
            printf("Error reading file: %s\n", file_path);
            free(md5_buffer);
            munmap(buffer, sb.st_size);
            return NULL;
        }

        MD5_Update(&ctx, read_buffer, read_size);
    }

    MD5_Final(md5_buffer, &ctx);

    char hash[33];
    for (int i = 0; i < 16; i++) {
        sprintf(&hash[i * 2], "%02x", md5_buffer[i]);
    }

    free(read_buffer);
    munmap(buffer, sb.st_size);

    // External API call
    char* metadata = get_metadata(file_path);

    if (metadata == NULL) {
        printf("Error getting file metadata: %s\n", file_path);
        return NULL;
    }

    int sequence_number = extract_sequence_number(metadata);

    free(metadata);

    free(indication_array);
    free(md5_buffer);

    return malloc(sizeof(struct {
        char* hash;
        int sequence_number;
    }));
}

int min(int a, int b) {
    return (a < b) ? a : b;
}
