int* readArray(int maxsize) {
    int i = 0;
    int* arr = (int*)malloc(maxsize * sizeof(int));

    if (!arr) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    while (i < maxsize && scanf("%d", &arr[i]) == 1);

    if (i >= maxsize) {
        printf("Input exceeded maximum size of %d elements.\n", maxsize);
        free(arr);
        return NULL;
    }

    for (int j = i - 1; j >= 0; j--) {
        if (arr[j] < arr[j + 1]) {
            printf("Invalid input format. Please enter integers only.\n");
            free(arr);
            return NULL;
        }
    }

    int* temp = (int*)malloc((i + 1) * sizeof(int));

    for (int j = 0; j < i; j++) {
        if (arr[j] == arr[j + 1]) {
            temp[j] = arr[j];
            i--;
            j--;
        } else {
            temp[j] = arr[j];
        }
    }

    for (int j = i; j >= 0; j--) {
        temp[j] = arr[j];
    }

    free(arr);
    return temp;
}

void findLargest(int* arr, int size) {
    if (size == 1 || arr[0] > 0) {
        printf("The largest integer is %d.\n", arr[0]);
    } else {
        for (int i = 0; i < size; i++) {
            if (arr[i] > 0) {
                printf("The largest integer is %d.\n", arr[i]);
                return;
            }
        }

        printf("All integers are negative. The largest integer is %d.\n", arr[0]);
    }
}

int main() {
    int maxsize = 10000;

    while (1) {
        int* array = readArray(maxsize);

        if (!array) {
            return 0;
        }

        int size = sizeof(array) / sizeof(array[0]);

        printf("Do you want to find the largest integer in the sorted or unsorted array? Type 's' for sorted or 'u' for unsorted: ");
        char choice;
        scanf(" %c", &choice);

        if (choice == 's') {
            findLargest(array, size);
        } else if (choice == 'u') {
            int* arr = (int*)malloc(size * sizeof(int));

            for (int i = 0; i < size; i++) {
                arr[i] = array[size - i - 1];
            }

            findLargest(arr, size);

            free(arr);
        } else {
            printf("Invalid choice. Please choose 's' or 'u'.\n");
        }

        free(array);
    }

    return 0;
}

