#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[32];
    char CRC_INDICATION_REL8_TAG[32];
    int sequence_number;
    time_t timestamp;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct lru_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct lru_node* prev;
    struct lru_node* next;
};

typedef struct {
    struct lru_node* head;
    struct lru_node* tail;
    int size;
} LRU_LIST;

void init_lru_list(LRU_LIST* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

int is_full(LRU_LIST* list, int N) {
    return (list->size >= N);
}

NFAPI_CRC_INDICATION_PDU_T* lru_alloc(LRU_LIST* list, int N) {
    if (is_full(list, N)) {
        // Reclaim memory using LRU strategy
        struct lru_node* node = list->head;
        list->head = node->next;
        if (list->head != NULL)
            list->head->prev = NULL;
        else
            list->tail = NULL;
        free(node);
        N--;
    }
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int main() {
    // Initialize memory pool
    LRU_LIST lru_list;
    init_lru_list(&lru_list);

    for (int i = 0; i < 100; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = lru_alloc(&lru_list, 10);
        if (!pdu) {
            printf("Memory allocation failed\n");
            return -1;
        }
        // Initialize structure fields
        pdu->RNTI = (rand() % 1000) + 1;
        strcpy(pdu->RX_UE_INFORMATION_TAG, "TAG");
        srand(time(NULL));
        pdu->sequence_number = rand();
        pdu->timestamp = time(NULL);
        if (pdu->CRCFLAG == 0)
            printf("PDU allocated\n");
    }

    return 0;
}
