void* process_dataset(void* arg) {
    struct dataset* ds = (struct dataset*)arg;
    int largest_int = INT_MIN;
    int is_sorted = 1;

    for (int i = 0; i < ds->size - 1; i++) {
        if (ds->numbers[i] >= ds->numbers[i + 1]) {
            is_sorted = 1;
        } else {
            is_sorted = 0;
            break;
        }
    }

    largest_int = INT_MIN;

    for (int i = 0; i < ds->size; i++) {
        if ((long)ds->numbers[i] >= 0 && ds->numbers[i] > largest_int) {
            largest_int = ds->numbers[i];
        }
    }

    printf("Largest integer: %d, Sorted: %s\n", largest_int, is_sorted ? "Yes" : "No");

    free(ds->numbers);
    free(ds);

    return NULL;
}

void print_summary(int num_datasets, int total_integers) {
    pthread_mutex_lock(&mutex);
    printf("Number of datasets: %d, Total integers: %d\n", num_datasets, total_integers);

    int frequency[1000000] = {0};
    for (int i = 0; i < total_integers; i++) {
        if ((long)numbers[i] >= 0 && (long)numbers[i] < 1000000) {
            frequency[(int)(numbers[i])]++;
        }
    }

    int max_frequency = 0;
    int mode = INT_MIN;

    for (int i = 0; i < 1000000; i++) {
        if (frequency[i] > max_frequency) {
            max_frequency = frequency[i];
            mode = i;
        }
    }

    double average, median;
    pthread_mutex_unlock(&mutex);

    // Calculate summary statistics
    average = (double)total_integers / num_datasets;
    median = average;

    printf("Average: %.2f, Median: %.2f\n", average, median);
}

int main() {
    int total_elements = 0;
    struct dataset* datasets[TOTAL_ELEMENTS];
    pthread_t threads[TOTAL_ELEMENTS];

    int current_dataset_size = 0;
    int current_dataset_numbers[MAX_SIZE];

    for (int i = 0; i < TOTAL_ELEMENTS; i++) {
        int num_read;
        scanf("%d", &num_read);

        if (num_read > MAX_SIZE) {
            printf("Error: Dataset size exceeds maximum limit.\n");
            return 1;
        }

        for (int j = 0; j < num_read; j++) {
            double num;
            scanf("%lf", &num);
            current_dataset_numbers[current_dataset_size++] = (int)(round(num) >= -1 ? round(num) : INT_MIN);
        }

        datasets[i] = malloc(sizeof(struct dataset));
        datasets[i]->numbers = current_dataset_numbers;
        datasets[i]->size = current_dataset_size;

        pthread_create(&threads[i], NULL, process_dataset, datasets[i]);

        total_elements += num_read;

        current_dataset_size = 0;
    }

    for (int i = 0; i < TOTAL_ELEMENTS; i++) {
        pthread_join(threads[i], NULL);
    }

    int max_dataset_size = INT_MIN;

    for (int i = 0; i < TOTAL_ELEMENTS; i++) {
        if (datasets[i]->size > max_dataset_size) {
            max_dataset_size = datasets[i]->size;
        }
    }

    // Prioritize datasets based on size
    pthread_mutex_lock(&mutex);
    int highest_priority = 0;
    for (int i = 0; i < TOTAL_ELEMENTS; i++) {
        if (datasets[i]->size > highest_priority) {
            highest_priority = datasets[i]->size;
        }
    }

    // Start processing datasets based on priority
    pthread_mutex_unlock(&mutex);

    return 0;
}
