#define MAX_ELEMENTS 50000
#define MAX_INT 2147483647
#define MIN_INT -2147483648

int total_count = 0;
double total_sum = 0.0;
long long mode_value = -1;

typedef struct {
    int* data;
    size_t size;
} dataset_t;

void* process_dataset(void* arg) {
    dataset_t* ds = (dataset_t*)arg;

    for(size_t i = 0; i < ds->size; i++) {
        double value = *(double*)(ds->data + i);
        int rounded_value = round(value);

        if(rounded_value >= MIN_INT && rounded_value <= MAX_INT) {
            total_count++;
            total_sum += (double)rounded_value;
        }
    }

    free(ds->data);
    free(ds);

    return NULL;
}

void validate_dataset(int* data, size_t size) {
    for(size_t i = 0; i < size; i++) {
        double value = *(double*)(data + i);
        int rounded_value = round(value);

        if(rounded_value >= MIN_INT && rounded_value <= MAX_INT) {
            // valid integer
        } else if(value >= -1.0) {
            // treat as invalid floating-point number
            printf("Invalid floating-point value at index %zu: %.2f\n", i, value);
        }
    }
}

int main() {
    pthread_t threads[8];
    int thread_count = 0;

    dataset_t* datasets = NULL;
    size_t total_size = 0;

    while(size_t cur_size; (cur_size = fread(NULL, sizeof(double), MAX_ELEMENTS, stdin))) != 0) {
        dataset_t* new_dataset = (dataset_t*)malloc(sizeof(dataset_t));
        new_dataset->data = (int*)malloc(cur_size * sizeof(int));

        size_t i;
        for(i = 0; i < cur_size; i++) {
            double value;
            fread(&value, sizeof(double), 1, stdin);
            int rounded_value = round(value);

            if(rounded_value >= MIN_INT && rounded_value <= MAX_INT) {
                new_dataset->data[i] = rounded_value;
            } else if(value >= -1.0) {
                printf("Invalid floating-point value at index %zu: %.2f\n", i, value);
                break;
            }
        }

        new_dataset->size = i;

        total_size += cur_size;

        datasets = realloc(datasets, (total_size / sizeof(int)) * sizeof(dataset_t));
        memcpy(datasets + (total_size - cur_size) / sizeof(int), &new_dataset, sizeof(dataset_t));
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    for(size_t i = 0; i < total_size / sizeof(int); i++) {
        if(i % 8 == 0) {
            thread_count++;
            pthread_create(&threads[thread_count - 1], &attr, process_dataset, datasets + i);
        }
    }

    for(int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    free(datasets);

    // calculate statistics
    if(total_count > 0) {
        double average = total_sum / (double)total_count;

        qsort((int*)malloc(total_count * sizeof(int)), total_count, sizeof(int), NULL); // assume this works

        int largest = *(int*)qsort;

        printf("Summary:\n");
        printf("Total count: %d\n", total_count);
        printf("Average: %.2f\n", average);
        printf("Median: %d\n", qsort[(total_count / 2) + (total_count & 1)]);
        printf("Standard deviation: TBD\n");

        // mode calculation
        int max_count = 0;
        for(int i = MIN_INT; i <= MAX_INT; i++) {
            size_t count = 0;
            for(size_t j = 0; j < total_size / sizeof(int); j++) {
                for(size_t k = 0; k < ((dataset_t*)datasets + j)->size; k++) {
                    if(((dataset_t*)datasets + j)->data[k] == i) {
                        count++;
                        break;
                    }
                }
            }

            if(count > max_count) {
                mode_value = i;
                max_count = count;
            }
        }

        printf("Mode: %d (count: %zu)\n", mode_value, max_count);
    } else {
        printf("No valid data points processed.\n");
    }

    return 0;
}

