class TCP_CONNECTION {
public:
    std::string source_ip;
    std::string destination_ip;
    int port;
    int bytes_transferred;

    // Constructor
    TCP_CONNECTION(const std::string& src, const std::string& dst, int prt, int byts)
        : source_ip(src), destination_ip(dst), port(prt), bytes_transferred(byts) {}
};

class CONNECTION_MANAGER {
public:
    // Initialize the connection manager with an initial capacity
    CONNECTION_MANAGER(size_t N = 10) 
        : connections_(new TCP_CONNECTION*[N]), capacity_(N), size_(0) {}

    // Destructor: Release memory and destroy any dynamically allocated objects.
    ~CONNECTION_MANAGER() { clear(); }

    // Add a new connection to the list (single-connection mode)
    void add_connection(TCP_CONNECTION* conn);

    // Batch-processing mode: Add multiple connections at once
    void add_connections(const std::vector<TCP_CONNECTION*>& batch);

    // Filter and retrieve connections based on IP addresses or port ranges
    std::vector<TCP_CONNECTION*> filter_connections(
        const std::string& ip_filter, int port_range_start, int port_range_end);

    // Merge/consolidate connections across batches (batch-processing mode)
    void merge_connections(const std::vector<TCP_CONNECTION*>& batch);

private:
    TCP_CONNECTION** connections_;
    size_t capacity_;
    size_t size_;

    // Helper function to dynamically resize the connection list
    void resize(size_t new_capacity) {
        capacity_ = new_capacity;
        connections_ = new TCP_CONNECTION*[capacity_];
    }

    // Clear memory and destroy any dynamically allocated objects.
    void clear() {
        for (size_t i = 0; i < size_; ++i)
            delete connections_[i];
        delete[] connections_;
    }
};

void CONNECTION_MANAGER::add_connection(TCP_CONNECTION* conn) {
    if (size_ >= capacity_) {
        resize(capacity_ * 2);
    }
    connections_[size_++] = conn;
}

void CONNECTION_MANAGER::add_connections(const std::vector<TCP_CONNECTION*>& batch) {
    for (const auto& conn : batch) {
        add_connection(conn);
    }
}

