int num_nas_messages = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void nas_message_manager(int user_identity, const char* session_context, const char* authentication_params) {
    pthread_mutex_lock(&lock);

    // Add a new NAS message
    if (num_nas_messages >= 10000) {
        printf("Error: Maximum number of NAS messages exceeded.\n");
        return;
    }

    NAS_MESSAGE_T* new_message = (NAS_MESSAGE_T*)malloc(sizeof(NAS_MESSAGE_T));
    strcpy(new_message->session_context, session_context);
    strcpy(new_message->authentication_params, authentication_params);
    new_message->user_identity = user_identity;

    // Update an existing NAS message
    for (int i = 0; i < num_nas_messages; i++) {
        if (nas_messages[i].user_identity == user_identity) {
            free(nas_messages[i]);
            nas_messages[i] = new_message;
            return;
        }
    }

    // Add the new message to the array
    nas_messages = (NAS_MESSAGE_T*)realloc(nas_messages, (num_nas_messages + 1) * sizeof(NAS_MESSAGE_T));
    nas_messages[num_nas_messages++] = new_message;

    pthread_mutex_unlock(&lock);
}

