#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/socket.h>
#include <errno.h>
#include <pthread.h>

#define MAX_SIZE (1024 * 1024) // 1 MB

int process_integers(int sock, pthread_mutex_t* mutex) {
    int integers[MAX_SIZE];
    size_t count = 0;
    ssize_t bytes_read;

    while ((bytes_read = read(sock, &integers[count], sizeof(int))) > 0) {
        if (count >= MAX_SIZE) {
            fprintf(stderr, "Error: Input exceeds maximum size of %d MB\n", MAX_SIZE / (1024 * 1024));
            exit(1);
        }
        count += bytes_read / sizeof(int);
    }

    if (bytes_read < 0 && errno == EINTR) {
        // Network read interrupted; attempt to reconnect
        return -EINTR;
    } else if (bytes_read < 0) {
        // Network read failure; log error and exit
        perror("read");
        exit(1);
    }

    pthread_mutex_lock(mutex);
    int* temp = (int*) realloc(NULL, sizeof(int) * count + 1); // add one for null terminator
    memcpy(temp, integers, sizeof(int) * count);
    temp[count] = '\0'; // set last element to null terminator

    // Validate input array is sorted in ascending order
    for (size_t i = 0; i < count - 1; ++i) {
        if (temp[i] >= temp[i + 1]) {
            fprintf(stderr, "Error: Input array not sorted\n");
            exit(1);
        }
    }

    // Process the input array here
    for (size_t i = 0; i < count; ++i) {
        printf("%d ", temp[i]);
    }
    printf("\n");

    pthread_mutex_unlock(mutex);

    free(temp); // deallocate dynamically allocated memory

    return 0;
}

int main(int argc, char* argv[]) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    process_integers(sock, &mutex);

    close(sock); // close the socket
    return 0;
}

