#include <pthread.h>

// Define structure for LTE EUTRA SIB10 message
typedef struct {
    int cellID;
    int tddUL_DLConfigIndex;
    int subframeOffsets[8];
} LTE_EUTRA_SIB10_T;

// Define a dynamic array of LTE EUTRA SIB10 messages
typedef struct {
    LTE_EUTRA_SIB10_T* messages;
    size_t capacity;
    pthread_mutex_t lock;
} SIB10_Array_T;

// Initialize the SIB10 array with an initial capacity and lock for concurrent access
SIB10_Array_T sib10Array = {{NULL, 0}, {pthread_mutex_init(NULL, NULL)}};

// Function to add a new SIB10 message to the dynamic array
void addSIB10Message(int cellID, int tddUL_DLConfigIndex, int subframeOffsets[8]) {
    pthread_mutex_lock(&sib10Array.lock);

    // Check if the array needs to be resized
    if (sib10Array.capacity <= sib10Array.messages) {
        size_t newCapacity = sib10Array.capacity * 2;
        LTE_EUTRA_SIB10_T* newMessages = realloc(sib10Array.messages, sizeof(LTE_EUTRA_SIB10_T) * newCapacity);

        if (!newMessages) {
            // Handle memory allocation error
            perror("Memory allocation failed");
            pthread_mutex_unlock(&sib10Array.lock);
            return;
        }

        sib10Array.capacity = newCapacity;
        sib10Array.messages = newMessages;
    }

    // Add the new message to the array
    LTE_EUTRA_SIB10_T* newNode = malloc(sizeof(LTE_EUTRA_SIB10_T));
    if (!newNode) {
        // Handle memory allocation error
        perror("Memory allocation failed");
        pthread_mutex_unlock(&sib10Array.lock);
        return;
    }

    newNode->cellID = cellID;
    newNode->tddUL_DLConfigIndex = tddUL_DLConfigIndex;
    for (int i = 0; i < 8; i++) {
        newNode->subframeOffsets[i] = subframeOffsets[i];
    }

    sib10Array.messages[sib10Array.capacity - 1] = *newNode;
    free(newNode);

    pthread_mutex_unlock(&sib10Array.lock);
}

// Function to update an existing SIB10 message in the dynamic array
void updateSIB10Message(int cellID, int tddUL_DLConfigIndex, int subframeOffsets[8]) {
    pthread_mutex_lock(&sib10Array.lock);

    // Find the index of the message with the matching cell ID
    for (int i = 0; i < sib10Array.capacity; i++) {
        if (sib10Array.messages[i].cellID == cellID) {
            // Update the message fields
            sib10Array.messages[i].tddUL_DLConfigIndex = tddUL_DLConfigIndex;
            for (int j = 0; j < 8; j++) {
                sib10Array.messages[i].subframeOffsets[j] = subframeOffsets[j];
            }
            break;
        }
    }

    pthread_mutex_unlock(&sib10Array.lock);
}

// Function to retrieve a SIB10 message from the dynamic array based on its cell ID
LTE_EUTRA_SIB10_T* getSIB10Message(int cellID) {
    pthread_mutex_lock(&sib10Array.lock);

    // Find the index of the message with the matching cell ID
    for (int i = 0; i < sib10Array.capacity; i++) {
        if (sib10Array.messages[i].cellID == cellID) {
            LTE_EUTRA_SIB10_T* message = malloc(sizeof(LTE_EUTRA_SIB10_T));
            *message = sib10Array.messages[i];
            return message;
        }
    }

    // Return NULL if the message is not found
    pthread_mutex_unlock(&sib10Array.lock);
    return NULL;
}

// Function to periodically clean up inactive messages and free up resources
void cleanupSIB10Messages() {
    pthread_mutex_lock(&sib10Array.lock);

    // Iterate over the array and remove inactive messages
    for (int i = 0; i < sib10Array.capacity; i++) {
        if (/* check message activity */) {
            free(sib10Array.messages[i]);
            memmove(&sib10Array.messages[i], &sib10Array.messages[i + 1], sizeof(LTE_EUTRA_SIB10_T) * (sib10Array.capacity - i - 1));
            sib10Array.capacity--;
        }
    }

    pthread_mutex_unlock(&sib10Array.lock);
}

// Example usage
int main() {
    addSIB10Message(123, 5, {0, 1, 2, 3, 4, 5, 6, 7});
    updateSIB10Message(123, 6, {8, 9, 10, 11, 12, 13, 14, 15});

    LTE_EUTRA_SIB10_T* message = getSIB10Message(123);
    if (message) {
        printf("Retrieved SIB10 message: cellID=%d, tddUL_DLConfigIndex=%d, subframeOffsets=[%d, %d, %d, ...]\n", 
               message->cellID, message->tddUL_DLConfigIndex, message->subframeOffsets[0], message->subframeOffsets[1]);
        free(message);
    }

    cleanupSIB10Messages();

    return 0;
}
