    void receiveProfiles(std::vector<std::shared_ptr<UserProfile>> profiles) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (calculateTotalMemoryUsage(profiles) > maxMemory_) {
            logError("Exceeded maximum memory footprint. Terminating.");
            return;
        }

        profiles_.insert(profiles_.end(), profiles.begin(), profiles.end());
    }

private:
    size_t calculateTotalMemoryUsage(const std::vector<std::shared_ptr<UserProfile>>& profiles) const {
        size_t totalSize = 0;
        for (const auto& profile : profiles) {
            totalSize += profile->size();
        }
        return totalSize;
    }

    void logError(const std::string& message) const {
        // Implement logging mechanism
        std::cerr << "Error: " << message << std::endl;
        exit(1);
