class UserProfileManager {
public:
    UserProfileManager(size_t dailyLimit) : dailyLimit_(dailyLimit), totalMemoryUsage_(0), cache_(new std::map<std::string, std::shared_ptr<UserProfile>>()) {}

    void updateProfiles(const std::vector<UserProfile>& newProfiles) {
        for (const auto& profile : newProfiles) {
            if (totalMemoryUsage_ + profile.getSize() > dailyLimit_) {
                logError("Total memory usage exceeded daily limit");
                return;
            }
            cache_->insert({profile.getId(), std::make_shared<UserProfile>(profile)});
            totalMemoryUsage_ += profile.getSize();
        }
    }

    UserProfile* getProfile(const std::string& id) const {
        auto it = cache_->find(id);
        if (it != cache_->end()) {
            return it->second.get();
        }
        return nullptr;
    }

private:
    size_t dailyLimit_;
    size_t totalMemoryUsage_;
