    while (allocation_attempts < max_attempts) {
        array = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array != NULL) {
            break;
        }
        allocation_attempts++;
        // Exponential backoff for consecutive failures
        int delay_in_ms = 1 << allocation_attempts;
        printf("Memory allocation failed. Retrying in %d ms...\n");
        sleep(delay_in_ms);
    }

    if (array == NULL) {
        printf("Memory allocation failed after %d attempts.\n", max_attempts);
        return -1; // Allocation failure
