#include <iostream>
#include <string>
#include <map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <curl/curl.h>

class UserProfileManager {
public:
    UserProfileManager(int dailyLimit) : dailyLimit_(dailyLimit), cacheSize_(0) {}

    void addProfile(std::shared_ptr<APIUserProfile> profile) {
        if (cacheSize_ + profile->getSize() > dailyLimit_) {
            logError("Memory limit exceeded");
            return;
        }
        // Add to cache and update size
        cache_.insert({profile.get(), std::move(profile)});
        cacheSize_ += profile->getSize();
    }

    void removeProfile(std::shared_ptr<APIUserProfile> profile) {
        if (cache_.erase(profile.get()) == 0) return;
        cacheSize_ -= profile->getSize();
    }

private:
    int dailyLimit_;
    size_t cacheSize_;

    std::map<std::shared_ptr<APIUserProfile>, std::shared_ptr<APIUserProfile>> cache_;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfo;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcIndication;
};

NFAPI_CRC_INDICATION_PDU_T* generateArray(int size) {
    NFAPI_CRC_INDICATION_PDU_T* array = new NFAPI_CRC_INDICATION_PDU_T[size];
    for (int i = 0; i < size; i++) {
        // Initialize structures
        array[i].ueInfo = {};
        array[i].RNTI = rand();
        array[i].crcIndication = {rand(), rand()};  // CRCFLAG

        // Compute MD5 hash of RNTI string
        std::string rntiStr = std::to_string(array[i].RNTI);
        unsigned char* md5Bytes = new unsigned char[16];
        try {
            uint8_t* md5Hash = reinterpret_cast<uint8_t*>(md5(rntiStr.c_str(), strlen(rntiStr.c_str()), md5Bytes));
            array[i].crcIndication.CRCFLAG = *(uint16_t*)md5Hash;
        } catch (const std::exception& e) {
            // Handle exception
        }
    }
    return array;
}

