void print_largest(int* arr, int n) {
    if (n == 0) {
        printf("No elements to process.\n");
        return;
    }

    int largest = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (arr[i] > largest)
            largest = arr[i];
    }
    printf("Largest integer: %d\n", largest);
}

void find_duplicates(int* arr, int n) {
    if (n == 0) {
        printf("No elements to process.\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if (arr[i] == arr[j]) {
                printf("First duplicate: %d at index %d\n", arr[i], i);
                return;
            }
        }
    }
    printf("No duplicates found.\n");
}

void process_input(int* arr, int n) {
    // Validate array
    for (int i = 0; i < n-1; i++) {
        if (arr[i] >= arr[i+1]) {
            printf("Array is not sorted in ascending order. Exiting...\n");
            exit(EXIT_FAILURE);
        }
    }

    print_largest(arr, n);

    int max_idx = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > arr[max_idx])
            max_idx = i;
    }

    if (n > 1) {
        find_duplicates(&arr[0], n);
    } else if (n == 1) {
        printf("No duplicates found.\n");
    }
}

int main() {
    int max_size = 10000, count = 0;
    int* arr = NULL;

    while (1) {
        char c;
        int num;

        // Read a number from the standard input
        scanf("%d", &num);

        if (feof(stdin)) {
            break;  // End of file reached, exit loop.
        }

        count++;

        if (count > max_size) {
            printf("Error: Input exceeded maximum size.\n");
            free(arr);  // Deallocate the memory
            return 1;
        }

        arr = realloc(arr, sizeof(int)*(count));
        arr[count-1] = num;  // Store the number in the array.
    }

    process_input(arr, count);

    free(arr);  // Deallocate the memory

    return 0;
}

