        indications[i].RX_UE_INFORMATION_TAG = i;
        indications[i].RNTI = rnti;
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        indications[i].CRCFLAG = rand() % 2;

        if (i % CRC_CHECK_INTERVAL == 0) {
            int checksum = custom_checksum(&indications[i]);
            if (checksum != 0) {
                indications[i].CRCFLAG = -1; // error condition
                printf("Error: Integrity check failed for structure %d\n", i);
            }
        }

        printf("Created indication %d with RNTI %d and CRCFLAG %d\n", i, rnti, indications[i].CRCFLAG);

