        strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S", localtime(&now));
        printf("Logged indication %d: RNTI=%d, CRCFLAG=%d at %s\n", i, rnti, indications[i].CRCFLAG, timestamp);
    }

    return indications;
}

int custom_checksum(NFAPI_CRC_INDICATION_PDU_T* p) {
    // implement your custom checksum algorithm here
