#include <string.h>
#include <time.h>

typedef struct {
    // Include necessary structure fields here...
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    enum { CRCFLAG_OFF = 0, CRCFLAG_ON } CRCFLAG;
    union {
        struct {
            time_t timestamp;
            uint16_t sequence_number;
        } CRC_INDICATION_REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(int N) {
    NFAPI_CRC_INDICATION_PDU_T* indications = NULL;
    int retry_count = 0;
    int max_retries = 5;
    int backoff_time = 1; // in seconds

    for (int i = 0; i < N; i++) {
        do {
            indications = realloc(indications, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!indications) {
                if (++retry_count > max_retries) {
                    printf("Memory allocation failed after %d retries. Terminating...\n", max_retries);
                    return NULL;
                }
                usleep(backoff_time * 1000); // exponential backoff
            }
        } while (!indications);

        indications[i].RX_UE_INFORMATION_TAG = i; // Initialize with a valid value...
        indications[i].RNTI = rand() % 1024; // Random RNTI within the valid range...
        if (rand() & 1) {
            indications[i].CRCFLAG = CRCFLAG_ON;
        } else {
            indications[i].CRCFLAG = CRCFLAG_OFF;
        }
        indications[i].CRC_INDICATION_REL8_TAG.timestamp = time(NULL);
        indications[i].CRC_INDICATION_REL8_TAG.sequence_number = i;

        // Validate RNTI and log unusual patterns...
        if (indications[i].RNTI < 0 || indications[i].RNTI > 1023) {
            printf("Unusual RNTI pattern detected: %d\n", indications[i].RNTI);
        }
    }

    return indications;
}
