#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int largest_integer(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void sort_array(int** arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if ((*arr)[j] > (*arr)[j + 1]) {
                int temp = (*arr)[j];
                (*arr)[j] = (*arr)[j + 1];
                (*arr)[j + 1] = temp;
            }
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);

    if (n <= 0) {
        printf("No integers provided\n");
        return 0;
    }

    int* arr = (int*)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1 || getchar() != ' ') {
            printf("Invalid input. Please provide integers separated by spaces.\n");
            free(arr);
            return 1;
        }
    }

    getchar(); // Consume the trailing newline

    sort_array(&arr, n);

    int max = largest_integer(arr, n);
    printf("Largest integer: %d\n", max);

    free(arr);

    return 0;
}
