void process_dir(const char* dir_path, int depth) {
    DIR* dp = opendir(dir_path);
    if (dp == NULL) {
        perror("opendir");
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dp)) != NULL) {
        const char* path = ent->d_name;

        // Ignore hidden files unless requested
        if (*path == '.') continue;

        // Recursively process directories
        if (S_ISDIR(ent->d_type)) {
            char buffer[MAX_PATH + 1];
            snprintf(buffer, sizeof(buffer), "%s/%s", dir_path, path);
            process_dir(buffer, depth + 1);
        } else {
            int i;
            for (i = 0; i < num_file_types; i++) {
                if (strcmp(file_types[i].extension, &path[strlen(path) - 3]) == 0) {
                    file_types[i].process_file(dir_path, fopen(buffer, "r"), NULL);
                    break;
                }
            }
        }
    }

    closedir(dp);
}

