    if (argc <= 2) {
        printf("Error: missing input directory(s)\n");
        return 1;
    }

    // Process directories
    for (int i = 2; i < argc; i++) {
        process_dir(argv[i], 0);
    }

    // Generate summary report (if requested)
    if (batch_mode) {
        FILE* f = fopen(output_dir, "w");
        if (f == NULL) {
            perror("fopen");
            return 1;
        }

