                    // Process files and count lines
                    file_types[j].process_file(dir_path, fopen(buffer, "r"), NULL);
                    int lines_per_file = 0;
                    FILE* f = fopen(buffer, "r");
                    if (f == NULL) {
                        perror("fopen");
                        return 1;
                    }

                    while (fscanf(f, "%*s\n") != EOF) {
                        lines_per_file++;
                    }
                    fclose(f);

                    total_lines_per_type += lines_per_file;

                    files_per_type++;
                }
            }

            total_files += files_per_type;
            total_lines += total_lines_per_type;

            fprintf(ftype_f, "Total Lines: %d\n", total_lines_per_type);
            fprintf(ftype_f, "Files: %d\n", files_per_type);

            fclose(ftype_f);
        }

        fprintf(f, "Total Files: %d\n", total_files);
        fprintf(f, "Total Lines: %d\n", total_lines);
        fclose(f);
    }

    return 0;
}
