#include <inttypes.h>

#define MAX_SIZE 10000

void readArray(int** array, size_t* size) {
    *size = 0;
    int num;
    while (scanf("%d", &num) == 1 && (*size) < MAX_SIZE) {
        (*array)[(*size)++] = num;
    }
    if (ferror(stdin)) {
        printf("Error reading input.\n");
        exit(1);
    }
}

int findLargest(int* array, size_t size) {
    int max = INT_MIN;
    for (size_t i = 0; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int isValidSorted(int* array, size_t size) {
    size_t swaps = 0;
    for (size_t i = 1; i < size; i++) {
        if (array[i-1] > array[i]) {
            printf("Array is not sorted.\n");
            return -1;
        }
    }
    return 0;
}

int findDuplicates(int* array, size_t size) {
    int count[10001] = {0};
    for (size_t i = 0; i < size; i++) {
        if (++count[array[i]] > 1) {
            printf("Duplicate value found: %d\n", array[i]);
        }
    }
}

int computeAverage(int* array, size_t size) {
    int sum = 0;
    for (size_t i = 0; i < size; i++) {
        sum += array[i];
    }
    return sum / ((size > 0)?size:1);
}

int main() {
    int* array = NULL;
    size_t size = 0;
    readArray(&array, &size);

    if (size == 0) {
        printf("No values found.\n");
        return 0;
    }

    int largest = findLargest(array, size);
    printf("Largest value: %d\n", largest);

    int average = computeAverage(array, size);
    printf("Average value: %d\n", average);

    if (isValidSorted(array, size) == -1) {
        return 1;
    }

    findDuplicates(array, size);

    free(array);
    return 0;
}
