void* alloc_stream_buffer(size_t size) {
    return malloc(size);
}

int validate_video_stream_buffer(VIDEO_STREAM_BUFFER_T* buffer) {
    if (!buffer->stream_id || !buffer->frame_rate || !buffer->bitrate || !buffer->video_format[0] || !buffer->buffer_size || !buffer->buffer) {
        return -1;
    }
    return 0;
}

int validate_audio_stream_metadata(AUDIO_STREAM_METADATA_T* metadata) {
    if (!metadata->audio_track_id || !metadata->sample_rate || !metadata->channel_count || !metadata->bit_depth || !metadata->event_count) {
        return -1;
    }
    for (int i = 0; i < metadata->event_count; i++) {
        if (!metadata->audio_events[i]) {
            return -1;
        }
    }
    return 0;
}

void print_stream_info(VIDEO_STREAM_BUFFER_T* buffer, AUDIO_STREAM_METADATA_T* metadata) {
    printf("Video Stream Buffer: stream_id=%d, frame_rate=%.2f, bitrate=%d, video_format='%s', buffer_size=%zu\n", buffer->stream_id, buffer->frame_rate, buffer->bitrate, buffer->video_format, buffer->buffer_size);
    printf("Audio Stream Metadata: audio_track_id=%d, sample_rate=%d, channel_count=%d, bit_depth=%d, event_count=%d\n", metadata->audio_track_id, metadata->sample_rate, metadata->channel_count, metadata->bit_depth, metadata->event_count);
}

void free_stream_buffer(VIDEO_STREAM_BUFFER_T* buffer) {
    free(buffer->buffer);
    free(buffer);
}

void free_audio_stream_metadata(AUDIO_STREAM_METADATA_T* metadata) {
    for (int i = 0; i < metadata->event_count; i++) {
        free(metadata->audio_events[i]);
    }
    free(metadata->audio_events);
    free(metadata);
}
