// Function to dynamically manage a list of NAS messages
void* nas_message_manager(void* arg) {
    // Initialize the lock for thread-safe operations
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the message list and count
    NAS_MESSAGE_T *messages = NULL;
    int message_count = 0;

    // Function to add a new message
    void add_message(int user_id, char *session_context, int auth_params[10]) {
        pthread_mutex_lock(&lock);

        // Allocate memory for the new message
        NAS_MESSAGE_T *new_message = (NAS_MESSAGE_T*)malloc(sizeof(NAS_MESSAGE_T));
        if (!new_message) {
            printf("Error allocating memory for new message.\n");
            return;
        }

        // Initialize the new message
        new_message->user_id = user_id;
        new_message->session_context = session_context;
        memcpy(new_message->auth_params, auth_params, sizeof(int) * 10);

        // Add the new message to the list
        messages = realloc(messages, (message_count + 1) * sizeof(NAS_MESSAGE_T));
        if (!messages) {
            printf("Error allocating memory for message list.\n");
            free(new_message);
            return;
        }
        messages[message_count++] = *new_message;

        pthread_mutex_unlock(&lock);
    }

    // Function to update an existing message
    void update_message(int user_id, int new_auth_params[10]) {
        pthread_mutex_lock(&lock);

        for (int i = 0; i < message_count; i++) {
            if (messages[i].user_id == user_id) {
                memcpy(messages[i].auth_params, new_auth_params, sizeof(int) * 10);
                break;
            }
        }

        pthread_mutex_unlock(&lock);
    }

    // Function to retrieve a message by user ID
    NAS_MESSAGE_T* get_message(int user_id) {
        pthread_mutex_lock(&lock);

        for (int i = 0; i < message_count; i++) {
            if (messages[i].user_id == user_id) {
                NAS_MESSAGE_T *message = (NAS_MESSAGE_T*)malloc(sizeof(NAS_MESSAGE_T));
                memcpy(message, &messages[i], sizeof(NAS_MESSAGE_T));
                return message;
            }
        }

        pthread_mutex_unlock(&lock);
        return NULL;
    }

