    // Traverse the directory recursively...
    for (const auto& entry : recursive_directory_entries(dir_path)) {
        if (entry.is_file()) {
            // Process each metrics file...
            if (entry.path().ends_with(".metrics")) {
                (*metric_files).push_back(entry.path());
            }
