#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define BUFFER_SIZE 10000
#define RATE_LIMIT (1024 * 1024) // 1 MB per second

void process_integers(int* buffer, int* rate_timer);
int find_largest_integer(int* buffer);

int main() {
    int* buffer = NULL;
    int* rate_timer = 0;

    while (1) {
        if ((buffer = realloc(buffer, sizeof(int) * BUFFER_SIZE)) == NULL) {
            printf("Memory allocation failed.\n");
            break;
        }

        process_integers(buffer, &rate_timer);

        free(buffer);
        buffer = NULL;
    }

    return 0;
}

void process_integers(int* buffer, int* rate_timer) {
    time_t start_time = time(NULL);
    int integer;

    while (read(STDIN_FILENO, &integer, sizeof(int)) == sizeof(int)) {
        if (*rate_timer + 1 < RATE_LIMIT) {
            *buffer = integer;
            *rate_timer += 1;
        } else {
            // Backpressure mechanism: pause data processing until rate decreases
            usleep(RATE_LIMIT - *rate_timer);
            *rate_timer -= RATE_LIMIT / 2; // Reset rate timer by half
        }
    }

    if (*buffer[0] > 0) { // Check if buffer contains positive integers
        qsort(buffer, BUFFER_SIZE, sizeof(int), int_compare);

        printf("Largest integer: %d\n", find_largest_integer(buffer));
    } else {
        printf("No positive integers found.\n");
    }

    *buffer = NULL;
}

int compare(const void* a, const void* b) {
    return *(const int*)a - *(const int*)b;
}

int find_largest_integer(int* buffer) {
    int max_integer = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (*buffer[i] > max_integer && *buffer[i] > 0)
            max_integer = *buffer[i];
        else if (*buffer[i] > 0) // Check for new maximum
            return *buffer[i];
    }

    return -1;
}
