// Command-line options
#define HELP_FLAG 1
#define VERBOSE_FLAG 2
#define OUTPUT_DIR_FLAG 3
#define BATCH_MODE_FLAG 4

int main(int argc, char *argv[]) {
    int opt;
    char *output_dir = NULL;
    int verbose = 0;
    int batch_mode = 0;

    while ((opt = getopt(argc, argv, "hvo:")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [options] directory...\n", argv[0]);
                return 0;
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_dir = optarg;
                break;
            case 'b':
                batch_mode = 1;
                break;
        }
    }

    if (argc < 2) {
        printf("No directory specified. Use --help for more information.\n");
        return 1;
    }

    // Process directories
    for (int i = optind; i < argc; i++) {
        char *dir = argv[i];
        DIR *dp = opendir(dir);
        if (!dp) {
            perror(dir);
            continue;
        }

        struct dirent *ent;
        while ((ent = readdir(dp))) {
            if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) {
                continue;
            }

            char file_path[PATH_MAX];
            sprintf(file_path, "%s/%s", dir, ent->d_name);

            // Process files
            FILE *file = fopen(file_path, "r");
            if (!file) {
                perror(file_path);
                continue;
            }

            int line_count = 0;
            while (fscanf(file, "%*s\n") == 1) {
                line_count++;
            }

            printf("File: %s, Line count: %d\n", file_path, line_count);

            fclose(file);
        }

        closedir(dp);
    }

    return 0;
}
