#define MAX_CLIENTS 1000
#define MAX_WORKERS 10

typedef struct {
    int socket;
    pthread_t thread;
} client_info;

void *handle_client(void *arg) {
    client_info *client = (client_info *) arg;
    // Handle the client's request here
    printf("Handling client %d\n", client->socket);
    close(client->socket); // Close the client socket after handling
    free(arg); // Free the client info structure
    return NULL;
}

void manage_file_descriptors() {
    pthread_t worker_threads[MAX_WORKERS];
    int worker_count = 0;

    while (1) {
        // Accept new client connections
        int client_socket = accept(listen_fd, NULL, NULL);
        if (client_socket < 0) {
            perror("accept");
            continue;
        }

        // Check for resource limits
        struct rlimit rl;
        getrlimit(RLIMIT_NOFILE, &rl);
        if (rl.rlim_cur < MAX_CLIENTS) {
            close(client_socket); // Close the client socket to avoid exceeding the limit
            continue;
        }

        // Spawn a new worker thread to handle the client
        pthread_create(&worker_threads[worker_count], NULL, handle_client, malloc(sizeof(client_info)));
        worker_count++;
    }
}

int main() {
    manage_file_descriptors();
    return 0;
}
