        pthread_mutex_lock(&mutex);
        if (cached_records[i] != NULL) {
            free(cached_records[i]);
        }
        cached_records[i] = new_record;
        pthread_mutex_unlock(&mutex);

        // Optimize resource usage by reusing structures when possible
        if (i % 1000 == 0) {
            pthread_mutex_lock(&mutex);
            for (int j = i; j > 0; j--) {
                cached_records[j] = cached_records[j - 1];
            }
            free(cached_records[0]);
            pthread_mutex_unlock(&mutex);
        }
    }

    return NULL;
}

