**Task 1: Dynamic Memory Allocation with Largest Integer Finder**

```c
#include <stdio.h>
#include <stdlib.h>

// Function to read integers from standard input and store in array
void readIntegers(int **arr, int *size) {
    int i;
    while (scanf("%d", &i) == 1) {
        (*arr) = realloc((*arr), (*size + 1) * sizeof(int));
        if (!(*arr)) {
            printf("Memory allocation failed\n");
            return;
        }
        (*arr)[*size] = i;
        (*size)++;
    }
}

// Function to find and print the largest integer in the array
int findLargest(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

// Function to initialize and manage multiple threads
void threadManager() {
    pthread_t threads[5]; // Create an array of threads

    for (int i = 0; i < 5; i++) {
