} EVENT_POOL;

// Function to manage event pool
void *manage_event_pool(void *args) {
    // Initialize the event pool
    EVENT_POOL *event_pool = (EVENT_POOL *) args;
    event_pool->event_count = 0;
    pthread_mutex_init(&event_pool->mutex, NULL);

    while (1) {
        // Process events from the pool
        for (int i = 0; i < MAX_EVENTS; i++) {
            if (event_pool->log_events[i].EVENT_ID != -1) {
                process_log_event(&event_pool->log_events[i]);
            }
            if (event_pool->alert_events[i].EVENT_ID != -1) {
                process_alert_event(&event_pool->alert_events[i]);
