            }
            if (event_pool->status_events[i].EVENT_ID != -1) {
                process_status_event(&event_pool->status_events[i]);
            }
        }

        // Release the event pool
        pthread_mutex_lock(&event_pool->mutex);
        for (int i = 0; i < MAX_EVENTS; i++) {
            event_pool->log_events[i].EVENT_ID = -1;
            event_pool->alert_events[i].EVENT_ID = -1;
            event_pool->metric_events[i].EVENT_ID = -1;
            event_pool->audit_events[i].EVENT_ID = -1;
            event_pool->status_events[i].EVENT_ID = -1;
        }
        event_pool->event_count = 0;
        pthread_mutex_unlock(&event_pool->mutex);
    }

    return NULL;
}

