Conn* create_conn(int sock, const char* addr, const char* port) {
    Conn* conn = (Conn*)malloc(sizeof(Conn));
    conn->sock = sock;
    strncpy(conn->addr, addr, sizeof(conn->addr));
    strncpy(conn->port, port, sizeof(conn->port));
    return conn;
}

