double calculateAverage(double* arr, int size);

int main() {
    int n;
    double* numbers = NULL;

    printf("Enter the number of floating-point numbers: ");
    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return -1;
    }

    if (n <= 0) {
        fprintf(stderr, "Please enter a positive integer.\n");
        return -1;
    }

    numbers = (double*)malloc(n * sizeof(double));

    for (int i = 0; i < n; i++) {
        printf("Enter the %d-th floating-point number: ", i + 1);
        if (scanf("%lf", &numbers[i]) != 1) {
            fprintf(stderr, "Invalid input. Please enter a valid floating-point number.\n");
            free(numbers);
            return -1;
        }
    }

    double average = calculateAverage(numbers, n);

    printf("The average value of the numbers is: %f\n", average);

    free(numbers);

    return 0;
}

double calculateAverage(double* arr, int size) {
    double sum = 0.0;

    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }

    return sum / size;
}
