        if (num_datasets >= MAX_DATASETS) {
            printf("Error: Too many datasets. Exiting.\n");
            exit(1);
        }

        video_buffers[num_datasets] = video_buffer;
        audio_metadata[num_datasets] = audio_metadata_item;
        num_datasets++;
    }

    for (int i = 0; i < num_datasets; i++) {
        pthread_create(&threads[i], NULL, process_dataset, &video_buffers[i]);
    }

    for (int i = 0; i < num_datasets; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the datasets
    free(video_buffers);
    free(audio_metadata);

    return 0;
}
