#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include "nfa_api_crc_indication_pdu_t.h"
#include "signal_processing_library.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int rnti;
} PduStruct;

void create_and_populate_pdu_structures(int num_structures, FILE* log_file) {
    PduStruct* pdu_structs = (PduStruct*)malloc(num_structures * sizeof(PduStruct));
    if (!pdu_structs) {
        printf("Memory allocation failed!\n");
        return;
    }

    for (int i = 0; i < num_structures; i++) {
        srand(time(NULL) + i);
        pdu_structs[i].pdu.rx_ue_info_tag = rand() % 1000;
        pdu_structs[i].rnti = rand() % 10000;

        // Randomly set CRCFLAG
        pdu_structs[i].pdu.crc_indication_rel8_tag.crcflag = (rand() % 2) ? CRCFLAG_VALID : CRCFLAG_INVALID;
    }

    // Validate CRC flags against test vectors using signal processing library
    for (int i = 0; i < num_structures; i++) {
        if (!validate_crc_flag(&pdu_structs[i].pdu, log_file)) {
            printf("CRC flag validation failed!\n");
        }
    }

    // Log any validation errors to the specified file
    if (ferror(log_file) != 0) {
        printf("Error logging validation errors: %s\n", strerror(errno));
    }

    free(pdu_structs);
}

int validate_crc_flag(const NFAPI_CRC_INDICATION_PDU_T* pdu, FILE* log_file) {
    // Call signal processing library to validate CRC flag
    int result = signal_processing_library_validate_crc_flag(&pdu->rx_ue_info_tag, &pdu->rnti, &pdu->crc_indication_rel8_tag.crcflag);

    if (result != 0) {
        fprintf(log_file, "CRC flag validation error: %d\n", result);
        return 0;
    }

    return 1;
}

int main() {
    int num_structures = 1000; // Dynamic scaling can be implemented here
    create_and_populate_pdu_structures(num_structures, stdout);

    return 0;
}
