#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SIZE 1000 // Maximum size of the list
#define LOCK_FREE_QUEUE_SIZE 10000 // Size of the lock-free queue for DL Grants

typedef struct {
    int valid;              // Valid PHR indicator (0 or 1)
    float snr;              // Signal-to-Noise Ratio value
    struct dl_grant *grants; // List of downlink grants
} LTE_PHY_RX_FRAME;

typedef struct {
    int rg;                  // Resource grid allocation
    int power;               // Power level setting
} DL_GRANT;

// Lock-free queue for DL Grants
struct lock_free_queue {
    DL_GRANT *elements[LOCK_FREE_QUEUE_SIZE];
    int head;
    int tail;
};

LTE_PHY_RX_FRAME* init_lte_phy_rx_frame(int size) {
    LTE_PHY_RX_FRAME* frames = (LTE_PHY_RX_FRAME*)calloc(size, sizeof(LTE_PHY_RX_FRAME));
    if (!frames) return NULL;

    for (int i = 0; i < size; i++) {
        frames[i].valid = 1;
        frames[i].snr = 10.0f; // Default SNR value
        frames[i].grants = (struct dl_grant*)calloc(5, sizeof(struct dl_grant));
    }
    return frames;
}

void insert_lte_phy_rx_frame(LTE_PHY_RX_FRAME** frames, int* size) {
    *size += 1;
    (*frames) = realloc(*frames, *size * sizeof(LTE_PHY_RX_FRAME));
}

void cleanup_unused_frames(LTE_PHY_RX_FRAME** frames, int* size) {
    for (int i = 0; i < *size - 5; i++) {
        free(frames[i].grants);
        free(&frames[i]);
    }
    *size -= 5;
}

int validate_snr(float snr) {
    if (snr >= 0.0f && snr <= 20.0f) return 1;
    return 0; // Default SNR value
}

void update_lte_phy_rx_frame(LTE_PHY_RX_FRAME** frames, int* size, float snr) {
    for (int i = 0; i < *size; i++) {
        if (!frames[i].valid) continue;

        if (!validate_snr(snr)) snr = 10.0f; // Default SNR value

        for (int j = 0; j < 5; j++) {
            frames[i].grants[j].rg = rand() % 100;
            frames[i].grants[j].power = rand() % 20;
        }
    }
}

void insert_dl_grant(struct lock_free_queue* queue, DL_GRANT grant) {
    int tail = atomic_fetch_add(&queue->tail, 1);
    if (tail >= LOCK_FREE_QUEUE_SIZE) tail = 0;

    queue->elements[tail] = &grant;
}
