#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int RSRP;
    int RSRQ;
    pthread_mutex_t lock;
    struct {
        int bandwidth_part_allocation;
        int modulation_and_coding_scheme;
    } DL_Layers[10];
} NRPHY_RX_FRAME;

NRPHY_RX_FRAME *init_NRPHY_RX_FRAME(int num_Downlink_Layers) {
    NRPHY_RX_FRAME *frame = (NRPHY_RX_FRAME *)malloc(sizeof(NRPHY_RX_FRAME));
    frame->RSRP = -1; // default value
    frame->RSRQ = -1; // default value
    pthread_mutex_init(&frame->lock, NULL);
    for(int i=0; i<num_Downlink_Layers; i++) {
        frame->DL_Layers[i].bandwidth_part_allocation = -1;
        frame->DL_Layers[i].modulation_and_coding_scheme = -1;
    }
    return frame;
}

void populate_NRPHY_RX_FRAME(NRPHY_RX_FRAME *frame, int RSRP, int RSRQ) {
    pthread_mutex_lock(&frame->lock);
    if(RSRP > 90 && RSRP < 110) {
        frame->RSRP = RSRP;
    } else {
        frame->RSRP = -1; // default value
    }
    if(RSRQ > -20 && RSRQ < -10) {
        frame->RSRQ = RSRQ;
    } else {
        frame->RSRQ = -1; // default value
    }
    pthread_mutex_unlock(&frame->lock);
}

void insert_DL_Layer(NRPHY_RX_FRAME *frame, int bandwidth_part_allocation, int modulation_and_coding_scheme) {
    pthread_mutex_lock(&frame->lock);
    for(int i=0; i<10; i++) {
        if(frame->DL_Layers[i].bandwidth_part_allocation == -1) {
            frame->DL_Layers[i].bandwidth_part_allocation = bandwidth_part_allocation;
            frame->DL_Layers[i].modulation_and_coding_scheme = modulation_and_coding_scheme;
            pthread_mutex_unlock(&frame->lock);
            return;
        }
    }
    pthread_mutex_unlock(&frame->lock);
}

void cleanup_NRPHY_RX_FRAME(NRPHY_RX_FRAME *frame) {
    if(frame == NULL) return;
    for(int i=0; i<10; i++) {
        frame->DL_Layers[i].bandwidth_part_allocation = -1;
        frame->DL_Layers[i].modulation_and_coding_scheme = -1;
    }
    free(frame);
}

// Example usage
int main() {
    NRPHY_RX_FRAME *frame = init_NRPHY_RX_FRAME(5);
    populate_NRPHY_RX_FRAME(frame, 95, 0);
    insert_DL_Layer(frame, 20, 2);
    // ... and so on
    cleanup_NRPHY_RX_FRAME(frame);
    return 0;
}
