#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int* data;
    size_t size;
} Array;

Array read_array() {
    Array arr = {NULL, 0};
    int max_size = 10000;

    for (size_t i = 0; !feof(stdin); i++) {
        if (i >= max_size) {
            fprintf(stderr, "Error: input exceeds maximum size of %zu elements.\n", max_size);
            exit(1);
        }

        int num;
        if (!(fscanf(stdin, "%d\n", &num) == 1)) {
            break; // invalid input
        }

        if (num < -1000000 || num > 1000000) {
            continue; // skip out-of-range integers
        }

        arr.data = realloc(arr.data, (i + 1) * sizeof(int));
        arr.data[i] = num;
        arr.size = i + 1;
    }

    return arr;
}

void print_largest(Array arr) {
    if (!arr.size) {
        printf("Error: empty array.\n");
        return;
    }

    qsort(arr.data, arr.size, sizeof(int), compare);

    if (arr.size > 0 && arr.data[arr.size - 1] < 0) {
        printf("Error: all integers are negative.\n");
        return;
    }

    printf("Largest integer: %d\n", arr.data[arr.size - 1]);
}

int compare(const void* a, const void* b) {
    int *ia = (int*)a;
    int *ib = (int*)b;

    return *ib - *ia;
}

int main() {
    Array arr = read_array();
    print_largest(arr);
    free(arr.data);
    return 0;
}
