typedef struct LTE_UPLINK_SRB_T {
    int SRB_TYPE;
    int SRB_PRIORITY;
    int SRB_DATA_SIZE;
    char* SRB_DATA;
    time_t timestamp;
    int sequence_number;
} LTE_UPLINK_SRB_T;

LTE_UPLINK_SRB_T** create_pool(int N) {
    // Allocate memory for the pool of structures
    LTE_UPLINK_SRB_T** pool = (LTE_UPLINK_SRB_T**)malloc((N+1)*sizeof(LTE_UPLINK_SRB_T*));

    if (!pool) return NULL;  // Initialization failed

    int i;
    for (i = 0; i <= N; i++) {
        pool[i] = NULL;  // Initialize each structure to be empty
    }

    return pool;
}

LTE_UPLINK_SRB_T** reuse_pool(int N, LTE_UPLINK_SRB_T** pool) {
    int i;
    for (i = 0; i <= N; i++) {
        if (!pool[i]) continue;

        // Reuse an existing structure
        pool[i]->SRB_DATA = (char*)malloc(pool[i]->SRB_DATA_SIZE);
        if (!pool[i]->SRB_DATA) return NULL;  // Initialization failed

        srand(time(NULL));
        for (int j = 0; j < pool[i]->SRB_DATA_SIZE; j++) {
            pool[i]->SRB_DATA[j] = rand() % 256;
        }

        pool[i]->timestamp = time(NULL);
        pool[i]->sequence_number++;

        return pool;
    }

    // If no suitable structures are found, initialize new ones
    LTE_UPLINK_SRB_T** new_pool = create_pool(N);

    if (!new_pool) return NULL;  // Initialization failed

    return new_pool;
}

int main() {
    int N = 10;
    LTE_UPLINK_SRB_T** pool = reuse_pool(N, NULL);
    if (pool) {
        for (int i = 0; i < N; i++) {
            printf("%d\n", pool[i]->SRB_TYPE);
        }
    }

    return 0;
}

