        pool[i]->RNTI = rand() % 65536;
        pool[i]->timestamp = time(NULL);
        pool[i]->sequence_number = i;
        if ((rand() & 1) == 1) pool[i]->CRCFLAG |= 0x01;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T** pool_reuse(int N, int* available_slots) {
    NFAPI_CRC_INDICATION_PDU_T** pool = NULL;

    if (*available_slots > 0) {
        pool = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pool, (*available_slots + 1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        *available_slots -= sizeof(NFAPI_CRC_INDICATION_PDU_T*)/sizeof(int);
    }

    if (!pool || *available_slots < N) {
        pool = pool_allocate(N - *available_slots);
        *available_slots += (N - *available_slots > 0 ? N - *available_slots : 0);
    }

    return pool;
}

void pool_free(NFAPI_CRC_INDICATION_PDU_T** pool, int available_slots) {
    for (int i=0; i<available_slots; i++) free(pool[i]);
    free(pool);
}
