int findLargestInt(int *arr, int size) {
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

int validateSortedArray(int *arr, int size) {
    for (int i = 1; i < size; i++) {
        if (arr[i - 1] >= arr[i]) {
            printf("Error: Input array is not sorted.\n");
            return -1;
        }
    }
    return 0;
}

