    }

    // Remove leading whitespace
    while (str[0] <= ' ') {
        memmove(str, str + 1, --len);
    }

    // Remove trailing whitespace
    while (len > 0 && str[len - 1] <= ' ') {
        str[--len] = '\0';
    }

    return str;
}

byteArray processFileAndEncrypt(const char* filePath, const char* plaintext, const char* key, const char* iv, PaddingType padding) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    char strings[100][256]; 
    int index = 0;

    while (fgets(strings[index], sizeof(strings[index]), file)) {
        strings[index] = trim(strings[index]);
        if (strlen(strings[index]) > 0) {
            count++;
        }
        index++;
    }
    fclose(file);

    // Encrypt the plaintext message
    AES_KEY aes_key;
    AES_set_encrypt_key((unsigned char*)key, strlen(key) * 8, &aes_key);

    unsigned char ciphertext[100]; 
    unsigned char authTag[16]; 

    int len = strlen(plaintext);
    unsigned char* plainTextBytes = (unsigned char*)malloc(len + 1);
    memcpy(plainTextBytes, plaintext, len);
    plainTextBytes[len] = '\0';

    AES_gcm_encrypt(&aes_key, (unsigned char*)iv, &len, plainTextBytes, ciphertext, authTag);

    free(plainTextBytes);

    byteArray result;
    result.ciphertext = (char*)malloc(len + 16);
    memcpy(result.ciphertext, ciphertext, len);
    for(int i=0; i<16; i++){
        ((unsigned char*)result.ciphertext)[i+len] = authTag[i];
    }
    result.size = len + 16;

    return result;
}

// Structure to represent a byte array
typedef struct {
    char* ciphertext;
    int size;
} byteArray;

