    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[CRCFLAG_MAX];
} NFAPI_CRC_INDICATION_PDU_T;

void* nfa_pi_crc_indication_pdu_pool_manager(int N, int mode) {
    static int pool_size = 0;
    static int num_alloc_failures = 0;
    static int last_used_index = -1;
    static NFAPI_CRC_INDICATION_PDU_T* pool[MAX_POOL_SIZE] = {NULL};

    if (N <= 0) return NULL;

    if (mode == 0) {
        // Allocate new memory
        pool_size = N;
        for (int i = 0; i < N; i++) {
            pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pool[i]) {
                num_alloc_failures++;
                return NULL;
            }
            pool[i]->RX_UE_INFORMATION_TAG = i;
            pool[i]->RNTI = (unsigned short)(rand() % RNTI_MAX);
            time_t now = time(NULL);
            struct tm* timer = localtime(&now);
            int timestamp = (int)timer->tm_sec;
            int sequence_number = i;
            for (int j = 0; j < CRCFLAG_MAX; j++) {
                pool[i]->CRC_INDICATION_REL8_TAG[j] = rand() % CRCFLAG_MAX;
            }
        }
    } else if (mode == 1) {
        // Reuse existing structures
        int available_slots = 0;
        for (int i = last_used_index + 1; i < pool_size; i++) {
            if (!pool[i]->RX_UE_INFORMATION_TAG && !available_slots) {
                available_slots++;
                if (i >= N) break;
            }
        }
        if (available_slots) {
            // Reuse existing structures
            for (int i = 0; i < available_slots; i++) {
                pool[last_used_index + i]->RX_UE_INFORMATION_TAG = last_used_index + i;
                pool[last_used_index + i]->RNTI = (unsigned short)(rand() % RNTI_MAX);
                time_t now = time(NULL);
                struct tm* timer = localtime(&now);
                int timestamp = (int)timer->tm_sec;
                int sequence_number = last_used_index + i;
                for (int j = 0; j < CRCFLAG_MAX; j++) {
                    pool[last_used_index + i]->CRC_INDICATION_REL8_TAG[j] = rand() % CRCFLAG_MAX;
                }
            }
        } else {
            // Allocate new memory
            int alloc_size = N - available_slots;
            for (int i = 0; i < alloc_size; i++) {
                pool[pool_size + i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pool[pool_size + i]) {
                    num_alloc_failures++;
                    return NULL;
                }
                pool[pool_size + i]->RX_UE_INFORMATION_TAG = pool_size + i;
                pool[pool_size + i]->RNTI = (unsigned short)(rand() % RNTI_MAX);
                time_t now = time(NULL);
                struct tm* timer = localtime(&now);
                int timestamp = (int)timer->tm_sec;
                int sequence_number = pool_size + i;
                for (int j = 0; j < CRCFLAG_MAX; j++) {
                    pool[pool_size + i]->CRC_INDICATION_REL8_TAG[j] = rand() % CRCFLAG_MAX;
                }
            }
            last_used_index += alloc_size;
        }
    }

    return pool;
}

void nfa_pi_crc_indication_pdu_pool_manager_clear(void) {
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        if (pool[i]) free(pool[i]);
    }
    pool_size = 0;
    num_alloc_failures = 0;
    last_used_index = -1;
}

