void* logging_system;
log_type_t log_type = LOG_NONE;

int max_value(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void process_input() {
    int size = 0;
    int* arr = NULL;

    while (1) {
        int num;
        scanf("%d", &num);
        if (feof(stdin))
            break;

        size++;
        arr = realloc(arr, sizeof(int) * size);
        arr[size - 1] = num;
    }

    printf("Max value: %d\n", max_value(arr, size));

    free(arr);
}

void* log_data(void* data) {
    int* d = (int*)data;
    char buffer[256];
    time_t now = time(NULL);

    if (log_type == LOG_STDOUT)
        sprintf(buffer, "Max value: %d, Processed elements: %d, Timestamp: %s\n", *d, size, ctime(&now));
    else if (log_type == LOG_FILE) {
        FILE* f = fopen("log.txt", "a");
        fprintf(f, "Max value: %d, Processed elements: %d, Timestamp: %s\n", *d, size, ctime(&now));
        fclose(f);
    }

    return NULL;
}

void set_logging_system(int log_option) {
    if (log_option == 0)
        log_type = LOG_NONE;
    else if (log_option == 1)
        log_type = LOG_STDOUT;
    else
        log_type = LOG_FILE;

    logging_system = pthread_mutex_init(NULL, NULL);
}

int main() {
    set_logging_system(2); // Example usage for file-based logging

    pthread_t thread;
    pthread_create(&thread, NULL, log_data, &size);

    process_input();

    return 0;
}
