#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
int pool_size = 0;
int max_pool_size = 1000;
int num_allocation_failures = 0;
int reuse_attempts = 0;

void init_pool(int N) {
    if (N > max_pool_size)
        N = max_pool_size;
    pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool_size = N;
}

void clear_pool() {
    free(pool);
    pool = NULL;
    pool_size = 0;
}

int get_pool_index(int RNTI) {
    for (int i = 0; i < pool_size; i++) {
        if (pool[i].RNTI == RNTI)
            return i;
    }
    return -1;
}

void crc_indication_relay(int N, int reuse_mode) {
    if (!pool || pool_size < N) {
        init_pool(N);
    } else if (reuse_mode && pool_size > 0) {
        for (int i = 0; i < pool_size; i++) {
            if (get_pool_index(pool[i].RNTI) != -1) {
                reuse_attempts++;
                return;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        int idx;
        if (reuse_mode && pool_size > 0) {
            idx = get_pool_index(rand() % (pool_size - 1));
            if (idx != -1) {
                reuse_attempts++;
                break;
            }
        } else {
            idx = pool_size;
        }

        if (idx >= max_pool_size) {
            num_allocation_failures++;
            return;
        }

        time_t timestamp = time(NULL);
        srand(timestamp + i);

        for (int j = 0; j < sizeof(NFAPI_CRC_INDICATION_PDU_T); j++) {
            pool[idx].RX_UE_INFORMATION_TAG[j] = 'x';
        }
        pool[idx].RNTI = rand() % 65536;
        pool[idx].CRC_INDICATION_REL8_TAG.CRCFLAG = (char)rand();
        pool[idx].timestamp = timestamp;
        pool[idx].sequence_number = i;

        pool_size++;
    }
}

int main() {
    crc_indication_relay(10, 1);
    return 0;
}
