        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output_dir") == 0) {
            output_dir = argv[argc - 1];
            argc--;
            i++;
        } else if (strcmp(argv[i], "--batch-mode") == 0) {
            batch_mode = 1;
        }
    }

    if (argc < 2) {
        fprintf(stderr, "Error: No input directories specified\n");
        return 1;
    }

    int total_lines = 0;

    DIR *dirp;
    struct dirent *dp;
    char file_path[256];

    for (int i = 1; i < argc; i++) {
        dirp = opendir(argv[i]);
        if (!dirp) {
            perror("opendir");
            continue;
        }

        while ((dp = readdir(dirp)) != NULL) {
            if (strcmp(dp->d_name, ".") == 0 || strcmp(dp->d_name, "..") == 0) {
                continue;
            }

            char file_path[256];
            sprintf(file_path, "%s/%s", argv[i], dp->d_name);

            FILE *file = fopen(file_path, "r");
            if (!file) {
                perror("fopen");
                continue;
            }

            int lines = 0;

            while (1) {
                char line[1024];
                if (!fgets(line, sizeof(line), file)) {
                    break;
                }
                lines++;
            }

            total_lines += lines;

            fclose(file);
        }

        closedir(dirp);
    }

    printf("Total lines: %d\n", total_lines);

    return 0;
}
