#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTS 1000
#define MEMORY_POOL_SIZE 1024
#define GROWTH_FACTOR 2
#define RECLAIM_THRESHOLD 0.8

typedef struct {
    int* data;
    int size;
    int capacity;
} memory_pool;

void init_memory_pool(memory_pool* pool, int initial_size) {
    pool->data = (int*)malloc(initial_size * sizeof(int));
    pool->size = 0;
    pool->capacity = initial_size;
}

int grow_memory_pool(memory_pool* pool) {
    if (pool->size >= pool->capacity * RECLAIM_THRESHOLD) {
        int new_capacity = pool->capacity * GROWTH_FACTOR;
        void* new_data = realloc(pool->data, new_capacity * sizeof(int));
        if (!new_data) return 1; // allocation failed
        pool->data = new_data;
        pool->capacity = new_capacity;
    }
    return 0; // no errors
}

void reclaim_memory_pool(memory_pool* pool) {
    int new_size = (int)(pool->size * RECLAIM_THRESHOLD);
    if (new_size < 1) return;
    void* new_data = realloc(pool->data, new_size * sizeof(int));
    if (!new_data) return; // allocation failed
    pool->data = new_data;
    pool->size = 0;
}

int process_integers(memory_pool* pool) {
    int count = 0;
    char buffer[10];
    FILE* file = stdin;

    while (fscanf(file, "%s", buffer) == 1 && count < MAX_INTS) {
        int num;
        if (sscanf(buffer, "%d", &num) != 1) return -1; // invalid input

        if (grow_memory_pool(pool)) return -1; // memory allocation failed
        pool->data[pool->size++] = num;

        if (ferror(file)) return -2; // EOF or error reading file
    }

    if (count == 0) {
        printf("No integers provided.\n");
        return -3; // no valid integers read
    }

    qsort(pool->data, pool->size, sizeof(int), compare_ints);

    int largest = find_largest_integer(pool->data, pool->size);
    printf("Largest integer: %d\n", largest);

    return 0;
}

int main() {
    memory_pool pool;
    init_memory_pool(&pool, MEMORY_POOL_SIZE);
    process_integers(&pool);
    reclaim_memory_pool(&pool);
    free(pool.data);
    return 0;
}
