    if ((host = gethostbyname(hostname)) == NULL) {
        return (u_char*)malloc(strlen(hostname)+1);
    }
    char buffer[MAX_IP_ADDRESS];
    strcpy(buffer, inet_ntoa(*(struct in_addr*)host->h_addr));
    free(host);
    return (u_char*)buffer;
