        !json_object_object_get(token, "expires_in") || 
        !json_object_object_get(token, "token_type")) {
        return false;
    }
    char* access_token = json_object_to_json_string_ext(token, JSON_C_TO_STRING_NOCOPY);
    if (strcmp(access_token, "Bearer") != 0) {
        free(access_token);
        return false;
    }
    int expires_in = json_object_get_int(token, "expires_in");
    if (expires_in < 1) {
        free(access_token);
        return false;
    }
    char* refresh_token = json_object_to_json_string_ext(token, JSON_C_TO_STRING_NOCOPY);
    if (!refresh_token || strlen(refresh_token) > MAX_HOSTNAME) {
        free(refresh_token);
        free(access_token);
        return false;
    }
    free(refresh_token);
    free(access_token);
    return true;
}

