    tcp_connection_record_pool = (TCP_CONNECTION_RECORD *)malloc(N * sizeof(TCP_CONNECTION_RECORD));
    if (!tcp_connection_record_pool) {
        printf("Memory allocation failed. Increasing initial pool size to %d.\n", N + 100);
        N += 100;
        return initialize_pool(N);
    }

    pool_size = N;
    for (int i = 0; i < N; i++) {
        tcp_connection_record_pool[i].CONN_ID = -1;
        strcpy(tcp_connection_record_pool[i].SRC_IP, "0.0.0.0");
        strcpy(tcp_connection_record_pool[i].DST_IP, "255.255.255.255");
        tcp_connection_record_pool[i].SYN_FLAG = 0;
    }

    return 0;
}

TCP_CONNECTION_RECORD *get_connection_record(int CONN_ID) {
    for (int i = 0; i < pool_size; i++) {
        if (tcp_connection_record_pool[i].CONN_ID == -1) {
            tcp_connection_record_pool[i].CONN_ID = CONN_ID;
            return &tcp_connection_record_pool[i];
        }
    }

    TCP_CONNECTION_RECORD *new_record = malloc(sizeof(TCP_CONNECTION_RECORD));
    if (!new_record) {
        failed_allocations++;
        printf("Memory allocation failed. Increasing pool size.\n");
        new_record = get_connection_record(CONN_ID);
    } else {
        new_record->CONN_ID = CONN_ID;
    }

    return new_record;
}

void log_memory_leak() {
    if (failed_allocations > 0) {
        printf("Memory leak detected: %d failed allocations.\n", failed_allocations);
    }
}
