    public Report analyzeLibrary(String libraryVersion, Map<String, Boolean> filters) throws IOException {
        Report report = fetchLatestInformation(libraryVersion);
        if (report == null) {
            return new Report("No information found for the given library version.");
        }
        report.setFilters(filters);

        // Process and filter issues
        report.getIssues().stream()
                .filter(issue -> !filters.containsKey("all-severity") || issue.getSeverity() != Severity.CRITICAL)
                .forEach(this::handleIssue);

        return report;
    }

    private Report fetchLatestInformation(String libraryVersion) throws IOException {
        if (cache.containsKey(libraryVersion)) {
            return getFromCache(libraryVersion);
        }
        String response = apiClient.fetchLibraryInfo(libraryVersion);
        cache.put(libraryVersion, response);
        Timer timer = new Timer();
        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                cache.remove(libraryVersion);
            }
        }, API_CACHE_TIME);
        return parseResponse(response);
    }

