#include <stdio.h>
#include <stdlib.h>

double average(float* arr, int size) {
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum / size;
}

void printArray(float* arr, int size) {
    printf("Array: ");
    for (int i = 0; i < size; i++) {
        printf("%f ", arr[i]);
    }
    printf("\n");
}

float* readArray(int* size) {
    float* arr = NULL;
    int count = 0;

    while (1) {
        float num;
        if (!(scanf("%f", &num))) {
            if (feof(stdin)) {
                break; // End of file, stop reading
            }
            else {
                printf("Invalid input. Please enter a floating-point number.\n");
                while(getchar() != '\n'); // Flush the buffer
                rewind(stdin); // Reset the file pointer
            }
        }
        arr = realloc(arr, (count + 1) * sizeof(float));
        if (!arr) {
            printf("Memory allocation failed. Terminating program.\n");
            exit(EXIT_FAILURE);
        }
        arr[count++] = num;
    }

    *size = count;
    return arr;
}

int main() {
    int size;
    float* arr = readArray(&size);

    if (size == 0) {
        printf("No numbers entered. Average cannot be calculated.\n");
    }
    else {
        double avg = average(arr, size);
        printf("Average: %f\n", avg);
    }

    free(arr); // Release allocated memory
    return 0;
}
