                processImage(file.path(), format, outputDir, verbose);
            }
        }
    } else {
        std::cerr << "No input directory specified. Use -o option to specify an output directory." << std::endl;
    }

    return 0;
}

void processImage(const fs::path& filePath, Format format, const std::string& outputDir, bool verbose) {
    // Convert image to specified format
    cv::Mat image = cv::imread(filePath.string());
    cv::Mat convertedImage;
    switch (format) {
        case Format::JPEG:
            cv::imencode(".jpg", image, convertedImage);
            break;
        case Format::PNG:
            cv::imencode(".png", image, convertedImage);
            break;
    }

    // Write converted image to output directory
    std::ofstream file(outputDir + "/" + filePath.filename().string(), std::ios_base::binary);
    file << convertedImage;

    if (verbose) {
        std::cout << "Processed image: " << filePath.filename() << std::endl;
    }
}

