void manage_dynamic_array(LTE_EUTRA_SIB10_T **array, int *size) {
    // Initialize octree data structure
    OCTREE *oct = octree_create();

    for (int i = 0; i < *size; i++) {
        LTE_EUTRA_SIB10_T *sib10 = array[i];

        // Set CRCFLAG using pseudo-random number generator
        sib10->crcflag = crcflag_generate(sib10->tdd_ul_dl_config_index);

        // Add SIB10 message to octree
        octree_insert(oct, sib10);
    }

    // Process data asynchronously for handling multiple concurrent UE instances
    pthread_t threads[*size];
    for (int i = 0; i < *size; i++) {
        pthread_create(&threads[i], NULL, process_data, array[i]);
    }
    for (int i = 0; i < *size; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up inactive messages
