    if (N <= 0) return; // handle invalid input

    pool_size = N;
    tcp_conn_pool = malloc(pool_size * sizeof(TCP_CONNECTION_RECORD));
    if (!tcp_conn_pool) {
        printf("Memory allocation failed!\n");
        num_alloc_failures++;
        return;
    }

    for (int i = 0; i < pool_size; i++) {
        tcp_conn_pool[i].Conn_ID = i + 1;
        tcp_conn_pool[i].Src_IP = 0x00000000;
        tcp_conn_pool[i].Dst_IP = 0x00000000;
        tcp_conn_pool[i].Syn_Flag = SYN_FLAG;
    }
}

void tcp_conn_pool_clear() {
    if (!tcp_conn_pool) return; // handle invalid input

    for (int i = 0; i < pool_size; i++) {
        free(tcp_conn_pool + i);
    }

    free(tcp_conn_pool);
    tcp_conn_pool = NULL;
    pool_size = 0;
}

