['Here is the C code block for the `log_manager` function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    char* event_type;
    int severity_level;
    char* source_identifier;
} log_entry;

typedef struct {
    pthread_mutex_t mutex;
    log_entry** entries;
    int entry_count;
} log_manager;

log_manager* log_manager_new() {
    log_manager* manager = (log_manager*)malloc(sizeof(log_manager));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void log_manager_add_entry(log_manager* manager, long timestamp, const char* event_type, int severity_level, const char* source_identifier) {
    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    entry->timestamp = timestamp;
    entry->event_type = (char*)malloc(strlen(event_type) + 1);
    strcpy(entry->event_type, event_type);
    entry->severity_level = severity_level;
    entry->source_identifier = (char*)malloc(strlen(source_identifier) + 1);
    strcpy(entry->source_identifier, source_identifier);

    pthread_mutex_lock(&manager->mutex);
    manager->entries = (log_entry**)realloc(manager->entries, (manager->entry_count + 1) * sizeof(log_entry*));
    manager->entries[manager->entry_count] = entry;
    manager->entry_count++;
    pthread_mutex_unlock(&manager->mutex);
}

void log_manager_update_entry(log_manager* manager, const char* source_identifier, long timestamp, const char* event_type, int severity_level) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->entry_count; i++) {
        if (strcmp(manager->entries[i]->source_identifier, source_identifier) == 0) {
            free(manager->entries[i]->event_type);
            manager->entries[i]->event_type = (char*)malloc(strlen(event_type) + 1);
            strcpy(manager->entries[i]->event_type, event_type);
            manager->entries[i]->timestamp = timestamp;
            manager->entries[i]->severity_level = severity_level;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

log_entry* log_manager_get_entry(log_manager* manager, const char* source_identifier) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->entry_count; i++) {
        if (strcmp(manager->entries[i]->source_identifier, source_identifier) == 0) {
            log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
            *entry = *manager->entries[i];
            return entry;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}
