#define FLOAT_SIZE sizeof(float)

void processFloats(int sockfd) {
    int numFloats = 0;
    float *floats = NULL;

    // Receive the number of floats from the client
    int len = recv(sockfd, &numFloats, sizeof(int), 0);
    if (len != sizeof(int)) {
        perror("recv");
        return;
    }

    // Allocate memory for the array of floats
    floats = (float *)malloc(numFloats * FLOAT_SIZE);
    if (!floats) {
        perror("malloc");
        return;
    }

    // Receive and store the floats in the array
    len = recv(sockfd, floats, numFloats * FLOAT_SIZE, 0);
    if (len != (numFloats * FLOAT_SIZE)) {
        free(floats);
        perror("recv");
        return;
    }

    // Compute the average of the floats
    float sum = 0.0f;
    for (int i = 0; i < numFloats; i++) {
        if (isnan(floats[i]) || isinf(floats[i])) {
            printf("Corrupted data detected: %f\n", floats[i]);
            free(floats);
            return;
        }
        sum += floats[i];
    }

    float average = sum / numFloats;

    // Send the computed average back to the client
    len = send(sockfd, &average, sizeof(float), 0);
    if (len != sizeof(float)) {
        perror("send");
    }

    free(floats);
}
