#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ALLOCATIONS 1000
#define LATENCY_THRESHOLD 10 // in milliseconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    enum { CRCFLAG_VALID, CRCFLAG_INVALID } crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_array(int N) {
    static int total_allocations = 0;
    static int max_allocated = 0;
    static int queue_size = 0;

    if (total_allocations >= MAX_ALLOCATIONS) {
        // Queue new allocations
        while (queue_size < MAX_ALLOCATIONS - total_allocations && N > 0) {
            if ((NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)) == NULL) {
                return NULL;
            }
            queue_size++;
            N--;
        }

        // Wait until space becomes available
        while (queue_size > 0 && total_allocations < MAX_ALLOCATIONS);
    }

    if (N <= 0 || total_allocations + N > max_allocated) {
        // Calculate the required memory size
        size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

        // Allocate a memory pool with the required size
        void* memory_pool = mmap(NULL, required_memory, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
        if (memory_pool == MAP_FAILED) {
            return NULL;
        }

        max_allocated += N;

        // Initialize the array
        NFAPI_CRC_INDICATION_PDU_T* array = memory_pool;
        for (int i = 0; i < N; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 100;
            array[i].RNTI = rand() % 200 + 1;
            array[i].crcflag = CRCFLAG_VALID;

            // Set the timestamp and sequence number
            array[i].CRC_INDICATION_REL8_TAG.timestamp = time(NULL);
            array[i].CRC_INDICATION_REL8_TAG.sequence_number = i;

            // Validate RNTI range
            if (array[i].RNTI < 1 || array[i].RNTI > 200) {
                return NULL;
            }
        }

        // Update the total allocations and queue size
        total_allocations += N;
        queue_size -= N;

        munmap(memory_pool, required_memory);
    } else {
        // Reuse existing structures if possible
        for (int i = 0; i < N; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 100;
            array[i].RNTI = rand() % 200 + 1;
            array[i].crcflag = CRCFLAG_VALID;

            // Set the timestamp and sequence number
            array[i].CRC_INDICATION_REL8_TAG.timestamp = time(NULL);
            array[i].CRC_INDICATION_REL8_TAG.sequence_number = i;

            // Validate RNTI range
            if (array[i].RNTI < 1 || array[i].RNTI > 200) {
                return NULL;
            }
        }
    }

    return array;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_array(10);

    // Log the allocation result
    printf("%s: Allocated %d structures in %.2fms\n", asctime(localtime(&clock())), 10, clock() / (double)CLOCKS_PER_SEC * 1000.0);
}
