import java.io.*;
import java.util.zip.*;

public class SessionStateLoader {
    public static SessionState loadSessionState(String filePath) throws IOException {
        FileInputStream fileInputStream = new FileInputStream(filePath);
        ZipInputStream zipInputStream = new ZipInputStream(fileInputStream);

        ZipEntry entry = zipInputStream.getNextEntry();
        if (entry != null && entry.getName().equals("session_state.ser")) {
            ObjectInputStream objectInputStream = new ObjectInputStream(zipInputStream);
            SessionState sessionState = (SessionState) objectInputStream.readObject();

            return sessionState;
        } else {
            throw new IOException("Invalid file or no session state found");
        }
    }
}
