#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int conn_id;
    char src_ip[16];
    char dst_ip[16];
    int syn_flag;
    long timestamp;
    int seq_num;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD **pool = NULL;
int pool_size = 0;
int max_pool_size = 1024;
int allocation_failures = 0;
int reuse_attempts = 0;

void clear_pool() {
    for (int i = 0; i < pool_size; i++) {
        free(pool[i]);
    }
    free(pool);
    pool = NULL;
    pool_size = 0;
}

TCP_CONNECTION_RECORD *create_connection(int conn_id, char src_ip[], char dst_ip[]) {
    TCP_CONNECTION_RECORD *conn = (TCP_CONNECTION_RECORD *)malloc(sizeof(TCP_CONNECTION_RECORD));
    if (!conn) {
        allocation_failures++;
        return NULL;
    }
    conn->conn_id = conn_id;
    strcpy(conn->src_ip, src_ip);
    strcpy(conn->dst_ip, dst_ip);
    conn->syn_flag = 1; // assuming all connections start in SYN_SENT state
    long timestamp = time(NULL); // get current timestamp
    int seq_num = 0; // initialize sequence number to 0
    return conn;
}

TCP_CONNECTION_RECORD *manage_pool(int N) {
    if (pool_size == 0 || pool[pool_size-1]->conn_id != -1) { // allocate new memory for the pool
        pool = (TCP_CONNECTION_RECORD **)realloc(pool, sizeof(TCP_CONNECTION_RECORD *) * (N + 1));
        for (int i = 0; i < N; i++) {
            pool[i] = create_connection(i, "0.0.0.0", "255.255.255.255");
            if (!pool[i]) {
                allocation_failures++;
                return NULL;
            }
        }
        pool_size = N + 1;
    } else { // reuse existing structures
        for (int i = 0; i < pool_size - 1; i++) {
            if (pool[i]->conn_id == -1) {
                int conn_id = i;
                char src_ip[16] = "reused";
                char dst_ip[16] = "connection";
                return create_connection(conn_id, src_ip, dst_ip);
            }
        }
    }
}

int main() {
    // manage the pool with N connections
    TCP_CONNECTION_RECORD *conn = manage_pool(5);

    if (!conn) {
        printf("Memory allocation failed. Allocation failures: %d\n", allocation_failures);
        return 1;
    }

    // use the connection record
    conn->syn_flag = 0; // set SYN flag to 0 after using the connection

    // clear the pool and start fresh
    clear_pool();

    return 0;
}
