#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to represent a log entry
typedef struct {
    int timestamp;
    char* event_type;
    int severity_level;
    char* source_identifier;
} LogEntry;

// Define the structure to represent the log manager
typedef struct {
    pthread_mutex_t lock; // Mutex for thread-safe operations
    size_t capacity; // Maximum number of log entries
    LogEntry** log_entries; // Array of log entries
    int num_entries; // Number of current log entries
} LogManager;

// Function to create a new log manager instance
LogManager* log_manager_create(size_t capacity) {
    LogManager* lm = (LogManager*)malloc(sizeof(LogManager));
    lm->capacity = capacity;
    lm->log_entries = (LogEntry**)calloc(capacity, sizeof(LogEntry*));
    lm->num_entries = 0;
    pthread_mutex_init(&lm->lock, NULL);
    return lm;
}

// Function to add a new log entry
void log_manager_add_entry(LogManager* lm, int timestamp, char* event_type, int severity_level, char* source_identifier) {
    pthread_mutex_lock(&lm->lock); // Lock for thread-safe operations

    if (lm->num_entries >= lm->capacity) {
        printf("Error: Log manager capacity exceeded.\n");
        return;
    }

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->event_type = strdup(event_type);
    entry->severity_level = severity_level;
    entry->source_identifier = strdup(source_identifier);

    lm->log_entries[lm->num_entries++] = entry;

    pthread_mutex_unlock(&lm->lock); // Unlock
}

// Function to retrieve log entries by source identifier
void log_manager_get_entries_by_source(LogManager* lm, char* source_identifier) {
    pthread_mutex_lock(&lm->lock); // Lock for thread-safe operations

    int i;
    for (i = 0; i < lm->num_entries; i++) {
        if (strcmp(lm->log_entries[i]->source_identifier, source_identifier) == 0) {
            printf("Timestamp: %d, Event Type: %s, Severity Level: %d\n", lm->log_entries[i]->timestamp, lm->log_entries[i]->event_type, lm->log_entries[i]->severity_level);
        }
    }

    pthread_mutex_unlock(&lm->lock); // Unlock
}

// Function to destroy a log manager instance
void log_manager_destroy(LogManager* lm) {
    int i;
    for (i = 0; i < lm->num_entries; i++) {
        free(lm->log_entries[i]->event_type);
        free(lm->log_entries[i]->source_identifier);
        free(lm->log_entries[i]);
    }
    free(lm->log_entries);
    pthread_mutex_destroy(&lm->lock);
    free(lm);
}

