    char src_ip[16];
    char dst_ip[16];
    int syn_flag;
    time_t timestamp;
    int seq_num;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD* tcp_connection_pool = NULL;
int pool_size = 0;
int max_connections = 0;
int allocation_failures = 0;

void clear_tcp_connection_pool() {
    if (tcp_connection_pool != NULL) {
        free(tcp_connection_pool);
        tcp_connection_pool = NULL;
        pool_size = 0;
        max_connections = 0;
        allocation_failures = 0;
    }
}

TCP_CONNECTION_RECORD* allocate_tcp_connection(int n) {
    TCP_CONNECTION_RECORD* new_pool = (TCP_CONNECTION_RECORD*)malloc(n * sizeof(TCP_CONNECTION_RECORD));
    if (new_pool == NULL) {
        allocation_failures++;
        return tcp_connection_pool; // reuse existing pool
    } else {
        free(tcp_connection_pool);
        tcp_connection_pool = new_pool;
        pool_size = n;
        max_connections = MAX_TCP_CONNECTIONS;
        allocation_failures = 0;
    }
    return tcp_connection_pool;
}

void handle_tcp_connection(int conn_id, char* src_ip, char* dst_ip, int syn_flag) {
    // implement validation and timestamping logic here
    TCP_CONNECTION_RECORD* record = tcp_connection_pool + (conn_id % pool_size);
    if (record->conn_id == 0) {
        strcpy(record->src_ip, src_ip);
        strcpy(record->dst_ip, dst_ip);
        record->syn_flag = syn_flag;
        record->timestamp = time(NULL);
        record->seq_num = conn_id;
    }
}

int main() {
    // example usage
    int n = 16;
    TCP_CONNECTION_RECORD* pool = allocate_tcp_connection(n);

    for (int i = 0; i < n; i++) {
        handle_tcp_connection(i, "192.168.1.100", "8.8.8.8", i % 2 == 0 ? 1 : 0);
    }

    clear_tcp_connection_pool();

    return 0;
}
