#include <stdio.h>
#include <stdlib.h>

int largest_integer_in_list() {
    // Initialize variables to store the maximum integer and the current size of the list.
    int max_int = INT_MIN;
    size_t list_size = 0;

    // Dynamically allocate memory for the array based on the number of elements in the input file.
    int* integers = NULL;
    while (1) {
        char buffer[256];
        fgets(buffer, sizeof(buffer), stdin);

        if (feof(stdin)) {
            break; // End-of-file reached. Exit loop.
        }

        // Check if the current line contains a non-integer value.
        char* token = strtok(buffer, " ");
        while (token) {
            int num;
            if (sscanf(token, "%d", &num) != 1 || num < INT_MIN || num > INT_MAX) {
                printf("Invalid input: %s. Please enter an integer.\n", token);
                return -1; // Exit the function with a failure status.
            }

            // Update the maximum integer if necessary.
            max_int = (num > max_int) ? num : max_int;

            // Dynamically allocate memory to store the current list size plus one, considering the worst-case scenario where all elements are positive integers.
            if (list_size == 0 || list_size % 10 == 0) {
                integers = realloc(integers, sizeof(int) * (list_size + 10));
            }

            // Store the current integer in the array.
            integers[list_size] = num;
            list_size++;

            token = strtok(NULL, " ");
        }
    }

    // Free dynamically allocated memory and print the maximum integer found in the list.
    free(integers);
    printf("The largest integer in the list is: %d.\n", max_int);

    return 0; // Exit with a success status.
}
