typedef struct {
    int timestamp;
    char eventType[20];
    int severityLevel;
    char sourceIdentifier[30];
} LogEntry;

typedef struct {
    pthread_mutex_t mutex;
    LogEntry* logEntries;
    int numLogEntries;
} LogManager;

void log_manager_init(LogManager* logManager, int maxNumLogEntries) {
    logManager->numLogEntries = 0;
    logManager->logEntries = (LogEntry*)malloc(maxNumLogEntries * sizeof(LogEntry));
}

void add_log_entry(LogManager* logManager, LogEntry newEntry) {
    pthread_mutex_lock(&logManager->mutex);
    if (logManager->numLogEntries < 10000) {
        logManager->logEntries[logManager->numLogEntries] = newEntry;
        logManager->numLogEntries++;
    }
    pthread_mutex_unlock(&logManager->mutex);
}

void update_log_entry(LogManager* logManager, char sourceIdentifier[], int severityLevel) {
    pthread_mutex_lock(&logManager->mutex);
    for (int i = 0; i < logManager->numLogEntries; i++) {
        if (strcmp(logManager->logEntries[i].sourceIdentifier, sourceIdentifier) == 0) {
            logManager->logEntries[i].severityLevel = severityLevel;
            break;
        }
    }
    pthread_mutex_unlock(&logManager->mutex);
}

LogEntry* get_log_entry(LogManager* logManager, char sourceIdentifier[]) {
    LogEntry* result = NULL;
    pthread_mutex_lock(&logManager->mutex);
    for (int i = 0; i < logManager->numLogEntries; i++) {
        if (strcmp(logManager->logEntries[i].sourceIdentifier, sourceIdentifier) == 0) {
            result = &logManager->logEntries[i];
            break;
        }
    }
    pthread_mutex_unlock(&logManager->mutex);
    return result;
}

void free_log_manager(LogManager* logManager) {
    free(logManager->logEntries);
}
