#define MAX_TASKS 100
#define MAX_TASK_NAME 255

typedef struct {
    char name[MAX_TASK_NAME];
    int executed;
} Task;

int main(int argc, char *argv[]) {
    FILE *log_file = NULL;
    Task tasks[MAX_TASKS] = {{""},};
    int task_count = 0;

    // Parse command line options
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--help")) {
            // Help message goes here
        } else if (!strcmp(argv[i], "--add") && i + 1 < argc) {
            char task_name[MAX_TASK_NAME];
            strcpy(task_name, argv[i + 1]);
            // Add the task to the tasks array and increment count
            tasks[task_count].name[0] = '\0';
            strcpy(tasks[task_count].name, task_name);
            task_count++;
        } else if (!strcmp(argv[i], "--remove") && i + 1 < argc) {
            char task_name[MAX_TASK_NAME];
            strcpy(task_name, argv[i + 1]);
            // Remove the task from the tasks array and decrement count
            for (int j = 0; j < task_count; j++) {
                if (!strcmp(tasks[j].name, task_name)) {
                    task_count--;
                    memmove(&tasks[j], &tasks[j + 1], sizeof(Task) * (task_count - j));
                    break;
                }
            }
        } else if (!strcmp(argv[i], "--list")) {
            // List the tasks
            for (int i = 0; i < task_count; i++) {
                printf("%s\n", tasks[i].name);
            }
        } else if (!strcmp(argv[i], "--log_file") && i + 1 < argc) {
            char log_file_path[MAX_TASK_NAME];
            strcpy(log_file_path, argv[i + 1]);
            // Open the log file
            log_file = fopen(log_file_path, "w");
        }
    }

    // Execute tasks sequentially
    for (int i = 0; i < task_count; i++) {
        // Simulate task execution and increment executed flag
        tasks[i].executed++;
        if (log_file) {
            fprintf(log_file, "%s: %d\n", tasks[i].name, tasks[i].executed);
        }
    }

    fclose(log_file);

    return 0;
}
