    LTE_PHY_TX_RX_PDU_T* current_pdu_t = NULL;
    int i, j, k, l;

    // Check if the requested allocation size is within valid range
    if (N > max_pool_size) {
        printf("Invalid allocation size. Maximum pool size exceeded.\n");
        return NULL;
    }

    // Check for memory leaks and report errors
    if (total_allocation_failures >= MAX_ALLOCATION_FAILURES) {
        printf("Memory allocation failed too many times. Terminating program.\n");
        exit(1);
    }

    // Calculate the total number of structures required
    int total_structures = N;

    // If reuse_threshold is greater than zero, attempt to reuse previously allocated structures
    if (reuse_threshold > 0) {
        // Check for available reused slots and update total_structures accordingly
        for (i = 0; i < reuse_threshold && i < max_pool_size; i++) {
            if (!available_slots[i]) {
                total_structures++;
            }
        }
    }

    // Allocate memory for the pool of structures
    pool = (LTE_PHY_TX_RX_PDU_T*)malloc(total_structures * sizeof(LTE_PHY_TX_RX_PDU_T));
    available_slots = (LTE_PHY_TX_RX_PDU_T**)malloc(max_pool_size * sizeof(LTE_PHY_TX_RX_PDU_T*));

    if (!pool || !available_slots) {
        current_allocation_failures++;
        total_allocation_failures++;

        // If memory allocation fails, log the error and return
        printf("Memory allocation failed. Trying again.\n");
        free(pool);
        pool = NULL;
        free(available_slots);
        available_slots = NULL;

        if (current_allocation_failures >= MAX_ALLOCATION_FAILURES) {
            printf("Memory allocation failed too many times. Terminating program.\n");
            exit(1);
        }
    } else {
        current_allocation_failures = 0;
        total_allocation_failures = 0;
    }

    // Initialize the pool and available slots
    for (i = 0; i < max_pool_size; i++) {
        available_slots[i] = &pool[i];
    }

    // Reuse previously allocated structures
    if (reuse_threshold > 0) {
        for (j = 0; j < total_structures - N; j++) {
            current_pdu_t = pool;
            k = 0;

            // Iterate through the available slots to find a suitable structure to reuse
            for (i = 0; i < max_pool_size; i++) {
                if (!available_slots[i]) {
                    k++;
                    if (k >= total_structures - N) {
                        break;
                    }
                }
            }

            // If no suitable structure is found, allocate new memory and update available slots
            if (k < total_structures - N) {
                for (i = 0; i < max_pool_size; i++) {
                    if (!available_slots[i]) {
                        current_pdu_t = &pool[i];
                        break;
                    }
                }

                // Reset the reused structure's timestamp, sequence number, and flags
                current_pdu_t->tx_buffer_desc.timestamp = j;
                current_pdu_t->tx_buffer_desc.sequence_number = j;
                current_pdu_t->tx_buffer_desc.flags = 0;

                available_slots[i] = NULL;
            }
        }
    }

    // Clear the pool of structures and reset available slots
    for (i = 0; i < max_pool_size; i++) {
        free(available_slots[i]);
        available_slots[i] = NULL;
    }

    return pool;
}

