#include <zlib.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE 4096

int main(int argc, char **argv) {
    int c;
    FILE *input_file = NULL;
    char output_file[256] = "";
    int print_to_stdout = 0;
    int compress_output = 0;

    while ((c = getopt(argc, argv, "o:p:cs")) != -1) {
        switch (c) {
            case 'o':
                strcpy(output_file, optarg);
                break;
            case 'p':
                print_to_stdout = 1;
                break;
            case 's':
                compress_output = 1;
                break;
            case 'm':
                printf("Usage information goes here...\n");
                return 0;
        }
    }

    if (argc - optind < 1) {
        fprintf(stderr, "Error: No input file provided.\n");
        printf("Usage: %s [-cs] [-o output_file] [-p] [input_file]\n", argv[0]);
        return 1;
    }

    char *input_file_name = argv[optind];

    if ((input_file = fopen(input_file_name, "r")) == NULL) {
        perror("Error opening input file");
        return 1;
    }

    int line_count = 0;
    int total_chars = 0;

    char buffer[BUFFER_SIZE];
    size_t read_bytes;

    while ((read_bytes = fread(buffer, 1, BUFFER_SIZE, input_file)) > 0) {
        for (size_t i = 0; i < read_bytes; i++) {
            if ('\n' == buffer[i]) line_count++;
            total_chars += buffer[i];
        }
    }

    fclose(input_file);

    // Calculate compression ratio
    size_t original_size = ftell(input_file);
    fseek(input_file, 0, SEEK_SET);
    char *compressed_buffer;
    size_t compressed_size;

    if (compress_output) {
        compressed_buffer = malloc(original_size + 1);
        int status = compress2(compressed_buffer, &compressed_size, buffer, read_bytes, Z_DEFAULT_COMPRESSION);
        if (status != Z_OK) {
            perror("Error compressing data");
            return 1;
        }

        printf("%d lines, %zu characters.\n", line_count, total_chars);

        if (print_to_stdout) {
            fwrite(compressed_buffer, 1, compressed_size, stdout);
            free(compressed_buffer);
        } else {
            FILE *output = fopen(output_file, "w");
            fwrite(compressed_buffer, 1, compressed_size, output);
            fclose(output);
            free(compressed_buffer);
        }
    } else {
        printf("%d lines, %zu characters.\n", line_count, total_chars);

        if (print_to_stdout) {
            fwrite(buffer, 1, read_bytes, stdout);
        } else {
            FILE *output = fopen(output_file, "w");
            fwrite(buffer, 1, read_bytes, output);
            fclose(output);
        }
    }

    return 0;
}
