    for (int i = 0; i < N; i++) {
        // Reset the structure to its initial state
        arr[i].desc.timestamp = 0;
        arr[i].desc.sequence_number = 0;
        arr[i].desc.flags = 0;
        arr[i].state = TX_BUFFER_STATE_VALID;
        arr[i].transport_format = 0;
