    LTE_PHY_TX_RX_PDU_T* newArr = (LTE_PHY_TX_RX_PDU_T*)malloc(newSize * sizeof(LTE_PHY_TX_RX_PDU_T));

    if (newArr == NULL) {
        return NULL;
    }

    // Copy the existing data to the new array
    for (int i = 0; i < N; i++) {
        newArr[i] = arr[i];
    }

    // Free the original array
