    FILE* file;
} InputArray;

// Function to initialize the dynamic array
void init_array(InputArray* array, size_t max_size) {
    array->array = (int*)malloc(max_size * sizeof(int));
    array->size = 0;
}

// Function to add an integer to the array
void add_integer(InputArray* array, int val) {
    if (array->size >= array->array) {
        array->array = (int*)realloc(array->array, (array->size + 1) * sizeof(int));
    }
    array->array[array->size] = val;
    array->size++;
}

// Function to compress the array into binary format
void compress_array(InputArray* array, FILE* output_file) {
    fwrite(&array->size, sizeof(size_t), 1, output_file);
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->array[i], sizeof(int), 1, output_file);
    }
}

// Function to find the largest integer in the array
int find_largest(InputArray* array) {
    int max_val = INT_MIN;
    for (int i = 0; i < array->size; i++) {
        if (array->array[i] > max_val) {
            max_val = array->array[i];
        }
    }
    return max_val;
}

// Function to calculate the average of the integers in the array
double calculate_average(InputArray* array) {
    double sum = 0.0;
    for (int i = 0; i < array->size; i++) {
        sum += array->array[i];
    }
    return sum / array->size;
}

// Function to read input from multiple sources and handle compressed binary format
void process_input(InputArray* array, FILE* file) {
    int val;
    while (fscanf(file, "%d", &val) == 1) {
        add_integer(array, val);
    }
}

