void print_usage() {
    printf("Usage: ./program [-v] [-d directory] [--recursive] [--help]\n");
    printf("Options:\n");
    printf("-v\tVerbose mode\n");
    printf("-d directory\tSpecify the input directory\n");
    printf("--recursive\tProcess all files within a directory hierarchy\n");
    printf("--help\tShow this help message and exit\n");
}

int main(int argc, char *argv[]) {
    int verbose = 0;
    char *directory = DEFAULT_DIR;
    int recursive = 0;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            directory = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "--recursive") == 0) {
            recursive = 1;
        } else if (strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        }
    }

    // Load configuration file
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        logging_error("Failed to open configuration file");
        return -1;
    }

    // Process directories
    DIR *dir = opendir(directory);
    if (!dir) {
        logging_error("Failed to open directory %s", directory);
        return -1;
    }

    struct dirent *entry;
    long total_size = 0;

    while ((entry = readdir(dir))) {
        char path[MAX_PATH];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        if (recursive && opendir(path)) {
            // Recursively process subdirectories
            DIR *subdir = opendir(path);
            if (!subdir) {
                logging_error("Failed to open subdirectory %s", path);
                continue;
            }

            while ((entry = readdir(subdir))) {
                char subpath[MAX_PATH];
                snprintf(subpath, sizeof(subpath), "%s/%s", path, entry->d_name);

                // Process files in the subdirectory
                if (is_regular_file(subpath)) {
                    FILE *file = fopen(subpath, "r");
                    if (!file) {
                        logging_error("Failed to open file %s", subpath);
                        continue;
                    }

                    int size = 0;
                    char buffer[1024];

                    while (fgets(buffer, sizeof(buffer), file)) {
                        size += strlen(buffer);
                    }

                    total_size += size;

                    fclose(file);
                }
            }

            closedir(subdir);
        } else if (is_regular_file(path)) {
            // Process files in the directory
            FILE *file = fopen(path, "r");
            if (!file) {
                logging_error("Failed to open file %s", path);
                continue;
            }

            int size = 0;
            char buffer[1024];

            while (fgets(buffer, sizeof(buffer), file)) {
                size += strlen(buffer);
            }

            total_size += size;

            fclose(file);
        }
    }

    closedir(dir);

    // Print average file size
    printf("Average file size: %ld bytes\n", total_size / 1024);

    return 0;
}

bool is_regular_file(const char *path) {
    struct stat statbuf;
    if (stat(path, &statbuf) != 0) {
        return false;
    }

    return S_ISREG(statbuf.st_mode);
}
