        printf("Memory allocation failed.\n");
        exit(-1);
    }
    *size_ptr = 0;
    while (1) {
        int num;
        scanf("%d", &num);
        if (feof(stdin))
            break;
        if (*size_ptr >= MAX_SIZE) {
            printf("Input exceeded maximum size.\n");
            free(*array_ptr);
            exit(-1);
        }
        (*array_ptr)[*size_ptr] = num;
        (*size_ptr)++;
    }
}

