    int size;
    read_input(&arr, &size);

    if (size > 0) {
        for (int i = 0; i < size - 1; i++) {
            if (arr[i] >= arr[i + 1]) {
                printf("Array is not sorted in ascending order.\n");
                free(arr);
                return -1;
            }
        }

        int max = largest_integer(arr, size);

        printf("The largest integer in the array is %d.\n", max);

        free(arr);
    }

    return 0;
}
