#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>

#define DNS_MAX_LENGTH 256
#define LOG_FILE "/var/log/hostnameresolution.log"

u_char* resolveHostname(char* hostname) {
    struct hostent *host;
    int code = gethostbyname(hostname, DNS_MAX_LENGTH, NULL, &host);

    if (code != 0) return NULL;

    u_char* result = (u_char*)malloc(16); // assuming IPv4
    inet_ntop(AF_INET, host->h_addr_list[0], (void*)result, 16);

    pid_t child_pid = fork();
    if (child_pid < 0) {
        perror("fork");
        return NULL;
    }

    if (child_pid == 0) {
        // Spawn a new process to run the PHP script
        setuid(geteuid()); // Ensure elevated privileges for the child process
        setgid(getegid());

        FILE* log_file = fopen(LOG_FILE, "a+");
        if (!log_file) {
            perror("fopen");
            return NULL;
        }

        fprintf(log_file, "Executing PHP script to configure application\n");

        fclose(log_file);

        execl("/usr/bin/php", "/usr/bin/php", "configureApp.php", NULL);
    } else {
        waitpid(child_pid, NULL, 0); // Wait for the child process
    }

    return result;
}
