void add_sib10_message(int cell_id, int tdd_ul_dl_config_index, int subframe_offsets[4]) {
    // Allocate memory for new SIB10 message
    LTE_EUTRA_SIB10_T* new_message = (LTE_EUTRA_SIB10_T*)malloc(sizeof(LTE_EUTRA_SIB10_T));
    if (!new_message) return;  // Handle memory allocation failure

    // Initialize new message with input parameters
    new_message->cell_id = cell_id;
    new_message->tdd_ul_dl_config_index = tdd_ul_dl_config_index;
    memcpy(new_message->subframe_offsets, subframe_offsets, sizeof(int) * 4);

    // Add new message to dynamic array
    if (num_sib10_messages == 0 || sib10_messages[num_sib10_messages - 1] != NULL) {
        LTE_EUTRA_SIB10_T** new_array = (LTE_EUTRA_SIB10_T**)realloc(sib10_messages, sizeof(LTE_EUTRA_SIB10_T*) * (num_sib10_messages + 1));
        if (!new_array) return;  // Handle memory reallocation failure
        sib10_messages = new_array;
    }
    sib10_messages[num_sib10_messages++] = new_message;
}

void update_sib10_message(int cell_id, int tdd_ul_dl_config_index, int subframe_offsets[4]) {
    for (int i = 0; i < num_sib10_messages; i++) {
