                if not chunk:
                    break
                chunks.append(chunk)

            for i, chunk in enumerate(chunks):
                chunk_hash = hashlib.md5(chunk).hexdigest()
                if chunk_hash != self.config['checksum']:
                    logging.error(f"Chunk {i} has invalid checksum")
                    return None

            lines = [line.decode('utf-8') for line in chunks]
            sequence_numbers = []
            for line in lines:
                match = re.match(r'seq=(\d+)', line)
                if match:
                    sequence_numbers.append(int(match.group(1)))

            return {'sequence_numbers': sequence_numbers, 'data': [line for line in lines]}

