NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu_array(int *n, int **memory_failure_count) {
    if (*n == 0) return NULL;

    // Create a new array with the requested size
    int* temp = (int*)malloc(sizeof(int));
    *temp = 0;
    NFAPI_CRC_INDICATION_PDU_T** arr = (NFAPI_CRC_INDICATION_PDU_T**)malloc((1 + *n)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < *n; i++) {
        // Allocate memory for the structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (pdu == NULL) {
            (*memory_failure_count)++;
            continue;
        }

        // Initialize the structure with a valid RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG
        pdu->RX_UE_INFORMATION_TAG = 0x12345678;
        pdu->RNTI = rand() % (65536 - 1 + 1) + 1;  // Generate random RNTI within valid range (0 to 65535)
