typedef struct {
    int packet_id;
    unsigned long timestamp;
    int data_length;
} RX_PACKET_INFO;

typedef struct {
    RX_PACKET_INFO info;
    void* data;  // pointer to the actual packet data
    int used;     // indicates if the structure is in use or not
} NFIXP_RX_BUFFER_T;

void manage_packet_buffer(int N, NFIXP_RX_BUFFER_T** buffer, int* buffer_size) {
    int i;
    for (i = 0; i < *buffer_size; i++) {
        // Reuse existing structures if possible
        if (!buffer[i]->used) {
            // Validate packet_id and timestamp range
            if (buffer[i]->info.packet_id >= 1 && buffer[i]->info.packet_id <= 4096 &&
                buffer[i]->info.timestamp > 0) {
                // Update the reused structure's info
                buffer[i]->info = (RX_PACKET_INFO){N, buffer[i]->info.timestamp, 0};
                buffer[i]->used = 1;
                return;  // Reuse successful, exit function
            }
        }
    }

    // If no suitable structures are found, allocate new memory
    *buffer_size += N;
    *buffer = realloc(*buffer, (*buffer_size) * sizeof(NFIXP_RX_BUFFER_T));
    if (*buffer == NULL) {
        printf("Memory allocation failed.\n");
        return;  // Handle memory allocation failure
    }

    int j;
    for (j = *buffer_size - N; j < *buffer_size; j++) {
        buffer[j]->used = 0;  // Initialize new structures as unused
    }
}
