#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONCURRENT_RESOLUTIONS 10
#define MAX_TOTAL_DNS_QUERIES 50
#define TIMEOUT 5000 // in milliseconds

typedef struct {
    char* hostname;
    u_char ip[4];
} ResolutionTask;

void* resolve_dns(void* task) {
    ResolutionTask* task_ptr = (ResolutionTask*)task;
    struct sockaddr_in addr;
    getaddrinfo(task_ptr->hostname, NULL, AF_INET, &addr);
    inet_ntop(AF_INET, &addr.sin_addr, task_ptr->ip, sizeof(task_ptr->ip));
    freeaddrinfo(&addr);
    pthread_exit(NULL);
}

int perform_dns_resolution(char* hostname) {
    pthread_t thread;
    ResolutionTask task = {hostname, {(u_char)0}};
    if (pthread_create(&thread, NULL, resolve_dns, &task)) {
        return -1; // error creating thread
    }
    pthread_join(thread, NULL);
    if (!task.ip[0]) {
        return -2; // hostname not resolved
    }
    return 0;
}

int main() {
    for (int i = 0; i < 5; ++i) {
        int result = perform_dns_resolution("example.com");
        if (result == -1 || result == -2) {
            printf("Error: %d\n", result);
        } else {
            printf("Resolved IP address: ");
            for (int j = 0; j < 4; ++j) {
                printf("%x", task.ip[j]);
            }
            printf("\n");
        }
    }
    return 0;
}
