#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_POOL_SIZE 1000
#define MAX_CONNECTIONS 256

typedef struct {
    int conn_id;
    char src_ip[16];
    char dst_ip[16];
    int syn_flag;
    time_t timestamp;
    int seq_num;
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD* tcp_pool[MAX_POOL_SIZE];
int pool_size = 0;
int max_connections = MAX_CONNECTIONS;
int allocation_failure_count = 0;

void clear_tcp_pool() {
    for (int i = 0; i < pool_size; i++) {
        free(tcp_pool[i]);
    }
    pool_size = 0;
}

TCP_CONNECTION_RECORD* get_tcp_connection(int conn_id, char src_ip[16], char dst_ip[16], int syn_flag) {
    TCP_CONNECTION_RECORD* ret = NULL;

    if (pool_size > 0) {
        for (int i = 0; i < pool_size; i++) {
            if ((tcp_pool[i]->conn_id == -1) && (strncmp(src_ip, tcp_pool[i]->src_ip, 16) == 0) && (strncmp(dst_ip, tcp_pool[i]->dst_ip, 16) == 0)) {
                ret = tcp_pool[i];
                break;
            }
        }
    }

    if (ret == NULL) {
        ret = malloc(sizeof(TCP_CONNECTION_RECORD));
        if (ret != NULL) {
            strcpy(ret->src_ip, src_ip);
            strcpy(ret->dst_ip, dst_ip);
            ret->conn_id = conn_id;
            ret->syn_flag = syn_flag;
            time(&ret->timestamp);
            ret->seq_num = pool_size;
            pool_size++;
        }
    }

    if (ret == NULL) {
        allocation_failure_count++;
        printf("Memory allocation failed. Retrying...\n");
        sleep(1); // pause for a second before trying again
        return get_tcp_connection(conn_id, src_ip, dst_ip, syn_flag);
    }

    return ret;
}

int is_valid_ip(char ip[16]) {
    int i = 0;
    for (i = 0; i < 15; i++) {
        if ((ip[i] >= '0' && ip[i] <= '9') || (ip[i] >= 'a' && ip[i] <= 'f') || (ip[i] >= 'A' && ip[i] <= 'F')) {
            continue;
        }
        else if (ip[i] == '.') {
            i++;
            while ((i < 15) && (ip[i] != '.')) {
                i++;
            }
        }
        else {
            return 0;
        }
    }
    return 1;
}

int main() {
    // example usage
    TCP_CONNECTION_RECORD* conn = get_tcp_connection(123, "192.168.1.100", "10.0.0.1", 1);
    if (conn != NULL) {
        printf("Connection ID: %d\n", conn->conn_id);
        printf("Source IP: %s\n", conn->src_ip);
        printf("Destination IP: %s\n", conn->dst_ip);
        printf("SYN flag: %d\n", conn->syn_flag);
    }
    else {
        printf("Failed to allocate memory.\n");
    }

    clear_tcp_pool();

    return 0;
}
