        if (!pdu) {
            // Memory allocation failed, reduce batch size by 50%
            int new_size = size / 2;
            if (new_size > 0) {
                arr = realloc(arr, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                pdu = arr + (i % (size / 2));
            } else {
                // No more memory available
                return NULL;
            }
        } else {
            // Reuse existing structure if possible
            if (!arr) {
                arr = malloc(size);
                memset(arr, 0, size); // Zero out the memory
