    LTE_EUTRA_SIB10_T* sib10_message;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t rnti;
    RX_UE_INFORMATION_TAG rx_ue_info;
} RNTI_AND_RX_UE_INFORMATION_TAG;

struct octree_node {
    RNTI_AND_RX_UE_INFORMATION_TAG data;
    struct octree_node* left;
    struct octree_node* right;
};

struct octree {
    struct octree_node* root;
    uint32_t seed;
    uint32_t crcflag;
};

void init_octree(struct octree* octree, int max_depth) {
    // Initialize octree node allocation
    octree->root = NULL;
    octree->seed = time(NULL);
    octree->crcflag = 0;
}

void add_sib10_message_to_octree(struct octree* octree, LTE_EUTRA_SIB10_T* sib10_message) {
    // Create a new octree node and add the SIB10 message
    struct octree_node* node = (struct octree_node*)malloc(sizeof(struct octree_node));
    node->data.rnti = sib10_message->rnti;
    node->data.rx_ue_info.cell_id = sib10_message->cell_id;
    node->data.sib10_message = sib10_message;

    // Insert the node into the octree
    insert_octree_node(octree, node, max_depth);
}

void update_sib10_message_in_octree(struct octree* octree, LTE_EUTRA_SIB10_T* new_sib10_message) {
    // Find the corresponding node in the octree and update its SIB10 message
    struct octree_node* node = find_octree_node(octree, new_sib10_message->rnti);
    if (node != NULL) {
        node->data.sib10_message = new_sib10_message;
    }
}

void retrieve_sib10_message_from_octree(struct octree* octree, uint32_t rnti, LTE_EUTRA_SIB10_T** sib10_message) {
    // Find the corresponding node in the octree and return its SIB10 message
    struct octree_node* node = find_octree_node(octree, rnti);
    if (node != NULL) {
        *sib10_message = node->data.sib10_message;
    }
}

void free_sib10_messages_in_octree(struct octree* octree) {
    // Free the SIB10 messages in the octree
    free_octree_nodes(octree, octree->root);
}
