        return;
    }

    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        total_lines++;
        // Process the line
        printf("%s", line);
    }

    fclose(fp);

    printf("Total lines: %d\n", total_lines);
}

int main(int argc, char **argv) {
