        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int N) {
    // Check if the input size is valid
    if (N <= 0) {
        return NULL;
    }

    // Set a fallback strategy to reduce the size by 50% if an allocation fails
    int fallback_N = N / 2;

    // Initialize memory pointers and sequence numbers for each window
    NFAPI_CRC_INDICATION_PDU_T* memory = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory) {
        printf("Memory allocation failed: %s\n", strerror(errno));

        // Fallback strategy to reduce the size by 50%
        N -= fallback_N;
        memory = (NFAPI_CRC_INDICATION_PDU_T*)realloc(memory, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Validate each structure and set valid CRCFLAG
    for (int i = 0; i < N; i++) {
        memory[i].RX_UE_INFORMATION_TAG = rand() % RAND_MAX;
        memory[i].RNTI = rand() % RAND_MAX;

        // Ensure RNTI is within a valid range
        while (memory[i].RNTI > RAND_MAX) {
            memory[i].RNTI = rand() % RAND_MAX;
        }

        time_t timestamp = time(NULL);
        memory[i].CRC_INDICATION_REL8_TAG.timestamp = (int)(timestamp * 1000); // accurate to millisecond level
        memory[i].CRC_INDICATION_REL8_TAG.sequence_number = i % 1024; // unique within a sliding window of 1024 indications
        memory[i].CRC_INDICATION_REL8_TAG.error_code = rand() % RAND_MAX;
        memory[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % RAND_MAX;
    }

    return memory;
}

int main() {
    int N = 10; // Set the input size for demonstration purposes
    NFAPI_CRC_INDICATION_PDU_T* memory = allocate_memory(N);

    if (memory) {
        printf("Memory allocation successful.\n");

        // Example usage of the allocated memory
        for (int i = 0; i < N; i++) {
            printf("Structure %d: RX_UE_INFORMATION_TAG = %d, RNTI = %d, timestamp = %ld, sequence_number = %d, error_code = %d, CRCFLAG = %d\n",
                   i, memory[i].RX_UE_INFORMATION_TAG, memory[i].RNTI, (long int)memory[i].CRC_INDICATION_REL8_TAG.timestamp,
                   memory[i].CRC_INDICATION_REL8_TAG.sequence_number, memory[i].CRC_INDICATION_REL8_TAG.error_code, memory[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }

        // Handle memory deallocation
        free(memory);
    }

    return 0;
}
