    if (priv_key_file == NULL || cert_file == NULL) {
        printf("Error opening private key or certificate file\n");
        exit(1);
    }

    // Read private key and certificate
    char priv_key_data[1024];
    fread(priv_key_data, 1, 1023, priv_key_file);  // Assume this function is implemented to read the private key
    char cert_data[1024];
    fread(cert_data, 1, 1023, cert_file);  // Assume this function is implemented to read the certificate

    // Combine private key and certificate into PEM file
    FILE* pem_file = fopen("output.pem", "wb");
    fwrite("-----BEGIN PRIVATE KEY-----\n", 1, 24, pem_file);
    fwrite(priv_key_data, 1, strlen(priv_key_data), pem_file);
    fwrite("\n-----END PRIVATE KEY-----\n", 1, 20, pem_file);
    fwrite("-----BEGIN CERTIFICATE-----\n", 1, 22, pem_file);
    fwrite(cert_data, 1, strlen(cert_data), pem_file);
    fwrite("\n-----END CERTIFICATE-----\n", 1, 21, pem_file);

    // Close files
    fclose(priv_key_file);
    fclose(cert_file);
    fclose(pem_file);
}

