#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char destinationAddress[17]; // 16 bytes for MAC address and 1 byte for null terminator
    char sourceAddress[17];
    int payloadLength;
    long timestamp;
    unsigned int checksum; // calculate checksum based on payload and packet header fields
} PACKET_HEADER;

PACKET_HEADER* allocatePackets(int M) {
    if (M <= 0) return NULL; // invalid input size

    PACKET_HEADER* packets = (PACKET_HEADER*)malloc(M * sizeof(PACKET_HEADER));
    if (!packets) return NULL; // memory allocation failed

    for (int i = 0; i < M; i++) {
        // Initialize fields
        sprintf(packets[i].destinationAddress, "00:00:00:00:00:00");
        sprintf(packets[i].sourceAddress, "00:00:00:00:00:00");
        packets[i].payloadLength = 0;
        packets[i].timestamp = time(NULL); // set timestamp to current time
        packets[i].checksum = 0; // initialize checksum for the packet header and payload

        // Perform additional checks or calculations as needed
    }

    return packets;
}

void freePackets(PACKET_HEADER* packets, int M) {
    if (!packets || M <= 0) return; // check for valid input

    free(packets);
}
