// Function to manage a dynamic array of LTE_EUTRA_SIB10_T structures
Sib10Array* sib10_array_init(size_t initial_capacity) {
    Sib10Array* array = (Sib10Array*)malloc(sizeof(Sib10Array));
    array->messages = (LTE_EUTRA_SIB10_T*)calloc(initial_capacity, sizeof(LTE_EUTRA_SIB10_T));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

// Function to add a new message to the dynamic array
int sib10_array_add(Sib10Array* array, LTE_EUTRA_SIB10_T* message) {
    if (array->size >= array->capacity) {
        // Reallocate memory with double the capacity
        array->messages = (LTE_EUTRA_SIB10_T*)realloc(array->messages, 2 * array->capacity * sizeof(LTE_EUTRA_SIB10_T));
        array->capacity *= 2;
    }
    array->messages[array->size++] = *message;
    return 0;
}

// Function to update an existing message in the dynamic array
int sib10_array_update(Sib10Array* array, int cell_id, LTE_EUTRA_SIB10_T* updated_message) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i].cell_id == cell_id) {
            // Update the existing message
            memcpy(&array->messages[i], updated_message, sizeof(LTE_EUTRA_SIB10_T));
            return 0;
        }
    }
    return -1; // Message not found
}

// Function to retrieve a message based on its cell ID
LTE_EUTRA_SIB10_T* sib10_array_get(Sib10Array* array, int cell_id) {
    for (int i = 0; i < array->size; i++) {
        if (array->messages[i].cell_id == cell_id) {
            return &array->messages[i];
        }
    }
    return NULL; // Message not found
}

// Function to free the dynamic array and its contents
void sib10_array_free(Sib10Array* array) {
    if (array != NULL) {
        free(array->messages);
        free(array);
    }
}
