#define MAX_FILE_SIZE 10000
#define BUFFER_SIZE 1024

typedef struct {
    int32_t *data;
    size_t len;
} list_t;

list_t read_list(int sockfd) {
    list_t result = {NULL, 0};
    int32_t buffer[BUFFER_SIZE];
    size_t len = 0;

    while (1) {
        int bytes_received = recv(sockfd, buffer, sizeof(buffer), 0);
        if (bytes_received == -1) {
            perror("recv");
            break;
        }
        else if (bytes_received == 0) {
            break; // connection closed
        }

        for (int i = 0; i < bytes_received / sizeof(int32_t); i++) {
            result.data = realloc(result.data, (result.len + 1) * sizeof(int32_t));
            result.data[result.len++] = buffer[i];
        }
    }

    return result;
}

void print_list(list_t list) {
    for (size_t i = 0; i < list.len; i++) {
        printf("%d", list.data[i]);
        if (i < list.len - 1)
            printf(",");
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in addr = { .sin_family = AF_INET };
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    connect(sockfd, (struct sockaddr *)&addr, sizeof(addr));

    list_t list = read_list(sockfd);
    free(list.data);

    close(sockfd);
    return 0;
}

