} NFAPI_CRC_INDICATION_PDU_T;

void init_ue_rxindications(LTE_UE_RXINDICATIONS **ue_rxindications, int *n_ue_rxindications) {
    *ue_rxindications = (LTE_UE_RXINDICATIONS *)malloc(sizeof(LTE_UE_RXINDICATIONS));
    if (*ue_rxindications == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    *n_ue_rxindications = 1;
}

void add_ue_rxindication(LTE_UE_RXINDICATIONS **ue_rxindications, int *n_ue_rxindications, int max_size) {
    if (*n_ue_rxindications >= max_size) {
        printf("Maximum size reached. Cannot add more UE RX indications.\n");
        return;
    }

    (*ue_rxindications) = (LTE_UE_RXINDICATIONS *)realloc(*ue_rxindications, (*n_ue_rxindications + 1) * sizeof(LTE_UE_RXINDICATIONS));
    if (*ue_rxindications == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    (*n_ue_rxindications)++;
}

void filter_duplicates(LTE_UE_RXINDICATIONS **ue_rxindications, int *n_ue_rxindications) {
    for (int i = 0; i < *n_ue_rxindications - 1; i++) {
        for (int j = i + 1; j < *n_ue_rxindications; j++) {
            if (ue_rxindications[i]->rnti == ue_rxindications[j]->rnti) {
                free(ue_rxindications[j]);
                (*n_ue_rxindications)--;
                break;
            }
        }
    }
}

void validate_crc(LTE_UE_RXINDICATIONS **ue_rxindications, int *n_ue_rxindications) {
    FILE *file = fopen("validation_errors.log", "w");
    if (file == NULL) {
        printf("Error opening file for logging.\n");
        return;
    }

    for (int i = 0; i < *n_ue_rxindications; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_info = ue_rxindications[i]->rx_info;
        pdu.rnti = ue_rxindications[i]->rnti;
        pdu.pdu.crc_tag = ue_rxindications[i]->crc_tag;

        if (!validate_crc_signal_processing_library(&pdu)) {
            fprintf(file, "Error validating CRC for RNTI %d.\n", pdu.rnti);
        }
    }

    fclose(file);
}

void free_ue_rxindications(LTE_UE_RXINDICATIONS **ue_rxindications, int *n_ue_rxindications) {
    for (int i = 0; i < *n_ue_rxindications; i++) {
        free(ue_rxindications[i]);
    }

    free(*ue_rxindications);
    (*n_ue_rxindications) = 0;
}
