int find_max(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void print_largest(int** arr, int size) {
    printf("The largest integer in the array is: %d\n", find_max(*arr, size));
}

int read_input(int** arr, int* size) {
    int chunk_size = 1000;
    *size = 0;

    FILE* fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error opening file.\n");
        return -1;
    }

    while (!feof(fp)) {
        int read_size = fread(*arr + (*size), sizeof(int), chunk_size, fp);
        *size += read_size;

        if (*size > 50000) {
            printf("Input exceeds maximum size. Exiting.\n");
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);

    return 0;
}

int main() {
    int* arr = NULL;
    int size = 0;

    read_input(&arr, &size);

    if (size > 0) {
        for (int i = 0; i < size - 1; i++) {
            if (arr[i] >= arr[i + 1]) {
                printf("Error: Input array is not sorted in ascending order.\n");
                free(arr);
                return -1;
            }
        }

        print_largest(&arr, size);
        free(arr);
    } else {
        printf("No input read. Exiting.\n");
    }

    return 0;
}
