typedef struct {
    int cell_id;
    LTE_EUTRA_SIB10_T* message;
    int version;
} Sib10Entry;

typedef struct {
    int size;
    Sib10Entry** entries;
    pthread_mutex_t lock;
} Sib10Array;

Sib10Array* sib10_array_create() {
    Sib10Array* array = (Sib10Array*) malloc(sizeof(Sib10Array));
    array->size = 0;
    array->entries = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void sib10_array_free(Sib10Array* array) {
    for (int i = 0; i < array->size; i++) {
        free(array->entries[i]->message);
    }
    free(array->entries);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

Sib10Entry* sib10_entry_create(int cell_id, LTE_EUTRA_SIB10_T* message) {
    Sib10Entry* entry = (Sib10Entry*) malloc(sizeof(Sib10Entry));
    entry->cell_id = cell_id;
    entry->message = message;
    entry->version = 0;
    return entry;
}

void sib10_array_add_entry(Sib10Array* array, Sib10Entry* entry) {
    pthread_mutex_lock(&array->lock);
    if (array->size == 0 || array->entries[array->size - 1]->cell_id != entry->cell_id) {
        array->entries = realloc(array->entries, sizeof(Sib10Entry*) * (array->size + 2));
        array->entries[array->size] = entry;
        array->size++;
    } else {
        array->entries[array->size - 1] = entry;
    }
    pthread_mutex_unlock(&array->lock);
}

Sib10Entry* sib10_array_get_entry(Sib10Array* array, int cell_id) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        if (array->entries[i]->cell_id == cell_id) {
            Sib10Entry* entry = array->entries[i];
            pthread_mutex_unlock(&array->lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void sib10_array_update_entry(Sib10Array* array, int cell_id, LTE_EUTRA_SIB10_T* new_message) {
    Sib10Entry* entry = sib10_array_get_entry(array, cell_id);
    if (entry != NULL) {
        entry->message = new_message;
        entry->version++;
    }
}

void sib10_array_remove_entry(Sib10Array* array, int cell_id) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        if (array->entries[i]->cell_id == cell_id) {
            Sib10Entry* entry = array->entries[i];
            memmove(&array->entries[i], &array->entries[i + 1], sizeof(Sib10Entry*) * (array->size - i));
            array->size--;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

Sib10Array* sib10_array_resize(Sib10Array* array) {
    Sib10Array* new_array = sib10_array_create();
    for (int i = 0; i < array->size; i++) {
        Sib10Entry* entry = array->entries[i];
        Sib10Entry* new_entry = sib10_entry_create(entry->cell_id, entry->message);
        new_entry->version = entry->version;
        sib10_array_add_entry(new_array, new_entry);
    }
    sib10_array_free(array);
    return new_array;
}

int main() {
    Sib10Array* array = sib10_array_create();

    // Example usage
    LTE_EUTRA_SIB10_T* message1 = ...;  // Initialize a valid SIB10 message
    Sib10Entry* entry1 = sib10_entry_create(123, message1);
    sib10_array_add_entry(array, entry1);

    LTE_EUTRA_SIB10_T* message2 = ...;  // Initialize another valid SIB10 message
    Sib10Entry* entry2 = sib10_entry_create(456, message2);
    sib10_array_add_entry(array, entry2);

    // Retrieve and update a specific entry
    Sib10Entry* retrieved_entry = sib10_array_get_entry(array, 123);
    LTE_EUTRA_SIB10_T* new_message1 = ...;  // Update the message
    sib10_array_update_entry(array, 123, new_message1);

    // Remove an entry
    sib10_array_remove_entry(array, 456);

    // Monitor and dynamically resize the array as necessary

    return 0;
}
