#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int pdp_context_id;
    char *pdr_data;
    int version;
} LTE_EPC_SGW_PDR_T;

void *allocate_array(size_t size) {
    return malloc(size);
}

void deallocate_array(void *array, size_t size) {
    free(array);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
LTE_EPC_SGW_PDR_T **pdr_array;
size_t pdr_array_size;
int current_version;

void add_pdr(int pdp_context_id, char *pdr_data) {
    pthread_mutex_lock(&mutex);

    if (pdr_array == NULL || pdr_array_size == 0) {
        pdr_array = allocate_array(sizeof(LTE_EPC_SGW_PDR_T *) * 1);
        pdr_array[0] = malloc(sizeof(LTE_EPC_SGW_PDR_T));
        current_version = 0;
    } else if (pdp_context_id >= pdr_array_size) {
        size_t new_size = pdr_array_size + 2;
        LTE_EPC_SGW_PDR_T **new_array = allocate_array(sizeof(LTE_EPC_SGW_PDR_T *) * new_size);
        memcpy(new_array, pdr_array, sizeof(LTE_EPC_SGW_PDR_T *) * pdr_array_size);
        deallocate_array(pdr_array, sizeof(LTE_EPC_SGW_PDR_T *) * pdr_array_size);
        pdr_array = new_array;
    }

    LTE_EPC_SGW_PDR_T *pdr = pdr_array[pdp_context_id];
    if (pdr == NULL) {
        pdr = malloc(sizeof(LTE_EPC_SGW_PDR_T));
        pdr->pdp_context_id = pdp_context_id;
        pdr->pdr_data = strdup(pdr_data);
        pdr->version = current_version++;
        if (pdp_context_id >= pdr_array_size) {
            pdr_array_size = pdp_context_id + 1;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void update_pdr(int pdp_context_id, char *new_pdr_data) {
    pthread_mutex_lock(&mutex);

    LTE_EPC_SGW_PDR_T *pdr = pdr_array[pdp_context_id];
    if (pdr != NULL) {
        free(pdr->pdr_data);
        pdr->pdr_data = strdup(new_pdr_data);
        pdr->version++;
    }

    pthread_mutex_unlock(&mutex);
}

char *get_pdr(int pdp_context_id) {
    pthread_mutex_lock(&mutex);

    LTE_EPC_SGW_PDR_T *pdr = pdr_array[pdp_context_id];
    if (pdr != NULL) {
        char *data = strdup(pdr->pdr_data);
        pthread_mutex_unlock(&mutex);
        return data;
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

int main() {
    // Initialize array
    pdr_array_size = 0;

    // Example usage:
    add_pdr(1, "Initial PDR Data");
    update_pdr(1, "Updated PDR Data");
    char *data = get_pdr(1);
    printf("PDR Data: %s\n", data);
    free(data);

    return 0;
}
