void printLargestAndAverage() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    int* arr = NULL;
    for(int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);
        arr = (int*) realloc(arr, sizeof(int) * (i + 1));
        arr[i] = num;
    }

    if(n == 0) {
        printf("No integers provided.\n");
    } else {
        int max = arr[0];
        for(int i = 1; i < n; i++) {
            if(arr[i] > max)
                max = arr[i];
        }
        double avg = findAverage(arr, n);
        printf("Largest integer: %d\n", max);
        printf("Average: %.2f\n", avg);
    }

    free(arr);
}

int main() {
    printLargestAndAverage();
    return 0;
}
