int* allocate_crc_indication_pdu(int num_structures) {
    // Allocate memory for the structures
    void** pool = (void**)calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pool) {
        return NULL;
    }

    int i;
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pool + i;

        // Initialize the RX_UE_INFORMATION_TAG
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;

        // Set RNTI within the range of 0 to 65535
        pdu->RNTI = rand() % 65536;

        // Set CRCFLAG and initialize the timestamp and sequence number
        srand(time(NULL));
        int crcflag = rand() % 2;
        pdu->CRC_INDICATION_REL8_TAG[15] = time(NULL);
        pdu->CRC_INDICATION_REL8_TAG[14] = rand() % 65536;

        // Initialize the CRCFLAG
        pdu->CRC_INDICATION_REL8_TAG[crcflag] = 1;
    }

    return pool;
}

int* reuse_crc_indication_pdu(int num_structures) {
    int* pool = (int*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pool) {
        return NULL;
    }

    // Reuse the existing structures
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pool;

        // Initialize the RX_UE_INFORMATION_TAG
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;

