void process_integers() {
    int count = 0;
    int max_count = 10000; // limit of array size to prevent buffer overflow
    double sum = 0.0;
    int* integers = NULL;

    while (scanf("%d", &integers[count]) == 1 && count < max_count) {
        if (!integers) {
            integers = (int*)malloc((count + 2) * sizeof(int));
            integers[count] = 0; // sentinel value
        } else {
            integers = (int*)realloc(integers, (count + 2) * sizeof(int));
        }
        sum += integers[count++];
    }

    if (count > 0) {
        printf("Largest integer: %d\n", integers[0]);
        printf("Average of all integers: %.1f\n", sum / count);
    } else {
        printf("No integers provided.\n");
    }

    free(integers);
}
