namespace RoleManagement.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class RolesController : ControllerBase
    {
        private readonly RoleContext _roleContext;

        public RolesController(RoleContext roleContext)
        {
            _roleContext = roleContext;
        }

        // Update Role
        [HttpPut]
        public IActionResult UpdateRole(int roleId, [FromBody] RoleUpdateRequest request)
        {
            var role = _roleContext.Roles.Find(roleId);
            if (role == null) return NotFound();

            // Check for valid permissions and user associations
            // ...

            role.Permissions = request.Permissions;
            role.Users = request.Users;
            role.IsActive = true;

            _roleContext.SaveChanges();
            return Ok(new RoleResponse { Id = roleId, Permissions = request.Permissions, Users = request.Users, IsActive = true });
        }

        // Delete Role
        [HttpDelete]
        public IActionResult DeleteRole(int roleId)
        {
            var role = _roleContext.Roles.Find(roleId);
            if (role == null) return NotFound();

            // Check for active users assigned to the role
            // ...

            if (!role.IsActive) return Ok(new RoleResponse { Id = roleId, Status = "Deleted" });

            // Transfer roles or prompt a warning message
            // ...

            _roleContext.Roles.Remove(role);
            _roleContext.SaveChanges();
            return Ok(new RoleResponse { Id = roleId, Status = "Deleted" });
        }

        // Retrieve Role Details
        [HttpGet("{roleId}")]
        public IActionResult GetRoleDetails(int roleId)
        {
            var role = _roleContext.Roles.Find(roleId);
            if (role == null) return NotFound();

            return Ok(new RoleResponse { Id = roleId, Permissions = role.Permissions, Users = role.Users, IsActive = role.IsActive });
        }

        // Feature Expansion: Role Versioning
        [HttpPost("versions")]
        public IActionResult CreateRoleVersion(int roleId)
        {
            var role = _roleContext.Roles.Find(roleId);
            if (role == null) return NotFound();

            var version = new RoleVersion { RoleId = roleId, Timestamp = DateTime.UtcNow, Version = 1 };
            _roleContext.RoleVersions.Add(version);

            _roleContext.SaveChanges();
            return Ok(new RoleResponse { Id = roleId, Version = version.Version });
        }

        // Concurrency Handling: Optimistic Locking
        private int? GetOptimisticLockValue(int roleId)
        {
            var role = _roleContext.Roles.Find(roleId);
            if (role == null) return null;

            return role.OptimisticLockValue;
        }
    }

    public class RoleUpdateRequest
    {
        public List<string> Permissions { get; set; }
        public List<int> Users { get; set; }
    }

    public class RoleResponse
    {
        public int Id { get; set; }
        public List<string> Permissions { get; set; }
        public List<int> Users { get; set; }
        public bool IsActive { get; set; }
        public int? Version { get; set; }
        public string Status { get; set; }
    }

    public class RoleContext : DbContext
    {
        public DbSet<Role> Roles { get; set; }
        public DbSet<RoleVersion> RoleVersions { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            optionsBuilder.UseSqlServer("Data Source=<your_database>;Initial Catalog=<your_catalog>;User ID=<your_username>;Password=<your_password>;MultipleActiveResultSets=True;");
        }
    }

    public class Role
    {
        public int Id { get; set; }
        public List<string> Permissions { get; set; }
        public List<int> Users { get; set; }
        public bool IsActive { get; set; }
        public int? OptimisticLockValue { get; set; }
    }

    public class RoleVersion
    {
        public int Id { get; set; }
        public int RoleId { get; set; }
        public DateTime Timestamp { get; set; }
        public int Version { get; set; }
    }
}
