#include <jansson/jansson.h>

typedef struct {
    int id;
    double amount;
    time_t timestamp;
    char status[10];
} Transaction;

Transaction* process_transactions() {
    json_object *json, *trans;
    int count = 0, success_count = 0, total_amount = 0;
    Transaction* transactions = NULL;

    while (1) {
        json = json_object_from_file_pointer(stdin);
        if (!json)
            break;

        trans = json_object_object_get(json, "transactions");
        if (!trans || !json_object_is_type(trans, json_type_array))
            continue;

        for (int i = 0; i < json_object_array_length(trans); i++) {
            Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
            json_object *transaction_json = json_object_array_get_idx(trans, i);
            if (!transaction_json)
                continue;

            transaction->id = json_object_get_int(transaction_json, "id");
            transaction->amount = json_object_get_double(transaction_json, "amount");
            transaction->timestamp = json_object_get_int(transaction_json, "timestamp");
            strcpy(transaction->status, json_object_get_string(transaction_json, "status"));

            if (strcmp(transaction->status, "success") == 0) {
                success_count++;
                total_amount += transaction->amount;
            }

            transactions = realloc(transactions, sizeof(Transaction) * ++count);
            transactions[count - 1] = *transaction;
        }
    }

    free(json);

    return transactions;
}

int main() {
    Transaction* transactions = process_transactions();

    if (!transactions || count > 100000) {
        fprintf(stderr, "Error: Maximum transaction limit exceeded.\n");
        exit(1);
    }

    qsort(transactions, count, sizeof(Transaction), (int(*)(const void*, const void*))strcmp);

    printf("Total amount for successful transactions: %f\n", total_amount);

    free(transactions);

    return 0;
}
