int nfaapi_crc_indication_pdu_t_pool_alloc_count = 0;

void* allocation_mode(int N) {
    if (nfaapi_crc_indication_pdu_t_pool == NULL || nfaapi_crc_indication_pdu_t_pool_size < N) {
        int i, j;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_pool == NULL) {
            nfaapi_crc_indication_pdu_t_pool_alloc_count++;
