        return ret_val;
    } else {
        for(j = 0; j < 16; j++) {
            sprintf(&nfaapi_crc_indication_pdu_t_pool[i].CRC_INDICATION_REL8_TAG[j], "%02x", rand() % RAND_MAX % 256);
        }

        return &nfaapi_crc_indication_pdu_t_pool[i];
    }
}

