            transaction->id = json_object_get_int(json_object_array_iterate(root));
            transaction->amount = json_object_get_double(json_object_object_get(root, "amount"));
            transaction->timestamp = json_object_get_long(json_object_object_get(root, "timestamp"));
            strcpy(transaction->status, json_object_get_string(json_object_object_get(root, "status")));

            transactions[total_transactions] = transaction;
            current_transactions++;
        }

        if (current_transactions > max_transactions) {
            fprintf(stderr, "Maximum number of transactions exceeded. Exiting...\n");
            free_transactions(transactions, total_transactions);
            return -1;
        }

        total_transactions += current_transactions;

        free_json_object(root);

        // Reset for the next dataset
        root = NULL;
    }

    free(line);
    free_json_object_array(root);
    free_transactions(transactions, total_transactions);
}

void free_transactions(Transaction **transactions, int total_transactions) {
    for (int i = 0; i < total_transactions; i++) {
        if (transactions[i]) {
            free(transactions[i]);
        }
    }

    free(transactions);
}
