#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_REUSE 10
#define MIN_RNTI 0x0001
#define MAX_RNTI 0xFFFF

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(int N) {
    if (N <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int reused = 0;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;

        if (reused > MAX_REUSE) {
            free(array);
            array = NULL;
            reused = 0;
        }

        if (array == NULL || reused >= i) {
            pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            reused++;
        } else {
            pdu = &array[i - reused];
        }

        if (pdu == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rand() % ((MAX_RNTI - MIN_RNTI + 1));
        pdu->CRC_INDICATION_REL8_TAG = (int)time(NULL);
        pdu->CRCFLAG = rand() & 0x01;

        if (pdu->RNTI < MIN_RNTI || pdu->RNTI > MAX_RNTI) {
            free(pdu);
            return NULL;
        }
    }

    return array;
}

void deallocate_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N; i++) {
        if (array[i].CRCFLAG & 0x01) {
            free(&array[i]);
        }
    }

    free(array);
}
