void process_data(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }

    int size = 0;
    double* data = NULL;

    char buffer[1024];
    while (fscanf(file, "%lf", &buffer) == 1) {
        size++;
        if (!data) {
            data = (double*)malloc(size * sizeof(double));
        } else {
            data = (double*)realloc(data, size * sizeof(double));
        }
        *(data + (size - 1)) = atof(buffer);
    }

    fclose(file);

    if (size > 0) {
        int max_int = (int)data[0];
        int min_int = (int)data[0];
        double avg = find_average(data, size);

        for (int i = 1; i < size; i++) {
            if ((int)data[i] > max_int) max_int = (int)data[i];
            if ((int)data[i] < min_int) min_int = (int)data[i];
        }

        printf("Largest integer: %d\n", max_int);
        printf("Smallest integer: %d\n", min_int);
        printf("Average value: %.2lf\n", avg);

        free(data);
    }
}

