#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_POOL_SIZE 1000
#define LRU_CACHE_SIZE 10

typedef struct {
    RX_UE_INFORMATION_TAG;
    RNTI;
    CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct pool_entry {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    int size;
};

struct pool {
    struct pool_entry* entries;
    int count;
    pthread_mutex_t lock;
};

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n, struct pool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;

    if (pool->count > 0) {
        // Reuse an existing structure
        int i = rand() % pool->count;
        int idx = i % LRU_CACHE_SIZE;
        pdu = pool->entries[idx].structures;
        pool->entries[idx].size--;
        if (pool->entries[idx].size == 0) {
            pthread_mutex_lock(&pool->lock);
            for (int j = 0; j < LRU_CACHE_SIZE; j++) {
                if (j != idx && pool->entries[j].size == 0) {
                    pool->count--;
                    break;
                }
            }
            pthread_mutex_unlock(&pool->lock);
        }
    } else {
        // Allocate a new structure
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            return NULL;
        }
        pool->entries = realloc(pool->entries, (pool->count + 1) * sizeof(struct pool_entry));
        pool->entries[pool->count].structures = pdu;
        pool->entries[pool->count].size = 1;
        pool->count++;
    }

    if (pdu != NULL) {
        // Initialize the structure
        pdu->RX_UE_INFORMATION_TAG = malloc(sizeof(RX_UE_INFORMATION_TAG));
        pdu->RNTI = rand() % 256; // Randomly set RNTI within valid range
        pdu->CRC_INDICATION_REL8_TAG = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        pdu->CRC_INDICATION_REL8_TAG->timestamp = time(NULL);
        pdu->CRC_INDICATION_REL8_TAG->sequence_number = rand();
        pdu->CRCFLAG = (rand() % 2) ? CRCFLAG_VALID : CRCFLAG_INVALID;

        // Log allocation
        pthread_mutex_lock(&pool->lock);
        printf("Allocated %d bytes at %ld\n", sizeof(NFAPI_CRC_INDICATION_PDU_T), time(NULL));
        pthread_mutex_unlock(&pool->lock);

        return pdu;
    }

    return NULL;
}

void free_crc_indication_pdu(struct pool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        // Free the structure
        free(pdu->RX_UE_INFORMATION_TAG);
        free(pdu->CRC_INDICATION_REL8_TAG);

        int i;
        for (i = 0; i < pool->count; i++) {
            if (pool->entries[i].structures == pdu) {
                pool->entries[i].size--;
                break;
            }
        }

        // If the structure was reused, remove it from the pool
        if (pdu->RX_UE_INFORMATION_TAG == NULL && pdu->CRC_INDICATION_REL8_TAG == NULL && pdu->RNTI == 0) {
            pthread_mutex_lock(&pool->lock);
            for (i = 0; i < LRU_CACHE_SIZE; i++) {
                if (pool->entries[i].size == 0) {
                    pool->count--;
                    break;
                }
            }
            pthread_mutex_unlock(&pool->lock);
        }

        free(pdu);

        // Log deallocation
        pthread_mutex_lock(&pool->lock);
        printf("Deallocated %d bytes at %ld\n", sizeof(NFAPI_CRC_INDICATION_PDU_T), time(NULL));
        pthread_mutex_unlock(&pool->lock);
    }
}
