<?php
function handleUserRequest($request) {
    require_once 'Database.php';
    $db = new Database();

    if (!isset($request['sub_action'])) {
        $request['sub_action'] = 'create';
    }

    switch ($request['sub_action']) {
        case 'create':
            return createUser($request, $db);
        case 'update':
            return updateUser($request, $db);
        case 'delete':
            return deleteUser($request, $db);
        default:
            return json_encode(['status' => 'error', 'message' => 'Invalid sub_action']);
    }
}

function validateUserInput(array $input): array {
    $errors = [];

    if (!isset($input['name']) || empty($input['name'])) {
        $errors[] = 'Name is required';
    } elseif (strlen($input['name']) > 255) {
        $errors[] = 'Name must be under 256 characters';
    }

    if (!isset($input['email']) || empty($input['email'])) {
        $errors[] = 'Email is required';
    } elseif (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
        $errors[] = 'Invalid email format';
    }

    if (!isset($input['password']) || empty($input['password'])) {
        $errors[] = 'Password is required';
    } elseif (strlen($input['password']) < 8) {
        $errors[] = 'Password must be at least 8 characters long';
    } elseif (!preg_match('/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!%*#?&]{8,}$/i', $input['password'])) {
        $errors[] = 'Password must contain at least one uppercase letter, one lowercase letter, one digit and one special character';
    }

    return $errors;
}

function createUser(array $request, Database $db): array {
    $errors = validateUserInput($request);

    if (!empty($errors)) {
        return json_encode(['status' => 'error', 'message' => implode(', ', $errors)]);
    }

    $user_data = [
        'name' => $request['name'],
        'email' => $request['email'],
        'password' => password_hash($request['password'], PASSWORD_DEFAULT),
    ];

    if (!$db->insertUser($user_data)) {
        return json_encode(['status' => 'error', 'message' => 'Failed to create user']);
    }

    return json_encode(['status' => 'success', 'message' => 'User created successfully']);
}

function updateUser(array $request, Database $db): array {
    $errors = validateUserInput($request);

    if (!empty($errors)) {
        return json_encode(['status' => 'error', 'message' => implode(', ', $errors)]);
    }

    $user_data = [
        'name' => $request['name'],
        'email' => $request['email'],
    ];

    if (isset($request['password'])) {
        $user_data['password'] = password_hash($request['password'], PASSWORD_DEFAULT);
