#define MAX_TRANSACTIONS 100000
#define MAX_DATASETS 10

typedef struct {
    int id;
    double amount;
    long timestamp;
    char* status;
} Transaction;

Transaction* process_transactions() {
    json_object* json_obj = NULL;
    FILE* file = stdin;
    char buffer[1024];
    size_t len;
    int num_transactions = 0, dataset_num = 0;
    Transaction** transactions = NULL;
    double total_amount = 0.0;

    while ((len = fread(buffer, 1, 1024, file)) > 0) {
        json_obj = json_load_buffer(len, buffer);
        if (json_obj == NULL) {
            printf("Error parsing JSON\n");
            continue;
        }

        Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
        strcpy(transaction->status, json_object_get_string(json_obj, "status"));
        transaction->id = json_object_get_int(json_obj, "id");
        transaction->timestamp = json_object_get_int(json_obj, "timestamp");

        if (!json_object_get_boolean(json_obj, "success")) {
            free(transaction);
            continue;
        }

        transaction->amount = json_object_get_double(json_obj, "amount");

        transactions = (Transaction**)realloc(transactions, ++num_transactions * sizeof(Transaction*));
        transactions[num_transactions - 1] = transaction;

        if (num_transactions >= MAX_TRANSACTIONS) {
            printf("Exceeded maximum number of transactions per dataset\n");
            break;
        }

        json_object_free(json_obj);
    }

    // Process and sort transactions
    for (int i = 0; i < num_transactions; ++i) {
        int j;
        for (j = 1; j < num_transactions; ++j) {
            if (transactions[j - 1]->timestamp > transactions[j]->timestamp) {
                Transaction* temp = transactions[j];
                transactions[j] = transactions[j - 1];
                transactions[j - 1] = temp;
            }
        }

        total_amount += transactions[i]->amount;

        // Print successful transactions
        for (j = 0; j < num_transactions && transactions[j]->status != NULL && strcmp(transactions[j]->status, "success") == 0; ++j) {
            printf("Transaction %d: id=%d, timestamp=%ld, amount=%.2f\n", j + 1, transactions[j]->id, transactions[j]->timestamp, transactions[j]->amount);
        }
    }

    // Calculate average transaction amount
    if (num_transactions > 0) {
        double avg_amount = total_amount / num_transactions;
        printf("Average transaction amount: %.2f\n", avg_amount);
    }

    for (int i = 0; i < num_transactions; ++i) {
        free(transactions[i]);
    }
    free(transactions);

    return NULL;
}

int main() {
    // Process transactions
    process_transactions();

    return 0;
}
