#include <arpa/inet.h>

int* initialize_array(int max_size);
void manage_array(int* array, int size);

int main(int argc, char** argv) {
    int max_size = 10000; // Default maximum size
    if (argc > 1) {
        max_size = atoi(argv[1]);
    }
    int* array = initialize_array(max_size);
    manage_array(array, 0); // Initialize and manage the array
    return 0;
}

int* initialize_array(int max_size) {
    int* array = (int*)malloc((max_size + 1)*sizeof(int));
    if (!array) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return array;
}

void manage_array(int* array, int size) {
    // Initialize the array
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    // Check if the array is sorted in ascending order
    for (int i = 1; i < size; i++) {
        if (array[i] < array[i-1]) {
            printf("Error: The input array is not sorted.\n");
            exit(1);
        }
    }

    int max_int = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max_int) {
            max_int = array[i];
        }
    }

    // Calculate the average of the integers
    double avg = 0.0;
    for (int i = 0; i < size; i++) {
        avg += array[i];
    }
    avg /= size;

    printf("The largest integer is %d.\n", max_int);
    printf("The average is %.2f.\n", avg);

    // Compress the resulting array into a binary format
    int compressed_size = sizeof(int) * (size + 1);
    char* compressed_array = (char*)malloc(compressed_size);
    if (!compressed_array) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        *(int*)(&compressed_array[i*sizeof(int)]) = array[i];
    }

    // Write the compressed data to a file
    FILE* file = fopen("output.bin", "wb");
    if (!file) {
        printf("Error writing to the file.\n");
        exit(1);
    }
    fwrite(compressed_array, compressed_size, 1, file);
    fclose(file);

    free(array);
    free(compressed_array);
}

