#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <time.h>

#define MAX_TRANSACTIONS 100000
#define MAX_DATASETS 10
#define JSON_BUFFER_SIZE 1024

typedef struct {
    int id;
    double amount;
    time_t timestamp;
    char status[20];
} Transaction;

void process_transactions() {
    json_object *json_obj = NULL;
    FILE *input_stream = stdin;
    int dataset_count = 0;
    Transaction *transactions = NULL;
    int transaction_count = 0;
    long total_amount = 0;
    time_t last_timestamp = 0;

    while (dataset_count < MAX_DATASETS && json_object_*json_read_file(input_stream, JSON_BUFFER_SIZE)) {
        transactions = realloc(transactions, (transaction_count + MAX_TRANSACTIONS) * sizeof(Transaction));
        if (!transactions) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        transaction_count = 0;

        while (json_object_get(json_obj, "transactions")) {
            json_object *txn_obj = json_object_object_get(json_object_get(json_obj, "transactions"), transaction_count++);
            Transaction *txn = &transactions[transaction_count - 1];

            if (!json_object_is_type(txn_obj, json_type_object)) {
                fprintf(stderr, "Invalid JSON object\n");
                break;
            }

            if (json_object_get_int_value(txn_obj, "id", &(txn->id)) < 0) {
                fprintf(stderr, "Failed to read id field\n");
                break;
            }

            if (!json_object_get_double_value(txn_obj, "amount", &(txn->amount))) {
                fprintf(stderr, "Failed to read amount field\n");
                break;
            }

            if (time(&txn->timestamp) == 0) {
                fprintf(stderr, "Failed to read timestamp field\n");
                break;
            }

            strcpy(txn->status, json_object_get_string_value(txn_obj, "status", NULL));

            if (strcmp(txn->status, "success") != 0) {
                continue;
            }

            total_amount += txn->amount;

            if (txn->timestamp > last_timestamp)
                last_timestamp = txn->timestamp;

        }

        free(json_obj);
        json_obj = NULL;

        printf("Total transaction amount: %f\n", total_amount);

    }
}

int main() {
    process_transactions();
    return 0;
}
