// Define the maximum number of transactions per dataset and total datasets
#define MAX_TRANSACTIONS 100000
#define TOTAL_DATASETS 10

typedef struct {
    int id;
    double amount;
    long timestamp;
    char status[20];
} Transaction;

void process_transactions() {
    json_object *json_obj = NULL;
    FILE *input_file = stdin;
    size_t transactions_count = 0;
    int datasets_count = 0;
    Transaction **transactions = NULL;
    Transaction *current_dataset = NULL;
    double total_amount = 0.0;
    double average_amount = 0.0;

    while ((json_obj = json_object_from_file(input_file)) && (datasets_count < TOTAL_DATASETS)) {
        if (json_obj == NULL || json_object_get_type(json_obj) != JSON_OBJECT) {
            fprintf(stderr, "Error: Invalid JSON object\n");
            continue;
        }

        // Process each transaction in the dataset
        current_dataset = realloc(current_dataset, sizeof(Transaction) * (MAX_TRANSACTIONS + 1));
        for (int i = 0; i < MAX_TRANSACTIONS && json_object_object_iter_next(json_obj, NULL); ) {
            Transaction transaction;

            if (json_object_object_iter(json_obj, "id") && json_object_get_type(json_object_object_iter_value(json_obj)) == JSON_INTEGER) {
                transaction.id = json_object_get_int_value(json_object_object_iter_value(json_obj));
            } else {
                fprintf(stderr, "Error: Invalid 'id' field in JSON object\n");
                break;
            }

            if (json_object_object_iter(json_obj, "amount") && json_object_get_type(json_object_object_iter_value(json_obj)) == JSON_REAL) {
                transaction.amount = json_object_get_double_value(json_object_object_iter_value(json_obj));
            } else {
                fprintf(stderr, "Error: Invalid 'amount' field in JSON object\n");
                break;
            }

            if (json_object_object_iter(json_obj, "timestamp") && json_object_get_type(json_object_object_iter_value(json_obj)) == JSON_INTEGER) {
                transaction.timestamp = json_object_get_int_value(json_object_object_iter_value(json_obj));
            } else {
                fprintf(stderr, "Error: Invalid 'timestamp' field in JSON object\n");
                break;
            }

            if (json_object_object_iter(json_obj, "status") && json_object_get_type(json_object_object_iter_value(json_obj)) == JSON_STRING) {
                strcpy(transaction.status, json_object_get_string_value(json_object_object_iter_value(json_obj)));
            } else {
                fprintf(stderr, "Error: Invalid 'status' field in JSON object\n");
                break;
            }

            // Validate and add the transaction to the dataset
            if (transaction.id > 0 && isfinite(transaction.amount) && transaction.timestamp >= 0) {
                current_dataset[transactions_count++] = transaction;

                // Check for status success
                if (!strcmp(transaction.status, "success")) {
                    total_amount += transaction.amount;
                }
            } else {
                break;
            }

            i++;
        }

        // Sort the transactions by timestamp in ascending order
        qsort(current_dataset, transactions_count, sizeof(Transaction), compare_transactions);

        // Calculate the total transaction amount for successful transactions
        for (int i = 0; i < transactions_count; i++) {
            if (!strcmp(current_dataset[i].status, "success")) {
                total_amount += current_dataset[i].amount;
            }
        }

        free(json_obj);
        json_obj = NULL;

        // Print the processed dataset
        printf("Dataset %d:\n", datasets_count + 1);
        for (int i = 0; i < transactions_count; i++) {
            printf("%d %f %ld '%s'\n", current_dataset[i].id, current_dataset[i].amount, current_dataset[i].timestamp, current_dataset[i].status);
        }
        printf("Total amount: %f\n", total_amount);

        // Reset the processing state
        free(current_dataset);
        current_dataset = NULL;
        transactions_count = 0;
        total_amount = 0.0;

        datasets_count++;
    }

    if (datasets_count > 0) {
        average_amount = total_amount / datasets_count;
        printf("Average transaction amount: %f\n", average_amount);
    } else {
        printf("No successful transactions found.\n");
    }
}

int main() {
    process_transactions();
    return 0;
}
