        new_pool[i].state = CONN_INIT;
        inet_pton(AF_INET, "0.0.0.0", new_pool[i].remote_ip);
        new_pool[i].remote_port = 0;
    }
    return new_pool;
}

TCP_CONNECTION_INFO_T *allocate_connection(int conn_id) {
    TCP_CONNECTION_INFO_T *conn_info = NULL;

    if (current_allocation_count >= max_allocations_per_session) {
