#include "lte_eutra_sib10_t.h"
#include <stdlib.h>
#include <string.h>

// Define a struct to represent the dynamic array of LTE_EUTRA_SIB10_T structures
typedef struct {
    LTE_EUTRA_SIB10_T* messages;
    size_t capacity;
    size_t count;
} SIB10_Array;

// Function to create a new SIB10 array with an initial capacity
SIB10_Array* sib10_array_create(size_t initial_capacity) {
    SIB10_Array* array = (SIB10_Array*)malloc(sizeof(SIB10_Array));
    array->messages = (LTE_EUTRA_SIB10_T*)calloc(initial_capacity, sizeof(LTE_EUTRA_SIB10_T));
    array->capacity = initial_capacity;
    array->count = 0;
    return array;
}

// Function to add a new message to the SIB10 array
void sib10_array_add(SIB10_Array* array, LTE_EUTRA_SIB10_T message) {
    if (array->count >= array->capacity) {
        // Reallocate memory with doubled capacity if the array is full
        array->messages = (LTE_EUTRA_SIB10_T*)realloc(array->messages, sizeof(LTE_EUTRA_SIB10_T) * array->capacity * 2);
        array->capacity *= 2;
    }
    array->messages[array->count++] = message;
}

// Function to update an existing message in the SIB10 array
void sib10_array_update(SIB10_Array* array, size_t cell_id, LTE_EUTRA_SIB10_T new_message) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->messages[i].cell_id == cell_id) {
            // Update the existing message
            memcpy(&array->messages[i], &new_message, sizeof(LTE_EUTRA_SIB10_T));
            return;
        }
    }
}

// Function to retrieve a message from the SIB10 array based on its cell ID
LTE_EUTRA_SIB10_T* sib10_array_get(SIB10_Array* array, size_t cell_id) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->messages[i].cell_id == cell_id) {
            return &array->messages[i];
        }
    }
    // Return NULL if the message is not found
    return NULL;
}

// Function to free the memory allocated for a SIB10 array
void sib10_array_free(SIB10_Array* array) {
    free(array->messages);
    free(array);
}
