#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function prototypes
int* readArray(int max_size);
void printLargest(int* arr, int size);
int* sortArray(int* arr, int size, char algo);
void quicksort(int* arr, int low, int high);
void mergesort(int* arr, int low, int high);

// Command-line interface
int main(int argc, char** argv) {
    if (argc < 3 || strcmp(argv[1], "-h") == 0) {
        printf("Usage: %s [-h] [-q|-m] [max_size]\n", argv[0]);
        return 0;
    }

    int max_size = atoi(argv[2]);

    // Read array from standard input
    int* arr = readArray(max_size);

    if (arr == NULL) {
        printf("Error: Input exceeded maximum size.\n");
        return 1;
    }

    // Check if array is sorted in ascending order
    if (!isSorted(arr, max_size)) {
        // Sort the array using the specified algorithm
        char algo = strcmp(argv[3], "-q") == 0 ? 'q' : 'm';
        arr = sortArray(arr, max_size, algo);
    }

    // Print the largest integer in the array
    printLargest(arr, max_size);

    // Free dynamically allocated memory
    free(arr);

    return 0;
}

// Read a list of integers from standard input and store them in a dynamically allocated array
int* readArray(int max_size) {
    int* arr = (int*)malloc(max_size * sizeof(int));

    if (arr == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < max_size; i++) {
        scanf("%d", &arr[i]);

        if (i >= max_size) {
            printf("Error: Input exceeded maximum size.\n");
            free(arr);
            return NULL;
        }
    }

    return arr;
}

// Print the largest integer in the array
void printLargest(int* arr, int size) {
    int max = arr[0];

    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    printf("Largest integer: %d\n", max);
}

// Sort the array in ascending order using the specified algorithm
int* sortArray(int* arr, int size, char algo) {
    switch (algo) {
        case 'q':
            return quicksort(arr, 0, size - 1);

        case 'm':
            return mergesort(arr, 0, size - 1);

        default:
            printf("Error: Invalid sorting algorithm.\n");
            return NULL;
    }
}

// Quicksort algorithm
void quicksort(int* arr, int low, int high) {
    if (low < high) {
        int pivot = partition(arr, low, high);
        quicksort(arr, low, pivot - 1);
        quicksort(arr, pivot + 1, high);
    }
}

// Partition function for quicksort
int partition(int* arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;

    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }

    swap(&arr[i + 1], &arr[high]);
    return i + 1;
}

// Swap two integers
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Mergesort algorithm
int* mergesort(int* arr, int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2;

        // Sort the left half
        int* left = sortArray(arr, mid - low + 1, 'm');
        arr = left;

        // Sort the right half
        left = sortArray(&arr[mid], high - mid, 'm');
        arr = left;

        // Merge the sorted halves
        merge(&arr[low], mid - low + 1, &arr[mid], high - mid);
    }

    return arr;
}

// Merge two sorted arrays
void merge(int* arr1, int size1, int* arr2, int size2) {
    int i = 0, j = 0;

    for (int k = 0; k < size1 + size2; k++) {
        if (i >= size1) {
            arr[k] = arr2[j++];
        } else if (j >= size2) {
            arr[k] = arr1[i++];
        } else if (arr1[i] <= arr2[j]) {
            arr[k] = arr1[i++];
        } else {
            arr[k] = arr2[j++];
        }
    }
}

// Check if the array is sorted in ascending order
int isSorted(int* arr, int size) {
    for (int i = 0; i < size - 1; i++) {
        if (arr[i] > arr[i + 1]) {
            return 0;
        }
    }

    return 1;
}
