            }

            current_pdu = &(*pdu_array)[i];
        }
    }

    // Deallocate unused structures
    for (int j = 0; j < i; j++) {
        if (!current_pdu) break;
        free(current_pdu);
        struct_deallocations++;
        current_pdu--;
    }

    // Print memory allocation failure count and structure deallocation count
    printf("Memory allocation failures: %d\n", mem_alloc_failures);
