        int lines = process_file(input_directory, config_entries, config_entry_count);
        total_lines = lines;
    }

    // generate summary report
    FILE *summary_report = fopen("summary.txt", "w");
    fprintf(summary_report, SUMMARY_REPORT_FORMAT_DEFAULT, input_directory, total_files, total_lines);
    fclose(summary_report);

    return 0;
}

