#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to hold LTE EUTRA SIB 10 message information
typedef struct LTE_EUTRA_SIB10_T {
    int cell_id;
    int tdd_ul_dl_config_index;
    int subframe_offsets[6];
} LTE_EUTRA_SIB10_T;

// Dynamic array structure to manage SIB10 messages
typedef struct {
    LTE_EUTRA_SIB10_T* messages;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} dynamic_array;

// Function to initialize a dynamic array with the given initial capacity
dynamic_array* init_dynamic_array(size_t initial_capacity) {
    dynamic_array* arr = (dynamic_array*)malloc(sizeof(dynamic_array));
    arr->messages = (LTE_EUTRA_SIB10_T*)calloc(initial_capacity, sizeof(LTE_EUTRA_SIB10_T));
    arr->capacity = initial_capacity;
    arr->used = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Function to add a new SIB10 message to the dynamic array
void add_message(dynamic_array* arr, LTE_EUTRA_SIB10_T* message) {
    pthread_mutex_lock(&arr->lock);

    if (arr->used == arr->capacity) {
        // Reallocate memory for the messages array with double capacity
        arr->messages = (LTE_EUTRA_SIB10_T*)realloc(arr->messages, 2 * sizeof(LTE_EUTRA_SIB10_T));
        arr->capacity *= 2;
    }

    arr->messages[arr->used++] = *message;

    pthread_mutex_unlock(&arr->lock);
}

// Function to update an existing SIB10 message in the dynamic array
void update_message(dynamic_array* arr, int cell_id, LTE_EUTRA_SIB10_T new_message) {
    pthread_mutex_lock(&arr->lock);

    for (int i = 0; i < arr->used; i++) {
        if (arr->messages[i].cell_id == cell_id) {
            *arr->messages + i = new_message;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to retrieve a SIB10 message from the dynamic array based on its cell ID
LTE_EUTRA_SIB10_T* get_message(dynamic_array* arr, int cell_id) {
    LTE_EUTRA_SIB10_T* result = NULL;

    pthread_mutex_lock(&arr->lock);

    for (int i = 0; i < arr->used; i++) {
        if (arr->messages[i].cell_id == cell_id) {
            result = &arr->messages[i];
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);

    return result;
}

// Function to free the dynamic array and its contents
void destroy_dynamic_array(dynamic_array* arr) {
    pthread_mutex_destroy(&arr->lock);
    for (int i = 0; i < arr->used; i++) {
        free(arr->messages + i);
    }
    free(arr->messages);
    free(arr);
}

// Example usage:
int main() {
    dynamic_array* arr = init_dynamic_array(10);

    LTE_EUTRA_SIB10_T message1 = {123, 4, {0, 1, 2, 3, 4, 5}};
    LTE_EUTRA_SIB10_T message2 = {456, 5, {6, 7, 8, 9, 10, 11}};

    add_message(arr, &message1);
    add_message(arr, &message2);

    LTE_EUTRA_SIB10_T* retrieved_message = get_message(arr, 123);
    if (retrieved_message) {
        printf("Retrieved message: cell_id = %d, tdd_ul_dl_config_index = %d, subframe_offsets = {%d, %d, ...}\n",
               retrieved_message->cell_id, retrieved_message->tdd_ul_dl_config_index,
               retrieved_message->subframe_offsets[0], retrieved_message->subframe_offsets[1]);
    }

    destroy_dynamic_array(arr);
    return 0;
}
