typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[2]; // timestamp and sequence number
} NFAPI_CRC_INDICATION_PDU_T;

void initAndPopulateNFAPCrcIndications(int N) {
    static int allocated = 0;
    static int used = 0;
    static int *structures = NULL;
    static int mode = 0; // 0: primary, 1: secondary

    if (N <= 0) return;

    if (!structures || used + N > allocated) {
        // allocate new memory
        structures = realloc(structures, (allocated += N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        mode = 0; // reset to primary mode
    }

    for (int i = 0; i < N; i++) {
        structures[used + i].RX_UE_INFORMATION_TAG = 1;
        structures[used + i].RNTI = rand() % 65536;
        structures[used + i].CRC_INDICATION_REL8_TAG[0] = time(NULL);
        structures[used + i].CRC_INDATION_REL8_TAG[1] = used;

        // compute MD5 hash
        unsigned char md5[16];
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, &structures[used + i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        MD5_Final(md5, &ctx);

        // log allocation and reuse
        if (mode) {
            printf("Reusing structure %d for UE %d\n", used + i, structures[used + i].RNTI);
        } else {
            printf("Allocating new structure for UE %d\n", structures[used + i].RNTI);
        }

        // increment usage count
        used++;
    }
}
