#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 10000
#define BUFFER_SIZE 1024

typedef struct {
    int* data;
    size_t size;
} dataset;

dataset* read_data(char* source, FILE* file) {
    dataset* ds = (dataset*)malloc(sizeof(dataset));
    ds->data = (int*)calloc(BUFFER_SIZE, sizeof(int));
    ds->size = fread(ds->data, sizeof(int), BUFFER_SIZE, file);
    while (ds->size < BUFFER_SIZE && !feof(file)) {
        ds->data += ds->size;
        ds->size = fread(ds->data, sizeof(int), BUFFER_SIZE - ds->size, file);
    }
    return ds;
}

void process_data(dataset* primary, dataset* secondary) {
    dataset* current = primary;
    int max_size = 0;

    while (current && current->size > 0) {
        size_t i;
        for (i = 0; i < current->size; ++i) {
            if (current->data[i] >= 0 && current->data[i] > MAX_SIZE) {
                printf("Error: Dataset exceeded maximum size.\n");
                exit(1);
            }
            if (current == primary) {
                secondary->data = realloc(secondary->data, (max_size + i + 1) * sizeof(int));
                memcpy(secondary->data + max_size, current->data, i * sizeof(int));
                secondary->size = max_size + i;
            } else if (i > 0 && primary->data[max_size] < primary->data[i - 1]) {
                printf("Error: Dataset is not sorted.\n");
                exit(1);
            }
        }
        current = current == primary ? secondary : primary;
    }

    void find_largest(dataset* ds) {
        int max_val = INT_MIN;
        size_t i;
        for (i = 0; i < ds->size; ++i) {
            if (ds->data[i] > max_val)
                max_val = ds->data[i];
        }
        printf("Largest integer: %d\n", max_val);
    }

    find_largest(secondary);

    free(primary->data);
    free(primary);
    free(secondary->data);
    free(secondary);
}

int main() {
    FILE* primary_file = fopen("primary_source.txt", "r");
    FILE* secondary_file = fopen("secondary_cache.txt", "r");

    dataset* primary = read_data("Primary Source", primary_file);
    dataset* secondary = read_data("Secondary Cache", secondary_file);

    process_data(primary, secondary);

    fclose(primary_file);
    fclose(secondary_file);

    return 0;
}
