    class NfarandGenerator {
    public:
        static NfarandGenerator& instance() {
            static NfarandGenerator inst;
            return inst;
        }

        std::list<NFAPI_CRC_INDICATION_PDU_T> generatePdus(int numUsers) {
            std::list<NFAPI_CRC_INDICATION_PDU_T> pdus;

            for (int i = 0; i < numUsers; i++) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                pdu.rx_ue_info.tag = RX_UE_INFORMATION_TAG();
                pdu.rnti = rand() % 10000000; // Randomly set RNTI
                pdu.crc_indication_rel8_tag.crcflag = static_cast<NFAPI_CRC_FLAG>(rand() & 0x1);

                pdus.push_back(pdu);
            }

            return pdus;
        }
    };

    NfarandGenerator::~NfarandGenerator() {}

} // namespace Nfarand

#include <dns.h>
#include <string.h>

char* resolveHostname(const char* hostname) {
    struct sockaddr_in addr;
    struct hostent* he;

    if ((he = gethostbyname(hostname)) == NULL)
        return "Error: DNS resolution failed";

    char* ipAddr = (char*)malloc(INET6_ADDRSTRLEN);
    inet_ntop(AF_INET, &he->h_addr, ipAddr, INET6_ADDRSTRLEN);

    return ipAddr;
}

#include <stdlib.h>
#include <stdio.h>

NFAPI_CRC_INDICATION_PDU_T* generatePdus(int numUsers) {
    NfarandGenerator& generator = Nfarand::NfarandGenerator::instance();
    std::list<NFAPI_CRC_INDICATION_PDU_T> pdus = generator.generatePdus(numUsers);

    NFAPI_CRC_INDICATION_PDU_T* pdusArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pdus.size() * sizeof(NFAPI_CRC_INDIFICATION_PDU_T));

    int i = 0;
    for (const auto& pdu : pdus) {
        pdusArray[i++] = pdu;
    }

    return pdusArray;
}

#include <cstdlib>
#include <ctime>

int main() {
    srand(time(0));
    // Use the generated pdus
    NFAPI_CRC_INDICATION_PDU_T* pdus = generatePdus(100);
    free(pdus);

    return 0;
}
