void process_text(char* text) {
    regex_t book_pattern[66];
    const char* book_names[] = {"Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth", "1Samuel", "2Samuel", "1Kings", "2Kings", "1Chronicles", "2Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "SongOfSolomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"};

    for (int i = 0; i < 66; i++) {
        sprintf(book_pattern[i], "(?i)%s", book_names[i]);
    }

    int count[66] = {0};
    regex_t** patterns = (regex_t**)malloc(66 * sizeof(regex_t));
    regex_t* temp;
    for (int j = 0; j < 66; j++) {
        temp = (regex_t*)malloc(sizeof(regex_t));
        regcomp(temp, book_pattern[j], REG_EXTENDED);
        patterns[j] = temp;
    }

    int match[66];
    regmatch_t match_data;

    for (int k = 0; k < 66; k++) {
        regmatch_t pmatch;
        if (regexec(patterns[k], text, (rsize_t)strlen(text), &pmatch, 0)) {
            continue;
        } else {
            for (int i = 0; i <= pmatch.rm_eo; i++) {
                char c = text[i];
                while (c == ' ' || c == '.' || c == ',' || c == '?' || c == '!') {
                    i++;
                    c = text[i];
                }
                if (c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z') {
                    int book_index = 0;
                    for (; book_index < 66; book_index++) {
                        if (regexec(patterns[book_index], &text[i], 1, NULL, 0) == 0) {
                            break;
                        }
                    }
                    if (book_index < 66) {
                        count[book_index]++;
                        i = pmatch.rm_eo;
                    } else {
                        i++;
                    }
                } else {
                    i++;
                }
            }
        }
    }

    free(patterns);

    printf("Book counts:\n");
    for (int j = 0; j < 66; j++) {
        if (count[j] > 0) {
            printf("%s: %d\n", book_names[j], count[j]);
        }
    }
}

int main() {
    // Function call
    return 0;
}
