import java.util.ArrayList;
import java.util.List;

public class Main {
    public static String getWeaknesses(Pokemon pokemon, int[] array) {
        long start = System.nanoTime();
        List<String> weaknesses = new ArrayList<>();

        switch (pokemon.getType()) {
            case "Fire":
                weaknesses.add("Water");
                weaknesses.add("Rock");
                break;
            case "Grass":
                weaknesses.add("Fire");
                weaknesses.add("Ice");
                break;
            // Add more types and their corresponding weaknesses
        }

        long end = System.nanoTime();
        long timeTaken = (end - start);
        System.out.println("Weaknesses: " + String.join(", ", weaknesses));
        System.out.println("Time taken: " + timeTaken + " milliseconds");

        int disjointPairs = 0;
        DisjointSet unionFind = new DisjointSet(array.length);

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!unionFind.find(i).equals(unionFind.find(j))) {
                    unionFind.union(i, j);
                    disjointPairs++;
                    long startPair = System.nanoTime();
                    long endPair = System.nanoTime();
                    long timeTakenPair = (endPair - startPair);
                    System.out.println("Time taken for pair: " + timeTakenPair + " milliseconds");
                }
            }
        }

        return "Number of disjoint pairs: " + disjointPairs;
    }
}

class DisjointSet {
    private int[] parent;

    public DisjointSet(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    public String find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return "" + parent[x];
    }

    public void union(int x, int y) {
        parent[find(x)] = find(y);
    }
}
